                            if
                                type(key2) == "string"
                                and key2:sub(1, #d + 1) == d .. "_"
                                and type(entry4) == "table"
                                and entry4.equipped == true
                                and tostring(entry4.imageId) == D
                            then
                                return entry4
                            end
                        end
                    end
                end
                if index2 == 1 then
                    scanInventoryTables(_)
                end
            end
            return nil
        end
        gearProfiles.forItem = function(d, L, O, S)
            local D = gearProfiles.gearFor(d, L, O, S)
            return D and gearProfiles.compute(D, d) or nil
        end
        gearProfiles.color = function(d)
            if d >= 99 then
                return Color3.fromRGB(155, 255, 220)
            end
            if d >= 90 then
                return Color3.fromRGB(105, 235, 135)
            end
            if d >= 75 then
                return Color3.fromRGB(190, 230, 105)
            end
            if d >= 50 then
                return Color3.fromRGB(255, 220, 105)
            end
            if d >= 25 then
                return Color3.fromRGB(255, 166, 90)
            end
            return Color3.fromRGB(255, 110, 120)
        end
    end

    components.movementBoost = function(context)
        local config, runtimeState = context.CFG, context.RT
        local localPlayer, speedSettings =
            context.LocalPlayer, {
                TargetSpeed = 24,
                MinSpeed = 18,
                MaxSpeed = 26,
                FallbackSpeed = 16,
            }
        local character = localPlayer.Character
        local humanoid, boostEnabled, originalWalkSpeed, moverHeading =
            character and (character:FindFirstChildOfClass("Humanoid")), false
        local function ensureCharacter()
            local u = character and character.Parent and humanoid and humanoid.Parent
            if u then
                return true
            end
            character = localPlayer.Character
            humanoid = character and character:FindFirstChildOfClass("Humanoid")
            u = humanoid
            return u ~= nil
        end
        local function setMoverHeading(moverHeading2)
            moverHeading = moverHeading2
            runtimeState.moverHeading = moverHeading2
        end
        local targetSpeed = speedSettings.TargetSpeed
        local function enableSpeedBoost(R)
            local y = not ensureCharacter()
            if y then
                local q = targetSpeed
                return q
            end
            local q, locomotionSpeed =
                math.clamp(
                    tonumber(R) or speedSettings.TargetSpeed,
                    speedSettings.MinSpeed,
                    speedSettings.MaxSpeed
                ),
                boostEnabled
            if locomotionSpeed then
                R = math.abs(q - targetSpeed) >= 2
                if R then
                    targetSpeed = q
                end
                y = humanoid.WalkSpeed ~= targetSpeed
                if y then
                    humanoid.WalkSpeed = targetSpeed
                end
                runtimeState.locomotionSpeed = targetSpeed
                local y = targetSpeed
                return y
            end
            boostEnabled, targetSpeed = true, q
            originalWalkSpeed = humanoid.WalkSpeed > 0 and humanoid.WalkSpeed or nil
            humanoid.WalkSpeed = targetSpeed
            locomotionSpeed = nil
            locomotionSpeed, runtimeState.locomotion = targetSpeed, true
            runtimeState.locomotionSpeed = locomotionSpeed
            R = targetSpeed
            return R
        end
        local function disableSpeedBoost()
            moverHeading = nil
            runtimeState.moverHeading = nil
            local y = boostEnabled
            if not y then
                return
            end
            boostEnabled = false
            runtimeState.locomotion = false
            runtimeState.locomotionSpeed = nil
            y = ensureCharacter()
            if y then
                local humanoid2 = humanoid
                humanoid2.WalkSpeed = originalWalkSpeed or speedSettings.FallbackSpeed
            end
            originalWalkSpeed = nil
        end
        local characterAddedConnection = localPlayer.CharacterAdded:Connect(function(newCharacter)
            character = newCharacter
            humanoid, boostEnabled, originalWalkSpeed, moverHeading =
                newCharacter:FindFirstChildOfClass("Humanoid"), false, nil, nil
            runtimeState.moverHeading = nil
            runtimeState.locomotion = false
            runtimeState.locomotionSpeed = nil
        end)
        local function stopSpeedBoost()
            disableSpeedBoost()
            local connection = characterAddedConnection
            if connection then
                characterAddedConnection:Disconnect()
                characterAddedConnection = nil
            end
        end
        context.LC = {
            on = enableSpeedBoost,
            off = disableSpeedBoost,
            steer = setMoverHeading,
            stop = stopSpeedBoost,
            CONFIG = speedSettings,
            active = function()
                return false
            end,
            boosted = function()
                local d = boostEnabled
                return d
            end,
            speed = function()
                local d = boostEnabled and targetSpeed or nil
                return d
            end,
        }
    end

    components.hazardReader = function(context)
        local config = context.CFG
        local runtimeState = context.RT
        local timing = context.TIMING
        local projectileHints = context.PROJECTILE_HINTS
        local attackCatalog = context.ATTACKS
        local ourAttacks = context.OURS
        local workspace = context.Workspace
        local replicatedStorage = context.ReplicatedStorage
        local players = context.Players
        local localPlayer = context.LocalPlayer
        local contextLog = context.log
        local contextLogT = context.logT
        local contextIsOurs = context.isOurs
        local contextCharacter = context.character
        local contextFlatDistance = context.flatDistance
        local lowercase = string.lower
        local min = math.huge
        local sqrt = math.sqrt
        local abs = math.abs
        local max = math.max
        local min2, hazardReader, v, M =
            math.min, {
                models = {},
                parts = {},
                zones = {},
                enemies = {},
                walls = {},
                beams = {},
                connections = {},
                spawns = {},
                spawnSet = {},
                watch = {},
                twinSeen = {},
            }, setmetatable, {
                __mode = "k",
            }
        hazardReader.spent = v({}, M)
        M, v = setmetatable, {
            __mode = "k",
        }
        hazardReader.hitSize = M({}, v)
        M, v = setmetatable, {
            __mode = "k",
        }
        hazardReader.seen = M({}, v)
        M, v = setmetatable, {
            __mode = "k",
        }
        hazardReader.shown = M({}, v)
        hazardReader.safeSpots = {}
        hazardReader.safeField = nil
        hazardReader.fanUntil = -min
        hazardReader.lastSweep = -min
        hazardReader.lastEnemyScan = -min
        hazardReader.lastShow = -min
        hazardReader.count = 0
        local v = {
            Map = true,
            dungeon = true,
            enemies = true,
            Terrain = true,
            Lobby = true,
            Camera = true,
        }
        local function contextGameClock()
            if config.clockServerTime ~= false then
                return workspace:GetServerTimeNow()
            end
            local timeSync = hazardReader.timeSync
            if timeSync then
                local success, f = pcall(timeSync.GetTime, timeSync)
                if success and type(f) == "number" then
                    return f
                end
            end
            return workspace:GetServerTimeNow()
        end
        local function serverTimestampToLocalClock(serverTimestamp)
            return os.clock() + (serverTimestamp - contextGameClock())
        end
        local function getLagAdjustedServerTime()
            local timeSync = hazardReader.timeSync
            if timeSync then
                local success, o = pcall(timeSync.GetTime, timeSync)
                if success and type(o) == "number" then
                    return o
                end
            end
            return workspace:GetServerTimeNow() - (config.syncLag or 0.93)
        end
        local function adjustedTimestampToLocalClock(serverTimestamp)
            return os.clock() + (serverTimestamp - getLagAdjustedServerTime())
        end
        local function contextFootprint(zone, cframe, size, round, cyl)
            local position = cframe.Position
            zone.cx, zone.cz, zone.cy = position.X, position.Z, position.Y
            if cyl then
                zone.r, zone.hy = size.Y * 0.5, size.X * 0.5
            elseif round then
                zone.r, zone.hy = size.X * 0.5, size.Y * 0.5
            else
                zone.r = nil
                local rightVector, N, lookVector = cframe.RightVector, cframe.UpVector, cframe.LookVector
                local F, C, g = abs(rightVector.Y), abs(N.Y), abs(lookVector.Y)
                local i, b
                if C >= F and C >= g then
                    zone.ha, zone.hb, zone.hy = size.X * 0.5, size.Z * 0.5, size.Y * 0.5
                    i, b = rightVector, lookVector
                else
                    if F >= g then
                        zone.ha, zone.hb, zone.hy = size.Y * 0.5, size.Z * 0.5, size.X * 0.5
                        i, b = N, lookVector
                    else
                        zone.ha, zone.hb, zone.hy = size.X * 0.5, size.Y * 0.5, size.Z * 0.5
                        i, b = rightVector, N
                    end
                end
                F, N = max(sqrt(i.X * i.X + i.Z * i.Z), 0.001), max(sqrt(b.X * b.X + b.Z * b.Z), 0.001)
                zone.ax, zone.az, zone.bx, zone.bz = i.X / F, i.Z / F, b.X / N, b.Z / N
            end
            zone.cframe = cframe
            zone.size = size
            zone.round = round
            zone.cyl = cyl
            zone.moving = false
            return zone
        end
        local function detectRoundDimensions(A, vector)
            local rightVector, a, e = A.RightVector, A.UpVector, A.LookVector
            local N, I, F = abs(rightVector.Y), abs(a.Y), abs(e.Y)
            A, a, e = nil
            if I >= N and I >= F then
                A, a, e = vector.Y, vector.X, vector.Z
            else
                if N >= F then
                    A, a, e = vector.X, vector.Y, vector.Z
                else
                    A, a, e = vector.Z, vector.X, vector.Y
                end
            end
            if a > 2 and e > 2 and abs(a - e) <= max(a, e) * (config.roundMeshTol or 0.1) then
                return max(a, e), A
            end
            return nil
        end
        local function detectRoundPart(k)
            local x = k:IsA("Part")
            if x and k.Shape == Enum.PartType.Ball then
                local size = k.Size
                return true, max(size.X, size.Z), size.Y
            end
            if
                x and k:FindFirstChildOfClass("SpecialMesh") ~= nil
                or not x and (k:IsA("MeshPart") or k:IsA("UnionOperation"))
            then
                local x, a = detectRoundDimensions(k.CFrame, k.Size)
                if x then
                    return true, x, a
                end
            end
            return false
        end
        local function contextAddZone(x)
            if not x.bubbleKeep then
                return
            end
            if not x.moving then
                contextFootprint(x, x.cframe, x.size, x.round, x.cyl)
            end
            hazardReader.zones[#hazardReader.zones + 1] = x
            hazardReader.boxGen = (hazardReader.boxGen or 0) + 1
            if #hazardReader.zones > 240 then
                table.remove(hazardReader.zones, 1)
            end
        end
        local function contextDropZones(a, e)
            for index = #hazardReader.zones, 1, -1 do
                local I = hazardReader.zones[index]
                if I.madeAt and I.madeAt < e and I.name:sub(1, #a) == a then
                    table.remove(hazardReader.zones, index)
                end
            end
        end
        local function normalizeHalfTurnAngle(angleDegrees)
            angleDegrees %= 180
            return if angleDegrees > 90 then angleDegrees - 180 else angleDegrees
        end
        local function recordBeamSample(N, I)
            local F, beams = N.CFrame.LookVector, hazardReader.beams
            beams[#beams + 1] = {
                t = I,
                yaw = math.deg(math.atan2(F.X, F.Z)) % 180,
                hub = N.Position,
                size = N.Size,
            }
            hazardReader.hub = N.Position
            hazardReader.hubAt = I
            if #beams > 24 then
                table.remove(beams, 1)
            end
            F = 0
            for index = #beams, 1, -1 do
                if I - beams[index].t <= 0.5 then
                    F += 1
                else
                    break
                end
            end
            if F >= 4 then
                if I > (hazardReader.fanUntil or -min) then
                    contextDropZones("slam incoming", I + 1)
                    hazardReader.fanStarts = hazardReader.fanStarts or {}
                    hazardReader.fanStarts[#hazardReader.fanStarts + 1] = I
                    while #hazardReader.fanStarts > 6 do
                        table.remove(hazardReader.fanStarts, 1)
                    end
                    local g = {}
                    for index2 = 2, #hazardReader.fanStarts, 1 do
                        local b = hazardReader.fanStarts[index2] - hazardReader.fanStarts[index2 - 1]
                        if b >= 5 and b <= 60 then
                            g[#g + 1] = b
                        end
                    end
                    table.sort(g)
                    hazardReader.fanPeriod = #g > 0 and g[math.ceil(#g / 2)] or nil
                    hazardReader.lastFanStart = I
                end
                hazardReader.fanUntil = I + 4
                hazardReader.fanBeamAt = I
                local g, g, g = contextCharacter()
                if
                    config.fanDance == false
                    and (g and contextFlatDistance(g.Position, N.Position) or 0)
                        < config.fanRadius - 4
                then
                    runtimeState.reflex = {
                        name = "fan",
                        from = N.Position,
                        radius = config.fanRadius,
                        untilAt = I + 3.5,
                    }
                end
            end
            contextDropZones("beam next", I - 0.5)
            if F >= 4 then
                return
            end
            N, F = beams[#beams], 0
            for index3 = #beams - 1, 1, -1 do
                local i = beams[index3]
                local C, b = N.t - i.t, normalizeHalfTurnAngle(N.yaw - i.yaw)
                if C > 0.8 then
                    break
                end
                if C >= 0.08 and abs(b) >= 15 and abs(b) <= 25 then
                    hazardReader.fanSweep = b > 0 and 1 or -1
                    hazardReader.fanSweepAt = I
                    hazardReader.beamYaw, hazardReader.beamYawAt, hazardReader.beamRate = N.yaw, I, abs(b) / C
                    F += 1
                    for index4 = 1, 2, 1 do
                        i, index3 = math.rad(N.yaw + b * index4), I + C * index4
                        contextAddZone({
                            name = "beam next",
                            kind = "zone",
                            castRed = true,
                            bubbleKeep = true,
                            hardPending = true,
                            slim = 3,
                            cframe = CFrame.lookAt(N.hub, N.hub + Vector3.new(math.sin(i), 0, math.cos(i))),
                            size = N.size,
                            from = I,
                            untilAt = index3 + 1.16 + (config.beamHitTail or 0.2),
                            exact = true,
                            madeAt = I,
                        })
                    end
                    if F >= 2 then
                        break
                    end
                else
                end
            end
        end
        local raycastParams = RaycastParams.new()
        raycastParams.FilterType = Enum.RaycastFilterType.Exclude
        local function N(I, F, instance)
            local vector = F - I
            if vector.Magnitude < 1 then
                return false
            end
            local filterDescendantsInstances = {
                table.unpack(instance),
            }
            for index = 1, 6, 1 do
                raycastParams.FilterDescendantsInstances = filterDescendantsInstances
                index = workspace:Raycast(I, vector, raycastParams)
                if not index then
                    return false
                end
                instance = index.Instance
                local a = instance:FindFirstAncestorOfClass("Model")
                local I = a ~= nil and a:FindFirstChildOfClass("Humanoid") ~= nil
                if
                    instance.CanCollide
                    and instance.Transparency < 0.95
                    and not I
                    and not hazardReader.parts[instance]
                    and hazardReader.models[a] == nil
                    and (index.Position - F).Magnitude > (config.orbShieldNear or 2)
                then
                    return true
                end
                filterDescendantsInstances[#filterDescendantsInstances + 1] = I and a or instance
            end
            return false
        end
        context.crystalShield = function(a, I, F, C, g, i)
            if config.crystalShield == false or not a or not I or not context.bobCrystal then
                return false
            end
            local b = context.bobCrystal(a)
            if not b then
                return false
            end
            local B, G = C - I, g - F
            g = B * B + G * G
            if g < 1 then
                return false
            end
            C = ((b.X - I) * B + (b.Z - F) * G) / g
            if C <= 0 or C >= 1 then
                return false
            end
            local z, s, T = I + B * C - b.X, F + G * C - b.Z, config.crystalShieldR or 6.5
            if z * z + s * s > T * T then
                return false
            end
            b = math.sqrt(g)
            if b * (1 - C) < (config.crystalShieldPast or 3) then
                return false
            end
            a = i and hazardReader.parts[i]
            if
                a
                and a.spawn
                and (config.orbFuse or 20) - (os.clock() - a.spawn)
                    < b * C / (config.orbSpeed or 17) + (config.crystalShieldFuse or 0.5)
            then
                return false
            end
            return true
        end
        context.orbColour = function(a)
            return a and a.Name and string.lower(tostring(a.Name)):match("secondboss(%a+)orb") or nil
        end
        context.bobOrbsOnMe = function()
            local a, bobOrbsMe = os.clock(), hazardReader.bobOrbsMe
            if bobOrbsMe and a >= bobOrbsMe.at and a - bobOrbsMe.at < (config.bobOrbsMeTTL or 0.004) then
                return bobOrbsMe
            end
            bobOrbsMe = {
                at = a,
            }
            a = not (context.otherRoots and #context.otherRoots() > 0)
            for key, entry in pairs(hazardReader.parts or {}) do
                if key.Parent then
                    local colour = string.lower(key.Name):match("secondboss(%a+)orb")
                    if
                        colour
                        and (
                            entry.lineOwn == "me"
                            or entry.lineOwn == nil
                                and (entry.stick == "me" or a and entry.stick ~= "other")
                        )
                    then
                        local position = key.Position
                        bobOrbsMe[#bobOrbsMe + 1] = {
                            x = position.X,
                            z = position.Z,
                            colour = colour,
                            part = key,
                        }
                    end
                end
            end
            hazardReader.bobOrbsMe = bobOrbsMe
            return bobOrbsMe
        end
        context.wrongPillarOn = function(a, I, F, C, g)
            if not context.bobCrystal then
                return nil
            end
            local i, b = C - a, g - I
            local B, G, z, s = i * i + b * b, config.wrongPillarR or 13, math.huge, context.bobCrystal(F)
            if s and B > 1 then
                C = ((s.X - a) * i + (s.Z - I) * b) / B
                g = math.clamp(C, 0, 1)
                local T, W, K = a + i * g - s.X, I + b * g - s.Z, config.crystalShieldR or 6.5
                z = if C > 0 and T * T + W * W <= K * K then g else z
            else
            end
            for index, entry in ipairs(config.bobColours or { "red", "green", "yellow" }) do
                if entry ~= F then
                    C = context.bobCrystal(entry)
                    if C then
                        g = B > 1 and math.clamp(((C.X - a) * i + (C.Z - I) * b) / B, 0, 1) or 1
                        s, index = a + i * g - C.X, I + b * g - C.Z
                        if s * s + index * index < G * G and g < z then
                            return entry
                        end
                    end
                end
            end
            return nil
        end
        context.wrongPillarAt = function(a, vector)
            if config.wrongPillarGuard == false then
                return nil
            end
            local F = context.bobOrbsOnMe()
            if #F == 0 then
                return nil
            end
            local C, g = (a.X + vector.X) * 0.5, (a.Z + vector.Z) * 0.5
            for index = 1, #F, 1 do
                a = F[index]
                index = context.wrongPillarOn(a.x, a.z, a.colour, vector.X, vector.Z)
                    or context.wrongPillarOn(a.x, a.z, a.colour, C, g)
                if index then
                    return index, a.colour
                end
            end
            return nil
        end
        context.wrongPillarStep = function(a, I)
            local F, C = context.wrongPillarAt(a, I)
            if not F then
                return nil
            end
            if context.wrongPillarAt(a, a) then
                return nil
            end
            return F, C
        end
        context.orbNearShielded = function(a, I)
            local orbNear = hazardReader.orbNear
            return orbNear ~= nil
                and orbNear.x ~= nil
                and context.crystalShield(
                    orbNear.colour or context.orbColour(orbNear.part),
                    orbNear.x,
                    orbNear.z,
                    a,
                    I,
                    orbNear.part
                )
        end
        context.orbShielded = function(a, shielded)
            if config.orbPillarShield == false or not (a and a.Parent and shielded and shielded.Parent) then
                return false
            end
            local F, shieldAt = hazardReader.parts[a], os.clock()
            if F and F.shieldAt and shieldAt - F.shieldAt < (config.orbShieldEvery or 0.1) then
                return F.shielded == true
            end
            local position, position2, b, B =
                a.Position, shielded.Position, {
                    shielded.Parent,
                    a,
                }, context.orbColour(a)
            shielded = B ~= nil
                    and context.crystalShield(B, position.X, position.Z, position2.X, position2.Z, a)
                or N(position, Vector3.new(position2.X, position.Y, position2.Z), b)
                    and N(position, position2, b)
            if F then
                F.shieldAt = shieldAt
                F.shielded = shielded
            end
            return shielded
        end
        local function a(N, madeAt)
            local F, transform, size = N.Position, N.CFrame, N.Size
            N = size.X >= size.Z and transform.RightVector or transform.LookVector
            local i, b = N.X, N.Z
            N = math.sqrt(i * i + b * b)
            if N < 0.01 then
                return
            end
            i /= N
            b /= N
            N = math.deg(math.atan2(b, i))
            local from = math.floor((if N < 0 then N + 180 else N) / 6 + 0.5) % 30
            hazardReader.volleyRows = hazardReader.volleyRows or {}
            N = hazardReader.volleyRows[from]
            local vector = N and Vector3.new(F.X - N.pos.X, 0, F.Z - N.pos.Z) or nil
            local span = vector and vector.Magnitude or 0
            local s = N ~= nil
                and madeAt - N.t <= 0.4
                and span >= 6
                and span <= 40
                and math.abs(vector.X * i + vector.Z * b) / span <= 0.5
            local T = s and (N.n or 1) + 1 or 1
            hazardReader.volleyRows[from] = {
                t = madeAt,
                pos = F,
                n = T,
            }
            local W, K, rowDx, rowDz, X = not s
            if s then
                K, rowDx, rowDz = math.max(madeAt - N.t, 0.08), vector.X / span, vector.Z / span
                hazardReader.rowLearn = {
                    dt = K,
                    span = span,
                }
                X = span
            else
                local N = hazardReader.rowLearn
                X, K, rowDz = N and N.span or config.mageRowStep or 17, N and N.dt or config.mageRowDt or 0.15, -i
                local i, G = config.mageCasterNear or 6
                for index, entry in ipairs(hazardReader.enemies or {}) do
                    if entry.isMage and entry.root and entry.root.Parent then
                        N = math.sqrt((entry.x - F.X) ^ 2 + (entry.z - F.Z) ^ 2)
                        if N < i then
                            i, G = N, entry
                        else
                        end
                    else
                    end
                end
                if G and G.root and G.root.Parent then
                    N = G.root.CFrame.LookVector
                    local i = math.sqrt(N.X * N.X + N.Z * N.Z)
                    if i > 0.01 then
                        rowDx, rowDz = N.X / i, N.Z / i
                    else
                        rowDx = b
                    end
                else
                    rowDx = b
                end
            end
            if not (rowDx and rowDz) then
                return
            end
            span = Vector3.new(rowDx * X, 0, rowDz * X)
            hazardReader.lastRowDir = {
                dx = rowDx,
                dz = rowDz,
                t = madeAt,
            }
            hazardReader.mageShotSeen = {
                t = madeAt,
                x = F.X,
                z = F.Z,
            }
            F = "volley next " .. tostring(from)
            contextDropZones(F, madeAt - 0.05)
            for index2 = 1, W and (config.mageRowAheadGuess or 2) or (config.mageRowAhead or 4), 1 do
                if T + index2 > (config.mageRowSlabs or 7) then
                    break
                end
                from = madeAt + K * index2
                contextAddZone({
                    name = F,
                    kind = "zone",
                    bubbleKeep = true,
                    hardPending = true,
                    exact = true,
                    weight = 1,
                    madeAt = madeAt,
                    slim = config.mageMargin,
                    noLead = W or nil,
                    cframe = transform + span * index2,
                    size = Vector3.new(size.X, max(size.Y, 12), size.Z),
