            hazardReader.gildedMobClockNote = function(model, name, now) -- D-062: which mob attacked, and when
                local part = model:FindFirstChild("hitBox", true) or model:FindFirstChild("precast", true)
                if not (part and part:IsA("BasePart")) then
                    return
