                local lv = size.Z >= size.X and cf.LookVector or cf.RightVector
                local half = math.max(size.Z, size.X) / 2
                local lx, lz = lv.X, lv.Z
                local ll = math.sqrt(lx * lx + lz * lz)
                if ll < 0.1 then
                    return
                end
                lx, lz = lx / ll, lz / ll
                local px, pz = part.Position.X, part.Position.Z
                if (kind == "familiar" or kind == "mage" and config.gildedMageLanes ~= false) and part.Name == "hitBox" and half > 20 then
                    -- D-065: the lane itself, for the step across it - D-070: a Mage line too, until its strike is over
                    -- D-097: every hitBox of the model (a Mage attack is a cross of two lines), again at +0.15 s for late parts
