                            if q.Name == "hitBox" and q:IsA("BasePart") and not done[q] then
                                local qs, qc = q.Size, q.CFrame
                                local qv = qs.Z >= qs.X and qc.LookVector or qc.RightVector
                                local qh = math.max(qs.Z, qs.X) / 2
                                local ql = math.sqrt(qv.X * qv.X + qv.Z * qv.Z)
                                if qh > 20 and ql >= 0.1 then
                                    done[q] = true
                                    lanes[#lanes + 1] = { x = q.Position.X, z = q.Position.Z, lx = qv.X / ql, lz = qv.Z / ql, half = qh, kind = kind, model = model,
                                        hw = math.min(qs.X, qs.Z) / 2, at = now,
