                        local dx, dz = q.X - px, q.Z - pz
                        local d
                        if kind == "warrior" or kind == "knight" then
                            d = math.sqrt(dx * dx + dz * dz)
                        else
                            local a = math.clamp(dx * lx + dz * lz, -half, half)
                            d = math.sqrt((dx - a * lx) ^ 2 + (dz - a * lz) ^ 2) -- from its line
                        end
