                    if not context.gildedOwnTrailHit(pos.X, pos.Z, sx, sz, sp, now)
                        and not context.gildedOwnTrailHit(sx, sz, gx, gz, sp, now + d1 / sp) then
                        return Vector3.new(sx, pos.Y, sz)
                    end
                end
                return nil
            end
