    components.dangerGeometry = function(context)
        local config = context.CFG
        local runtimeState = context.RT
        local hazardReader = context.RD
        local workspace = game:GetService("Workspace")
        local contextHazards = context.hazards
        local sqrt = math.sqrt
        local abs = math.abs
        local max = math.max
        local min = math.min
        local infinity = math.huge
        local cdKeepAt, cdKeepOn = -math.huge, false
        local function cdKeep() -- D-049: Gilded Skies, the attack skill on cooldown (cached 0.1 s)
            local now = os.clock()
            if now - cdKeepAt < 0.1 then
                return cdKeepOn
            end
            cdKeepAt, cdKeepOn = now, false
            if hazardReader.gildedOn and config.gildedMeleeCdKeep ~= false and context.attackReady then
                local ok, ready, left = pcall(context.attackReady)
                cdKeepOn = ok and ready == false and (tonumber(left) or 1) > (config.gildedMeleeCdMin or 0.5)
            end
            return cdKeepOn
        end
        local dangerGeometry = {
            target = nil,
            reason = "",
            dangerHere = 0,
            here0 = 0,
            now = 0,
            offsets = {},
            outer = {},
            cands = {},
            boxes = {},
            reach = 2,
            halfHeight = 5,
            feet = 3,
            approach = nil,
            heading = nil,
            headingAt = -infinity,
            evalStats = {},
        }
        local function contextDepthOf(zone, y, q, V, E)
            local p = q - zone.cy
            if abs(p) > zone.hy + E then
                if
                    not (
                        p > 0
                        and p <= zone.hy + E + (config.sinkSlack or 4)
                        and zone.hy <= 1.5
                        and (zone.r or max(zone.ha or 0, zone.hb or 0)) >= 3
                        and context.belowNL
                        and context.belowNL()
                    )
                then
                    return -infinity
                end
            end
            p, E = y - zone.cx, V - zone.cz
            if zone.r then
                V = sqrt(p * p + E * E)
                q = zone.r - V
                if zone.ring then
                    if p * zone.sx + E * zone.sz < 0 then
                        return -infinity
                    end
                    q = min(q, V - zone.ring)
                else
                end
                return q
            end
            V, y = abs(p * zone.ax + E * zone.az) - zone.ha, abs(p * zone.bx + E * zone.bz) - zone.hb
            if V <= 0 and y <= 0 then
                return -max(V, y)
            end
            return -sqrt(max(V, 0) ^ 2 + max(y, 0) ^ 2)
        end
        local function depthWeight(R, y, q)
            local V = R + y
            if V >= 0 then
                return 1
            end
            if -V < q then
                return 1 + V / q
            end
            return 0
        end
        local function contextDangerAt(y, q, V, E, p, j, U)
            local J, w, Y, v, M =
                p or dangerGeometry.reach,
                dangerGeometry.halfHeight,
                j or config.dodgeShoulder,
                dangerGeometry.now,
                dangerGeometry.boxes
            j, p = v + E, 0
            for index = 1, #M, 1 do
                local n = M[index]
                if not n.far and not (U and U(n)) then
                    index = nil
                    if n.moving then
                        if j <= n.untilAt and (n.ground or abs(q - n.oy) <= n.halfH + w) then
                            local U, f = n.offset + n.speed * max(j - n.pathStart, 0), n.endAlong
                            U = if f and U > f then f else U
                            local r, o = n.dx, n.dz
                            local A, k = y - (n.ox + r * U), V - (n.oz + o * U)
                            local U, x, a = A * r + k * o, n.r
                            if x then
                                f = -A * o + k * r
                                index, a = x - sqrt(U * U + f * f), abs(f) - x
                            else
                                local f = abs(U) - n.halfL
                                a = abs(-A * o + k * r) - n.halfW
                                index = if f <= 0 and a <= 0
                                    then -max(f, a)
                                    else -sqrt(max(f, 0) ^ 2 + max(a, 0) ^ 2)
                            end
                            p = if index + J < 0
                                    and not n.noLane
                                    and not n.laneFree
                                    and U > n.halfL
                                    and a <= J
                                    and U - n.halfL <= n.speed * min(
                                        max(n.untilAt - j, 0),
                                        n.horizon or config.laneHorizon
                                    )
                                    and p < config.pathLaneDanger
                                then config.pathLaneDanger
                                else p
                        else
                        end
                    else
                        local from, U = n.from, not n.exact and (n.telegraphed or n.from > v)
                        local f = U and max(n.lead or config.dodgeLead, dangerGeometry.leadFloor or 0)
                            or (dangerGeometry.leadFloor or 0)
                        index = if j >= from - f and j <= n.untilAt then contextDepthOf(n, y, q, V, w) else index
                    end
                    if index then
                        local _, U
                        if n.fullKeep and not dangerGeometry.redRelax then
                            _, U = dangerGeometry.reach or J, config.redOrbShoulder or 0.75
                        else
                            _, U = J, Y
                        end
                        if n.slim then
                            _, U =
                                (min(_, n.slim + (dangerGeometry.lag or 0) * config.slimLagShare)),
                                min(U, config.slimShoulder)
                        else
                        end
                        local f = index + _
                        f = if n.soft and E > config.softAfter
                            then (if n.weight
                                then (if f >= 0 then 1 else if -f < U then 1 + f / U else 0) * n.weight
                                else if f >= 0 then 1 else if -f < U then 1 + f / U else 0) * config.softFactor
                            else if n.weight
                                then (if f >= 0 then 1 else if -f < U then 1 + f / U else 0) * n.weight
                                else if f >= 0 then 1 else if -f < U then 1 + f / U else 0
                        if f > p then
                            if f >= 1 then
                                return 1
                            end
                            p = f
                        else
                        end
                    else
                    end
                else
                end
            end
            j = hazardReader.leash
            if j then
                q = j.enemy.root
                if q.Parent then
                    M = q.Position
                    if sqrt((y - M.X) ^ 2 + (V - M.Z) ^ 2) - j.radius > -4 then
                        return 1
                    end
                end
            end
            q = hazardReader.enemies
            for index2 = 1, #q, 1 do
                v = q[index2]
                if v.melee and not v.isBoss then
                    index2 = min(E, 0.6)
                    w, M =
                        sqrt((y - v.x - v.vx * index2) ^ 2 + (V - v.z - v.vz * index2) ^ 2),
                        v.extent + v.meleeDistance + 2
                    j = w <= M + J and 1
                        or depthWeight(-(w - M - config.meleeBuffer), J, Y * 2)
                            * config.meleeBandWeight
                    if j < 1 and hazardReader.gildedOn and config.gildedMeleeKeep ~= false then
                        -- D-050 (Warrior / Knight: the only melee in Gilded Skies): keep out of reach all the time,
                        -- further and firmer while the attack recharges; soft, so a crowd cannot trap the bot
                        local cd = cdKeep()
                        if w <= (cd and (config.gildedMeleeCdR or 28) or (config.gildedMeleeKeepR or 22)) then
                            j = max(j, cd and (config.gildedMeleeCdWeight or 0.6) or (config.gildedMeleeKeepWeight or 0.4))
                        end
                    end
                    if j > p then
                        if j >= 1 then
                            return 1
                        end
                        p = j
                    else
                    end
                else
                end
            end
            return p
        end
        context.redOrbNear = function(O, P, _)
            local u, y, q, V, E, p, j, U =
                dangerGeometry.boxes or {},
                dangerGeometry.now or os.clock(),
                dangerGeometry.reach or 1.8,
                (config.redOrbStand or 0.5) + (_ or 0),
                config.redOrbStandStep or 0.2,
                O.X,
                O.Z,
                (P or 0) + 1.0E-6
            P = type(E) == "number" and E > 0
            for index = 1, #u, 1 do
                _ = u[index]
                if _.fullKeep and _.moving then
                    O = (_.r or _.halfW or 12) + q + V
                    local u, q, V, w, Y, endAlong, M, Z, n, f, r =
                        O * O,
                        (_.untilAt or 0) + 0.2,
                        _.offset or 0,
                        _.speed or 0,
                        _.pathStart or y,
                        _.endAlong,
                        _.ox,
                        _.oz,
                        _.dx,
                        _.dz,
                        0
                    while r <= U do
                        index = y + r
                        if index <= q then
                            local O = V + w * max(index - Y, 0)
                            O = if endAlong and O > endAlong then endAlong else O
                            local _, y = p - (M + n * O), j - (Z + f * O)
                            if _ * _ + y * y < u then
                                return true
                            end
                        elseif P then
                            break
                        end
                        r += E
                    end
                end
            end
            return false
        end
        local function contextWalkable(P, _, u, y, q)
            local V = config.maxStepHeight + 1.5
            local E = Vector3.new(P.X, P.Y - dangerGeometry.feet + V, P.Z)
            P = workspace:Blockcast(CFrame.new(E), Vector3.new(2.5, 3, 2.5), Vector3.new(_, u + V, y) - E, q)
            return P == nil, P
        end
        local function contextDecide(P, _)
            local now = os.clock()
            dangerGeometry.lag =
                min((runtimeState.pingS or 0) * max(runtimeState.speedNow or 16, 16), config.pingMarginMax)
            dangerGeometry.now, dangerGeometry.reach, dangerGeometry.halfHeight, dangerGeometry.feet =
                now,
                P.Size.X * 0.5 + config.dodgeMargin + dangerGeometry.lag,
                (_.HipHeight + P.Size.Y) * 0.5 + 2.5,
                _.HipHeight + P.Size.Y * 0.5
            dangerGeometry.halfWidth = P.Size.X * 0.5
            if context.carryIgnoresHits and context.carryIgnoresHits() then
                for index = #dangerGeometry.boxes, 1, -1 do
                    dangerGeometry.boxes[index] = nil
                end
            else
                contextHazards(now, dangerGeometry.boxes)
            end
            dangerGeometry.here0, dangerGeometry.dangerHere, dangerGeometry.target, dangerGeometry.reason, dangerGeometry.origin =
                0, 0, nil, "bubble", P.Position
            for index2 = #dangerGeometry.cands, 1, -1 do
                dangerGeometry.cands[index2] = nil
            end
            runtimeState.moveBoost = false
        end
        context.DG = dangerGeometry
        context.dangerAt = contextDangerAt
        context.decide = contextDecide
        context.walkable = contextWalkable
        context.depthOf = contextDepthOf
        context.RING_GAPS = { 31.25, 43.75, 56.25, 68.75, 81.25 }
        context.odinRankOff = function(L)
            local O, S, D, P =
                config.odinRankIn or 56.25,
                config.odinRankOut or 81.25,
                config.odinRank3In or 43.75,
                config.odinRank3Weight or 0.35
            if L >= O and L <= S then
                return 0
            end
            if L > S then
                return L - S
            end
            if L >= D then
                return (O - L) * P
            end
            return (O - D) * P + (D - L)
        end
        context.odinBandOff = function(d)
            local L, O = config.odinBandIn or 43.75, config.odinRankOut or 81.25
            if d < L then
                return L - d
            end
            if d > O then
                return d - O
            end
            return 0
        end
    end

    components.odinMechanics = function(context)
        local config = context.CFG
        local hazardReader = context.RD
        local workspace = game:GetService("Workspace")
        local sqrt = math.sqrt
        local floor = math.floor
        local abs = math.abs
        local infinity = math.huge
        local max = math.max
        local min, odinMechanics, setMetatable, weakKeys =
            math.min, {}, setmetatable, {
                __mode = "k",
            }
        odinMechanics.sets = setMetatable({}, weakKeys)
        odinMechanics.setList = {}
        odinMechanics.orbs = {}
        odinMechanics.orbList = {}
        odinMechanics.missiles = {}
        odinMechanics.missileList = {}
        odinMechanics.arrays = {}
        odinMechanics.lines = {}
        odinMechanics.lineList = {}
        odinMechanics.lastTick = 0
        context.OD = odinMechanics
        local function m(part)
            local y = max(part.Size.X, part.Size.Z) * 0.5
            if y < 10 then
                return nil
            end
            local q = part.CFrame.LookVector
            local V, E = q.X, q.Z
            q = sqrt(V * V + E * E)
            if q < 0.01 then
                return nil
            end
            V /= q
            E /= q
            q = part.Position
            return q.X - V * (y / 2),
                q.Z - E * (y / 2),
                y,
                y - (y >= 100 and (config.ringThicknessOuter or 17.5) or (config.ringThickness or 12.5)),
                V,
                E,
                q.Y
        end
        odinMechanics.noteRingSet = function(model, spawn)
            local q = odinMechanics.sets[model]
            if q then
                return q
            end
            q = {
                model = model,
                spawn = spawn,
                boxed = {},
                parts = {},
                bands = {},
                n = 0,
                centre = nil,
            }
            odinMechanics.sets[model] = q
            odinMechanics.setList[#odinMechanics.setList + 1] = q
            if context.logT then
                context.logT("rings", 2, "Odin", "ring set seen")
            end
            return q
        end
        local function R(y, madeAt)
            local V = config.ringLive or 1.3
            if not y.centreX then
                local E = y.model:FindFirstChild("center") or y.model:FindFirstChild("Center")
                if E and (E:IsA("BasePart")) then
                    y.centreX, y.centreZ = E.Position.X, E.Position.Z
                end
            end
            for index, child in ipairs(y.model:GetChildren()) do
                if child:IsA("BasePart") and not y.boxed[child] then
                    index = string.lower(child.Name)
                    if index == "ring" then
                        local j, centreZ, J, inner, Y, v, M = m(child)
                        if j and y.centreX then
                            local Z, n = child.Position.X - y.centreX, child.Position.Z - y.centreZ
                            local f = sqrt(Z * Z + n * n)
                            if f > 1 then
                                Y, v = Z / f, n / f
                            else
                            end
                            j, centreZ = y.centreX, y.centreZ
                        else
                            local arenaCentre = hazardReader.arenaCentre
                            j = if j
                                    and arenaCentre
                                    and abs(
                                            sqrt(
                                                (child.Position.X - arenaCentre.X) ^ 2
                                                    + (child.Position.Z - arenaCentre.Z) ^ 2
                                            ) - J / 2
                                        )
                                        > (config.ringPosTol or 4)
                                then nil
                                else j
                        end
                        if j then
                            y.boxed[child] = true
                            y.parts[#y.parts + 1] = child
                            y.bands[#y.bands + 1] = {
                                cx = j,
                                cz = centreZ,
                                R = J,
                                inner = inner,
                                sx = Y,
                                sz = v,
                            }
                            y.n = y.n + 1
                            if context.addZone then
                                context.addZone({
                                    name = "ring arc",
                                    kind = "zone",
                                    bubbleKeep = true,
                                    slim = config.ringSlim,
                                    tight = true,
                                    cframe = CFrame.new(j, M, centreZ),
                                    size = Vector3.new(
                                        (J + (config.ringPad or 0)) * 2,
                                        12,
                                        (J + (config.ringPad or 0)) * 2
                                    ),
                                    round = true,
                                    ring = inner - (config.ringPad or 0),
                                    sx = Y,
                                    sz = v,
                                    from = y.spawn,
                                    untilAt = y.spawn + V,
                                    exact = true,
                                    madeAt = madeAt,
                                    model = y.model,
                                })
                            end
                        end
                    elseif index == "center" then
                        y.boxed[child] = true
                        y.centre = child
                        local position, j = child.Position, max(child.Size.X, child.Size.Y, child.Size.Z)
                        y.centreR, y.centreX, y.centreZ = j * 0.5, position.X, position.Z
                        if context.addZone then
                            context.addZone({
                                name = "ring centre",
                                kind = "zone",
                                bubbleKeep = true,
                                cframe = CFrame.new(position.X, position.Y, position.Z),
                                size = Vector3.new(j, 12, j),
                                round = true,
                                from = y.spawn,
                                untilAt = y.spawn + V,
                                exact = true,
                                madeAt = madeAt,
                                model = y.model,
                            })
                        end
                    end
                end
            end
        end
        local function y(q)
            if config.ringInvulnFree == false or hazardReader.charAt == nil then
                return false
            end
            return q.spawn + (config.ringLive or 1.3)
                <= hazardReader.charAt
                    + (config.invulnAfterRespawn or 4)
                    - (config.ringInvulnMargin or 0.2)
        end
        local function q(V, E, p, j)
            if y(V) then
                return false
            end
            j = (j or 0) + (config.ringPad or 0)
            local bands = V.bands
            for index = 1, #bands, 1 do
                local zone = bands[index]
                local U, Y = E - zone.cx, p - zone.cz
                if U * zone.sx + Y * zone.sz >= -j then
                    index = sqrt(U * U + Y * Y)
                    if index >= zone.inner - j and index <= zone.R + j then
                        return true, zone.R
                    end
                end
            end
            if V.centreR then
                local U, J = E - V.centreX, p - V.centreZ
                if sqrt(U * U + J * J) <= V.centreR + j then
                    return true, 0
                end
            end
            return false
        end
        odinMechanics.ringClear = function(V, E, p)
            local j, U = config.ringLive or 1.3
            for index = 1, #odinMechanics.setList, 1 do
                local w = odinMechanics.setList[index]
                index = p - w.spawn
                if index >= -0.05 and index <= j and w.model.Parent and not y(w) then
                    local bands = w.bands
                    for index2 = 1, #bands, 1 do
                        local zone = bands[index2]
                        local p, w = V - zone.cx, E - zone.cz
                        if p * zone.sx + w * zone.sz >= 0 then
                            index2 = sqrt(p * p + w * w)
                            U = if U == nil
                                    or (
                                            if index2 < zone.inner
                                                then zone.inner - index2
                                                else if index2 > zone.R then index2 - zone.R else 0
                                        )
                                        < U
                                then if index2 < zone.inner
                                    then zone.inner - index2
                                    else if index2 > zone.R then index2 - zone.R else 0
                                else U
                        else
                        end
                    end
                else
                end
            end
            return U
        end
        odinMechanics.inRingBand = function(V, E, p, j)
            j = j or 0
            local U = config.ringLive or 1.3
            for index = 1, #odinMechanics.setList, 1 do
                local w = odinMechanics.setList[index]
                index = p - w.spawn
                if index >= -0.05 and index <= U and w.model.Parent then
                    local p, U = q(w, V, E, j)
                    if p then
                        return true, w, U
                    end
                end
            end
            return false
        end
        odinMechanics.ignoreSets = {}
        odinMechanics.ignoreLines = {}
        local function V(E, p, j, U)
            local J, w = config.ringLive or 1.3, config.ringFlashFrom or 0.9
            for index = 1, #odinMechanics.setList, 1 do
                local v = odinMechanics.setList[index]
                index = j - v.spawn
                if index >= w and index <= J and v.model.Parent and q(v, E, p, U) then
                    return true
                end
            end
            return false
        end
        odinMechanics.pathCrossesRing = function(E, p, j, U, J, w)
            if #odinMechanics.setList == 0 then
                return false
            end
            local Y, v = j - E, U - p
            U = sqrt(Y * Y + v * v)
            if U < 1 then
                return false
            end
            local M, Z = config.ringSlim or 2.5, max(2, math.ceil(U / 2))
            w = w or J
            for index = 1, Z, 1 do
                j = index / Z
                index, U = E + Y * j, p + v * j
                if odinMechanics.inRingBand(index, U, J + (w - J) * j, M) then
                    return true
                end
                if odinMechanics.inRingBand(index, U, J, M) then
                    return true
                end
            end
            return false
        end
        local function E(p, j, part, spawn)
            local w, position = j[part], part.Position
            local v = w
            if not w then
                w = {
                    part = part,
                    x = position.X,
                    z = position.Z,
                    vx = 0,
                    vz = 0,
                    t = spawn,
                    spawn = spawn,
                    hasV = false,
                }
                j[part] = w
                p[#p + 1] = w
                return w
            end
            p = spawn - v.t
            if p > 0.02 then
                j, w, part = (position.X - v.x) / p, (position.Z - v.z) / p, false
                if v.hasV and config.orbBounce ~= false then
                    local p = v.vx * j + v.vz * w
                    part = p < 0 or p * p < 0.5 * (v.vx * v.vx + v.vz * v.vz) * (j * j + w * w)
                else
                end
                if v.hasV and not part then
                    v.vx, v.vz = v.vx * 0.5 + j * 0.5, v.vz * 0.5 + w * 0.5
                else
                    v.vx = j
                    v.vz = w
                    v.hasV = true
                end
                v.x, v.z = position.X, position.Z
                v.t = spawn
            end
            return v
        end
        local function p(j, U, J, w)
            for index = #j, 1, -1 do
                local v = j[index]
                if
                    not v.part.Parent
                    or J - v.spawn > w
                    or v.part:IsA("BasePart") and v.part.Transparency >= 1
                then
                    U[v.part] = nil
                    table.remove(j, index)
                end
            end
        end
        local function j()
            local arenaCentre = hazardReader.arenaCentre
            if not arenaCentre then
                odinMechanics.arrays = {}
                return
            end
            local arrays = {}
            for index = 1, #odinMechanics.missileList, 1 do
                local Y = odinMechanics.missileList[index]
                local v, M = Y.vx, Y.vz
                index = sqrt(v * v + M * M)
                if index < 20 then
                    local lookVector = Y.part.CFrame.LookVector
                    v, M = lookVector.X, lookVector.Z
                    index = sqrt(v * v + M * M)
                    if index > 0.01 and (arenaCentre.X - Y.x) * v + (arenaCentre.Z - Y.z) * M < 0 then
                        v, M = -v, -M
                    else
                    end
                else
                end
                if index > 0.01 then
                    v /= index
                    M /= index
                    local w = math.atan2(v, M)
                    local Z
                    for index2, array in ipairs(arrays) do
                        if
                            abs((w - array.yaw + 3.141592653589793) % 6.283185307179586 - 3.141592653589793)
                            < 0.13962634015954636
                        then
                            Z = array
                            break
                        end
                    end
                    if not Z then
                        Z = {
                            yaw = w,
                            lx = v,
                            lz = M,
                            nx = -M,
                            nz = v,
                            at = Y.spawn,
                            n = 0,
                            maxAlong = -infinity,
                            pending = 0,
                            lastSpawn = Y.spawn,
                        }
                        arrays[#arrays + 1] = Z
                    else
                    end
                    Z.n = Z.n + 1
                    if Y.spawn < Z.at then
                        Z.at = Y.spawn
                    end
                    if Y.spawn > Z.lastSpawn then
                        Z.lastSpawn = Y.spawn
                    end
                    w = (Y.x - arenaCentre.X) * Z.lx + (Y.z - arenaCentre.Z) * Z.lz
                    if w > Z.maxAlong then
                        Z.maxAlong = w
                    end
                    if w < 30 then
                        Z.pending = Z.pending + 1
                    end
                end
            end
            odinMechanics.arrays = arrays
        end
        odinMechanics.lineSeenAt = odinMechanics.lineSeenAt or {}
        if not odinMechanics.lineSeenConn then
            odinMechanics.lineSeenConn = workspace.ChildAdded:Connect(function(U)
                if U.Name == "thirdBossLineShot" and U:IsA("Model") then
                    odinMechanics.lineSeenAt[U] = os.clock()
                end
            end)
        end
        if odinMechanics.lineSeenConn and context.sliderConnections then -- D-017: disconnect on destroy
            table.insert(context.sliderConnections, odinMechanics.lineSeenConn)
        end
        odinMechanics.tick = function(U)
            odinMechanics.lastTick = U
            local J = U - (odinMechanics.prevTick or U)
            odinMechanics.prevTick = U
            local ringLive = config.ringLive
            for index, child in ipairs(workspace:GetChildren()) do
                index = child.Name
                if index == "thirdBossMultiRings" then
                    local Y = odinMechanics.noteRingSet(child, U)
                    if Y.n < 7 and U - Y.spawn < 2 then
                        R(Y, U)
                    end
                    if U - Y.spawn < (config.ringSettle or 2) then
                        for index2 = 1, #Y.parts, 1 do
                            local v = Y.parts[index2]
                            if v.Parent then
                                local M, Z, n, inner, r, o = m(v)
                                local zone = Y.bands[index2]
                                if M and zone then
                                    zone.cx = M
                                    zone.cz = Z
                                    zone.R = n
                                    zone.inner = inner
                                    zone.sx = r
                                    zone.sz = o
                                end
                            end
                        end
                    end
                elseif index == "thirdBossBouncingOrb" and child:IsA("BasePart") then
                    E(odinMechanics.orbList, odinMechanics.orbs, child, U)
                elseif index == "thirdBossMissile" and child:IsA("BasePart") then
                    if child.Transparency < 1 then
                        E(odinMechanics.missileList, odinMechanics.missiles, child, U)
                    end
                elseif index == "thirdBossLineShot" and child:IsA("Model") then
                    if not odinMechanics.lines[child] then
                        local part = child:FindFirstChild("hitBox")
                            or child:FindFirstChild("HitBox")
                            or child:FindFirstChild("precast")
                        if part and (part:IsA("BasePart")) then
                            local R = {
                                model = child,
                                part = part,
                                spawn = odinMechanics.lineSeenAt and odinMechanics.lineSeenAt[child] or U,
                            }
                            if odinMechanics.lineSeenAt then
                                odinMechanics.lineSeenAt[child] = nil
                            end
                            odinMechanics.lines[child] = R
                            odinMechanics.lineList[#odinMechanics.lineList + 1] = R
                            if config.odinFirstBeamOnly ~= false then
                                local ignoredModels, ignoredModels2 = odinMechanics.ignoredModels
                                if ignoredModels then
                                    ignoredModels2 = ignoredModels
                                else
                                    local setMetatable2, weakKeys2 =
                                        setmetatable, {
                                            __mode = "k",
                                        }
                                    ignoredModels2 = setMetatable2({}, weakKeys2)
                                end
                                odinMechanics.ignoredModels = ignoredModels2
                                if
                                    R.spawn - (odinMechanics.lastLineAt or -infinity)
                                    > (config.odinFanQuiet or 2)
                                then
                                    odinMechanics.fan = {
                                        first = R,
                                        startAt = R.spawn,
                                    }
                                    odinMechanics.central = R
                                    odinMechanics.fanGreen = nil
                                    context.logT("odin", 1, "Odin", "fan: first beam - red")
                                else
                                    R.ignored = true
                                    odinMechanics.ignoredModels[child] = true
                                end
                                odinMechanics.lastLineAt =
                                    math.max(odinMechanics.lastLineAt or -infinity, R.spawn)
                            elseif odinMechanics.central == nil then
                                odinMechanics.central = R
                            end
                        end
                    end
                end
            end
            for index3 = #odinMechanics.setList, 1, -1 do
                local R = odinMechanics.setList[index3]
                if not R.model.Parent or U - R.spawn > 25 then
                    odinMechanics.sets[R.model] = nil
                    table.remove(odinMechanics.setList, index3)
                end
            end
            p(odinMechanics.orbList, odinMechanics.orbs, U, 40)
            p(odinMechanics.missileList, odinMechanics.missiles, U, 12)
            for index4 = 1, #odinMechanics.lineList, 1 do
                local R = odinMechanics.lineList[index4]
                if not R.firedAt and R.model and R.model.Parent then
                    index4 = R.model:FindFirstChild("precast")
                    local sig = index4 and floor(index4.Transparency * 100 + 0.5) or -1
                    if R.sig == nil then
                        R.sig = sig
                    elseif sig ~= R.sig then
                        local m = U - R.spawn
                        if m >= (config.lineFiredMin or 0.3) then
                            R.firedAt = U
                            if R == odinMechanics.central and odinMechanics.noteGreen then
                                pcall(odinMechanics.noteGreen, R, U)
                            end
                            odinMechanics.firedAges = odinMechanics.firedAges or {}
                            odinMechanics.firedAges[#odinMechanics.firedAges + 1] = m
                            if #odinMechanics.firedAges > 40 then
                                table.remove(odinMechanics.firedAges, 1)
                            end
                            if config.lineFiredLog ~= false then
                                context.logT(
                                    "odin",
                                    1,
                                    "Odin",
                                    ("line shot fired at age %.2f (precast %d -> %d)"):format(m, R.sig, sig)
                                )
                            end
                        end
                        R.sig = sig
                    end
                end
            end
            for index5 = 1, #odinMechanics.lineList, 1 do
                local R = odinMechanics.lineList[index5]
                if not R.firedAt and not R.ignored then
                    index5 = hazardReader.models and hazardReader.models[R.model]
                    if
                        index5
                        and (index5.detonatedAt or index5.fired)
                        and U - R.spawn >= (config.lineFiredMin or 0.3)
                    then
                        R.firedAt = U
                        if R == odinMechanics.central and odinMechanics.noteGreen then
                            pcall(odinMechanics.noteGreen, R, U)
                        end
                    end
                end
            end
            for index6 = #odinMechanics.lineList, 1, -1 do
                local R = odinMechanics.lineList[index6]
                if not R.model.Parent and not R.goneAt then
                    R.goneAt = U
                end
                if R.goneAt and U > R.goneAt + (config.beamHitTail or 0.2) or U - R.spawn > 6 then
                    odinMechanics.lines[R.model] = nil
                    if odinMechanics.danceSide then
                        odinMechanics.danceSide[R.model] = nil
                    end
                    if odinMechanics.central == R then
                        odinMechanics.central = nil
                    end
                    table.remove(odinMechanics.lineList, index6)
                end
            end
            j()
        end
        local function m(R, E, p, j, U)
            local arenaCentre = hazardReader.arenaCentre
            if not arenaCentre then
                return false
            end
            local w, Y = config.missileLanePitch or 15, (config.missileLaneWidth or 10) * 0.5
            for index = 1, U and 0 or #odinMechanics.missileList, 1 do
                local M = odinMechanics.missileList[index]
                index = sqrt(M.vx * M.vx + M.vz * M.vz)
                if index > 20 then
                    local Z, n, f, r = M.vx / index, M.vz / index, R - M.x, E - M.z
                    local o = f * Z + r * n
