    components.bossPhases = function(context)
        local config = context.CFG
        local runtimeState, hazardReader = context.RT, context.RD
        local sqrt = math.sqrt
        local max = math.max
        local min = math.min
        local infinity = math.huge
        local abs = math.abs
        local bossPhases = {
            boss = nil,
            phase = "idle",
            phaseAt = -infinity,
            fansSinceSlam = 0,
            lastFanAt = -infinity,
            lastSlamAt = -infinity,
            lastJumpAt = -infinity,
            lastChainAt = -infinity,
            lastSpikesAt = -infinity,
            lastFloorAt = -infinity,
            respawnAt = -infinity,
            lastLineAt = -infinity,
            lastMissileAt = -infinity,
            fanSeen = 0,
            slamSeen = 0,
            note = "",
        }
        context.PB = bossPhases
        local function c(u, h, m, R)
            local y, q = u - m, h - R
            return sqrt(y * y + q * q)
        end
        local function u(h)
            if not (h and h.isBoss and h.model) then
                return nil
            end
            return context.bossProfile(h.model.Name)
        end
        local function h(phase, phaseAt)
            if bossPhases.phase ~= phase then
                bossPhases.phase = phase
                bossPhases.phaseAt = phaseAt
            end
        end
        local function m(R, champEntry, q)
            if not hazardReader.champEntry and q and q.root and q.root.Parent then
                local position = q.root.Position
                if c(champEntry.X, champEntry.Z, position.X, position.Z) <= 140 then
                    hazardReader.champEntry = champEntry
                end
            end
            local fanStarts = hazardReader.fanStarts
            local lastFanAt = fanStarts and fanStarts[#fanStarts] or nil
            if lastFanAt and lastFanAt ~= bossPhases.lastFanAt then
                bossPhases.lastFanAt = lastFanAt
                bossPhases.fanSeen = bossPhases.fanSeen + 1
                bossPhases.fansSinceSlam = bossPhases.fansSinceSlam + 1
            end
            if hazardReader.lastSlamAt and hazardReader.lastSlamAt ~= bossPhases.lastSlamAt then
                bossPhases.lastSlamAt = hazardReader.lastSlamAt
                bossPhases.slamSeen = bossPhases.slamSeen + 1
                bossPhases.fansSinceSlam = 0
            end
            if hazardReader.jumpUpAt and hazardReader.jumpUpAt ~= bossPhases.lastJumpAt then
                bossPhases.lastJumpAt = hazardReader.jumpUpAt
            end
            local V, E, p =
                hazardReader.fanUntil ~= nil and R < hazardReader.fanUntil + 1,
                R - bossPhases.lastFanAt,
                R - bossPhases.lastSlamAt
            if V then
                h(bossPhases.fansSinceSlam == 1 and bossPhases.slamSeen > 0 and "bigfan" or "fan", R)
            elseif p < 3 then
                h("slam", R)
            elseif bossPhases.fansSinceSlam >= 1 and E > 6 then
                h("vortex", R)
            elseif bossPhases.lastFanAt > -infinity and E > 4 then
                h("between", R)
            else
                h("open", R)
            end
            pcall(bossPhases.champHop, R, champEntry, q)
        end
        local function R()
            if hazardReader.hopDelays then
                return hazardReader.hopDelays
            end
            local hopDelays = {}
            pcall(function()
                if isfile and isfile("Aur_Hub/data/champ_hop.json") then
                    local q = game:GetService("HttpService")
                        :JSONDecode(readfile("Aur_Hub/data/champ_hop.json"))
                    if type(q) == "table" then
                        for index, entry in ipairs(q) do
                            if type(entry) == "number" then
                                hopDelays[#hopDelays + 1] = entry
                            end
                        end
                    end
                end
            end)
            hazardReader.hopDelays = hopDelays
            return hopDelays
        end
        local function hopDelay()
            local q = R()
            if #q == 0 then
                return config.champHopDelay
            end
            local V = {}
            for index, entry in ipairs(q) do
                V[index] = entry
            end
            table.sort(V)
            return V[math.ceil(#V / 2)]
        end
        bossPhases.hopDelay = hopDelay
        bossPhases.champHop = function(q, champMid, E)
            if config.champHopKeep == false or not (E and E.root and E.root.Parent) then
                return
            end
            champMid = E.root.Position
            if not hazardReader.champMid and bossPhases.slamSeen == 0 then
                hazardReader.champMid = champMid
            end
            E = hazardReader.hub or hazardReader.champMid
            if not E then
                return
            end
            local p, champHop = c(champMid.X, champMid.Z, E.X, E.Z), hazardReader.champHop
            if
                bossPhases.slamSeen > 0
                and bossPhases.lastSlamAt > -infinity
                and (not champHop or champHop.slamAt ~= bossPhases.lastSlamAt)
            then
                champHop = {
                    slamAt = bossPhases.lastSlamAt,
                    away = false,
                }
                hazardReader.champHop = champHop
            else
            end
            if not champHop then
                return
            end
            if p > (config.champHopAwayR or 20) then
                champHop.away = true
            end
            if champHop.away and not champHop.backAt and p < (config.champHopHomeR or 10) then
                champHop.backAt = q
                local U = q - champHop.slamAt
                if U > 0.3 and U < 30 then
                    local J = R()
                    J[#J + 1] = U
                    while true do
                        local R, champHopKeepN = #J, config.champHopKeepN
                        if not (R > (champHopKeepN or 12)) then
                            break
                        end
                        table.remove(J, 1)
                    end
                    pcall(function()
                        writefile("Aur_Hub/data/champ_hop.json", game:GetService("HttpService"):JSONEncode(J))
                    end)
                end
                if context.logT then
                    context.logT(
                        "champhop",
                        0,
                        "Boss",
                        ("Midgardian hopped back to the middle %.1fs after the slam (learned %.1fs)"):format(
                            U,
                            hopDelay() or U
                        )
                    )
                end
            end
            p = hopDelay()
            local R, untilAt =
                p and champHop.slamAt + p - (config.champHopLead or 1.5)
                    or champHop.slamAt + (config.champHopFirst or 1),
                champHop.backAt and champHop.backAt + (config.champHopFanHold or 4)
                    or champHop.slamAt + (config.champHopMax or 15)
            untilAt = if p
                    and not champHop.backAt
                    and q > champHop.slamAt + p + (config.champHopLate or 3)
                then math.min(untilAt, q + 1)
                else untilAt
            hazardReader.champHopDue = not champHop.backAt and p and champHop.slamAt + p or nil
            if q >= R and q < untilAt and context.addZone then
                local R = config.champHopKeepR or 60
                if not champHop.zone then
                    local zone = {
                        name = "hop back",
                        kind = "zone",
                        bubbleKeep = true,
                        round = true,
                        exact = true,
                        weight = 1,
                        madeAt = q,
                        cframe = CFrame.new(E.X, champMid.Y, E.Z),
                        size = Vector3.new(R * 2, 20, R * 2),
                        from = q,
                        untilAt = untilAt,
                    }
                    context.addZone(zone)
                    champHop.zone = zone
                    if context.logT then
                        context.logT(
                            "champhop",
                            1,
                            "Boss",
                            ("hop back %s - out of the middle (%.0f round it)"):format(
                                p and ("due in %.1fs"):format(champHop.slamAt + p - q) or "not timed yet",
                                R
                            )
                        )
                    end
                end
                champHop.zone.untilAt = untilAt
            elseif champHop.zone and q >= untilAt then
                champHop.zone.untilAt = math.min(champHop.zone.untilAt or q, q)
            end
        end
        local function R(y)
            local lastCircle = hazardReader.lastCircle
            if lastCircle and lastCircle.t ~= bossPhases.lastChainAt then
                bossPhases.lastChainAt = lastCircle.t
            end
            if hazardReader.lastSpikesAt and hazardReader.lastSpikesAt ~= bossPhases.lastSpikesAt then
                bossPhases.lastSpikesAt = hazardReader.lastSpikesAt
            end
            if hazardReader.lastFloorAt and hazardReader.lastFloorAt ~= bossPhases.lastFloorAt then
                bossPhases.lastFloorAt = hazardReader.lastFloorAt
            end
            local q, V, E = y - bossPhases.lastChainAt, y - bossPhases.lastSpikesAt, y - bossPhases.lastFloorAt
            if q < 1.2 then
                h("circles", y)
            elseif q < 4 and V > q then
                h("spikes-due", y)
            elseif V < 2.5 then
                h("spikes", y)
            elseif E < 3 then
                h("floor", y)
            else
                h("between", y)
            end
        end
        local function y(q, vector, orbBlastAt)
            if not hazardReader.odinEntry and orbBlastAt and orbBlastAt.root and orbBlastAt.root.Parent then
                local odinMiddle = context.Workspace
                local j = odinMiddle and (odinMiddle:FindFirstChild("thirdBossMiddlePart", true))
                if j then
                    odinMiddle = j.Position
                    local j = c(vector.X, vector.Z, odinMiddle.X, odinMiddle.Z)
                    if j > 1 and j < 140 then
                        local U, J = (vector.X - odinMiddle.X) / j, (vector.Z - odinMiddle.Z) / j
                        if config.odinFarSide ~= false then
                            U, J = -U, -J
                        else
                        end
                        local position, w, Y, v =
                            orbBlastAt.root.Position,
                            (context.abilityReach and context.abilityReach() or 81) - (config.odinRingIn or 4),
                            { 81.25, 68.75, 56.25, 43.75, 31.25 }
                        for index, entry in ipairs(Y) do
                            local Y, Z = odinMiddle.X + U * entry, odinMiddle.Z + J * entry
                            if c(Y, Z, position.X, position.Z) <= w then
                                v = Vector3.new(Y, vector.Y, Z)
                                break
                            end
                        end
                        hazardReader.odinEntry = v
                            or Vector3.new(odinMiddle.X + U * 43.75, vector.Y, odinMiddle.Z + J * 43.75)
                        hazardReader.odinMiddle = odinMiddle
                    end
                end
            end
            if hazardReader.lastLineShotAt and hazardReader.lastLineShotAt ~= bossPhases.lastLineAt then
                bossPhases.lastLineAt = hazardReader.lastLineShotAt
            end
            if hazardReader.lastMissileAt and hazardReader.lastMissileAt ~= bossPhases.lastMissileAt then
                bossPhases.lastMissileAt = hazardReader.lastMissileAt
            end
            orbBlastAt = hazardReader.orbBlastAt
            if hazardReader.charAt and q - hazardReader.charAt < (config.invulnAfterRespawn or 4) then
                h("invuln", q)
            elseif q - bossPhases.lastLineAt < 2 then
                h("lines", q)
            elseif orbBlastAt and q > orbBlastAt - 3 and q < orbBlastAt + 1 then
                h("orbs", q)
            elseif q - bossPhases.lastMissileAt < 3 then
                h("missiles", q)
            else
                h("odin", q)
            end
        end
        bossPhases.tick = function(phaseAt, q, V)
            local E = u(V)
            local boss = E and V.model.Name or nil
            if boss ~= bossPhases.boss then
                bossPhases.boss = boss
                bossPhases.phase = "idle"
                bossPhases.phaseAt = phaseAt
                bossPhases.fansSinceSlam = 0
                bossPhases.fanSeen = 0
                bossPhases.slamSeen = 0
                bossPhases.lastFanAt, bossPhases.lastSlamAt, bossPhases.lastJumpAt, bossPhases.lastChainAt, bossPhases.lastSpikesAt, bossPhases.lastFloorAt =
                    -infinity, -infinity, -infinity, -infinity, -infinity, -infinity
            end
            if not E then
                bossPhases.phase = "idle"
                return
            end
            if E.fan then
                m(phaseAt, q, V)
            elseif E.home then
                R(phaseAt)
            else
                y(phaseAt, q, V)
            end
        end
        bossPhases.expectSlam = function(h)
            if bossPhases.boss == nil then
                return false
            end
            if not context.bossProfile(bossPhases.boss).fan then
                return false
            end
            if hazardReader.fanUntil ~= nil and h < hazardReader.fanUntil + 1 then
                return false
            end
            if h - bossPhases.lastSlamAt < 10 then
                return false
            end
            if bossPhases.lastFanAt == -infinity then
                return true
            end
            if h - bossPhases.lastFanAt < 6 then
                return false
            end
            return bossPhases.fansSinceSlam >= 1
        end
        bossPhases.fanHold = function(P)
            if bossPhases.boss == nil or not context.bossProfile(bossPhases.boss).fan then
                return nil
            end
            local h, m, R =
                hazardReader.fanUntil ~= nil and P < hazardReader.fanUntil + 1,
                hazardReader.fanPeriod
                    and hazardReader.lastFanStart
                    and P - hazardReader.lastFanStart
                        >= hazardReader.fanPeriod - (config.fanEarly or 2),
                P - bossPhases.lastSlamAt
            P = bossPhases.slamSeen > 0
                and bossPhases.fansSinceSlam == 0
                and R >= (config.slamHoldFrom or 10)
                and R < 25
            if not (h or m or P) then
                return nil
            end
            return config.fanRadius or 90
        end
        bossPhases.anchorPoint = function(vector, h)
            local m = u(h)
            if not m then
                return nil
            end
            if m.fan then
                local R = context.champWaypointsNow and context.champWaypointsNow() or config.champWaypoints
                if not R or #R == 0 then
                    return hazardReader.flankTarget
                end
                if context.champTourTarget then
                    local flankTarget =
                        context.champTourTarget(vector, h and h.root and h.root.Parent and h.root.Position or nil)
                    if flankTarget then
                        hazardReader.flankTarget = flankTarget
                        return flankTarget
                    end
                end
                local h = hazardReader.flankTarget
                if h and c(vector.X, vector.Z, h.X, h.Z) < 40 then
                    return h
                end
                local y, flankTarget2
                for index = 1, #R, 1 do
                    h = R[index]
                    index = c(vector.X, vector.Z, h[1], h[3])
                    if not y or index < y then
                        y, flankTarget2 = index, Vector3.new(h[1], vector.Y, h[3])
                    else
                    end
                end
                hazardReader.flankTarget = flankTarget2
                return flankTarget2
            end
            if not m.home then
                return hazardReader.odinEntry
            end
            return nil
        end
        bossPhases.hold = function(P, h)
            local m = u(h)
            if not m then
                return nil, nil
            end
            if m.fan then
                if config.champWaypoints and #config.champWaypoints > 0 then
                    return nil, nil
                end
                return bossPhases.fanHold(P), hazardReader.hub
            end
            if
                not m.home
                and bossPhases.phase == "lines"
                and h.root
                and h.root.Parent
                and not (m.ringBand and config.odinFirstBeamOnly ~= false)
            then
                return config.odinLineHold or 85, h.root.Position
            end
            return nil, nil
        end
        bossPhases.anchor = function(P, position, m, R)
            P = u(m)
            if not P or not m.root or not m.root.Parent then
                return nil
            end
            position = m.root.Position
            if P.home then
                m = hazardReader.bobHome or context.bobCrystalCentroid()
                if not m then
                    return nil
                end
                local u, y = m.X - position.X, m.Z - position.Z
                local q = sqrt(u * u + y * y)
                if q < 1 then
                    return nil
                end
                return Vector3.new(position.X + u / q * R, position.Y, position.Z + y / q * R)
            end
            if P.fan and hazardReader.hub then
                local P, u = position.X - hazardReader.hub.X, position.Z - hazardReader.hub.Z
                m = sqrt(P * P + u * u)
                if m < 6 then
                    return nil
                end
                return Vector3.new(position.X + P / m * R, position.Y, position.Z + u / m * R)
            end
            return nil
        end
        context.bobLine = function()
            if config.bobSpikeLine == false then
                return nil
            end
            local P = context.BR and context.BR.target
            if
                not (
                    P
                    and P.isBoss
                    and P.root
                    and P.root.Parent
                    and P.model
                    and context.bossProfile(P.model.Name).home
                )
            then
                return nil
            end
            local vector = context.bobCrystal and context.bobCrystal("green")
            if not vector then
                return nil
            end
            local position = P.root.Position
            local m, R = vector.X - position.X, vector.Z - position.Z
            local y = sqrt(m * m + R * R)
            if y < 1 then
                return nil
            end
            local q = context.standoffFor and context.standoffFor(P) or 57
            local P, V, E = min(config.bobLineKeep or q * (config.bobSpikeBackShare or 0.75), y), m / y, R / y
            return {
                ax = vector.X,
                az = vector.Z,
                bx = position.X + V * P,
                bz = position.Z + E * P,
                ux = V,
                uz = E,
                len = y - P,
            }
        end
        context.bobLinePoint = function(D, P, u)
            u = u or context.bobLine()
            if not u then
                return nil
            end
            local h = (D - u.bx) * u.ux + (P - u.bz) * u.uz
            h = if h < 0 then 0 else if h > u.len then u.len else h
            local m, R = u.bx + u.ux * h, u.bz + u.uz * h
            return m, R, sqrt((D - m) ^ 2 + (P - R) ^ 2), h
        end
        bossPhases.lean = function(D, vector, u)
            local h, m, R, y = vector.X, vector.Z
            local q, V =
                bossPhases.boss and context.bossProfile(bossPhases.boss) or nil,
                context.BR and context.BR.target or nil
            local E = V and V.isBoss and V.root and V.root.Parent and V.root.Position or nil
            if q and q.home and E and hazardReader.bobHome then
                local p, j = hazardReader.bobHome.X - E.X, hazardReader.bobHome.Z - E.Z
                local U, J = sqrt(p * p + j * j), context.standoffFor and context.standoffFor(V) or 57
                if U > 1 then
                    R, y = Vector3.new(E.X + p / U * J, E.Y, E.Z + j / U * J), config.bobCentreBias or 30
                else
                end
                local w = c(h, m, E.X, E.Z)
                local Y = w <= (context.abilityReach and context.abilityReach() or 77) - 6
                if
                    (bossPhases.phase == "circles" or bossPhases.phase == "spikes-due")
                    and w < (config.bobCircleLeanRange or 110)
                    and not Y
                then
                    y = config.bobCircleLean or 40
                    R = E
                else
                end
                local v = u and u.box and u.box.name or nil
                local M, Z, n, f = v ~= nil
                    and (v == "spikes grow" or v == "ground spikes" or v == "spike field" or v:find(
                        "icespikes",
                        1,
                        true
                    ) ~= nil)
                    and w < 130
                if M and config.bobSpikeLine ~= false and context.bobLinePoint then
                    Z, n, f = context.bobLinePoint(h, m)
                else
                end
                if Z then
                    if f > (config.bobLineNear or 4) then
                        R, y = Vector3.new(Z, vector.Y, n), config.bobSpikeLineLean or 55
                    else
                        if not Y then
                            v = context.bobLine()
                            R, y = Vector3.new(v.bx, vector.Y, v.bz), config.bobSpikeLean or 50
                        else
                        end
                    end
                else
                    if M then
                        local v, M, Z = 0, 0, 0
                        if U > 1 then
                            v, M = -j / U, p / U
                            Z = (h - E.X) * v + (m - E.Z) * M
                        else
                        end
                        local p = config.bobSpikeBackAt or J * (config.bobSpikeBackShare or 0.75)
                        if U > 1 and abs(Z) > (config.bobSpikeSideAt or 34) then
                            R, y = Vector3.new(h - v * Z, vector.Y, m - M * Z), config.bobSpikeMidLean or 55
                        else
                            if w < p then
                                local p, j = h - E.X, m - E.Z
                                local U = sqrt(p * p + j * j)
                                if U > 1 then
                                    R, y =
                                        Vector3.new(
                                            h + p / U * (config.bobSpikeBackOut or 40),
                                            vector.Y,
                                            m + j / U * (config.bobSpikeBackOut or 40)
                                        ),
                                        config.bobSpikeBackLean or 55
                                else
                                end
                            else
                                if not Y then
                                    y = config.bobSpikeLean or 50
                                    R = E
                                else
                                end
                            end
                        end
                    else
                    end
                end
            else
            end
            if
                q
                and not q.fan
                and not q.home
                and E
                and hazardReader.odinEntry
                and bossPhases.phase ~= "lines"
            then
                R, y = hazardReader.odinEntry, config.odinEntryLean or 30
            else
            end
            V = hazardReader.missileAxis
            if q and not q.fan and not q.home and V and D - V.t < 3 and bossPhases.phase ~= "lines" then
                local p, j = -V.dz, V.dx
                local U = (h - V.ox) * p + (m - V.oz) * j
                if abs(U) > 4 then
                    R, y = Vector3.new(h - p * U, vector.Y, m - j * U), config.odinAxisLean or 40
                else
                end
            else
            end
            if q and not q.fan and not q.home and E and bossPhases.phase == "lines" then
                local _, p = h - E.X, m - E.Z
                V = sqrt(_ * _ + p * p)
                if V < (config.odinLineHold or 85) + 10 then
                    if V < 1 then
                        _, p, V = 1, 0, 1
                    else
                    end
                    R, y = Vector3.new(h + _ / V * 60, vector.Y, m + p / V * 60), config.odinLineLean or 40
                else
                end
            else
            end
            if q and q.fan and hazardReader.hub then
                if hazardReader.fanUntil ~= nil and D < hazardReader.fanUntil + 1 then
                    E, V = h - hazardReader.hub.X, m - hazardReader.hub.Z
                    local _ = sqrt(E * E + V * V)
                    if _ < 1 then
                        E, V, _ = 1, 0, 1
                    else
                    end
                    local p, j, U = E / _, V / _, hazardReader.fanSweep or 0
                    if U ~= 0 then
                        local _ = U * math.rad(config.fanBehindDeg or 30)
                        local U, J = math.cos(_), math.sin(_)
                        p, j = p * U - j * J, p * J + j * U
                    else
                    end
                    R, y = Vector3.new(h + p * 60, vector.Y, m + j * 60), config.fanLean or 40
                else
                end
                if R == nil and context.quietDir then
                    local _, p = context.quietDir(D, h, m)
                    if _ then
                        local j, U = h - hazardReader.hub.X, m - hazardReader.hub.Z
                        local J = math.clamp(
                            sqrt(j * j + U * U),
                            (config.hubKeepOut or 60) + 5,
                            (config.fanRadius or 108) - 10
                        )
                        if context.champMid then
                            j, U = context.champMid()
                            J = if j then max(J, U + (config.champMidRing or 2)) else J
                        else
                        end
                        R, y =
                            Vector3.new(hazardReader.hub.X + _ * J, vector.Y, hazardReader.hub.Z + p * J),
                            config.quietLean or 30
                    else
                    end
                else
                end
            else
            end
            if
                q
                and q.fan
                and R == nil
                and config.champWaypoints
                and hazardReader.flankTarget
                and c(h, m, hazardReader.flankTarget.X, hazardReader.flankTarget.Z)
                    > (config.waypointHold or 14)
            then
                R, y = hazardReader.flankTarget, config.waypointLean or 25
            else
                if
                    q
                    and q.fan
                    and R == nil
                    and config.champEntryBox
                    and context.inEntryBox
                    and context.inEntryBox(h, m, 15)
                    and hazardReader.flankTarget
                then
                    R, y = hazardReader.flankTarget, config.entranceLean or 20
                else
                    if q and q.fan and hazardReader.champEntry and R == nil and not config.champEntryBox then
                        D, V = h - hazardReader.champEntry.X, m - hazardReader.champEntry.Z
                        E = sqrt(D * D + V * V)
                        if E < (config.entranceKeepOut or 45) + 25 then
                            if E < 1 then
                                D, V, E = 1, 0, 1
                            else
                            end
                            R, y =
                                Vector3.new(h + D / E * 60, vector.Y, m + V / E * 60), config.entranceLean or 20
                        else
                        end
                    else
                    end
                end
            end
            if q and q.fan and hazardReader.hub and u and u.box and u.box.name == "firstbossjumpslam" then
                V, E = h - hazardReader.hub.X, m - hazardReader.hub.Z
                D = sqrt(V * V + E * E)
                if D < 1 then
                    V, E, D = 1, 0, 1
                else
                end
                R, y = Vector3.new(h + V / D * 60, vector.Y, m + E / D * 60), config.slamAwayLean or 35
            else
            end
            E = context.BB and context.BB.pend or nil
            if E then
                for index = 1, #E, 1 do
                    D = E[index]
                    if D and (D.name == "slam incoming" or D.name == "slam soon") and D.ox and D.r then
                        V, index = h - D.ox, m - D.oz
                        local p = sqrt(V * V + index * index)
                        if p < D.r + 8 then
                            if hazardReader.hub then
                                V, index = h - hazardReader.hub.X, m - hazardReader.hub.Z
                                p = sqrt(V * V + index * index)
                            else
                            end
                            if p < 1 then
                                V, index, p = 1, 0, 1
                            else
                            end
                            R, y =
                                Vector3.new(h + V / p * 60, vector.Y, m + index / p * 60), config.slamLean or 30
                            break
                        end
                    end
                end
            else
            end
            if q and q.fan and R == nil and context.champMid then
                D, V = context.champMid()
                if D then
                    local _, p = h - D.X, m - D.Z
                    E = sqrt(_ * _ + p * p)
                    if E < V then
                        if E < 1 then
                            _, p, E = 1, 0, 1
                        else
                        end
                        local O = V + (config.champMidRing or 2)
                        R, y = Vector3.new(D.X + _ / E * O, vector.Y, D.Z + p / E * O), config.champMidLean or 40
                    else
                    end
                else
                end
            else
            end
            V = hazardReader.leash
            if q and q.fan and V and V.enemy and V.enemy.root and V.enemy.root.Parent then
                E = context.arenaCentre and context.arenaCentre() or V.enemy.root.Position
                local L, O, _, q, p =
                    c(h, m, E.X, E.Z),
                    (V.radius or config.leashRadius or 122) - (config.arenaEdge or 32),
                    u
                        and u.box
                        and (
                            u.box.name == "firstbossjumpslam"
                            or u.box.name == "slam incoming"
                            or u.box.name == "slam soon"
                        )
                if context.champMid then
                    q, p = context.champMid()
                else
                end
                D = O - 12
                if L > (if q then max(D, p + (config.champMidBand or 10)) else D) and not _ then
                    O = Vector3.new(E.X, vector.Y, E.Z)
                    if q and L > 1 then
                        local d = p + (config.champMidRing or 2)
                        R = Vector3.new(E.X + (h - E.X) / L * d, vector.Y, E.Z + (m - E.Z) / L * d)
                    else
                        R = O
                    end
                    y = max(y or 0, config.rimLean or 12)
                else
                end
            else
            end
            return R, y
        end
        bossPhases.state = function()
            return bossPhases.boss
                    and ("%s:%s f%d s%d"):format(
                        bossPhases.boss,
                        bossPhases.phase,
                        bossPhases.fansSinceSlam,
                        bossPhases.slamSeen
                    )
                or "-"
        end
    end

    components.bubbleBoss = function(context)
        local config = context.CFG
        local runtimeState = context.RT
        local hazardReader = context.RD
        local dangerGeometry = context.DG
        local contextDepthOf = context.depthOf
        local parent = game:GetService("Workspace")
        local players = game:GetService("Players")
        local abs = math.abs
        local sqrt = math.sqrt
        local max = math.max
        local min = math.min
        local infinity = math.huge
        local cos = math.cos
        local sin = math.sin
        local toRadians = math.rad
        local toDegrees = math.deg
        local atan2 = math.atan2
        local bubbleBoss = {
            active = false,
            lethal = false,
            threats = {},
            rel = {},
            soft = {},
            pend = {},
            mov = {},
            primary = nil,
            lastBreach = -infinity,
            dir = nil,
            dirAt = -infinity,
            count = 0,
            warmCount = 0,
            warnCount = 0,
            escapes = 0,
            folder = nil,
            pickedSafe = false,
            pickedDist = 0,
        }
        context.BB = bubbleBoss
        local function j(U, J, w, Y)
            local v = U.offset + U.speed * max(Y - U.pathStart, 0)
            v = if U.bounces and U.freeAhead
                then min(if U.endAlong and v > U.endAlong then U.endAlong else v, U.freeAhead)
                else if U.endAlong and v > U.endAlong then U.endAlong else v
            local M, Z = J - (U.ox + U.dx * v), w - (U.oz + U.dz * v)
            if U.r and (U.bbRound or config.roundMoving ~= false) then
                return U.r - sqrt(M * M + Z * Z)
            end
            Y, J = abs(M * U.dx + Z * U.dz) - U.halfL, abs(-M * U.dz + Z * U.dx) - U.halfW
            if Y <= 0 and J <= 0 then
                return -max(Y, J)
            end
            return -sqrt(max(Y, 0) ^ 2 + max(J, 0) ^ 2)
        end
        local U = 0
        local function J(w, Y, v)
            local M = Y > U + 0.05 and not w.noGrace and (config.expiryGrace or 0.6)
            local Z = M or 0
            local live = (w.from or 0) <= Y + ((if w.noLead then 0 else v) or 0) and (w.untilAt or infinity) + Z >= Y
            if live and w.name == "firstbosslongline" and w.from and hazardReader.gildedOn and config.gildedLinePulse == true then -- D-073: off
                -- D-072 (boss 1): after its strike a long line hurts only in pulses 0.605 s apart (0.50, 1.11, 1.71 ...)
                local age = Y - (w.from - (config.gildedLineFirst or 0.38))
                if age > (config.gildedLineSolid or 1.45) then
                    local period = config.gildedLinePeriod or 0.605
                    local ph = (age - (config.gildedLinePulse0 or 0.505)) % period
                    local half = config.gildedLinePulseHalf or 0.15
                    live = ph <= half or ph >= period - half - math.min(v or 0, 0.1)
                end
            end
            return live
        end
        context.gildedLiveAt = J -- D-072: for the tests
        bubbleBoss.vlineLead = function(box, lead)
            -- D-132 (boss 2): a vertical line decides at ~0.85 s, but it counted as on us only 0.35 s before that, so a line
            -- that showed on us was left at ~0.5 s (X17 / X19 / W14). Where we stand now, the next one to strike near us
            -- counts from when it shows; a later one waits for the strike before it (vlineNext). Ways keep the window.
            if box and box.name == "secondbossverticalline" and not box.moving and hazardReader.gildedOn
                and config.gildedVLineEarly ~= false
                and (not bubbleBoss.vlineNext or (box.from or 0) <= bubbleBoss.vlineNext + (config.gildedVLineSet or 0.3)) then
                return math.max(lead or 0, config.gildedVLineEarlyLead or 0.9)
            end
            return lead
        end
        local setMetatable, weakKeys = setmetatable, {
            __mode = "k",
        }
        local v = setMetatable({}, weakKeys)
        local function velocityOf(Y, M)
            if Y.moving then
                return Y.dx * Y.speed, Y.dz * Y.speed
            end
            local Z, n = Y.cx, Y.cz
            if not (Z and n) then
                return 0, 0
            end
            local f = v[Y]
            if not f then
                v[Y] = {
                    x = Z,
                    z = n,
                    t = M,
                    vx = 0,
                    vz = 0,
                }
                return 0, 0
            end
            Y = M - f.t
            if Y > 0.011111111111111112 then
                local v, r = (Z - f.x) / Y, (n - f.z) / Y
                if v * v + r * r > 160000 then
                    v, r = 0, 0
                else
                end
                f.vx, f.vz = f.vx * 0.5 + v * 0.5, f.vz * 0.5 + r * 0.5
                f.x = Z
                f.z = n
                f.t = M
            end
            return f.vx, f.vz
        end
        bubbleBoss.velocityOf = velocityOf
        local function Y(v, M, Z, n, f, r, o)
            if not J(v, f, o) then
                return nil
            end
            if v.moving then
                if not (v.ground or abs(Z - v.oy) <= (v.halfH or 6) + r) then
                    return nil
                end
                return j(v, M, n, f)
            end
            o = f - U
            f = o > 0.001
            if f then
                local j, f = velocityOf(v, U)
                if j * j + f * f > 4 then
                    M, n = M - j * o, n - f * o
                else
                end
            else
            end
            o = contextDepthOf(v, M, Z, n, r)
            if o == -infinity then
                return nil
            end
            return o
        end
