        bubbleBoss.mageSideStep = function(V, vector, J, w, v, M)
            local Z, n, f, r, o, side = bubbleBoss.mageStrafeDir(vector, J, V)
            if not Z then
                return nil
            end
            local A = vector.X
            local k = vector.Z
            local x, a, e, N =
                vector + Vector3.new(0, 2, 0),
                config.mageStrafeStep or 14,
                { 0, 20, -20, 40, -40 },
                runtimeState.mageExit
            if config.mageExitLean ~= false and N and N.q and J - (N.at or -infinity) < 0.3 then
                local I, F, i = N.q.X - A, N.q.Z - k, {}
