                    local G, z = Z * cos(index) + f * sin(index), n * cos(index) + r * sin(index)
                    index = sqrt(G * G + z * z)
                    i[entry] = index > 0 and (G * I + z * F) / index or -infinity
                end
                table.sort(e, function(I, F)
                    return i[I] > i[F]
                end)
