            local v = math.max((humanoid and humanoid.WalkSpeed or 16) * speedMul(), 16)
            dist = math.max(tonumber(dist) or 0, 0)
            local pressed, now = runtimeState.buffPressedAt, os.clock()
            if config.gildedFireLapseModel == false or not pressed or now - pressed > (config.gildedLapseRecent or 9) then
                return dist / v
            end
            local fast = math.max(config.gildedBuffSpeed or 29.25, v)
            local slow = math.min(v, config.gildedWalkSpeedSeen or 19.5)
            local s0 = now -- unbuffed: the lapse is now
            if v >= fast - 0.5 then
                s0 = math.max(now, pressed + (config.gildedBuffEnds or 5.5))
            end
            local s1 = s0 + (config.gildedFireLapse or 1.5)
            local t, left = 0, dist
            for _, leg in ipairs({ { s0 - now, v }, { s1 - s0, slow } }) do
                if leg[1] > 0 then
                    if left <= leg[2] * leg[1] then
