        context.mageArcSteer = function(vector, i, b)
            if not context.mageArcBad or (config.mageArcHard or 200) <= 0 then
                return nil
            end
            local magnitude = i.Magnitude
            if magnitude < 0.5 then
                return nil
            end
            local G, z, s = min(magnitude, config.mageArcLook or 10), i.X / magnitude, i.Z / magnitude
            if not context.mageArcBad(vector.X + z * G, vector.Z + s * G, vector.X, vector.Z) then
                return nil
            end
            local T, W =
                vector + Vector3.new(0, 1.5, 0), {
                    15,
                    -15,
                    30,
                    -30,
                    45,
                    -45,
                    60,
                    -60,
                    75,
                    -75,
                    90,
                    -90,
                    110,
                    -110,
                    135,
                    -135,
                    160,
                    -160,
                    180,
                }
            for index, entry in ipairs(W) do
                i = toRadians(entry)
                local W, H = cos(i), sin(i)
                local i, X = z * W - s * H, z * H + s * W
                index, W = vector.X + i * G, vector.Z + X * G
                if
                    not context.mageArcBad(index, W, vector.X, vector.Z)
                    and not contextWorkspace:Raycast(T, Vector3.new(i, 0, X) * (G + 2), contextRaycastParams())
                    and not (
                        context.BB
