                end
            end
            return nil
        end
        context.gildedStairsMid = function(sp, B)
            -- D-100 (room 9 stairs): walking moves keep to the centre line - the edges stalled us (12-22 off)
            local ox, oz = config.gildedStairsX or 1103, config.gildedStairsZ or -604
            local ux, uz = config.gildedStairsUX or 0.71, config.gildedStairsUZ or -0.71
            local function along(px, pz)
                return (px - ox) * ux + (pz - oz) * uz, (px - ox) * -uz + (pz - oz) * ux
            end
            local s0, l0 = along(sp.X, sp.Z)
            local s1, l1 = along(B.X, B.Z)
            local lo, hi = config.gildedStairsFrom or -77, config.gildedStairsTo or 89
            local half = config.gildedStairsHalf or 6
            local out, beside = B, false
            if s0 >= lo - 6 and s0 <= hi + 6 and math.abs(l0) < 40 and sp.Y > 50 and sp.Y < 104 then
                if math.abs(s1 - s0) > 10 then
                    local dir = s1 > s0 and 1 or -1
                    local s2 = math.clamp(s0 + dir * 14, lo - 4, hi + 4)
                    local l2 = math.clamp(l0, -half, half)
                    out = Vector3.new(ox + ux * s2 - uz * l2, B.Y, oz + uz * s2 + ux * l2)
