                runtimeState.stairsMidAt = os.clock()
                return B
            end
            if config.gildedStairsNoStill ~= false and out ~= B
                and (out.X - sp.X) ^ 2 + (out.Z - sp.Z) ^ 2 < near * near
                and (B.X - sp.X) ^ 2 + (B.Z - sp.Z) ^ 2 > near * near then
                runtimeState.stairsMidWhy = ("the stairs' line would stop us (%.0f along, %.0f off) - the move as it was"):format(s0, l0)
                runtimeState.stairsMidAt = os.clock() -- (AurRecorder 1.8.8 logs it in its "why" row)
                runtimeState.stairsMidKeep = beside and { x = B.X, z = B.Z, at = os.clock() } or nil
                return B
            end
            return out
        end
