        context.orbRoundPoint = function(vector, best, B, z, SF)
            if not (vector and best and B) then
                return nil
            end
            local yF, EF = B.x, B.z
            local JF, wF = vector.X - yF, vector.Z - EF
            local YF = math.sqrt(JF * JF + wF * wF)
            if YF < 0.5 then
                return nil
            end
            local phase, bestAt = best.X - yF, best.Z - EF
            yF = math.sqrt(phase * phase + bestAt * bestAt)
