        context.gildedPredict = function(posSeen, pts, speed, now) -- D-062: how many due mob attacks this path stays in
            local clock = hazardReader.mobClock
            if not (clock and hazardReader.gildedOn) or config.gildedPredict == false then
                return 0
            end
            speed = math.max(speed or 16, 8)
            local function at(t)
                local want = t * speed
                local px, pz, pd = posSeen.X, posSeen.Z, 0
                for _, pt in ipairs(pts) do
                    if pt.d >= want then
                        local f = (want - pd) / math.max(pt.d - pd, 0.01)
                        return px + (pt.x - px) * f, pz + (pt.z - pz) * f
                    end
                    px, pz, pd = pt.x, pt.z, pt.d
                end
                return px, pz
            end
            local horizon = config.gildedPredictAhead or 1.0
            local fails = 0
            for hum, c in pairs(clock) do
                local root = c.root
                local K = PREDICT[c.kind]
                if hum.Parent and hum.Health > 0 and root and root.Parent and K then
                    local mp = root.Position
                    if (mp.X - posSeen.X) ^ 2 + (mp.Z - posSeen.Z) ^ 2 <= K.range * K.range then
                        local due = c.last + K.cd
                        if K.pair and (not c.prev or c.last - c.prev > 1.0) and now - c.last < K.pair + 0.4 then
                            due = c.last + K.pair -- the Mage's second shot
                        end
                        local lead = due - now
                        if lead <= horizon and now - due < K.cd * 0.6 then
                            lead = math.max(lead, 0)
                            local bad = false
                            if K.melee then
                                for _, pt in ipairs(pts) do
                                    if pt.d / speed >= lead and (pt.x - mp.X) ^ 2 + (pt.z - mp.Z) ^ 2 < K.melee * K.melee then
