                    -- reach (~9 from the centre); a move toward its centre line goes along its side instead
                    local v0 = zF.AssemblyLinearVelocity
                    for _, L in ipairs(lanes) do
                        if now < L.untilAt and (L.kind ~= "mage" and now - L.at < (config.gildedFamiliarSideFor or 2.3)
                            or L.kind == "mage" and strikeGuard and now - L.at < strikeTo) then -- D-150: a striking Mage lane too (solo)
                            local w, a = rel(L, posSeen.X, posSeen.Z)
                            local reach = L.hw + (L.kind == "mage" and (config.gildedLaneMagePad or 3) or (config.gildedLaneFamPad or 4))
                            local closing = -v0.X * L.lz + v0.Z * L.lx -- velocity across the lane
                            local close = config.gildedFamiliarSideClose or 4
                            if math.abs(w) <= reach + (config.gildedFamiliarSideBand or 3) and math.abs(a) <= L.half + 2
                                and (w > 0 and closing < -close or w < 0 and closing > close) then
                                local sa = (v0.X * L.lx + v0.Z * L.lz) >= 0 and 1 or -1
                                local keepW = (w >= 0 and 1 or -1) * math.max(math.abs(w), reach + 1)
