                                local goal = Vector3.new(gx, posSeen.Y, gz)
                                local clear = true
                                if context.BB and context.BB.wayClear then
                                    local okC, r = pcall(context.BB.wayClear, posSeen, goal, math.max(humanoid.WalkSpeed, 16), y)
                                    clear = not okC or r ~= false
                                end
                                if clear and not inAny(gx, gz, 1.5) then
                                    if context.BB then
                                        context.BB.goal = nil
                                    end
                                    g(humanoid, zF, goal, e(), 1)
                                    contextSetState(L.kind == "mage" and "LANES: along the Mage lane's side until its strike is over (D-150)"
                                        or "LANES: along the Familiar lane's side until its strike is over")
                                    p(humanoid, zF, target, y)
                                    return true
                                end
                            end
