            local speed = math.max(humanoid.WalkSpeed * (context.speedMul and context.speedMul() or 1), 16)
            local margin = config.gildedFamiliarMargin or 4
            local step = runtimeState.famStep
            local cands = {}
            local now2 = os.clock()
            -- D-071: a way that did not move us a stud in 0.3 s is blocked (a mob's body): another way, for 1 s
            -- D-097: blocked = under 1.5 studs of progress in any 0.3 s window while the goal is still 3+ off (wall pins too)
            if step and step.dx and step.x then
                step.px, step.pz, step.pt = step.px or step.x, step.pz or step.z, step.pt or step.at or now2
                if now2 - step.pt > (config.gildedStuckAfter or 0.3) then
                    local moved2 = (posSeen.X - step.px) ^ 2 + (posSeen.Z - step.pz) ^ 2
                    local far = not step.goal or (posSeen.X - step.goal.X) ^ 2 + (posSeen.Z - step.goal.Z) ^ 2 > 9
                    if far and moved2 < (config.gildedStuckMin or 1.5) ^ 2 then
                        runtimeState.famBlocked = { dx = step.dx, dz = step.dz, untilAt = now2 + (config.gildedStuckFor or 1) }
                        runtimeState.famStep = nil -- the D-096 keep must not re-issue it
