                local dx, dz = math.cos(ang), math.sin(ang)
                local exitAt
                for d = 1, 30 do
                    if not inAny(posSeen.X + dx * d, posSeen.Z + dz * d, 1.5) then
                        exitAt = d
                        break
                    end
                end
                if exitAt then
                    local okW = true -- out of every lane for the margin after the edge too
                    for d = exitAt + 1, exitAt + margin do
