                            okW = false
                            break
                        end
                    end
                    if okW and blocked and dx * blocked.dx + dz * blocked.dz > (config.gildedStuckCos or 0.7) then
                        okW = false -- D-071: that way did not move us
                    end
                    if okW and bodyIn(dx, dz, exitAt + margin) then
                        okW = false -- D-071: a mob's body is on it
                    end
                    if okW and strikeGuard and crossesStrike(dx, dz, exitAt + margin, speed) then
                        okW = false -- D-150: across a Mage lane we are out of while it strikes
                    end
                    if okW then
                        local cost = exitAt
                        if vu then
                            cost = cost + (config.gildedFamiliarTurnCost or 3) * (1 - (dx * vu.X + dz * vu.Z)) / 2 -- keep going the way we go
                        end
                        if step and step.dx and dx * step.dx + dz * step.dz > 0.95 then
                            cost = cost - 2 -- no switching between near-equal ways
                        end
                        cands[#cands + 1] = { cost = cost, dx = dx, dz = dz, exitAt = exitAt }
                    end
                end
            end
            table.sort(cands, function(c1, c2)
                return c1.cost < c2.cost
            end)
