            -- may be crossed: a Knight's circle round us is left on the same way, further on)
            local best, bestCost, bestDir, bestOut
            local wallCache = {}
            local function wallFree(c) -- D-097: the lane step's ways stop short of walls (it had no wall check)
                if config.gildedLaneWalls == false then
                    return math.huge
                end
                if wallCache[c] == nil then
                    local free = math.huge
                    local okR, hit = pcall(function()
                        return contextWorkspace:Raycast(posSeen + Vector3.new(0, 2, 0), Vector3.new(c.dx, 0, c.dz) * 34, contextRaycastParams())
                    end)
                    if okR and hit and hit.Instance and hit.Instance.CanCollide then
                        free = hit.Distance - (config.gildedLaneWallClear or 3)
                    end
                    wallCache[c] = free
                end
                return wallCache[c]
