                    end
                    local goal = Vector3.new(gx, posSeen.Y, gz)
                    local okF, floor = pcall(contextFloorY, gx, posSeen.Y, gz, contextRaycastParams())
                    if not (okF and floor ~= nil and math.abs(floor - posSeen.Y) <= (config.maxStepHeight or 4) + 3) then
                        break
                    end
                    local clear = true
                    if context.BB and context.BB.wayClear then
                        local okC, r = pcall(context.BB.wayClear, posSeen, goal, speed, y)
                        clear = not okC or r ~= false
                    end
                    if clear then
                        local cost = c.cost + (d - c.exitAt - margin)
                        if not bestCost or cost < bestCost then
                            best, bestCost, bestDir, bestOut = goal, cost, { dx = c.dx, dz = c.dz }, c.exitAt
                        end
                        break
