                    d = d + 3
                end
            end
            if not best and context.BB and context.BB.ringClear then
                -- D-071: no way's end clear for its whole hold - the shortest way out of every lane whose end is clear
                -- when we get there (rather than giving up to an escape that may run along a lane)
                for i = 1, math.min(#cands, config.gildedFamiliarTry or 8) do
                    local c = cands[i]
                    local d = c.exitAt + margin
                    local gx, gz = posSeen.X + c.dx * d, posSeen.Z + c.dz * d
                    local okF, floor = pcall(contextFloorY, gx, posSeen.Y, gz, contextRaycastParams())
                    if d <= wallFree(c) and okF and floor ~= nil and math.abs(floor - posSeen.Y) <= (config.maxStepHeight or 4) + 3 then
                        local okC, clear = pcall(context.BB.ringClear, posSeen, { { x = gx, z = gz, d = d } }, speed, y)
                        if okC and clear then
                            best, bestDir, bestOut = Vector3.new(gx, posSeen.Y, gz), { dx = c.dx, dz = c.dz }, c.exitAt
                            break
                        end
                    end
                end
            end
            if not best then
                -- D-096: no way clear of everything this tick - keep the way chosen just before (no back and forth)
                local st = runtimeState.famStep
                if config.gildedLaneKeep ~= false and st and st.goal and now - (st.chosen or -math.huge) < (config.gildedLaneKeepFor or 0.5)
                    and not inAny(st.goal.X, st.goal.Z, 1.5) then
                    context.BB.goal = nil
                    g(humanoid, zF, st.goal, e(), 1)
                    contextSetState("LANES: keeping the way out (no other way clear)")
                    p(humanoid, zF, target, y)
                    return true
                end
                return false
            end
            if step and step.dx and step.x and bestDir.dx * step.dx + bestDir.dz * step.dz > 0.95 then
                bestDir.x, bestDir.z, bestDir.at = step.x, step.z, step.at -- the same way: its start stays
                bestDir.px, bestDir.pz, bestDir.pt = step.px, step.pz, step.pt -- D-097
            else
                bestDir.x, bestDir.z, bestDir.at = posSeen.X, posSeen.Z, now2
            end
            bestDir.goal, bestDir.chosen = best, now2 -- D-090
            runtimeState.famStep = bestDir
            context.BB.goal = nil
            g(humanoid, zF, best, e(), 1)
            contextSetState(("LANES: shortest way out of the Familiar / Mage lanes on us, %d studs"):format(bestOut))
            p(humanoid, zF, target, y)
            return true
        end
        context.b1NoReset = function() -- D-176 (user): no automatic reset of any kind while Kiryne is alive
            return config.gildedB1NoReset ~= false and context.kiryneUp ~= nil and context.kiryneUp() == true
        end
        context.kiryneUp = function() -- D-105: boss 1 alive (cached 0.5 s)
            local c = runtimeState.kiryneUpC
            if c and os.clock() - c.at < 0.5 then
                return c.up
            end
            local up = false
            for _, enemy in ipairs(hazardReader.enemies or {}) do
                if enemy.isBoss and enemy.model and enemy.model.Name == "Archpriestess Kiryne" and enemy.humanoid and enemy.humanoid.Health > 0 then
                    up = true
                    break
                end
            end
            runtimeState.kiryneUpC = { at = os.clock(), up = up }
            return up
        end
        context.spawnLeft = function()
            -- D-110 (boss 3, user): the respawn protection left (nil: none) from the ForceField on us - 6.0 s (5 of 5
            -- windows without our attack), and our attack ends it 1.3 s after the key (8 of 9 windows: 1.3-2.1 s)
            if not hazardReader.gildedOn then
                return nil
            end
            local character = localPlayer.Character
            local ff = character and character:FindFirstChildOfClass("ForceField")
            if not ff then
                runtimeState.ffSeen = nil
                return nil
            end
            local seen = runtimeState.ffSeen
            if not (seen and seen.ff == ff) then
                seen = { ff = ff, at = os.clock() }
                runtimeState.ffSeen = seen
            end
            local left = (config.gildedSpawnSafeFor or 6.0) - (os.clock() - seen.at)
            local lastE = tonumber(runtimeState.lastE)
            if lastE and lastE >= seen.at then
                left = math.min(left, lastE + (config.gildedSpawnAttackEnd or 1.3) - os.clock())
            end
            return math.max(left, 0)
        end
        context.lookAwayLive = function(lead)
            -- D-160 (boss 1, user): the Blinding Blast look-away window (lead s early), or nil - also nil while the respawn
            -- protection lasts until the blast lands: a blast announced while we were dead (D-158's reset) no longer turns
            -- a protected respawn away
            local a = runtimeState.faceAway
            local now = os.clock()
            if not a or now < (a.from or math.huge) - (lead or 0) or now > (a.untilAt or 0) then
                return nil
            end
            if config.gildedSpawnLook ~= false and context.spawnSafe then
                local land = (a.untilAt or now) - (config.lookAwayHold or 1.4) + (config.gildedSpawnLookLand or 1.1)
                if context.spawnSafe(math.max(land - now, 0)) then
                    return nil
                end
            end
            return a
        end
        context.blastProtHold = function()
            -- D-160: protected through a pending Blinding Blast, and an attack now would end the protection (1.3 s after the
            -- key, D-110) before it lands: the attack waits for the landing - everyone faces Kiryne through it
            if not hazardReader.gildedOn or config.gildedBlastProtHold == false then
                return false
            end
            local bp = runtimeState.blastPending
            local now = os.clock()
            if not bp or now > bp.land or bp.land - bp.at > (config.gildedBlastProtMax or 6) then
                return false
            end
            local left = context.spawnLeft and context.spawnLeft()
            if not left or left <= bp.land - now then
                return false -- not protected until it lands: casting changes nothing
            end
            return now + (config.gildedSpawnAttackEnd or 1.3) < bp.land
        end
        context.spawnSafe = function(margin) -- D-089 (Gilded Skies): the respawn ForceField takes no damage (D-110: spawnLeft)
            if not (hazardReader.gildedOn and config.gildedSpawnSafe ~= false) then
                return false
            end
            local left = context.spawnLeft()
            return left ~= nil and left > (margin or config.gildedSpawnSafeMargin or 1.5)
        end
        context.gildedRedLineStep = function(humanoid, zF, posSeen, y, target) -- D-073 (boss 1): the red lines the dungeon-run7 way
            if not (hazardReader.gildedOn and config.gildedRedLineStep ~= false and target and target.isBoss
                and target.model and target.model.Name == "Archpriestess Kiryne") then
                return false
            end
            local now = os.clock()
            -- each line's own clock: the moment it appeared (its strike ~1.1 s later)
            local seen = hazardReader.redLineSeen or setmetatable({}, { __mode = "k" })
            hazardReader.redLineSeen = seen
            local function lineClock()
                for _, ch in ipairs(contextWorkspace:GetChildren()) do
                    if ch.Name == "firstBossLongLine" and not seen[ch] then
                        seen[ch] = now
                    end
                end
            end
            -- D-140 (Y21 acct4): started before the returns below - a set born during another attack's dodge was
            -- dated ~0.45 s late, and D-121 waited for its strike inside the next set's line, which struck at the wait's end
            if config.gildedRedClock ~= false then
                lineClock()
            end
            if context.spawnSafe and context.spawnSafe() then
                runtimeState.redLine = nil
                return false -- D-089: protected - on to the boss
            end
            local field = hazardReader.safeField
            if field and now <= (field.untilAt or 0) and now >= (field.from or 0) - (field.lead or 0) then
                return false -- a refuge (the green circles) comes first
            end
            local BBp = context.BB and context.BB.primary
            if context.BB and context.BB.lethal and BBp and BBp.box and tostring(BBp.box.name) ~= "firstbosslongline" then
                return false -- inside another attack: its own dodge first
            end
            if config.gildedRedClock == false then
                lineClock()
            end
            local strikeAt, over = config.gildedRedStrike or 1.1, config.gildedRedOver or 0.2
            local cons, newest = {}, nil
            for model, at in pairs(seen) do
                local age = now - at
                if not model.Parent or age > 7 then
                    seen[model] = nil
                elseif age <= strikeAt + over then
                    local hb = model:FindFirstChild("hitBox")
                    if hb and hb:IsA("BasePart") then
                        local cf, size = hb.CFrame, hb.Size
                        local v, half
                        if size.X <= size.Z then
                            v, half = cf.RightVector, size.Z / 2
                        else
                            v, half = cf.LookVector, size.X / 2
                        end
                        local nl = math.sqrt(v.X * v.X + v.Z * v.Z)
                        if nl > 0.1 then
                            local nx, nz, p = v.X / nl, v.Z / nl, hb.Position
                            if math.abs((posSeen.X - p.X) * -nz + (posSeen.Z - p.Z) * nx) <= half + 4 then
                                local L = { nx = nx, nz = nz, px = p.X, pz = p.Z, strike = at + strikeAt, at = at }
                                cons[#cons + 1] = L
                                if not newest or at > newest.at then
                                    newest = L
                                end
                            end
                        end
                    end
                end
            end
            if not newest then
                runtimeState.redLine = nil
                return false
            end
            -- the axis across the lines, facing the boss's side (kept until the boss is well behind)
            local prev = runtimeState.redLine
            local ax, az = newest.nx, newest.nz
            if prev and prev.ax and ax * prev.ax + az * prev.az < 0 then
                ax, az = -ax, -az
            end
            if target.root and target.root.Parent then
                local bp = target.root.Position
                local toB = (bp.X - posSeen.X) * ax + (bp.Z - posSeen.Z) * az
                if (not prev and toB < 0) or (prev and toB < -(config.gildedRedFlip or 12)) then
                    ax, az = -ax, -az
                end
            end
            local o = posSeen.X * ax + posSeen.Z * az
            local keep = config.gildedRedKeep or 7.5 -- from a line's centre at its strike (dungeon-run7: 6.1-10; D-083: hits to ~7)
            local speed = math.max(humanoid.WalkSpeed * (context.speedMul and context.speedMul() or 1), 16)
            local list = {}
            for _, L in ipairs(cons) do
                local dot = L.nx * ax + L.nz * az
                if math.abs(dot) > 0.97 then
                    list[#list + 1] = { c = L.px * ax + L.pz * az, strike = L.strike }
                    if config.gildedRedEarly ~= false then -- D-074: a line also hurts ~0.5 s after it appears
                        list[#list + 1] = { c = L.px * ax + L.pz * az, strike = L.at + (config.gildedRedFirstHit or 0.5),
                            keep = config.gildedRedEarlyKeep or 5, w = config.gildedRedEarlyW or 0.25 } -- D-087: a weak hit (~5% vs ~30%)
                    end
                end
            end
            local function cost(s, wait) -- the way along the normal, and how far inside a line at any strike on the way
                -- D-121: `wait` s standing here first, then the way; `deep` = the most inside a full strike's keep
                local d = s - o
                local dist, dir, bad, deep = math.abs(d), d >= 0 and 1 or -1, 0, 0
                for _, C in ipairs(list) do
                    local dt = C.strike - now
                    if dt > -0.05 then
                        -- D-140: a wait is stood out `gildedRedWaitPad` s longer (the strike's spread 1.0-1.15 s, the first
                        -- move after the hold): never a wait inside a line that strikes during it
                        local wt = wait and wait + (config.gildedRedWaitPad or 0.25) or 0
                        local at = o + dir * math.min(math.max(dt - wt, 0) * speed, dist)
                        local m = math.abs(at - C.c)
                        local kp = C.keep or keep
                        if m < kp then
                            bad = bad + (kp - m) * (C.w or 1) -- D-087
                            if not C.w then
                                deep = math.max(deep, kp - m)
                            end
                        end
                    end
                end
                return dist + bad * 40, bad, deep
            end
            local ps
            if prev and prev.s and prev.ax then
                local dd = ax * prev.ax + az * prev.az
                ps = dd > 0.97 and prev.s or dd < -0.97 and -prev.s or nil
            end
            local cands = {}
            for k = -(config.gildedRedReach or 48), config.gildedRedReach or 48 do
                local s = o + k * 0.5
                local c2, b2 = cost(s)
                if ps and math.abs(s - ps) < 0.6 then
                    c2 = c2 - 1 -- the same spot: no dithering
                end
                cands[#cands + 1] = { s = s, c = c2, bad = b2 }
            end
            table.sort(cands, function(c1, c2)
                return c1.c < c2.c
            end)
            if ps and config.gildedRedHold ~= false then
                -- D-111: the gap we are going to while it stays clear of every known strike - F 07:21: two accounts
                -- flipped forward 24 / back 14 / forward 21 / back 18 / forward 6 in 1.1 s and one strike hit both
                local cK, bK = cost(ps)
                if bK == 0 and math.abs(ps - o) <= (config.gildedRedReach or 48) * 0.5 then
                    table.insert(cands, 1, { s = ps, c = cK, bad = 0 })
                end
            end
            local best
            for i = 1, math.min(#cands, 24) do
                local s = cands[i].s
                local gx, gz = posSeen.X + ax * (s - o), posSeen.Z + az * (s - o)
                local okF, floor = pcall(contextFloorY, gx, posSeen.Y, gz, contextRaycastParams())
                if okF and floor ~= nil and math.abs(floor - posSeen.Y) <= (config.maxStepHeight or 4) + 3 then
                    best = cands[i]
                    break
                end
            end
            if not best then
                runtimeState.redLine = nil
                return false
            end
            -- D-150 (boss 1): a turn-back of 15+ studs with a strike under 0.45 s away crossed the line just passed as it
            -- struck (31 @92.2, 32 @82.0, 33 @84.4; 9 of 21 such turns hit in 60 recordings, 6 of ~90 shorter ones) - the
            -- best spot on the side we are heading (or here) instead, when that side has one clear of every strike
            if ps and config.gildedRedNoFlip ~= false and math.abs(ps - o) > (config.gildedRedArrive or 0.75) then
                local soon = math.huge
                for _, C in ipairs(list) do
                    if C.strike > now then
                        soon = math.min(soon, C.strike - now)
                    end
                end
                local head, d0 = ps >= o and 1 or -1, best.s - o
                if soon <= (config.gildedRedNoFlipIn or 0.45) and d0 * head < 0 and math.abs(d0) >= (config.gildedRedNoFlipAt or 15) then
                    for i = 1, #cands do
                        local s = cands[i].s
                        local _, _, dk = cost(s)
                        if (s - o) * head >= -(config.gildedRedArrive or 0.75) and dk < (config.gildedRedWaitDeep or 1.5) then
                            local gx, gz = posSeen.X + ax * (s - o), posSeen.Z + az * (s - o)
                            local okF, floor = pcall(contextFloorY, gx, posSeen.Y, gz, contextRaycastParams())
                            if okF and floor ~= nil and math.abs(floor - posSeen.Y) <= (config.maxStepHeight or 4) + 3 then
                                best = cands[i]
                                break
                            end
                        end
                    end
                end
            end
            -- D-121 (boss 1; U4 17:27 acct4): the trap - the next set's gaps miss the striking set's, so every
            -- straight way passes within 6 of a line at its strike; "go now" took back 24 through the striking line. Then
            -- stand here until that strike is over (planned again every tick) when going after it is clear
            local waitFor, waitThen
            if config.gildedRedWait ~= false then
                local lim, reach = config.gildedRedWaitDeep or 1.5, config.gildedRedReach or 48
                local _, _, d0 = cost(best.s)
                local trapped = d0 >= lim
                if trapped then
                    for k = -reach, reach do
                        local _, _, dk = cost(o + k * 0.5)
                        if dk < lim then
                            trapped = false
                            break
                        end
                    end
                end
                if trapped then
                    local bestC, tried = nil, {}
                    for _, C in ipairs(list) do
                        local dt = C.strike - now
                        local key = math.floor(dt * 100 + 0.5)
                        if not C.w and dt > 0 and dt < (config.gildedRedWaitMax or 1.0) and not tried[key] then
                            tried[key] = true
                            local w = dt + 0.05
                            for k = -reach, reach do
                                local s = o + k * 0.5
                                local cw, _, dw = cost(s, w)
                                cw = cw + w * 2
                                if dw < lim and (not bestC or cw < bestC) then
                                    bestC, waitFor, waitThen = cw, w, s
                                end
                            end
                        end
                    end
                end
            end
            if waitFor then
                best = { s = o, c = 0, bad = 0 } -- stand where we are; the next ticks go once the strike is over
            end
            local hold = math.abs(best.s - o) < (config.gildedRedArrive or 0.75) and best.bad == 0
            runtimeState.redLine = { ax = ax, az = az, s = best.s, at = now, hold = hold, waitFor = waitFor, waitThen = waitThen }
            local away = context.lookAwayLive and context.lookAwayLive(config.lookAwayCastLead or 0.8) ~= nil -- D-160
            local cf0 = runtimeState.castFace
            local castHold = context.castWinding and context.castWinding()
                or cf0 ~= nil and cf0.dx ~= nil and now - (cf0.at or 0) < (config.castFaceHold or 0.45)
            if not away then
                runtimeState.gildedFace = { x = posSeen.X + ax * 60, z = posSeen.Z + az * 60, at = now } -- sideways to the lines
            end
            local nextStrike = math.huge
            for _, C in ipairs(list) do
                if C.strike > now then
                    nextStrike = math.min(nextStrike, C.strike - now)
                end
            end
            context.BB.goal = nil
            if hold then
                contextReleaseMover(humanoid, zF)
                if not away and not castHold and now - (movement.facedAt or -math.huge) > (config.gildedFaceYield or 0.35) then
                    pcall(function()
                        humanoid.AutoRotate = false
                        local rp = zF.Position
                        zF.CFrame = CFrame.lookAt(rp, rp + Vector3.new(ax, 0, az))
                    end)
                end
                if waitFor then
                    contextSetState(("RED LINES: waiting %.1fs for the strike, then %s %.0f studs (D-121)"):format(
                        waitFor, waitThen >= o and "forward" or "back", math.abs(waitThen - o)))
                else
                    contextSetState(("RED LINES: in the gap, facing across (next strike in %.1fs)"):format(nextStrike < math.huge and nextStrike or 0))
                end
            else
                local d = best.s - o
                g(humanoid, zF, Vector3.new(posSeen.X + ax * d, posSeen.Y, posSeen.Z + az * d), config.tweenEscape, 1)
                contextSetState(("RED LINES: %s %.0f studs into the gap (next strike in %.1fs)"):format(
                    d >= 0 and "forward" or "back", math.abs(d), nextStrike < math.huge and nextStrike or 0))
            end
            p(humanoid, zF, target, y)
            return true
        end
        context.gildedChaseKeep = function(humanoid, zF, posSeen, y, target) -- D-062 (boss 1): the beam chases - keep running the same way round
            if not (hazardReader.gildedOn and config.gildedBeamChase ~= false and target and target.isBoss and target.root
                and target.model and target.model.Name == "Archpriestess Kiryne" and context.BB and context.BB.ringClear) then
                return false
            end
            local now = os.clock()
            if now - (hazardReader.beamChaseAt or -math.huge) > (config.gildedChaseHold or 0.8) or hazardReader.safeField then
                return false
            end
            local bp = target.root.Position
            local rx, rz = posSeen.X - bp.X, posSeen.Z - bp.Z
            local rd = math.sqrt(rx * rx + rz * rz)
            if rd < 4 then
                return false
            end
            local chase = runtimeState.gildedChase
            if not chase or now - (chase.at or -math.huge) > 1.5 then
                -- the way round we are already going
                local v = zF.AssemblyLinearVelocity
                local cr = rx * v.Z - rz * v.X
                chase = { side = math.abs(cr) > 20 and (cr > 0 and 1 or -1) or runtimeState.orbitSide or 1 }
            end
            chase.at = now
            runtimeState.gildedChase = chase
            local speed = math.max(humanoid.WalkSpeed, 16)
            local base = math.atan2(rz, rx)
            local lo, hi = config.gildedChaseMin or 22, config.gildedChaseMax or 48
            local R0 = math.clamp(rd, lo, hi)
            for _, Rr in ipairs({ R0, math.min(R0 + 8, hi + 8), math.max(R0 - 8, lo) }) do
                local pts = {}
                for k = 1, 10 do
                    local d = k * 4
                    local rad = rd + (Rr - rd) * math.min(d / 16, 1)
                    local ang = base + chase.side * d / math.max(rad, 10)
                    pts[k] = { x = bp.X + math.cos(ang) * rad, z = bp.Z + math.sin(ang) * rad, d = d }
                end
                local ok, clear = pcall(context.BB.ringClear, posSeen, pts, speed, y)
                if ok and clear then
                    context.BB.goal = nil
                    runtimeState.orbitSide = chase.side
                    g(humanoid, zF, Vector3.new(pts[3].x, posSeen.Y, pts[3].z), e(), 1)
                    contextSetState(("BEAM: running on round Kiryne the same way, %.0f out"):format(rd))
                    p(humanoid, zF, target, y)
                    return true
                end
            end
            return false
        end
        context.gildedRingStep = function(humanoid, zF, posSeen, y, target, forceR, chosen) -- D-057/D-058: one way round the group
            local folder = target and target.model and target.model.Parent
            local cx, cz, n, members = 0, 0, 0, {}
            for _, enemy in ipairs(hazardReader.enemies or {}) do
                if not enemy.isBoss and enemy.humanoid and enemy.humanoid.Health > 0 and enemy.root and enemy.root.Parent
                    and (folder == nil or enemy.model and enemy.model.Parent == folder) then
                    local q = enemy.root.Position
                    if math.sqrt((q.X - posSeen.X) ^ 2 + (q.Z - posSeen.Z) ^ 2) <= (config.gildedRingGroup or 90)
                        and math.abs(q.Y - posSeen.Y) < (config.gildedRingDy or 30) then
                        cx, cz, n = cx + q.X, cz + q.Z, n + 1
                        members[n] = q
                    end
                end
            end
            if n == 0 then
                runtimeState.gildedRing = nil
                return false
            end
            cx, cz = cx / n, cz / n
            local ring = runtimeState.gildedRing
            if not ring or ring.room ~= folder then
                ring = { side = runtimeState.orbitSide or 1, room = folder, flipAt = -math.huge, x = cx, z = cz }
                local agL = context.gildedAggro and context.gildedAggro()
                local roomName = folder and folder.Parent and folder.Parent.Name
                if agL and agL.me and roomName and (config.gildedAggroLeftRooms or { room6 = true })[roomName] then
                    ring.side = 1 -- D-101 (test, room 6): the aggro account goes round to the left (the wall check still turns it)
                end
            end
            -- D-058: the centre eased (no jumps when one mob moves or dies), the radius fits the group
            local ease = config.gildedRingEase or 0.3
            ring.x, ring.z = ring.x + (cx - ring.x) * ease, ring.z + (cz - ring.z) * ease
            local far = 0
            for _, q in ipairs(members) do
                far = math.max(far, math.sqrt((q.X - ring.x) ^ 2 + (q.Z - ring.z) ^ 2))
            end
            local R = math.clamp(far + (config.gildedRingClear or 8), config.gildedRingMin or 22, config.gildedRingMax or 40) -- D-064: the reference keeps closer (median 36 from the centre)
            local ag = context.gildedAggro and context.gildedAggro()
            local stackA = context.gildedStackNow and context.gildedStackNow()
            if stackA and not stackA.me then -- D-102 (test room): stacked on the aggro account, 2 studs outside it
                local ap = stackA.root.Position
                local ox, oz = ap.X - ring.x, ap.Z - ring.z
                local od = math.max(math.sqrt(ox * ox + oz * oz), 1)
                ring.R, ring.at = R, os.clock()
                runtimeState.gildedRing = ring
                local sp = Vector3.new(ap.X + ox / od * (config.gildedStackOut or 2), posSeen.Y, ap.Z + oz / od * (config.gildedStackOut or 2))
                if (sp.X - posSeen.X) ^ 2 + (sp.Z - posSeen.Z) ^ 2 > (config.gildedStackStop or 3) ^ 2 then
                    g(humanoid, zF, sp, e(), 1)
                else
                    contextReleaseMover(humanoid, zF) -- D-106: there - no re-aiming each tick (the move flipped and the facing spun)
                end
                contextSetState("STACK: with the leader")
                p(humanoid, zF, target, y)
                return true
            end
            if ag then -- D-099 (user): the aggro account is the nearest (draws the attacks, the chasers bunch), the rest further out
                if ag.me then
                    R = math.clamp(far + (config.gildedAggroClear or 4), config.gildedAggroMin or 14, config.gildedAggroMax or 26)
                else
                    local ad = math.sqrt((ag.root.Position.X - ring.x) ^ 2 + (ag.root.Position.Z - ring.z) ^ 2)
                    -- D-100: just outside the aggro account (rings reached 58+ and supports were > 75 from every mob)
                    R = math.clamp(math.min(ad, 40) + (config.gildedSupportGap or 12), config.gildedSupportMin or 26, config.gildedSupportMax or 46)
                end
            end
            local rx, rz = posSeen.X - ring.x, posSeen.Z - ring.z
            local rd = math.sqrt(rx * rx + rz * rz)
            if rd > R + (config.gildedRingEngage or 30) then
                return false -- still on the way to the group
            end
            if rd < 1 then
                rx, rz, rd = 1, 0, 1
            end
            ring.R, ring.at = R, os.clock()
            runtimeState.gildedRing = ring
            -- close in 8 studs a step from outside, move out 6 a step from inside: no charging in, no jumping out
            local rt = rd > R + 8 and rd - 8 or rd < R - 6 and rd + 6 or R
            if forceR then
                rt = forceR -- D-061: a dodge on a tighter / wider ring
            end
            if not forceR and not chosen and context.gildedPredict and config.gildedPredict ~= false then
                -- D-062: not the way round that stays in the line of a mob whose attack is due
                local speed, now = math.max(humanoid.WalkSpeed, 16), os.clock()
                local function path(side, Rr)
                    local pts, base = {}, math.atan2(rz, rx)
                    for k = 1, 12 do
                        local d = k * 4
                        local rad = rd + (Rr - rd) * math.min(d / 16, 1)
                        local ang = base + side * d / math.max(rad, 10)
                        pts[k] = { x = ring.x + math.cos(ang) * rad, z = ring.z + math.sin(ang) * rad, d = d }
                    end
                    return pts
                end
                local okP, f0 = pcall(context.gildedPredict, posSeen, path(ring.side, rt), speed, now)
                if okP and f0 > 0 then
                    local alts = { { ring.side, R + 10 }, { ring.side, math.max(R - 8, 16) } }
                    if now - ring.flipAt > (config.gildedRingFlipGap or 2) then
                        alts[3], alts[4], alts[5] = { -ring.side, rt }, { -ring.side, R + 10 }, { -ring.side, math.max(R - 8, 16) }
                    end
                    for _, a2 in ipairs(alts) do
                        local pts = path(a2[1], a2[2])
                        local okF, f = pcall(context.gildedPredict, posSeen, pts, speed, now)
                        local okC, clear = true, true
                        if context.BB and context.BB.ringClear then
                            okC, clear = pcall(context.BB.ringClear, posSeen, pts, speed, y)
                        end
                        if okF and f == 0 and okC and clear then
                            if a2[1] ~= ring.side then
                                ring.side, ring.flipAt = a2[1], now
                            end
                            rt = a2[2]
                            break
                        end
                    end
                end
            end
            local step = config.gildedRingStep or 10
            local function pointFor(side)
                local ang = math.atan2(rz, rx) + side * step / math.max(rt, 10)
                return Vector3.new(ring.x + math.cos(ang) * rt, posSeen.Y, ring.z + math.sin(ang) * rt)
            end
            local function open(to)
                local d = Vector3.new(to.X - posSeen.X, 0, to.Z - posSeen.Z)
                if d.Magnitude < 0.5 then
                    return true
                end
                local hit = contextWorkspace:Raycast(posSeen + Vector3.new(0, 1.5, 0), d.Unit * math.min(d.Magnitude + 3, 25), contextRaycastParams())
                return not (hit and hit.Instance and hit.Instance.CanCollide)
            end
            local goal = pointFor(ring.side)
            if not open(goal) then
                if os.clock() - ring.flipAt > (config.gildedRingFlipGap or 2) and open(pointFor(-ring.side)) then
                    ring.side, ring.flipAt = -ring.side, os.clock()
                    goal = pointFor(ring.side)
                else
                    return false
                end
            end
            runtimeState.orbitSide = ring.side
            g(humanoid, zF, goal, e(), 1)
            contextSetState(("RING: round the group (%d mobs) at %.0f, keeping %.0f"):format(n, rd, R))
            p(humanoid, zF, target, y)
            return true
        end
        context.gildedRingKeep = function(humanoid, zF, posSeen, y, target) -- D-058: going on round clears it: keep going
            local ring = runtimeState.gildedRing
            if not (ring and ring.R and target and not target.isBoss and os.clock() - (ring.at or -math.huge) < 0.6
                and context.BB and context.BB.ringClear) then
                return false
            end
            local prim = context.BB.primary and context.BB.primary.box
            local pn = prim and string.lower(tostring(prim.name or "")) or ""
            if prim and pn:sub(1, 7) ~= "dracani" then
                return false -- mob attacks only
            end
            local rx, rz = posSeen.X - ring.x, posSeen.Z - ring.z
            local rd = math.sqrt(rx * rx + rz * rz)
            if rd < 1 then
                return false
            end
            local speed = math.max(humanoid.WalkSpeed, 16)
            local base = math.atan2(rz, rx)
            -- D-061: this way round, the other way, 8 studs in, 10 out - the first path clear of every attack
            local options = {
                { side = ring.side, R = ring.R },
                { side = -ring.side, R = ring.R },
                { side = ring.side, R = math.max(ring.R - 8, 16) },
                { side = ring.side, R = ring.R + 10 },
                { side = -ring.side, R = math.max(ring.R - 8, 16) },
                { side = -ring.side, R = ring.R + 10 },
            }
            local pick
            for _, o in ipairs(options) do
                local pts, short = {}, {}
                local steps = config.gildedRingCheckSteps or 8
                for k = 1, math.max(steps, 12) do
                    local d = k * 4
                    local rad = rd + (o.R - rd) * math.min(d / 16, 1)
                    local ang = base + o.side * d / math.max(rad, 10)
                    pts[k] = { x = ring.x + math.cos(ang) * rad, z = ring.z + math.sin(ang) * rad, d = d }
                    if k <= steps then
                        short[k] = pts[k]
                    end
                end
                local ok, clear = pcall(context.BB.ringClear, posSeen, short, speed, y)
                if ok and clear then
                    -- D-062: of the clear ones, the first that also stays out of the attacks due next
                    local okF, f = true, 0
                    if context.gildedPredict then
                        okF, f = pcall(context.gildedPredict, posSeen, pts, speed, os.clock())
                    end
                    if okF and f == 0 then
                        pick = o
                        break
                    end
                    pick = pick or o
                end
            end
            if pick then
                if pick.side ~= ring.side then
                    ring.side, ring.flipAt = pick.side, os.clock()
                end
                context.BB.goal = nil
                return context.gildedRingStep(humanoid, zF, posSeen, y, target, pick.R ~= ring.R and pick.R or nil, true)
            end
            return false
        end
        context.redOrbGuard = function(humanoid, zF, posSeen, y, target) -- D-086 (boss 3): a red orb on anyone kills the party
            local orbs = hazardReader.redOrbs
            if not (hazardReader.gildedOn and config.gildedOrbGuard ~= false and orbs and #orbs > 0) then
                return false
            end
            local now = os.clock()
            local R = config.gildedOrbGuardR or 13 -- the other script kept 12+ from every orb; it goes off within ~8
            local refuge -- D-093: a refuge with a blast coming (memory, colour, flame-wall gap) - keep heading for it
            do
                local f, sp = hazardReader.safeField, hazardReader.safeSpots and hazardReader.safeSpots[1]
                if f and sp and now <= (f.untilAt or 0) and now >= (f.from or 0) - (f.lead or 0)
                    and not tostring(f.name or ""):find("orb collect", 1, true) then
                    refuge = sp
                    R = config.gildedOrbGuardRefugeR or 10
                end
            end
            local look = config.gildedOrbGuardLook or 1.4
            local function pass(x, z, o) -- how close the orb comes to (x, z) in the next `look` seconds, and our side
                local rx, rz = x - o.ox, z - o.oz
                local along, across = rx * o.dx + rz * o.dz, -rx * o.dz + rz * o.dx
                local a0 = math.max((now - o.from) * o.speed, 0)
                local a1 = math.min((now + look - o.from) * o.speed, o.length)
                if a1 < 0 or a0 > o.length then
                    return nil
                end
                local ac = math.clamp(along, a0, math.max(a1, a0))
                return math.sqrt((along - ac) ^ 2 + across * across), across
            end
            local boxes = dangerGeometry.boxes or {}
            local function attackAt(x, z, any) -- D-123: a young S-shape circle / spiral shot (any: any live attack but an orb's) on (x, z)
                for _, box in ipairs(boxes) do
                    local bn = tostring(box.name or "")
                    local shape = bn == "thirdbosssshapecircle" or bn == "thirdbossspiralshot"
                    if (shape or any and (box.from or now) <= now + 0.35 and not (bn:find("comet", 1, true) or bn:find("passiveorb", 1, true)))
                        and (box.untilAt or 0) > now then
                        local okD, depth = pcall(contextDepthOf, box, x, box.cy or posSeen.Y, z, 0)
                        if okD and depth and depth >= -(config.gildedOrbShapeMargin or 1.5) then
                            return true
                        end
                    end
                end
                return false
            end
            -- D-123 (U5 17:31): near a memory circle / colour zone an orb we stepped for keeps the step's radius until it has
            -- passed - the walk back to the refuge took us inside 10 of its lane every other tick (it went off at 7.2).
            -- Not at the flame-wall gap (its walk owns the time); a live attack on us ends the hold (the dodge first)
            local fname = refuge and tostring(hazardReader.safeField and hazardReader.safeField.name or "") or ""
            runtimeState.redOrbGapLine = nil
            local gapLine = fname == "gilded firewall gap" and config.gildedOrbGapLine ~= false and refuge.lx and refuge.lz
                and refuge.lx * refuge.lx + refuge.lz * refuge.lz > 0.01 -- D-137: the gap is its line, not its spot
            local hold = runtimeState.redOrbHold
            local function refugeLate()
                -- D-129 (X20 01:10): the hold kept two out of the memory circle until its blast (25-35 out; the orb would
                -- pass 10-11 off) - it ends once it would bring us to the refuge later than 1.0 s before the blast
                local f = hazardReader.safeField
                if not (refuge and f) or config.gildedOrbHoldYield == false then
                    return false
                end
                if gapLine then -- D-137: late only when off the gap's line with the wall's pass near
                    local n = math.sqrt(refuge.lx * refuge.lx + refuge.lz * refuge.lz)
                    local lat = math.abs(-(posSeen.X - refuge.x) * refuge.lz / n + (posSeen.Z - refuge.z) * refuge.lx / n)
                    local keep = math.max((refuge.r or 6) - 2, 1.5)
                    local spL = math.max(humanoid.WalkSpeed * (context.speedMul and context.speedMul() or 1), 16)
                    return lat > keep and (lat - keep) / spL + (config.gildedOrbHoldSpare or 1.0) >= (f.passAt or f.untilAt or now) - now
                end
                local edge = fname == "gilded memory" and (config.gildedMemoryEdge or 4) or 2
                local walk = math.max(math.sqrt((posSeen.X - refuge.x) ^ 2 + (posSeen.Z - refuge.z) ^ 2)
                    - math.max((refuge.r or 4) - edge, 1), 0)
                local sp = math.max(humanoid.WalkSpeed * (context.speedMul and context.speedMul() or 1), 16)
                return walk / sp + (config.gildedOrbHoldSpare or 1.0) >= (f.from or now) - now
            end
            if hold and (not refuge or config.gildedOrbHold == false or fname == "gilded firewall gap" and not gapLine -- D-137
                or now > (hold.orb.untilAt or 0) + 0.3 or now - hold.at > (config.gildedOrbHoldMax or 3)
                or attackAt(posSeen.X, posSeen.Z, true) or refugeLate()) then
                runtimeState.redOrbHold, hold = nil, nil
            end
            local worst, wAcross, wOrb
            local held = false
            for i = #orbs, 1, -1 do
                local o = orbs[i]
                if now > o.untilAt + 0.3 then
                    table.remove(orbs, i)
                else
                    local d, across = pass(posSeen.X, posSeen.Z, o)
                    local rr = R
                    if hold and hold.orb == o then
                        rr = R + (config.gildedOrbHoldPad or 2.5)
                        held = d ~= nil and d < rr
                    end
                    if d and d < rr and (not worst or d < worst) then
                        worst, wAcross, wOrb = d, across, o
                    end
                end
            end
            if hold and not held then
                runtimeState.redOrbHold = nil -- D-123: that orb has passed
            end
            if not worst then
                return false
            end
            local px, pz = -wOrb.dz, wOrb.dx -- the lane's side axis (across > 0 on this side)
            local speed = math.max(humanoid.WalkSpeed * (context.speedMul and context.speedMul() or 1), 16)
            local function okAt(x, z, anyRoom)
                if context.yellowOrbNear then -- D-097: not onto / through the armed yellow orb
                    for k = 1, 4 do
                        local f = k / 4
                        if context.yellowOrbNear(posSeen.X + (x - posSeen.X) * f, posSeen.Z + (z - posSeen.Z) * f) then
                            return false
                        end
                    end
                end
                for _, o in ipairs(anyRoom and {} or orbs) do
                    local d = pass(x, z, o)
                    if d and d < R then
                        return false
                    end
                end
                if config.gildedOrbShapes ~= false and attackAt(x, z) then
                    return false -- D-123: not into a young S-shape circle / spiral shot (15:51: three walked in and were hit)
                end
                local okF, floor = pcall(contextFloorY, x, posSeen.Y, z, contextRaycastParams())
                return okF and floor ~= nil and math.abs(floor - posSeen.Y) <= (config.maxStepHeight or 4) + 3
            end
            local s0 = wAcross >= 0 and 1 or -1
            local best
            -- D-123 (U2 17:18): never across the lane in front of its orb - our side's point was 8 off the next lane, the guard
            -- went 26 studs across with the orb 23 away and it went off at 10.6
            local noCross = config.gildedOrbNoCross ~= false and math.abs(wAcross) > (config.gildedOrbCrossFree or 2)
            for _, s in ipairs({ s0, -s0 }) do
                local m = s * (R + 2) - wAcross -- along the side axis, to 15 studs off the lane on side s
                local gx, gz = posSeen.X + px * m, posSeen.Z + pz * m
                if not (noCross and s ~= s0) and okAt(gx, gz) then
                    local clear = true
                    if context.BB and context.BB.wayClear then
                        local okC, r = pcall(context.BB.wayClear, posSeen, Vector3.new(gx, posSeen.Y, gz), speed, y)
                        clear = not okC or r ~= false
                    end
                    local c = math.abs(m) + (clear and 0 or 30)
                    if refuge then
                        local d0 = math.sqrt((posSeen.X - refuge.x) ^ 2 + (posSeen.Z - refuge.z) ^ 2)
                        local d1 = math.sqrt((gx - refuge.x) ^ 2 + (gz - refuge.z) ^ 2)
                        if gapLine then -- D-137: off the gap's line, not off its spot (a step along it keeps the gap)
                            local n = math.sqrt(refuge.lx * refuge.lx + refuge.lz * refuge.lz)
                            d0 = math.abs(-(posSeen.X - refuge.x) * refuge.lz / n + (posSeen.Z - refuge.z) * refuge.lx / n)
                            d1 = math.abs(-(gx - refuge.x) * refuge.lz / n + (gz - refuge.z) * refuge.lx / n)
                        end
                        if d1 - d0 > (config.gildedOrbRefugeAway or 4) and worst >= (config.gildedOrbGuardHard or 8) then
                            c = math.huge -- D-093: away from the refuge for an orb that is not about to touch us
                        else
                            c = c + math.max(d1 - d0, 0) * 3
                        end
                    end
                    if c < math.huge and (not best or c < best.c) then
                        best = { x = gx, z = gz, c = c, m = m }
                    end
                end
            end
            if not best and noCross and config.gildedOrbRoom ~= false then
                -- D-123: no point R + 2 off every lane on our side - our side's point with the most room from every orb
                local function room(x, z)
                    local c = math.huge
                    for _, o in ipairs(orbs) do
                        local d = pass(x, z, o)
                        if d and d < c then
                            c = d
                        end
                    end
                    return c
                end
                local here, bestRoom = room(posSeen.X, posSeen.Z), nil
                for k = 2, math.floor(R + 10) do
                    local m = s0 * k - wAcross
                    local gx, gz = posSeen.X + px * m, posSeen.Z + pz * m
                    local rm = room(gx, gz)
                    if rm > here + 0.5 and (not bestRoom or rm > bestRoom + 0.25) and okAt(gx, gz, true) then
                        best, bestRoom = { x = gx, z = gz, c = math.abs(m), m = m }, rm
                    end
                end
            end
            if not best then
                return false
            end
            if context.BB then
                context.BB.goal = nil
            end
            runtimeState.refugeLeash = nil
            runtimeState.redOrbStep = { x = best.x, z = best.z, m = best.m, at = now }
            if refuge and (fname ~= "gilded firewall gap" or gapLine) and config.gildedOrbHold ~= false then -- D-137: on the gap's line too
                local h = runtimeState.redOrbHold -- D-123: held for this orb until it has passed
                runtimeState.redOrbHold = { orb = wOrb, at = h and h.orb == wOrb and h.at or now }
            end
            runtimeState.redOrbGapLine = gapLine or nil -- D-137: g() keeps this step on the gap's line
            g(humanoid, zF, Vector3.new(best.x, posSeen.Y, best.z), config.tweenEscape, 1)
            runtimeState.redOrbGapLine = nil
            contextSetState(("RED ORB: off its lane, %.0f studs (it would pass %.0f off)"):format(math.abs(best.m), worst))
            if target then
                p(humanoid, zF, target, y)
            end
            return true
        end
        context.gildedTetherPrimaryDepth = function(x, y, z)
            -- D-120: how deep (x, z) is in the dodge planner's current lethal attack (nil: none) - the tether never
            -- takes us deeper into it than its own dodge does
            local bb = context.BB
            local box = bb and bb.lethal and bb.primary and bb.primary.box
            if not (box and box.cx) then
                return nil
            end
            local ok, d = pcall(contextDepthOf, box, x, y, z, dangerGeometry.halfHeight or 5)
            return ok and type(d) == "number" and d > -math.huge and d or nil
        end
        context.gildedTetherNote = function(why) -- D-120: why the tether did not change a move (logged once a second)
            runtimeState.tetherWhy = why
            local now = os.clock()
            if why ~= runtimeState.tetherWhyLogged or now - (runtimeState.tetherWhyAt or -math.huge) > 1 then
                runtimeState.tetherWhyLogged, runtimeState.tetherWhyAt = why, now
                pcall(contextLogT, "tether", 2, "Brain", "orb tether: " .. tostring(why))
            end
        end
        context.gildedTetherLines = function(pos, speed, onUs)
            -- D-134 (boss 2): the vertical lines still to strike or striking. Beside one (its margin, not its box) the
            -- field reads 1 where the own-side hold stands us (box 6.5 from its centre + reach 2.3), so a step off a
            -- tether there is judged by each line's timing and our side's keep (7.5), the rest of the field as before
            if config.gildedTetherLineHold == false or not hazardReader.gildedOn then
                return nil
            end
            local now = dangerGeometry.now or os.clock()
            local keep = config.gildedVLineKeep or 7.5
            local lines, inside = {}, false
            for _, n in ipairs(dangerGeometry.boxes or {}) do
                -- D-134b: a struck line still listed bars its old band too unless the tether is on us (D-120 kept us
                -- out of the line just escaped through its primary box only, so it hung on the field's order)
                if n.name == "secondbossverticalline" and not n.far and not n.moving and n.cx and n.ax and n.untilAt
                    and (n.untilAt > now or not onUs) then
                    local nx, nz, half = n.ax, n.az, n.ha or 4
                    if n.ha and n.hb and n.hb < n.ha then
                        nx, nz, half = n.bx, n.bz, n.hb
                    end
                    local off0 = math.abs((pos.X - n.cx) * nx + (pos.Z - n.cz) * nz)
                    if off0 < half and n.untilAt > now then
                        inside = true -- in its box: its own escape goes first
                    end
                    lines[#lines + 1] = { n = n, nx = nx, nz = nz, need = math.min(keep, off0) - 0.05,
                        spent = n.untilAt <= now }
                end
            end
            local function notLine(n)
                return n.name == "secondbossverticalline"
            end
            local fast = math.max(tonumber(speed) or 16, config.burstMax or 28) -- the earliest we can be there
            return {
                inside = inside,
                count = #lines,
                dangerX = function(x, z, t) -- the field without the vertical lines
                    local ok, v = pcall(contextDangerAt, x, pos.Y, z, t, nil, nil, notLine)
                    return ok and tonumber(v) or 0
                end,
                clear = function(gx, gz) -- the way and the spot: off every line's keep until its window is over
                    local dx, dz = gx - pos.X, gz - pos.Z
                    local L = math.sqrt(dx * dx + dz * dz)
                    for _, e in ipairs(lines) do
                        -- D-134b: the part of the way we can walk before its window ends (at our fastest; all of it for
                        -- a struck line kept), exactly: the offset is linear - its far end, and no crossing of the centre
                        local f = (e.spent or L <= 1e-6) and 1 or math.min(1, fast * math.max(e.n.untilAt - now, 0) / L)
                        if f > 0 then
                            local o0 = (pos.X - e.n.cx) * e.nx + (pos.Z - e.n.cz) * e.nz
                            local o1 = o0 + (dx * e.nx + dz * e.nz) * f
                            if math.abs(o1) < e.need or o0 * o1 < 0 then
                                return false
                            end
                        end
                    end
                    return true
                end,
            }
        end
        context.gildedTetherGuard = function(humanoid, zF, posSeen, y, target)
            -- D-120 (boss 2): another player's orb tether kills on touch, and its player drags it over us (3 of the 4
            -- deaths: the tethered player walking 14-21 studs/s across a bot at 0-19) - off it, on our side of it
            local segs = hazardReader.gildedOn and config.gildedTether ~= false and hazardReader.gildedTetherSegs
                and hazardReader.gildedTetherSegs()
            if not segs then
                runtimeState.tetherStep = nil
                return false
            end
            local now = os.clock()
            local keep, lead = config.gildedTetherKeep or 4.5, config.gildedTetherLead or 0.4
            local dist = hazardReader.gildedTetherDist
            local d0, s0 = dist(posSeen.X, posSeen.Z, 0, segs)
            local d1, s1 = dist(posSeen.X, posSeen.Z, lead, segs)
            local near = math.min(d0, d1)
            local st = runtimeState.tetherStep
            if near >= keep and not (st and now - st.at < (config.gildedTetherHold or 0.3) and near < keep + 1.5) then
                runtimeState.tetherStep = nil
                return false
            end
            local function danger(x, z, t)
                local ok, v = pcall(contextDangerAt, x, posSeen.Y, z, t)
                return ok and tonumber(v) or 0
            end
            local here = danger(posSeen.X, posSeen.Z, 0)
            local depth = context.gildedTetherPrimaryDepth
            local dHere = depth(posSeen.X, posSeen.Y, posSeen.Z)
            local speed = math.max(humanoid.WalkSpeed * (context.speedMul and context.speedMul() or 1), 16)
            local lh = context.gildedTetherLines -- D-134 (boss 2); D-134b: the tether on us (2.0 now or 0.4 s on)
                and context.gildedTetherLines(posSeen, speed, near < (config.gildedTetherOnUs or 2.0))
            lh = lh and lh.count > 0 and lh or nil
            local hereX = lh and lh.dangerX(posSeen.X, posSeen.Z, 0) or here
            if here >= 1 or dHere and dHere > 0 then
                if not (lh and not lh.inside and hereX < 1 and not (dHere and dHere > 0)) then
                    context.gildedTetherNote("a lethal attack on us - its dodge goes first (kept off the tether where it can be)")
                    return false
                end -- D-134: only beside a line (its margin): off the tether, clear of the lines' strike
            end
            -- D-134b: which of two lines the planner has as its primary follows the field's order (pairs over the line
            -- models - arbitrary); beside the lines a primary line is judged like the others (lh.clear), not by its depth
            local bbBox = context.BB and context.BB.primary and context.BB.primary.box
            local primLine = bbBox ~= nil and bbBox.name == "secondbossverticalline"
            local orb = hazardReader.gildedCollect -- beamed: of the clear spots, the ones on the way to our own orb
            local best, lineMode
            for pass = 1, 2 do
                -- D-134: pass 1 as D-120 (the field), unless the field reads 1 beside a line; pass 2 (D-120 found
                -- nothing beside a line): the lines by their timing and our side's keep, the rest by the field
                lineMode = lh ~= nil and (pass == 2 or here >= 1)
                if pass == 2 and (best or not lh or here >= 1) then
                    break
                end
                for _, r in ipairs({ 4, 6.5, 9, 12.5, 16 }) do
                    for k = 0, 15 do
                        local a = k * math.pi / 8
                        local gx, gz = posSeen.X + math.cos(a) * r, posSeen.Z + math.sin(a) * r
                        local t = r / speed
                        if math.min((dist(gx, gz, t, segs)), (dist(gx, gz, t + lead, segs))) >= keep + 1
                            and hazardReader.gildedTetherWayOk(posSeen, Vector3.new(gx, posSeen.Y, gz), speed, segs) then
                            local mx, mz = (posSeen.X + gx) * 0.5, (posSeen.Z + gz) * 0.5
                            local dEnd, nearOk
                            if lineMode then
                                dEnd = lh.dangerX(gx, gz, t)
                                nearOk = dEnd <= hereX + 0.05 and lh.dangerX(mx, mz, t * 0.5) <= hereX + 0.05 and lh.clear(gx, gz)
                            else
                                dEnd = danger(gx, gz, t)
                                -- never nearer a line / slam than now: the line's own dodge is not overruled
                                nearOk = dEnd <= here + 0.05 and danger(mx, mz, t * 0.5) <= here + 0.05
                            end
                            local usePrim = dHere and not (lineMode and primLine) -- D-134b
                            local dpEnd = usePrim and depth(gx, posSeen.Y, gz)
                            local dpMid = usePrim and depth(mx, posSeen.Y, mz)
                            if nearOk and not (dpEnd and dpEnd > dHere + 0.25) and not (dpMid and dpMid > dHere + 0.25) then
                                local okF, floor = pcall(contextFloorY, gx, posSeen.Y, gz, contextRaycastParams())
                                if okF and floor ~= nil and math.abs(floor - posSeen.Y) <= (config.maxStepHeight or 4) + 3 then
                                    local c = r + dEnd * 10
                                    if orb and orb.x then
                                        c += (math.sqrt((gx - orb.x) ^ 2 + (gz - orb.z) ^ 2)
                                            - math.sqrt((posSeen.X - orb.x) ^ 2 + (posSeen.Z - orb.z) ^ 2)) * 0.5
                                    end
                                    if not best or c < best.c then
                                        best = { x = gx, z = gz, c = c, r = r }
                                    end
                                end
                            end
                        end
                    end
                    if best then
                        break -- the nearest ring with a clear spot
                    end
                end
            end
            if not best then
                if lineMode then -- D-134: nothing clear of both - the line's dodge / hold goes on
                    context.gildedTetherNote("no spot off it clear of the lines' strike (our side's keep) - the line's dodge goes on")
                    return false
                end
                context.gildedTetherNote("no spot off it that is no nearer a line or slam - the usual move goes on")
                return false
            end
            if context.BB then
                context.BB.goal = nil
            end
            runtimeState.tetherStep = { x = best.x, z = best.z, at = now }
            g(humanoid, zF, Vector3.new(best.x, posSeen.Y, best.z), config.tweenEscape, 1)
            local who = d0 <= d1 and s0 or s1 or s0
            contextSetState(("TETHER: off %s's orb tether, %.0f studs (it would pass %.1f off)%s"):format(
                tostring(who and who.name or "?"), best.r, near, lineMode and " - clear of the lines' strike" or ""))
            if target then
                p(humanoid, zF, target, y)
            end
            return true
        end
        context.gildedTetherClamp = function(from, to, speed)
            -- D-120 (boss 2): no move into / across another player's orb tether, whichever step chose it - the nearest
            -- spot to the move's own that is clear of it and no nearer a line / slam; none -> the move as it was (logged)
            local segs = hazardReader.gildedOn and config.gildedTether ~= false and hazardReader.gildedTetherSegs
                and hazardReader.gildedTetherSegs()
            if not segs then
                return nil
            end
            local wayOk = hazardReader.gildedTetherWayOk
            speed = math.max(tonumber(speed) or 16, 4)
            if wayOk(from, to, speed, segs) then
                return nil
            end
            local dx, dz = to.X - from.X, to.Z - from.Z
            local L = math.sqrt(dx * dx + dz * dz)
            if L < 0.5 then
                return nil
            end
            local function danger(x, z, t)
                local ok, v = pcall(contextDangerAt, x, from.Y, z, t)
                return ok and tonumber(v) or 0
            end
            local want = danger(to.X, to.Z, L / speed) -- the move's own spot: no other may be nearer a line / slam
            local depth = context.gildedTetherPrimaryDepth
            local dTo = depth(to.X, to.Y, to.Z) -- a lethal attack being dodged: no spot deeper in it than the dodge's own
            local dFrom = dTo and depth(from.X, from.Y, from.Z)
            local best
            local function try(x, z, short)
                local ex, ez = x - from.X, z - from.Z
                local l = math.sqrt(ex * ex + ez * ez)
                if l < 1 then
                    return -- a real move, never a stand-still
                end
                local t = l / speed
                if danger(x, z, t) > want + 0.05
                    or danger(from.X + ex * 0.5, from.Z + ez * 0.5, t * 0.5) > math.max(want, 0.5) + 0.05 then
                    return
                end
                if dTo then
                    local dEnd, dMid = depth(x, to.Y, z), depth(from.X + ex * 0.5, to.Y, from.Z + ez * 0.5)
                    if dEnd and dEnd > dTo + 0.25 or dMid and dMid > math.max(dTo, dFrom or dTo) + 0.25 then
                        return
                    end
                end
                local spot = Vector3.new(x, to.Y, z)
                if not wayOk(from, spot, speed, segs) then
                    return
                end
                local c = (x - to.X) ^ 2 + (z - to.Z) ^ 2 + (short and 0 or 4)
                if not best or c < best.c then
                    best = { p = spot, c = c }
                end
            end
            if not hazardReader.gildedCollect and not dTo then -- the same way, stopped short (never while we walk to our
                -- own orb, never inside a lethal attack's dodge)
                local dist, keep = hazardReader.gildedTetherDist, config.gildedTetherKeep or 4.5
                local d0 = dist(from.X, from.Z, 0, segs)
                local floor = d0 >= keep and keep or math.max(config.gildedTetherTouch or 1.5, d0 - 0.5)
                local n = math.max(1, math.ceil(L / 1.5))
                for i = 1, n do
                    local f = i / n
                    if dist(from.X + dx * f, from.Z + dz * f, L * f / speed, segs) < floor then
                        local back = math.max((i - 1) / n - 0.75 / L, 0)
                        try(from.X + dx * back, from.Z + dz * back, true)
                        break
                    end
                end
            end
            for _, r in ipairs({ 3, 6, 10 }) do -- round it: near the move's own spot first, then near us
                for k = 0, 7 do
                    local a = k * math.pi / 4
                    try(to.X + math.cos(a) * r, to.Z + math.sin(a) * r)
                end
            end
            for _, r in ipairs({ 4, 8 }) do
                for k = 0, 7 do
                    local a = k * math.pi / 4 + math.pi / 8
                    try(from.X + math.cos(a) * r, from.Z + math.sin(a) * r)
                end
            end
            if best then
                runtimeState.tetherClampAt = os.clock()
                return best.p
            end
            context.gildedTetherNote("every spot round it is blocked or nearer a line / slam - the move goes as it was")
            return nil
        end
        context.gildedRefugeFree = function(field) -- D-059 (boss 3): before a refuge's blast, the dodge may leave it
            if not (hazardReader.gildedOn and field and config.gildedRefugeFree ~= false) then
                return false
            end
            local name, now = tostring(field.name or ""), os.clock()
            if name == "gilded memory" then
                local left = (field.from or 0) - now
                local spot = hazardReader.safeSpots and hazardReader.safeSpots[1]
                local travel = 0
                pcall(function() -- D-094: only while the walk back into the circle still fits
                    local character = localPlayer.Character
                    local hum = character and character:FindFirstChildOfClass("Humanoid")
                    local root = hum and hum.RootPart
                    if root and spot then
                        local dx, dz = spot.x - root.Position.X, spot.z - root.Position.Z
                        local speed = math.max(hum.WalkSpeed * (context.speedMul and context.speedMul() or 1), 16)
                        travel = math.max(math.sqrt(dx * dx + dz * dz) - math.max((spot.r or 20) - 6, 2), 0) / speed
                    end
                end)
                return left > (config.gildedMemoryHold or 1.5) and left - travel > (config.gildedMemorySpare or 1.2)
            end
            if name:sub(1, 13) == "gilded colour" and name ~= "gilded colour wait" then
                return (field.blastBy or field.untilAt or 0) - now > (config.gildedColourHold or 1.9) -- D-124: the earliest blast
            end
            if name == "gilded firewall gap" and config.gildedFireSpawnSkip ~= false and context.spawnSafe then
                local passIn = (field.passAt or ((field.untilAt or 0) - 0.8)) - now
                if context.spawnSafe(math.max(passIn + (config.gildedFireSpawnMargin or 1.2), 0)) then
                    return true -- D-100: protected past the pass - on to the boss, not into the gap
                end
            end
            if name == "gilded firewall gap" then
                -- D-067: only while there is time to dodge AND still reach the gap (its distance at our speed)
                local left = (field.passAt or ((field.untilAt or 0) - 0.8)) - now -- D-082: the live pass time
                local prim = context.BB and context.BB.primary
                if config.gildedCometFirst ~= false and not (config.gildedFireOrbNoEscape ~= false and config.gildedOrbGuard ~= false)
                    and context.BB and context.BB.lethal and prim and prim.box -- D-099: the red-orb guard owns orbs
                    and tostring(prim.box.name) == "dracani comet" and left > (config.gildedCometWallSpare or 0.5) then
                    return true -- D-082: a red orb about to hit is dodged first (it stuns), the wall still 0.5 s+ away
                end
                local spot = hazardReader.safeSpots and hazardReader.safeSpots[1]
                local travel = 0
                pcall(function()
                    local character = localPlayer.Character
                    local hum = character and character:FindFirstChildOfClass("Humanoid")
                    local root = hum and hum.RootPart
                    if root and spot then
                        local dx, dz = spot.x - root.Position.X, spot.z - root.Position.Z
                        local speed = math.max(hum.WalkSpeed * (context.speedMul and context.speedMul() or 1), 16)
                        travel = math.max(math.sqrt(dx * dx + dz * dz) - (spot.r or 6), 0) / speed
                    end
                end)
                return left - travel > (config.gildedFireSpare or 1.0) and left > (config.gildedFireHold or 1.2)
            end
            return false
        end
        context.safeRoute = function(pos, goalX, goalZ, speed, now, directOnly, opts) -- D-061: a way clear of every attack
            local fresh, freshR = opts and opts.fresh, opts and opts.freshR or 8 -- D-074 (boss 2 orb): our own fresh circle
            local skip = fresh and function(x)
                return x.name == "secondbosspassivecircle" and now - (x.spawn or x.from or now) < fresh
                    and x.cx ~= nil and (x.cx - pos.X) ^ 2 + (x.cz - pos.Z) ^ 2 < freshR * freshR
            end or nil
            if not (context.BB and context.BB.ringClear) then
                return nil
            end
            local ownTrail = hazardReader.gildedOn and context.gildedOwnTrailPts and context.gildedOwnTrailOn
                and context.gildedOwnTrailOn()
            local function leg(ax, az, bx, bz, d0, out)
                local dx, dz = bx - ax, bz - az
                local L = math.sqrt(dx * dx + dz * dz)
                local n = math.max(1, math.ceil(L / 4))
                for i = 1, n do
                    out[#out + 1] = { x = ax + dx * i / n, z = az + dz * i / n, d = d0 + L * i / n }
                end
                return d0 + L
            end
            local function passiveOk(pts)
                for _, c in ipairs(hazardReader.craggPassive or {}) do
                    if now - c.at < (config.gildedPassiveLife or 12.3)
                        and not (fresh and now - c.at < fresh and (c.x - pos.X) ^ 2 + (c.z - pos.Z) ^ 2 < freshR * freshR) then
                        for _, q in ipairs(pts) do
                            if (q.x - c.x) ^ 2 + (q.z - c.z) ^ 2 < (config.gildedPassiveClearR or 17) ^ 2 then
                                return false
                            end
                        end
                    end
                end
                return true
            end
            local tetherSegs = hazardReader.gildedTetherSegs and hazardReader.gildedTetherSegs() -- D-120 (boss 2)
            local function tetherOk(pts) -- every point clear of another player's armed tether when we pass it
                if not tetherSegs then
                    return true
                end
                local keep, v = config.gildedTetherKeep or 4.5, math.max(speed or 16, 4)
                for _, q in ipairs(pts) do
                    if hazardReader.gildedTetherDist(q.x, q.z, q.d / v, tetherSegs) < keep then
                        return false
                    end
                end
                return true
            end
            local best, bestLen
            local function try(vx, vz)
                local pts = {}
                local d = vx and leg(pos.X, pos.Z, vx, vz, 0, pts) or 0
                local total = leg(vx or pos.X, vz or pos.Z, goalX, goalZ, d, pts)
                if (bestLen and total >= bestLen) or not passiveOk(pts) or not tetherOk(pts) then
                    return
                end
                if ownTrail and context.gildedOwnTrailPts(pts, speed, now) then
                    return -- D-111 (boss 1): back through our own trail (its squares of the last ~0.4 s are not down yet)
                end
                local ok, clear = pcall(context.BB.ringClear, pos, pts, speed, now, skip)
                if ok and clear then
                    best, bestLen = vx and Vector3.new(vx, pos.Y, vz) or Vector3.new(goalX, pos.Y, goalZ), total
                end
            end
            try(nil, nil)
            if best or directOnly then
                return best, bestLen
            end
            for k = 0, 11 do
                local a = k * math.pi / 6
                for _, rr in ipairs({ 14, 26 }) do
                    try(pos.X + math.cos(a) * rr, pos.Z + math.sin(a) * rr)
                end
            end
            return best, bestLen
        end
        local function smashPolar(geo, x, z)
            local dx, dz = x - geo.cx, z - geo.cz
            return math.sqrt(dx * dx + dz * dz), math.deg(math.atan2(dx * geo.wx + dz * geo.wz, dx * geo.ux + dz * geo.uz))
        end
        local function smashPoint(geo, r, deg)
            local a = math.rad(deg)
            return geo.cx + geo.ux * r * math.cos(a) + geo.wx * r * math.sin(a), geo.cz + geo.uz * r * math.cos(a) + geo.wz * r * math.sin(a)
        end
        context.smashClamp = function(x, z) -- D-061: the nearest point inside the hammer's safe band
            local geo = hazardReader.smashGeo
            if not geo or os.clock() > (geo.untilAt or 0) then
                return nil
            end
            if geo.free then -- D-066: the warning's outline - stay on uncovered ground
                if geo.free(x, z) then
                    return x, z
                end
                for d = 3, 24, 3 do
                    for k = 0, 15 do
                        local a = k * math.pi / 8
                        local px, pz = x + math.cos(a) * d, z + math.sin(a) * d
                        if geo.free(px, pz) then
                            return px, pz
                        end
                    end
                end
                return nil
            end
            local r, deg = smashPolar(geo, x, z)
            r = math.clamp(r, geo.rlo, geo.rhi)
            local span = (geo.hi - geo.lo) % 360
            local rel = (deg - geo.lo) % 360
            if rel > span then
                deg = ((rel - span) <= (360 - rel)) and geo.hi or geo.lo
            end
            return smashPoint(geo, r, deg)
        end
        context.smashSpotFree = function(x, z) -- D-061: the nearest band point not inside a live passive circle
            local geo = hazardReader.smashGeo
            if not geo then
                return nil
            end
            local function free(px, pz)
                for _, c in ipairs(hazardReader.craggPassive or {}) do
                    if os.clock() - c.at < (config.gildedPassiveLife or 12.3) and (px - c.x) ^ 2 + (pz - c.z) ^ 2 < (config.gildedPassiveClearR or 17) ^ 2 then
                        return false
                    end
                end
                return true
            end
            if geo.free then -- D-066: uncovered ground, out of the passive circles - the nearest
                if free(x, z) and geo.free(x, z) then
                    return x, z
                end
                for d = 3, 36, 3 do
                    for k = 0, 15 do
                        local a = k * math.pi / 8
                        local px, pz = x + math.cos(a) * d, z + math.sin(a) * d
                        if free(px, pz) and geo.free(px, pz) then
                            return px, pz
                        end
                    end
                end
                return nil
            end
            if free(x, z) then
                return x, z
            end
            local bestX, bestZ, bestD
            local span = (geo.hi - geo.lo) % 360
            for step = 0, math.floor(span / 6) do
                local deg = geo.lo + step * 6
                for r = geo.rlo, geo.rhi, 3 do
                    local px, pz = smashPoint(geo, r, deg)
                    if free(px, pz) then
                        local d = (px - x) ^ 2 + (pz - z) ^ 2
                        if not bestD or d < bestD then
                            bestX, bestZ, bestD = px, pz, d
                        end
                    end
                end
            end
            return bestX, bestZ
        end
        context.gildedStairs = function(pos) -- D-055: the stairs room after the second boss (all recordings)
            return pos ~= nil and pos.X >= (config.gildedStairsX1 or 1040) and pos.X <= (config.gildedStairsX2 or 1240)
                and pos.Z >= (config.gildedStairsZ1 or -760) and pos.Z <= (config.gildedStairsZ2 or -530)
        end
        context.gildedCoverage = function() -- D-054: mobs of the nearest mob's room the landing covers / within 110
            local character = localPlayer.Character
            local root = character and character:FindFirstChild("HumanoidRootPart")
            if not root then
                return 0, 0, math.huge, nil, 0
            end
            local nearestD, folder = math.huge, nil
            for _, enemy in ipairs(hazardReader.enemies or {}) do
                if not enemy.isBoss and enemy.humanoid and enemy.humanoid.Health > 0 and enemy.root and enemy.root.Parent and enemy.model then
                    local d = (enemy.root.Position - root.Position).Magnitude
                    if d < nearestD then
                        nearestD, folder = d, enemy.model.Parent
                    end
                end
            end
            if not folder then
                return 0, 0, math.huge, nil, 0
            end
            local place, radius = 40, 47.5
            if context.aoeLanding then
                local okLand, p, r = pcall(context.aoeLanding)
                if okLand and p and r then
                    place, radius = p, r
                end
            end
            local look = root.CFrame.LookVector
            local ll = math.max(math.sqrt(look.X * look.X + look.Z * look.Z), 0.1)
            local lx, lz = root.Position.X + look.X / ll * place, root.Position.Z + look.Z / ll * place
            local cov, tot, far = 0, 0, 0
            for _, enemy in ipairs(hazardReader.enemies or {}) do
                if not enemy.isBoss and enemy.model and enemy.model.Parent == folder and enemy.humanoid and enemy.humanoid.Health > 0
                    and enemy.root and enemy.root.Parent then
                    local p = enemy.root.Position
                    local d = math.sqrt((p.X - root.Position.X) ^ 2 + (p.Z - root.Position.Z) ^ 2)
                    if d <= (config.gildedGroupR or 110) then
                        tot += 1
                        far = math.max(far, d)
                        if (p.X - lx) ^ 2 + (p.Z - lz) ^ 2 <= (radius - (config.gildedMobCastInset or 6)) ^ 2 then
                            cov += 1
                        end
                    end
                end
            end
            return cov, tot, nearestD, folder.Parent, far
        end
        context.castWouldMissMobs = function() -- D-048: mob fights only (no boss near); no waiting, just no wasted cast
            local character = localPlayer.Character
            local root = character and character:FindFirstChild("HumanoidRootPart")
            if not root or (context.bossAliveNear and context.bossAliveNear()) then
                return false
            end
            local place, radius = 40, 47.5
            if context.aoeLanding then
                local okLand, p, r = pcall(context.aoeLanding)
                if okLand and p and r then
                    place, radius = p, r
                end
            end
            local look = root.CFrame.LookVector
            local ll = math.sqrt(look.X * look.X + look.Z * look.Z)
            if ll < 0.1 then
                return false
            end
            local lx, lz = root.Position.X + look.X / ll * place, root.Position.Z + look.Z / ll * place
            -- D-136: room 9's top - after the 1C gate let our first cast go this tick, its aim / D-119 decided the facing; the
            -- hold here refused 8 late accounts in range just after the wake (5-6 of 8 in the landing), and faceTick never
            -- turns to this rule's other way, so it could only run out while the lanes took them away
            local topGo = runtimeState.c1TopGoAt ~= nil and os.clock() - runtimeState.c1TopGoAt < 0.1
            if hazardReader.gildedOn and config.gildedCastCoverage ~= false and not topGo then
                -- D-072 (mob fights): not a cast that covers few of the group while another way from here, or a closer
                -- spot, would cover more - at most 1.2 s of waiting (no damage lost), never with the buff running out
                local mobs = {}
                for _, enemy in ipairs(hazardReader.enemies or {}) do
                    if not enemy.isBoss and enemy.humanoid and enemy.humanoid.Health > 0 and enemy.root and enemy.root.Parent then
                        local q = enemy.root.Position
                        if (q.X - root.Position.X) ^ 2 + (q.Z - root.Position.Z) ^ 2 <= 100 * 100 then
                            mobs[#mobs + 1] = { q.X, q.Z, enemy.extent or 2 }
                        end
                    end
                end
                if #mobs >= 2 then
                    local function count(cx, cz)
                        local c = 0
                        for _, m in ipairs(mobs) do
                            if (m[1] - cx) ^ 2 + (m[2] - cz) ^ 2 <= (radius + m[3]) ^ 2 then
                                c += 1
                            end
                        end
                        return c
                    end
                    local cur, best = count(lx, lz), 0
                    for k = 0, 35 do
                        local a = k * math.pi / 18
                        best = math.max(best, count(root.Position.X + math.cos(a) * place, root.Position.Z + math.sin(a) * place))
                    end
                    local now = os.clock()
                    local seen = hazardReader.buffHolderSeenAt
                    local buffLow = seen and now - seen > (config.gildedBuffLife or 5.3) - 1.5
                    local poor = (cur < #mobs * (config.gildedCastShare or 0.75) and best > cur)
                        or best < #mobs * (config.gildedCastReach or 0.6)
                    if poor and not buffLow then
                        local since = runtimeState.castHoldSince
                        if not since or now - since > 3 then
                            runtimeState.castHoldSince = now
                            since = now
                        end
                        if now - since < (config.gildedCastHoldMax or 1.2) then
                            return true
                        end
                    else
                        runtimeState.castHoldSince = nil
                    end
                end
            end
            local near = false
            for _, enemy in ipairs(hazardReader.enemies or {}) do
                if not enemy.isBoss and enemy.humanoid and enemy.humanoid.Health > 0 and enemy.root and enemy.root.Parent then
                    local ex, ez = enemy.root.Position.X, enemy.root.Position.Z
                    if (ex - lx) ^ 2 + (ez - lz) ^ 2 <= (radius + (enemy.extent or 2)) ^ 2 then
                        return false -- at least one mob is in the landing area
                    end
                    if (ex - root.Position.X) ^ 2 + (ez - root.Position.Z) ^ 2 <= (place + radius + 20) ^ 2 then
                        near = true
                    end
                end
            end
            return near
        end
        context.notFacingBoss = function() -- D-044: a live boss within 160 studs and the character not facing it
            local character = localPlayer.Character
            local root = character and character:FindFirstChild("HumanoidRootPart")
            if not root then
                return false
            end
            if context.lookAwayLive and context.lookAwayLive(config.lookAwayCastLead or 0.8) then -- D-054: 0.8 s before the turn too (D-160: not while protected)
                return true -- looking away from a Blinding Blast
            end
            local best, bestD
            for _, enemy in ipairs(hazardReader.enemies or {}) do
                if enemy.isBoss and enemy.humanoid and enemy.humanoid.Health > 0 and enemy.root and enemy.root.Parent then
                    local d = (enemy.root.Position - root.Position).Magnitude
                    if d <= (config.bossFaceRange or 160) and (not bestD or d < bestD) then
                        best, bestD = enemy, d
                    end
                end
            end
            if not best then
                return false
            end
            local look = root.CFrame.LookVector
            local bx, bz = best.root.Position.X - root.Position.X, best.root.Position.Z - root.Position.Z
            local bl, ll = math.sqrt(bx * bx + bz * bz), math.sqrt(look.X * look.X + look.Z * look.Z)
            if bl < 1 or ll < 0.1 then
                return false
            end
            return (look.X * bx + look.Z * bz) / (bl * ll) < math.cos(math.rad(config.bossFaceTol or 35))
        end
        local function bossNear(vector) -- D-099: a live boss within gildedClearResetBossR of us
            local R = config.gildedClearResetBossR or 120
            for _, enemy in ipairs(hazardReader.enemies or {}) do
                if enemy.isBoss and enemy.humanoid and enemy.humanoid.Health > 0 and enemy.root and enemy.root.Parent then
                    local q = enemy.root.Position
                    if (q.X - vector.X) ^ 2 + (q.Z - vector.Z) ^ 2 < R * R then
                        return true
                    end
                end
            end
            return false
        end
        local function partyMembers() -- D-099: the party list's enabled non-leech accounts, with their Player (or nil)
            local okL, d = pcall(function()
                return context.AF and context.AF.load()
            end)
            if not okL or type(d) ~= "table" or d.on ~= true or type(d.accounts) ~= "table" then
                return nil
            end
            local out, players = {}, game:GetService("Players"):GetPlayers()
            for _, acc in ipairs(d.accounts) do
                if type(acc) == "table" and acc.enabled ~= false and acc.role ~= "leech" and acc.name then
                    local pl
                    for _, q in ipairs(players) do
                        if string.lower(q.Name) == string.lower(tostring(acc.name)) then
                            pl = q
                            break
                        end
                    end
                    out[#out + 1] = { acc = acc, player = pl }
                end
            end
            return out
        end
        context.gildedAggro = function() -- D-099: the aggro account, once every party account is in the server
            if config.gildedAggro == false or not hazardReader.gildedOn or (context.gilded1COn and context.gilded1COn() and not (context.bossAliveNear and context.bossAliveNear())) then -- D-109 / D-110
                return nil
            end
            local members = partyMembers()
            if not members or #members < 2 then
                return nil
            end
            local agg
            for _, m in ipairs(members) do
                if not m.player then
                    return nil -- not every account is in the game yet
                end
                if m.acc.aggro == true then
                    agg = m.player
                end
            end
            local ch = agg and agg.Character
            local root = ch and ch:FindFirstChild("HumanoidRootPart")
            local hum = ch and ch:FindFirstChildOfClass("Humanoid")
            if not (root and hum and hum.Health > 0) then
                if config.gildedAggroDeadFallback == false and root and agg ~= localPlayer then
                    return { me = false, root = root, name = agg.Name, dead = true } -- D-100: supports stay out
                end
                return nil
            end
            return { me = agg == localPlayer, root = root, name = agg.Name }
        end
        context.gildedLeader = function() -- D-104: the aggro account if set, else the first party account by name
            local ag = context.gildedAggro and context.gildedAggro()
            if ag then
                return ag
            end
            local members = partyMembers()
            if not members or #members < 2 then
                return nil
            end
            local pick
            for _, m in ipairs(members) do
                local ch = m.player and m.player.Character
                local r = ch and ch:FindFirstChild("HumanoidRootPart")
                local h = ch and ch:FindFirstChildOfClass("Humanoid")
                if r and h and h.Health > 0 and (not pick or string.lower(m.player.Name) < string.lower(pick.player.Name)) then
                    pick = { player = m.player, root = r }
                end
            end
            return pick and { me = pick.player == localPlayer, root = pick.root, name = pick.player.Name } or nil
        end
        context.gildedStackNow = function() -- D-102/D-104: the leader when the room in play is a stack room (all mob rooms)
            local ag = context.gildedLeader and context.gildedLeader()
            if not ag or ag.dead or config.gildedStack == false or (context.gilded1COn and context.gilded1COn() and not (context.bossAliveNear and context.bossAliveNear())) then -- D-109 / D-110
                return nil
            end
            local rooms = config.gildedStackRooms or {} -- D-107: no stack (per-batch engagement instead)
            local me = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
            if not me then
                return nil
            end
            local best, bd = nil, (config.gildedStackNear or 140) ^ 2
            for _, enemy in ipairs(hazardReader.enemies or {}) do
                if not enemy.isBoss and enemy.humanoid and enemy.humanoid.Health > 0 and enemy.root and enemy.root.Parent and enemy.model then
                    local q = enemy.root.Position
                    local d = (q.X - me.Position.X) ^ 2 + (q.Z - me.Position.Z) ^ 2
                    if d < bd then
                        best, bd = enemy, d
                    end
                end
            end
            local folder = best and best.model.Parent
            local room = folder and folder.Parent
            if room and rooms[room.Name] then
                return ag
            end
            return nil
        end
        context.gildedAggroSupport = function() -- D-100: true for a non-aggro account while the aggro account plays
            local ag = context.gildedAggro and context.gildedAggro()
            return ag ~= nil and not ag.me
        end
        local function readyStamp(tag, name)
            return ("Aur_Hub/ready_%s_%s_%s.txt"):format(tostring(game.JobId), tostring(tag), tostring(name))
        end
        local function selfReady(now, minLeft)
            local okR, eReady = pcall(context.attackReady)
            if not (okR and eReady) and context.nextCastIn then -- D-105: the walk in covers the last second
                local okN, left = pcall(context.nextCastIn)
                if okN and type(left) == "number" and left <= (config.gildedReadyLead or 1.0) then
                    okR, eReady = true, true
                end
            end
            local buffOk = true
            if context.buffState then
                local okB, bst, _, left = pcall(context.buffState, now)
                if okB and (bst == "gap" or bst == "up" and type(left) == "number" and left < (minLeft or config.gildedGatherBuffLeft or 3)) then
                    buffOk = false
                end
            end
            return okR and eReady and buffOk
        end
        local function groupAt(tag, spot, members, now, slack, minLeft, skipDead)
            -- D-104: count who is stacked at the spot and whose ready stamp is fresh; stamp ourselves when ready there
            -- D-113 (1C): skipDead - a dead teammate (respawning 7.1-7.3 s, longer than the check) is not waited for, nor
            -- its stamp counted; one alive is, however far (the cap ends that wait)
            local here, loaded, nReady, out = 0, 0, 0, {}
            for _, m in ipairs(members) do
                local c = m.player and m.player.Character
                local r = c and c:FindFirstChild("HumanoidRootPart")
                if r then
                    local hm = skipDead and m.player ~= localPlayer and c:FindFirstChildOfClass("Humanoid")
                    if hm and hm.Health <= 0 then
                        out[m] = true
                    else
                        loaded += 1
                        if math.sqrt((r.Position.X - spot.X) ^ 2 + (r.Position.Z - spot.Z) ^ 2) <= slack then
                            here += 1
                        end
                    end
                end
            end
            local meReady = selfReady(now, minLeft)
            if type(readfile) ~= "function" or type(writefile) ~= "function" or config.gildedGatherReady == false then
                return here, loaded, here, meReady
            end
            local nowS = contextWorkspace:GetServerTimeNow()
            if meReady then
                pcall(writefile, readyStamp(tag, localPlayer.Name), tostring(nowS))
            end
            for _, m in ipairs(members) do
                local name = not out[m] and (m.player and m.player.Name or m.acc.name) or nil
                local okF, v = pcall(function()
                    local pth = readyStamp(tag, name)
                    if type(isfile) == "function" and not isfile(pth) then
                        return nil
                    end
                    return tonumber(readfile(pth))
                end)
                if okF and v and nowS - v < (config.gildedGatherReadyFresh or 1.0) then
                    nReady += 1
                end
            end
            return here, loaded, nReady, meReady
        end
        local function holdBuff()
            runtimeState.holdBuffUntil = os.clock() + 0.5 -- D-104: Enhanced Inner Focus is saved for the entry
        end
        local function wallSpot(centre, dir, fallback, y, off)
            local spot = Vector3.new(fallback.X, y, fallback.Z)
            pcall(function()
                local hit = contextWorkspace:Raycast(Vector3.new(centre.X, y + 2, centre.Z), dir * 90, contextRaycastParams())
                if hit and hit.Instance and hit.Instance.CanCollide then
                    spot = Vector3.new(hit.Position.X, y, hit.Position.Z) - dir * off
                end
            end)
            return spot
        end
        context.gildedPreStart = function(vector, now, humanoid, zF)
            -- D-104 (user): before START every account stacks against the platform's exit wall, loaded and ready
            if not hazardReader.gildedOn or config.gildedPreStart == false then
                return false
            end
            local started = contextWorkspace:FindFirstChild("dungeonStarted")
            if not (started and started:IsA("ValueBase")) or started.Value then
                return false
            end
            local members = partyMembers()
            if not members or #members < 2 then
                return false
            end
            local st = runtimeState.preStart
            if not st or st.job ~= game.JobId then
                local c = config.gildedStartCentre or Vector3.new(-100, vector.Y, 3)
                st = { job = game.JobId, spot = wallSpot(c, config.gildedStartDir or Vector3.new(1, 0, 0),
                    config.gildedStartSpot or Vector3.new(-50, vector.Y, 1), vector.Y, config.gildedStartWallOff or 3) }
                runtimeState.preStart = st
            end
            holdBuff()
            runtimeState.preWalk = { at = os.clock(), done = true, active = false } -- D-105: START waits for it
            local spot = st.spot
            local toSpot = math.sqrt((vector.X - spot.X) ^ 2 + (vector.Z - spot.Z) ^ 2)
            if toSpot > 3 then
                g(humanoid, zF, Vector3.new(spot.X, vector.Y, spot.Z), e(), 1)
                contextSetState(("pre-start: to the start wall (%.0f studs, at %.0f, %.0f)"):format(toSpot, spot.X, spot.Z))
                return true
            end
            local here, loaded, nReady, meReady = groupAt("start", spot, members, now, config.gildedGatherSlack or 8)
            st.ready = nReady >= #members and here >= #members
            contextReleaseMover(humanoid, zF)
            contextSetState(("pre-start: at the start wall (%.0f, %.0f) - %d of %d here, %d loaded, %d ready%s"):format(
                spot.X, spot.Z, here, #members, loaded, nReady, meReady and "" or " - not me yet")
                .. " | START: " .. tostring(runtimeState.startWhy or "the host decides"))
            return true
        end
        context.preStartReady = function()
            -- D-104: for the host's START - nil without a party list, else whether everyone is stacked and ready
            local members = partyMembers()
            if not hazardReader.gildedOn or config.gildedPreStart == false or not members or #members < 2 then
                return nil
            end
            local st = runtimeState.preStart
            if not st then
                return false
            end
            local here, _, nReady = groupAt("start", st.spot, members, os.clock(), config.gildedGatherSlack or 8)
            return here >= #members and nReady >= #members, here, nReady, #members
        end
        context.gildedPartyGather = function(vector, now, humanoid, zF)
            -- D-099/D-103/D-104 (user): before every mob room all accounts stack at one spot, ready, then go in together
            if not hazardReader.gildedOn or config.gildedPartyGather == false then
                return false
            end
            local dungeon = contextWorkspace:FindFirstChild("dungeon")
            if not dungeon then
                return false
            end
            local spots = config.gildedGatherSpots or {
                room1 = "wall",
                room2 = Vector3.new(187, 33, 1), -- D-106: 20 back (the stack was hit at 104-118 from the pack)
                room4 = Vector3.new(638, 87, 66), -- D-106: 20 back
                room5 = Vector3.new(642, 87, 90),
                room6 = Vector3.new(658, 88, -102),
                room8 = Vector3.new(917, 52, -391),
            } -- D-105: room9 (stairs) has no gather - the aggro account takes the Warriors
            -- the room in play: the one of the nearest live mob within sight (each room's enemyFolder)
            local room, folder, bd = nil, nil, (config.gildedGatherSee or 130) ^ 2
            for name in pairs(spots) do
                local rm = dungeon:FindFirstChild(name)
                local ef = rm and rm:FindFirstChild("enemyFolder")
                for _, m in ipairs(ef and ef:GetChildren() or {}) do
                    local h = m:FindFirstChildOfClass("Humanoid")
                    local r = m:FindFirstChild("HumanoidRootPart") or (m:IsA("Model") and m.PrimaryPart)
                    if h and r and h.Health > 0 then
                        local d = (r.Position.X - vector.X) ^ 2 + (r.Position.Z - vector.Z) ^ 2
                        if d < bd then
                            room, folder, bd = rm, ef, d
                        end
                    end
                end
            end
            if not room then
                return false
            end
            local all = runtimeState.roomGather
            if not all or all.dungeon ~= dungeon then
                all = { dungeon = dungeon, rooms = {} }
                runtimeState.roomGather = all
            end
            local st = all.rooms[room.Name]
            if not st then
                st = {}
                all.rooms[room.Name] = st
            end
            runtimeState.partyGather = st -- (the room in play; tests and the HUD read it)
            if st.released then
                return false
            end
            local mobs, hurt = {}, false
            for _, m in ipairs(folder:GetChildren()) do
                local h = m:FindFirstChildOfClass("Humanoid")
                local r = m:FindFirstChild("HumanoidRootPart") or (m:IsA("Model") and m.PrimaryPart)
                if h and r and h.Health > 0 then
                    mobs[#mobs + 1] = r.Position
                    if h.Health < h.MaxHealth then
                        hurt = true
                    end
                end
            end
            if #mobs == 0 then
                return false
            end
            local function nearest(q)
                local b = math.huge
                for _, m in ipairs(mobs) do
                    b = math.min(b, math.sqrt((m.X - q.X) ^ 2 + (m.Z - q.Z) ^ 2))
