                local was = now - (st.lastHpAt or -math.huge) < 0.5 and st.lastHp or nil
                st.lastHp, st.lastHpAt = hp, now
                if was and humanoid and was - hp >= humanoid.MaxHealth * (config.gildedGatherHitLeave or 0.35) then
                    return release("we are being hit")
                end
