                local dl = math.max(math.sqrt(dx * dx + dz * dz), 1)
                local leg = math.floor(now / (config.gildedGatherSwayLeg or 0.7)) % 2 == 0 and 1 or -1
                local w = config.gildedGatherSway or 5
