        context.gildedStunReset = function(vector, now, humanoid)
            -- D-107 (user, boss 3): trapped (the S-shape circle's stun) and a red orb about to pass within its trigger: reset,
            -- so it does not go off on the party. Not on an orb alone, not on a short stop.
            local orbs = hazardReader.redOrbs
            if not (hazardReader.gildedOn and config.gildedStunReset ~= false and orbs and #orbs > 0 and humanoid and humanoid.Health > 0) then
                return false
            end
            if #game:GetService("Players"):GetPlayers() < 2 and not config.gildedStunResetSolo then
                return false
            end
            local sp = contextWorkspace:FindFirstChild("stunParts")
            local track = runtimeState.stunTrack
            if not (sp and sp:FindFirstChild(localPlayer.Name)) then
                runtimeState.stunTrack = nil
                return false
            end
            if not track then
                runtimeState.stunTrack = { x = vector.X, z = vector.Z, at = now }
                return false
            end
            if math.sqrt((vector.X - track.x) ^ 2 + (vector.Z - track.z) ^ 2) >= (config.gildedStunStill or 1.5) then
                runtimeState.stunTrack = { x = vector.X, z = vector.Z, at = now }
                return false
            end
            if now - track.at < (config.gildedStunStillFor or 0.4) or now - (runtimeState.stunResetAt or -math.huge) < 10 or (context.b1NoReset and context.b1NoReset()) then -- D-176
                return false
            end
            local look, R = config.gildedStunResetLook or 0.9, config.gildedStunResetR or 9
            for _, o in ipairs(orbs) do
                local rx, rz = vector.X - o.ox, vector.Z - o.oz
                local along, across = rx * o.dx + rz * o.dz, -rx * o.dz + rz * o.dx
                local a0 = math.max((now - o.from) * o.speed, 0)
                local a1 = math.min((now + look - o.from) * o.speed, o.length)
                if a1 >= 0 and a0 <= o.length then
                    local ac = math.clamp(along, a0, math.max(a1, a0))
                    if math.sqrt((along - ac) ^ 2 + across * across) < R then
                        runtimeState.stunResetAt = now
                        runtimeState.selfResetAt = now
                        contextSetState("RED ORB: stunned in its path - reset so it does not go off on the party")
                        contextLogT("reset", 1, "Brain", "stunned with a red orb about to pass - resetting")
                        pcall(function()
                            humanoid.Health = 0
                        end)
                        pcall(function()
                            humanoid:ChangeState(Enum.HumanoidStateType.Dead)
                        end)
                        task.delay(0.5, function()
                            pcall(function()
                                local character = localPlayer.Character
                                local h2 = character and character:FindFirstChildOfClass("Humanoid")
                                if h2 and h2.Health > 0 then
                                    character:BreakJoints()
                                end
                            end)
                        end)
                        return true
                    end
                end
            end
            return false
        end
        context.gildedBatchHold = function() -- D-108: a pending batch near us - nobody fires at it before its release
