                { room = "room1", x = 126, z = 0, r = 30 },
                { room = "room2", x = 313, z = 0, r = 30 },
                { room = "room4", x = 699, z = 179, r = 28, name = "A" },
                { room = "room4", x = 744, z = 274, r = 32, name = "B" },
                { room = "room5", x = 594, z = -12, r = 42 },
                { room = "room6", x = 742, z = -167, r = 36 },
                { room = "room8", x = 988, z = -467, r = 38 },
                { room = "room9", x = 1095, z = -600, r = 50, name = "stair Warriors" },
