                st.holdFireAt = nil
                runtimeState.castGate = ("released %s %s: %s"):format(B.room, tostring(B.name or ""), why) -- D-108: recorded
                contextLogT("party", 1, "Brain", ("%s %s: in (%s)"):format(B.room, tostring(B.name or ""), why))
                return false
            end
            if hurt then
                return release("the batch is fighting")
