            end
            holdBuff() -- D-108: Enhanced Inner Focus saved for the release (no rushing ahead on its speed)
            if myC <= (config.gildedHoldFireR or 110) then
                st.holdFireAt = now -- D-108: nobody fires at a batch before its release (the first cast released all)
            end
            local engageR = config.gildedEngageR or 44
            if myC > (config.gildedEngageCatch or 85) then
                return false -- still on the way (normal pathing)
            end
            local members = partyMembers()
            if not members or #members < 2 then
                return release("no party list")
