                local ch = m.player and m.player.Character
                local h = ch and ch:FindFirstChildOfClass("Humanoid")
                local r = ch and ch:FindFirstChild("HumanoidRootPart")
                -- D-108: living accounts within 160 of the batch are waited for (a far respawn joins the fight later)
                if r and h and h.Health > 0
                    and math.sqrt((r.Position.X - cx) ^ 2 + (r.Position.Z - cz) ^ 2) <= (config.gildedEngageWaitFar or 160) then
