            -- our own point: on our side of the batch, 44 out (the stairs: on their centre line)
            local ux, uz = vector.X - cx, vector.Z - cz
            local ul = math.max(math.sqrt(ux * ux + uz * uz), 1)
            local px, pz = cx + ux / ul * engageR, cz + uz / ul * engageR
            if B.room == "room9" and config.gildedStairsMid ~= false then
                local ox, oz = config.gildedStairsX or 1103, config.gildedStairsZ or -604
                local sx, sz = config.gildedStairsUX or 0.71, config.gildedStairsUZ or -0.71
                local s = (px - ox) * sx + (pz - oz) * sz
                local l = math.clamp((px - ox) * -sz + (pz - oz) * sx, -(config.gildedStairsHalf or 6), config.gildedStairsHalf or 6)
                if s >= (config.gildedStairsFrom or -77) - 6 and s <= (config.gildedStairsTo or 89) + 6 then
                    px, pz = ox + sx * s - sz * l, oz + sz * s + sx * l
