        context.gildedStackEscort = function(vector, now, humanoid, zF)
            -- D-103 (stack room): the aggro account waits for the group (max 3 s) until the room's fight starts
            local ag = context.gildedStackNow and context.gildedStackNow()
            if not (ag and ag.me) or config.gildedStackEscort == false or (context.BB and context.BB.lethal) then
                return false
            end
            local best, bd = nil, math.huge
            for _, enemy in ipairs(hazardReader.enemies or {}) do
                if not enemy.isBoss and enemy.humanoid and enemy.humanoid.Health > 0 and enemy.root and enemy.root.Parent and enemy.model then
                    local q = enemy.root.Position
                    local d = (q.X - vector.X) ^ 2 + (q.Z - vector.Z) ^ 2
                    if d < bd then
                        best, bd = enemy, d
                    end
                end
            end
            local folder = best and best.model.Parent
            if not folder then
                return false
            end
            for _, m in ipairs(folder:GetChildren()) do
                local h = m:FindFirstChildOfClass("Humanoid")
                if h and h.Health > 0 and h.Health < h.MaxHealth then
                    return false -- the fight has started
                end
            end
            if context.BB and context.BB.wayClear then -- D-106: not standing in an attack while waiting
                local okW, clearW = pcall(context.BB.wayClear, vector, vector + Vector3.new(0.5, 0, 0), 1, now)
                if okW and clearW == false then
                    return false
                end
            end
