            if not es or es.folder ~= folder then
                es = { folder = folder, used = 0 }
                runtimeState.stackEscort = es
            end
            local members = partyMembers()
            local far = 0 -- D-106: how far the furthest teammate is BEHIND us (from the pack), not just away
            local mob = best.root.Position
            local myD = math.sqrt((mob.X - vector.X) ^ 2 + (mob.Z - vector.Z) ^ 2)
            for _, m in ipairs(members or {}) do
                local ch = m.player and m.player ~= localPlayer and m.player.Character
                local r = ch and ch:FindFirstChild("HumanoidRootPart")
                local h = ch and ch:FindFirstChildOfClass("Humanoid")
                if r and h and h.Health > 0 then
                    far = math.max(far, math.sqrt((r.Position.X - mob.X) ^ 2 + (r.Position.Z - mob.Z) ^ 2) - myD)
                end
            end
            if far <= (config.gildedStackLeash or 14) then
                es.last = nil
                return false
