                    return angles[(i - 1) % #angles + 1], i
                end
            end
            return nil
        end
        context.gildedB1OwnCircle = function(pos, speed, leftT, edgeIn, now)
            -- D-168 (user, 1C): our own green circle - the one in our quadrant (nearest the angle), not the one on her;
            -- nil when it is not reached in time or its way crosses our own beam's trail
            if config.gildedB1OwnCircle == false then
                return nil
            end
            local base = context.gildedB1QuadAngle()
            if not base then
                return nil
            end
            local K
            for _, en in ipairs(hazardReader.enemies or {}) do
