            for _, sp in ipairs(hazardReader.safeSpots or {}) do
                local dk = math.sqrt((sp.x - K.X) ^ 2 + (sp.z - K.Z) ^ 2)
                if dk > (config.gildedB1OwnCircleSkip or 25) then
                    local a = math.deg(math.atan2(sp.z - K.Z, sp.x - K.X))
                    local da = math.abs((a - base + 180) % 360 - 180)
                    if not bestA or da < bestA - 5 or math.abs(da - bestA) <= 5 and dk < bestD then
                        best, bestA, bestD = sp, da, dk
                    end
                end
            end
            if not best or bestA > (config.gildedB1OwnCircleArc or 60) then
                return nil
