            local d = math.sqrt((pos.X - best.x) ^ 2 + (pos.Z - best.z) ^ 2)
            local eta = math.max(d - math.max((best.r or 20) - edgeIn, 1), 0) / speed
            if eta > leftT then
                return nil
            end
            if context.gildedOwnTrailOn and context.gildedOwnTrailOn() and context.gildedOwnTrailHit
                and context.gildedOwnTrailHit(pos.X, pos.Z, best.x, best.z, speed, now) then
                return nil
            end
