            local base = context.gildedB1QuadAngle() or -132 -- D-168: on the quadrant circles (-132 / 110 / -57 / 56)
            local a = math.rad(base + (config.gildedB1QuadSway or 20) * math.sin(os.clock() * 2 * math.pi / (config.gildedB1QuadPeriod or 3)))
            local K = target.root.Position
            local R = config.gildedB1QuadR or 38
            local q = Vector3.new(K.X + math.cos(a) * R, pos.Y, K.Z + math.sin(a) * R)
            if context.gildedOwnTrailHit and context.gildedOwnTrailHit(pos.X, pos.Z, q.X, q.Z, 16, os.clock()) then
                return nil -- across our own beam's trail: the old strafe
            end
            runtimeState.b1Quad = { idx = idx, angle = base, at = os.clock() }
            return q, base
        end
        context.gildedB1VolleyReset = function(vector, now, humanoid)
            -- D-158 (user, 1C): after our 2nd Jade Rain on Kiryne, reset - the look-away attack passes while we are dead or
            -- protected, and the respawn (at her checkpoint, ~30 out) has the spells back for the finishing volley.
            -- 13:23 / 13:26: she is at 21-32% after the 2nd volley; every real hit at boss 1 came after it
            if not (hazardReader.gildedOn and config.gildedB1VolleyReset ~= false and context.gilded1COn and context.gilded1COn()) then
                return false
            end
            local st = runtimeState.b1Volley
            local function kiryne()
                for _, en in ipairs(hazardReader.enemies or {}) do
                    if en.isBoss and en.model and en.model.Name == "Archpriestess Kiryne" and en.humanoid and en.humanoid.Health > 0 then
                        return en
                    end
                end
                return nil
            end
            local boss = kiryne()
            if st and st.resetAt and st.resetAt > 0 and not st.logged and hazardReader.charAt and hazardReader.charAt > st.resetAt
                and humanoid and humanoid.Health > 0 then
                st.logged = true
                local after = boss and boss.humanoid.Health / math.max(boss.humanoid.MaxHealth, 1)
                contextLogT("reset", 1, "Brain", ("boss 1 volley reset: Kiryne %.0f%% before, %s after our respawn"):format(
                    (st.hpBefore or 0) * 100, after and ("%.0f%%"):format(after * 100) or "dead"))
            end
            local function partyBad()
                -- D-161 (user): all 4 in the server and alive - a teammate dead by its own volley reset (its stamp) is not
                -- a death; returns why not, or nil
                local members = partyMembers()
                local need = config.gildedB1VolleyParty or 4
                if not members or #members < need then
                    return ("%d of %d party accounts listed"):format(members and #members or 0, need), false
                end
                local nowS = contextWorkspace:GetServerTimeNow()
                for _, m in ipairs(members) do
                    if not m.player then
                        return tostring(m.acc and m.acc.name) .. " not in the server", false
                    end
                    local c = m.player.Character
                    local h = c and c:FindFirstChildOfClass("Humanoid")
                    if not (h and h.Health > 0) and m.player ~= localPlayer then
                        local okF, v = pcall(function()
                            local pth = readyStamp("b1reset", m.player.Name)
                            if type(isfile) == "function" and not isfile(pth) then
                                return nil
                            end
                            return tonumber(readfile(pth))
                        end)
                        if not (okF and v and nowS - v < (config.gildedB1VolleyStampFresh or 12)) then
                            return m.player.Name .. " died", true
                        end
                    end
                end
                return nil
            end
            if boss and st and st.model == boss.model and (st.casts or 0) >= 1 and not st.blocked
                and not (st.resetAt and st.resetAt ~= 0) then
                -- D-161: a death in this fight (from our 1st cast on her) - no volley reset in it
                local why, died = partyBad()
                if humanoid and humanoid.Health <= 0
                    or st.firstAt and hazardReader.charAt and hazardReader.charAt > st.firstAt then
                    why, died = "we died", true -- D-161b: a respawn since our 1st cast on her
                end
                if died then
                    st.blocked = why
                    contextLogT("reset", 1, "Brain", ("boss 1: no volley reset this fight - %s"):format(why))
                end
            end
            if not (boss and humanoid and humanoid.Health > 0) then
                return false
            end
            local clock = os.clock()
            if not st or st.model ~= boss.model then
                st = { model = boss.model, casts = 0, seenE = tonumber(runtimeState.lastE) or -math.huge }
                runtimeState.b1Volley = st
            end
            local lastE = tonumber(runtimeState.lastE) or -math.huge
            if lastE > st.seenE then
                st.seenE, st.casts, st.castAt = lastE, st.casts + 1, lastE
                st.firstAt = st.firstAt or lastE -- D-161b
            end
            if st.resetAt or st.casts < (config.gildedB1VolleyAfter or 2) or not st.castAt then
                return false
            end
            local since = clock - st.castAt
            if since < (config.gildedB1VolleyDelay or 1.2) then
                return false
            end
            local frac = boss.humanoid.Health / math.max(boss.humanoid.MaxHealth, 1)
            if since > (config.gildedB1VolleyLate or 4) or frac > (config.gildedB1VolleyMaxHp or 0.4) then
                st.resetAt = -1 -- this fight: no volley reset (too late for the look-away, or she is not low enough)
                contextLogT("reset", 1, "Brain", ("boss 1: no volley reset (Kiryne %.0f%%, %.1fs after our 2nd cast)"):format(frac * 100, since))
                return false
            end
            if context.b1NoReset and context.b1NoReset() then
                st.resetAt = -1 -- D-176 (user): no reset during her fight
                contextLogT("reset", 1, "Brain", "boss 1: no volley reset - no automatic reset while she is alive")
                return false
            end
            local bad = st.blocked or partyBad()
            if bad then
                st.resetAt = -1 -- D-161: not all 4 here and alive - no volley reset this fight
                contextLogT("reset", 1, "Brain", ("boss 1: no volley reset - %s"):format(bad))
                return false
            end
            pcall(function() -- D-161: the others count our death as a reset, not a loss
                if type(writefile) == "function" then
                    writefile(readyStamp("b1reset", localPlayer.Name), tostring(contextWorkspace:GetServerTimeNow()))
                end
            end)
            st.resetAt, st.hpBefore = clock, frac
            runtimeState.selfResetAt = now
            contextSetState(("boss 1: reset after our 2nd volley (Kiryne %.0f%%) - the look-away passes while we respawn"):format(frac * 100))
            contextLogT("reset", 1, "Brain", ("boss 1: reset after our 2nd volley (Kiryne %.0f%%)"):format(frac * 100))
            pcall(function()
                humanoid.Health = 0
            end)
            pcall(function()
                humanoid:ChangeState(Enum.HumanoidStateType.Dead)
            end)
            task.delay(0.5, function()
                pcall(function()
                    local character = game:GetService("Players").LocalPlayer.Character
                    local h2 = character and character:FindFirstChildOfClass("Humanoid")
                    if h2 and h2.Health > 0 then
                        character:BreakJoints()
                    end
                end)
            end)
            return true
        end
        context.gildedBossClearReset = function(vector, now, humanoid)
            -- D-097: after the last kill of the room before a boss, reset: the respawn is at the boss checkpoint (it switches
            -- <= 0.2 s after the last kill; respawn 7.1-7.3 s, ForceField 5.6-6.1 s), all accounts together
            if not hazardReader.gildedOn or config.gildedClearReset == false then
