            local rooms = config.gildedClearRooms or (context.gilded1COn and context.gilded1COn() and {
                -- D-109 (1C team mode, user): after rooms 2, 4 (both batches: 5 + 6), 6 and 9 (the top too), as the
                -- reference reset (respawns (487,89,1), (651,89,93), (836,52,-295), (1278,104,-809))
                room2 = { on = true, kills = 5, boss = "room3" },
