                -- D-157 (user): room 5 too, once all 9 of its mobs are dead (D-111: 9 in every recorded run)
                room5 = { on = config.gilded1CRoom5Reset ~= false, kills = 9, boss = "room6" },
                room6 = { on = true, kills = 8, boss = "room7" },
                -- D-221 (user: "it doesn't reset"): always: chasing the last Mages took one account to 59 from the checkpoint, under the 60 limit, so it walked into the last boss alone with no spells back (00:56)
                room9 = { on = true, kills = 15, boss = "bossRoom", always = config.gilded1CRoom9AlwaysReset ~= false },
                -- D-113 (user, a test): after boss 1 / boss 2 too. D-114: to their respawns as recorded, (650,91) and
                -- (967,-439) - the rooms' checkPoint parts are elsewhere (13:58: room 5's ~(700,-126), 223 from the boss-1
                -- respawn, so the landing check judged it a miss and the test stopped before boss 2)
                room3 = { on = config.gilded1CBossReset ~= false, kills = 1, boss = "room5", test = true,
                    spawn = config.gilded1CBossSpawn1 or { x = 650, z = 91 } },
                room7 = { on = config.gilded1CBossReset ~= false, kills = 1, boss = "room8", test = true,
                    spawn = config.gilded1CBossSpawn2 or { x = 967, z = -439 } },
            }) or {
                room2 = { on = true, kills = 5, boss = "room3" }, -- D-098 (user): on for boss 1
                room6 = { on = true, kills = 8, boss = "room7" }, -- D-098 (user): on for boss 2
                room9 = { on = true, kills = 15, boss = "bossRoom" },
            }
            local st = runtimeState.clearReset
            if not st or st.dungeon ~= dungeon then
                st = { dungeon = dungeon, seen = {}, n = {}, emptyAt = {}, done = {} }
                runtimeState.clearReset = st
            end
            local tst = st.test -- D-113: where the post-boss test's respawn went (a miss stops the test for this run)
            if tst and hazardReader.charAt and hazardReader.charAt > tst.at and humanoid and humanoid.Health > 0 then
                st.test = nil
                if now - hazardReader.charAt < 2 then
                    local off = math.sqrt((vector.X - tst.x) ^ 2 + (vector.Z - tst.z) ^ 2)
                    st.testOff = off > (config.gildedClearResetFar or 60) or nil
                    contextLogT("reset", 1, "Brain", ("%s: the post-boss test's respawn %d studs from its spawn%s"):format(
                        tst.room, math.min(off, 9999), st.testOff and " - no further test resets this run" or ""))
                end
            end
            for roomName, R in pairs(rooms) do
                local folder = R.on and not st.done[roomName] and dungeon:FindFirstChild(roomName)
                folder = folder and folder:FindFirstChild("enemyFolder")
                if folder then
                    st.seen[roomName] = st.seen[roomName] or {}
                    local seen, alive = st.seen[roomName], 0
                    for _, m in ipairs(folder:GetChildren()) do
                        local h = m:FindFirstChildOfClass("Humanoid")
                        if h then
                            if not seen[m] then
                                seen[m] = true
                                st.n[roomName] = (st.n[roomName] or 0) + 1
                            end
                            if h.Health > 0 then
                                alive += 1
                            end
                        end
                    end
                    if alive > 0 or (st.n[roomName] or 0) < (R.kills or 1) then
                        st.emptyAt[roomName] = nil -- a wave gap is not the clear: every mob of the room counted
                    else
                        st.emptyAt[roomName] = st.emptyAt[roomName] or now
                        local since = now - st.emptyAt[roomName]
                        if since > (config.gildedClearResetWithin or 3) then
                            st.done[roomName] = true -- too late (we may already stand at the boss): walk as before
                        elseif hazardReader.charAt and hazardReader.charAt >= st.emptyAt[roomName] - 0.2 then
                            st.done[roomName] = true -- D-100: respawned after the clear = already at the boss checkpoint
                        elseif since >= 0.3 and humanoid and humanoid.Health > 0 and not bossNear(vector) and (roomName == "room2" or not (context.b1NoReset and context.b1NoReset())) then -- D-176; D-205: she shows 0.13-0.60 s after room 2 clears, so D-176 cancelled this reset: it is before her fight
                            -- D-099: the next boss shows 0.13-0.60 s after the clear - only a boss near us blocks it, and
                            -- the spawn ForceField never does (it held acct1-12 past the boss's arrival)
                            local bossRoom = dungeon:FindFirstChild(R.boss or "")
                            local cp = bossRoom and bossRoom:FindFirstChild("checkPoint")
                            local far = math.huge
                            if cp and cp:IsA("BasePart") then
                                far = (Vector3.new(cp.Position.X, 0, cp.Position.Z) - Vector3.new(vector.X, 0, vector.Z)).Magnitude
                            end
                            st.done[roomName] = true
                            -- D-113 (the post-boss test): every account, near the checkpoint or not - the four respawn there
                            -- together with their spells back (12:29: one stood 22 from room 5's when Kiryne died); only
                            -- with the next checkpoint found, and while the test's respawns land on it
                            local spawn = R.test and R.spawn -- D-114: the respawn as recorded (the parts are not it)
                            if spawn then
                                far = math.sqrt((vector.X - spawn.x) ^ 2 + (vector.Z - spawn.z) ^ 2)
                            end
                            local test = spawn and not st.testOff
                            if R.test and not test then
                                contextLogT("reset", 1, "Brain", ("%s cleared: no post-boss test reset (%s)"):format(roomName,
                                    st.testOff and "a test respawn missed its spawn" or "no spawn known"))
                            elseif far > (config.gildedClearResetFar or 60) or test or R.always then
                                runtimeState.selfResetAt = now
                                if test then
                                    st.test = { room = roomName, at = now, x = spawn.x, z = spawn.z }
                                end
                                local toWhat = R.test and "next checkpoint (the post-boss test)" or "boss checkpoint"
                                contextSetState(("%s cleared: reset to the %s (%d studs)"):format(roomName, toWhat, math.min(far, 9999)))
                                contextLogT("reset", 1, "Brain", ("%s cleared - resetting to the %s (%d studs off)"):format(roomName, toWhat, math.min(far, 9999)))
                                pcall(function()
                                    humanoid.Health = 0
                                end)
                                pcall(function()
                                    humanoid:ChangeState(Enum.HumanoidStateType.Dead)
                                end)
                                task.delay(0.5, function()
                                    pcall(function()
                                        local character = game:GetService("Players").LocalPlayer.Character
                                        local h2 = character and character:FindFirstChildOfClass("Humanoid")
                                        if h2 and h2.Health > 0 then
                                            character:BreakJoints()
                                        end
                                    end)
                                end)
                                return true
                            end
                        end
                    end
                end
            end
            return false
        end
        -- D-109 (user): the Gilded Skies 1C team mode - each mob batch cleared in one ability cycle by the party's
        -- combined damage. Reference (three legit 1C runs, 4 players): every mob Jade Rain was cast running at full
        -- buffed speed straight at the pack (0-9 deg off its centre, 52-69 studs from it), 0.2-2.8 s after Enhanced
        -- Inner Focus; the packs died 0.6-1.4 s later. Only with the option on, in Gilded Skies, in mob encounters
        -- (no boss alive near): bosses, the start, other maps and the option off run as before
        context.c1Share = { at = -math.huge } -- (no new locals here: this function is at Luau's 200-local limit)
        context.gilded1CSelected = function() -- the option: one switch for every account on this PC, else this account's
            local now = os.clock()
            local sh = context.c1Share
            if now - sh.at > 2 then
                sh.at, sh.on = now, nil
                pcall(function()
                    if type(isfile) == "function" and isfile("Aur_Hub/configs/gilded1c_shared.json") then
                        local raw = tostring(readfile("Aur_Hub/configs/gilded1c_shared.json")):gsub("%s", "")
                        if raw == "on" then
                            sh.on = true
                        elseif raw == "off" then
                            sh.on = false
                        end
                    end
                end)
            end
            if sh.on ~= nil then
                return sh.on
            end
            return config.gilded1C == true
        end
        context.setGilded1C = function(on)
            config.gilded1C = on == true
            context.c1Share.on, context.c1Share.at = on == true, os.clock()
            if type(writefile) == "function" then
                pcall(writefile, "Aur_Hub/configs/gilded1c_shared.json", on == true and "on" or "off")
            end
            if context.saveConfig then
                pcall(context.saveConfig)
            end
        end
        context.gilded1CShareReset = function() -- re-read the shared switch now (tests, a file changed by hand)
            context.c1Share.at = -math.huge
        end
        context.gilded1COn = function()
            return hazardReader.gildedOn == true and context.gilded1CSelected()
        end
        context.gilded1CRefs = { -- the batches and where the reference opened on them (names, the recorder's comparisons)
            -- D-111: n = its mobs, by where each first stood (the same in every recorded run)
            { room = "room1", x = 126, z = 0, ox = 71, oz = 0, n = 5 },
            { room = "room2", x = 313, z = 0, ox = 251, oz = 0, n = 5 },
            { room = "room4", name = "A", x = 699, z = 179, ox = 666, oz = 122, n = 5 },
            { room = "room4", name = "B", x = 744, z = 274, ox = 720, oz = 220, n = 6 },
            -- D-117: room 5's aim (all of it in the landing either way) puts its far edge nearest the landing's centre
            { room = "room5", x = 594, z = -12, ox = 626, oz = 49, n = 9, aimEdge = true },
            -- D-135: room 6's ready check stands 72 from its nearest mob (the batch wakes as one with an account within ~66
            -- of a mob of it) and counts an account here within 6 of that (new_runs-14..25: "all 4 here" within 125 of
            -- the centre sent followers 9-24 behind into the first lanes; > 11 behind at the lane: late in 9 of 9)
            { room = "room6", x = 742, z = -167, ox = 684, oz = -136, n = 8, stageNear = 72, stageSlack = 6 },
            { room = "room8", x = 988, z = -467, ox = 949, oz = -421, n = 5 },
            -- D-114 (user): room 9's batches open on a share of them (a line on the stairs, Knights in front of the top)
            -- and the top comes after the stairs (6 Warriors in every recorded run)
            { room = "room9", name = "stairs", x = 1095, z = -600, ox = 1093, oz = -550, n = 6, share = 0.5 },
            -- D-115: the top's opening spot as the humans' full clear (1157,-693) and through it first: with the batch at rest
            -- the landing holds 7-8 of 8 there, 6 from (1166,-679), 5 where the bots cast (1166,-672) - every recorded run
            { room = "room9", name = "top", x = 1205, z = -731, ox = 1157, oz = -693, n = 9, share = 0.5, after = "room9-stairs",
                viaAlways = true, climb = true, aimFine = true },
        }
        context.gilded1CIdentScan = function()
            -- D-111 (user): every mob of a referenced room is named once, at first sight, by its room, the reference
            -- batch it first stood nearest (rooms 4 and 9 have two), its kind and a number (room4_batchA_mage_01), and
            -- keeps that name and batch while it moves or chases - the D-109 40-stud clusters split room 9's top batch
            -- into 4 + 5 and regrouped room 8 / room 9's stairs as mobs moved. Deaths count once. Game objects keep their
            -- names. A batch is cleared once all of it is dead and at least its known count was seen
            local dungeon = contextWorkspace:FindFirstChild("dungeon")
            local I = hazardReader.c1Ident
            if not I or I.dungeon ~= dungeon then
                I = { dungeon = dungeon, by = {}, byHum = setmetatable({}, { __mode = "k" }), batches = {}, areas = {},
                    at = -math.huge }
                hazardReader.c1Ident = I
            end
            local now = os.clock()
            if not dungeon or now - I.at < (config.gilded1CIdentEvery or 0.1) then
                return I
            end
            I.at = now
            local byRoom = {}
            for _, Q in ipairs(config.gilded1CBatches or context.gilded1CRefs) do
                byRoom[Q.room] = byRoom[Q.room] or {}
                table.insert(byRoom[Q.room], Q)
            end
            for roomName, list in pairs(byRoom) do
                local room = dungeon:FindFirstChild(roomName)
                local folder = room and room:FindFirstChild("enemyFolder")
                for _, m in ipairs(folder and folder:GetChildren() or {}) do
                    if not I.by[m] then
                        local h = m:FindFirstChildOfClass("Humanoid")
                        local r = m:FindFirstChild("HumanoidRootPart") or (m:IsA("Model") and m.PrimaryPart)
                        if h and r and h.Health > 0 then
                            local Q, best = list[1], math.huge
                            for _, Q2 in ipairs(list) do
                                local d = (Q2.x - r.Position.X) ^ 2 + (Q2.z - r.Position.Z) ^ 2
                                if d < best then
                                    Q, best = Q2, d
                                end
                            end
                            local key = Q.name and (roomName .. "-" .. Q.name) or roomName
                            local Bt = I.batches[key]
                            if not Bt then
                                Bt = { key = key, room = roomName, ref = Q, seen = 0, dead = 0, kinds = {} }
                                I.batches[key] = Bt
                            end
                            local kind = string.lower(m.Name):gsub("^dracanic? ", ""):gsub("[^%a]", "")
                            Bt.kinds[kind] = (Bt.kinds[kind] or 0) + 1
                            Bt.seen += 1
                            local id = { id = ("%s_batch%s_%s_%02d"):format(roomName, Q.name or "A", kind, Bt.kinds[kind]),
                                key = key, room = roomName, model = m, humanoid = h, root = r, isBoss = false,
                                x = r.Position.X, z = r.Position.Z, at = now }
                            I.by[m] = id
                            I.byHum[h] = id
                        end
                    end
                end
            end
            for m, id in pairs(I.by) do
                if not id.dead then
                    if m.Parent and id.humanoid.Parent and id.humanoid.Health > 0 and id.root.Parent then
                        id.x, id.z = id.root.Position.X, id.root.Position.Z
                    else
                        id.dead = now
                        local Bt = I.batches[id.key]
                        if Bt then
                            Bt.dead += 1
                        end
                    end
                end
            end
            return I
        end
        context.gilded1CAim = function(b, pos)
            -- D-111: the way to face for the landing that holds the most of the batch (its centre on a tie) - 07:21 room
            -- 9: the four first casts held the 4 Knights in front, the 5 behind them 53-73 from the landing
            local place, reach = context.gilded1CLanding()
            local base = math.atan2(b.z - pos.Z, b.x - pos.X)
            local bestA, bestN, bestK = base, -1, math.huge
            -- D-117: room 5 (aimEdge) - on a tie, the way whose landing has its farthest mob nearest (5 deg steps). Every
            -- room-5 survivor (G1, H, R1, 15:51) was a Familiar at the far edge, 20.2-25.8 from one cast's nearest crystal
            -- (a crystal hits within ~20); the Familiars stood 33 from the landing centres (p90 40), the Mages 18
            local edge = b.ref and b.ref.aimEdge and config.gilded1CAimEdge ~= false
            local kMax, stepR = 6, math.rad(config.gilded1CAimStep or 10)
            if edge or (b.ref and b.ref.aimFine and config.gilded1CAimFine ~= false) then -- (D-119: room 9's top too -
                -- replayed on its 40 recorded first casts, 10 deg steps hold the best facing from the caster's spot in 33, 5 in 40)
                kMax, stepR = 12, math.rad(config.gilded1CAimEdgeStep or 5)
            end
            local bestF = math.huge
            for k = -kMax, kMax do
                local a = base + k * stepR
                local lx, lz = pos.X + math.cos(a) * place, pos.Z + math.sin(a) * place
                local n, far = 0, 0
                for _, m in ipairs(b.members) do
                    local q = m.root.Position
                    local d2 = (q.X - lx) ^ 2 + (q.Z - lz) ^ 2
                    if d2 <= reach * reach then
                        n += 1
                    end
                    if d2 > far then
                        far = d2
                    end
                end
                far = math.sqrt(far)
                local better = n > bestN
                if not better and n == bestN then
                    if edge and far < bestF - 1 then
                        better = true
                    elseif (not edge or far <= bestF + 1) and math.abs(k) < bestK then
                        better = true
                    end
                end
                if better then
                    bestA, bestN, bestK, bestF = a, n, math.abs(k), far
                end
            end
            return pos.X + math.cos(bestA) * 60, pos.Z + math.sin(bestA) * 60, bestN
        end
        context.gilded1CClimbTo = function(pos, b)
            -- D-117: on room 9's stairs below the batch: the stairs' top end on their centre line (D-100's line), or nil
            local ox, oz = config.gildedStairsX or 1103, config.gildedStairsZ or -604
            local ux, uz = config.gildedStairsUX or 0.71, config.gildedStairsUZ or -0.71
            local lo, hi = config.gildedStairsFrom or -77, config.gildedStairsTo or 89
            local s = (pos.X - ox) * ux + (pos.Z - oz) * uz
            local l = (pos.X - ox) * -uz + (pos.Z - oz) * ux
            if s < lo - 6 or s > hi or math.abs(l) > (config.gilded1CClimbSide or 14) or pos.Y > (b.y or pos.Y) - 6 then
                return nil
            end
            local e = hi - (config.gilded1CClimbShort or 2)
            return Vector3.new(ox + ux * e, pos.Y, oz + uz * e)
        end
        context.gilded1CStageFor = function(b)
            -- D-113: where the ready check stands - 100 from the batch's centre and 85 from its nearest mob, outside its
            -- reach (melee mobs start at 55-80 in the humans' runs, the stairs' Warriors to ~100; 12:29 room 9 top: the hold
            -- 100 from the centre was ~70 from its front Knights and they came)
            local near = context.gilded1CStageNear(b)
            if near then
                return (b.d - b.nearest) + near -- D-135: a stage distance per mob (room 6), not 100 from the centre
            end
            return math.max(config.gilded1CStage or 100, (b.d - b.nearest) + (config.gilded1CAggroKeep or 85))
        end
        context.gilded1CStageNear = function(b)
            -- D-135: the nearest-mob distance a flagged batch's ready check stands at (room 6: 72), nil for the others or
            -- with gilded1CStageNear = false (a number sets it)
            local R = b and b.ref
            if not (R and R.stageNear) or config.gilded1CStageNear == false then
                return nil
            end
            return tonumber(config.gilded1CStageNear) or R.stageNear
        end
        context.gilded1CKeepFor = function(b)
            -- the nearest-mob distance the hold keeps (D-113: 85; D-135: the flagged batch's stage)
            return context.gilded1CStageNear(b) or (config.gilded1CAggroKeep or 85)
        end
        context.gilded1CAtStage = function(b, members, R)
            -- D-135: the party accounts within R of a mob of the batch (a dead teammate left out, as groupAt's skipDead)
            local n = 0
            for _, m in ipairs(members or {}) do
                local c = m.player and m.player.Character
                local r = c and c:FindFirstChild("HumanoidRootPart")
                local hm = c and c:FindFirstChildOfClass("Humanoid")
                if r and not (m.player ~= localPlayer and hm and hm.Health <= 0) then
                    local best = math.huge
                    for _, e in ipairs(b.members or {}) do
                        local q = e.root and e.root.Position
                        if q then
                            best = math.min(best, (q.X - r.Position.X) ^ 2 + (q.Z - r.Position.Z) ^ 2)
                        end
                    end
                    if best <= R * R then
                        n += 1
                    end
                end
            end
            return n
        end
        context.gilded1CWentIn = function(key, members)
            -- D-113: a teammate released for this batch within 3 s (its cap, a mob close, all here): its name
            if type(readfile) ~= "function" then
                return nil
            end
            local nowS = contextWorkspace:GetServerTimeNow()
            for _, m in ipairs(members or {}) do
                local name = m.player and m.player.Name or (m.acc and m.acc.name)
                if name and name ~= localPlayer.Name then
                    local okF, v = pcall(function()
                        local pth = readyStamp("c1go_" .. key, name)
                        if type(isfile) == "function" and not isfile(pth) then
                            return nil
                        end
                        return tonumber(readfile(pth))
                    end)
                    if okF and v and nowS - v >= 0 and nowS - v < (config.gilded1CGoFresh or 3) then
                        return name
                    end
                end
            end
            return nil
        end
        context.gilded1CSoon = function(b, members, hereR)
            -- D-114: the soonest alive teammate, not here yet, closing in on the batch: its name and seconds to here
            -- (13:58 room 6: "all 4 here and ready" came 3.2 s after the first arrival - 0.3 s inside the cap)
            local best
            for _, m in ipairs(members or {}) do
                local c = m.player and m.player ~= localPlayer and m.player.Character
                local r = c and c:FindFirstChild("HumanoidRootPart")
                local hm = c and c:FindFirstChildOfClass("Humanoid")
                if r and hm and hm.Health > 0 then
                    local dx, dz = r.Position.X - b.x, r.Position.Z - b.z
                    local d = math.sqrt(dx * dx + dz * dz)
                    local okV, v = pcall(function()
                        return r.AssemblyLinearVelocity
                    end)
                    if d > hereR and okV and v then
                        local closing = -(v.X * dx + v.Z * dz) / math.max(d, 0.1)
                        if closing >= (config.gilded1CSoonSpeed or 10) then
                            local eta = (d - hereR) / closing
                            if eta <= (config.gilded1CSoonEta or 2) and (not best or eta < best.eta) then
                                best = { name = m.player.Name, eta = eta }
                            end
                        end
                    end
                end
            end
            return best
        end
        context.gilded1CCarryReach = function(B)
            -- D-115: in a 1C mob fight that is on (its batch hurt or engaged, or our go), the normal travel closes to Jade
            -- Rain's range instead of its generic reach (13:55 room 6: three parked "in range at 77", 62-64 from the pack,
            -- and cast with 1-3 of 8, 3-4 s after the first)
            if config.gilded1CCarryClose == false or not (context.gilded1COn and context.gilded1COn())
                or (context.bossAliveNear and context.bossAliveNear()) then
                return B
            end
            local character = localPlayer.Character
            local root = character and character:FindFirstChild("HumanoidRootPart")
            local b = root and context.gilded1CBatch(root.Position)
            local st = runtimeState.c1
            if not (b and st and st.cast) then
                return B
            end
            if b.opened or (st.engaged and st.engaged[b.key]) or (st.go and st.go[b.key]) or st.cast[b.key] then
                return math.min(B, config.gilded1CCarryReach or 50)
            end
            return B
        end
        context.gilded1CAfterPending = function(enemy)
            -- D-114 (user): a mob of a batch that comes after another (room 9: the top after the stairs) while that one
            -- is not cleared - every one of it confirmed dead
            local I = hazardReader.c1Ident
            local id = I and enemy and enemy.model and I.by[enemy.model]
            local Bt = id and I.batches[id.key]
            local after = Bt and Bt.ref and Bt.ref.after
            local P = after and I.batches[after]
            if not P then
                return false
            end
            return P.dead < math.max(P.seen, P.ref and P.ref.n or 0)
        end
        context.gilded1CState = function()
            local dungeon = contextWorkspace:FindFirstChild("dungeon")
            local st = runtimeState.c1
            if not st or st.dungeon ~= dungeon then
                st = { dungeon = dungeon, cast = {} } -- per run: a batch's opening is never carried into the next run
                runtimeState.c1 = st
            end
            return st
        end
        context.gilded1CLanding = function()
            local place, radius = 40, 47.5
            if context.aoeLanding then
                local okLand, p1, r1 = pcall(context.aoeLanding)
                if okLand and p1 and r1 then
                    place, radius = p1, r1
                end
            end
            return place, radius - (config.gildedMobCastInset or 6)
        end
        context.gilded1CBatch = function(pos, target)
            -- the target's group among the live mobs of its room (linked within 40 studs: a chased mob stays in its
            -- batch while near one of it): members, centre, spread, studs to it, whether anybody has hurt it, its name
            target = target or combatBrain.target
            if not pos then
                return nil
            end
            local now = os.clock()
            local cache = hazardReader.c1Batch
            if cache and cache.at == now and cache.target == target and cache.pos == pos then
                return cache.b
            end
            local folder = target and not target.isBoss and target.model and target.model.Parent
            if not folder then
                local best = math.huge
                for _, enemy in ipairs(hazardReader.enemies or {}) do
                    if not enemy.isBoss and enemy.model and enemy.humanoid and enemy.humanoid.Health > 0 and enemy.root
                        and enemy.root.Parent then
                        local q = enemy.root.Position
                        local d = (q.X - pos.X) ^ 2 + (q.Z - pos.Z) ^ 2
                        if d < best then
                            best, folder, target = d, enemy.model.Parent, enemy
                        end
                    end
                end
            end
            local list, b = {}, nil
            -- D-111: the target's reference batch - all of it alive, wherever it moved (else the 40-stud cluster)
            local I = config.gilded1CStableBatch ~= false and context.gilded1CIdentScan and context.gilded1CIdentScan()
            local tid = I and target and target.model and I.by[target.model]
            if tid then
                for _, id in pairs(I.by) do
                    if id.key == tid.key and not id.dead and id.humanoid.Health > 0 and id.root.Parent then
                        local q = id.root.Position
                        list[#list + 1] = { e = id, x = q.X, y = q.Y, z = q.Z }
                    end
                end
                folder = folder or (list[1] and list[1].e.model.Parent) -- (the target's model gone)
            end
            for _, enemy in ipairs(not tid and folder and hazardReader.enemies or {}) do
                if not enemy.isBoss and enemy.model and enemy.model.Parent == folder and enemy.humanoid
                    and enemy.humanoid.Health > 0 and enemy.root and enemy.root.Parent then
                    local q = enemy.root.Position
                    list[#list + 1] = { e = enemy, x = q.X, y = q.Y, z = q.Z }
                end
            end
            if #list > 0 then
                local link, up = tid and math.huge or (config.gilded1CLink or 40) ^ 2, {}
                for i = 1, #list do
                    up[i] = i
                end
                local function top(i)
                    while up[i] ~= i do
                        i = up[i]
                    end
                    return i
                end
                for i = 1, #list do
                    for j = i + 1, #list do
                        if (list[i].x - list[j].x) ^ 2 + (list[i].z - list[j].z) ^ 2 <= link then
                            local ti, tj = top(i), top(j)
                            if ti ~= tj then
                                up[tj] = ti
                            end
                        end
                    end
                end
                local pick, best = nil, math.huge
                for i, q in ipairs(list) do
                    if q.e == target then
                        pick = top(i)
                        break
                    end
                    local d = (q.x - pos.X) ^ 2 + (q.z - pos.Z) ^ 2
                    if d < best then
                        best, pick = d, top(i)
                    end
                end
                b = { members = {}, n = 0, x = 0, y = 0, z = 0, r = 0, opened = false, nearest = math.huge }
                for i, q in ipairs(list) do
                    if top(i) == pick then
                        b.n += 1
                        b.members[b.n] = q.e
                        b.x, b.y, b.z = b.x + q.x, b.y + q.y, b.z + q.z
                        local h = q.e.humanoid
                        if h.MaxHealth and h.Health < h.MaxHealth then
                            b.opened = true -- somebody has hurt it: the opening is over
                        end
                        b.nearest = math.min(b.nearest, math.sqrt((q.x - pos.X) ^ 2 + (q.z - pos.Z) ^ 2))
                    end
                end
                b.x, b.y, b.z = b.x / b.n, b.y / b.n, b.z / b.n
                for _, m in ipairs(b.members) do
                    local q = m.root.Position
                    b.r = math.max(b.r, math.sqrt((q.X - b.x) ^ 2 + (q.Z - b.z) ^ 2))
                end
                b.d = math.sqrt((b.x - pos.X) ^ 2 + (b.z - pos.Z) ^ 2)
                local place, reach = context.gilded1CLanding()
                -- the furthest the landing still holds all of it (the reference opened 52-69 out)
                b.fire = math.clamp(place + reach - b.r - 2, config.gilded1CClose or 45, 70)
                b.folder, b.roomModel = folder, folder and folder.Parent or nil -- D-111 (the review): no folder, no index
                b.room = b.roomModel and b.roomModel.Name or "?"
                b.key = b.room
                local kd = math.huge
                for _, R in ipairs(config.gilded1CBatches or context.gilded1CRefs) do
                    if R.room == b.room then
                        local d = (R.x - b.x) ^ 2 + (R.z - b.z) ^ 2
                        if d < kd then
                            kd, b.key, b.ref = d, R.name and (b.room .. "-" .. R.name) or b.room, R
                        end
                    end
                end
                if tid then -- D-111: the batch's own name and record; one of it dead = its fight is on
                    local Bt = I.batches[tid.key]
                    b.key, b.ident = tid.key, true
                    b.ref = Bt and Bt.ref or b.ref
                    b.total, b.dead = Bt and Bt.seen or b.n, Bt and Bt.dead or 0
                    if b.dead > 0 then
                        b.opened = true
                    end
                end
            end
            hazardReader.c1Batch = { at = now, target = target, pos = pos, b = b }
            return b
        end
        context.gilded1CTeam = function(b)
            -- the party's other accounts against this batch (seconds to its opening distance at their speed): who is
            -- behind / ahead; a dead (respawning), absent or not closing account is reported, never waited for
            local out, now = { behind = 0, ahead = 0, why = "" }, os.clock()
            local members = partyMembers()
            out.n = members and #members or 0 -- D-113: the ready check holds only with a party
            local character = localPlayer.Character
            local myRoot = character and character:FindFirstChild("HumanoidRootPart")
            if not (members and myRoot and b) then
                return out
            end
            local fast, slow = config.gildedBuffSpeed or 29.25, config.gildedWalkSpeedSeen or 19.5
            local function eta(r, h)
                local d = math.sqrt((r.Position.X - b.x) ^ 2 + (r.Position.Z - b.z) ^ 2)
                return math.max(d - b.fire, 0) / ((h and h.WalkSpeed or 16) >= 20 and fast or slow), d
            end
            local mine = eta(myRoot, character:FindFirstChildOfClass("Humanoid"))
            local seen = runtimeState.c1Seen or {}
            runtimeState.c1Seen = seen
            local parts, gapMax = {}, config.gilded1CPaceGap or 1.5
            for _, m in ipairs(members) do
                local pl = m.player
                if not pl then
                    parts[#parts + 1] = tostring(m.acc and m.acc.name) .. " not in the server"
                elseif pl ~= localPlayer then
                    local ch = pl.Character
                    local h = ch and ch:FindFirstChildOfClass("Humanoid")
                    local r = ch and ch:FindFirstChild("HumanoidRootPart")
                    if not (h and r and h.Health > 0) then
                        parts[#parts + 1] = pl.Name .. " respawning"
                    else
                        local t, d = eta(r, h)
                        local s = seen[pl.Name]
                        if not s or s.b ~= b.key then
                            s = { b = b.key, d = d, at = now }
                            seen[pl.Name] = s
                        elseif now - s.at >= 0.5 then
                            s.prev, s.d, s.at = s.d, d, now
                        end
                        local closing = s.prev == nil or s.prev - s.d >= 1.5
                        local gap = t - mine
                        if gap > gapMax then
                            if closing then
                                out.behind += 1
                                parts[#parts + 1] = ("%s %.1fs behind"):format(pl.Name, gap)
                            else
                                parts[#parts + 1] = ("%s %.1fs behind, not closing in"):format(pl.Name, gap)
                            end
                        elseif gap < -gapMax then
                            out.ahead += 1
                            parts[#parts + 1] = ("%s %.1fs ahead"):format(pl.Name, -gap)
                        end
                    end
                end
            end
            out.why = table.concat(parts, ", ")
            return out
        end
        context.gilded1CBuffWait = function(now)
            -- Enhanced Inner Focus on the way to a batch: up at the opening with 1 s of it usable, its speed on the
            -- way. Bot runs 1.9.45-55: first attack 0.9-1.8 s (median) after reaching a pack with it on, 2.9-9.4 s
            -- with < 0.8 s of it left. Buff 5.3 s, cooldown 6 s, 29.25 / 19.5 studs/s. nil: press as before
            if not context.gilded1COn() or (context.bossAliveNear and context.bossAliveNear()) then
                return nil
            end
            if (context.BB and context.BB.lethal)
                or (runtimeState.meleeEscapeAt and os.clock() - runtimeState.meleeEscapeAt < 0.5) then
                return nil -- D-110 (the review): a dodge asks for its speed - pressed (1.9.55 pressed it there)
            end
            local character = localPlayer.Character
            local root = character and character:FindFirstChild("HumanoidRootPart")
            local b = root and context.gilded1CBatch(root.Position)
            if not b or b.opened then
                return nil -- the fight is on
            end
            local st = context.gilded1CState()
            local h = st.hold
            if h and h.key == b.key and not (st.go and st.go[b.key]) and os.clock() - (h.seen or 0) < 0.5 then
                -- D-110: kept through the ready check - pressed at the commit (the reference: 0.2-2.8 s before its cast)
                return ("1C %s: Enhanced Inner Focus kept for the team's opening (ready check)"):format(b.key)
            end
            local walk = b.d - b.fire
            if walk <= 0 then
                return nil
            end
            local fast, slow = config.gildedBuffSpeed or 29.25, config.gildedWalkSpeedSeen or 19.5
            local life, cd = config.gildedBuffLife or 5.3, config.buffCooldown or 6
            local usable = life - (config.gildedCastBuffLeft or 0.8) - (config.gilded1CArriveLeft or 1)
            local lo = fast * usable -- pressed with this much (or less) to walk: up at the opening with 1 s usable
            local team = context.gilded1CTeam(b)
            runtimeState.c1Team = team.why
            -- D-111: for the travel only when it is back (5.3 s up + its cooldown) by the ready check ~100 out - 07:21 room
            -- 6: all four pressed it 7.2-7.7 s before the opening and were on cooldown at the check ("0 ready")
            local toCheck = b.d - context.gilded1CStageFor(b)
            local back = fast * life + slow * (cd + 0.22 - life)
            local keep = config.gilded1CBuffTravel ~= false and toCheck > 0 and toCheck < back + (config.gilded1CBuffTravelPad or 10)
            if keep and (team.n or 0) >= 2 and config.gilded1CKeepFirst ~= false and config.gilded1CReadyCheck ~= false
                and not (st.go and st.go[b.key]) and not st.cast[b.key] and not (st.engaged and st.engaged[b.key]) then
                -- D-113: also when behind the others or near enough while our check is ahead (12:29 room 4-A: two pressed
                -- it 40-67 before the check for "behind", on cooldown there - "0 ready", the cap sent one in; room 6: three
                -- 48-75 before it, one cast 3 s late on its cooldown)
                return ("1C %s: Enhanced Inner Focus kept for the opening (%.0f to the ready check)"):format(b.key, toCheck)
            end
            if team.ahead > 0 or walk <= lo then
                return nil -- behind the others (its speed now), or near enough
            end
            if keep then
                return ("1C %s: Enhanced Inner Focus kept for the opening (%.0f to the ready check)"):format(b.key, toCheck)
            end
            if team.behind > 0 then
                return ("1C %s: pacing for %s (%.0f to walk)"):format(b.key, team.why, walk)
            end
            -- pressed now it runs out on the way and the opening waits for the cooldown (6 s + 0.22 s to land);
            -- walking on to `lo` first opens sooner while that costs less than the wait (and the walk is under a cycle)
            local cycle = fast * life + slow * (cd - life)
            local hi = math.min(lo + slow * (cd + 0.22 - usable - 0.3), cycle)
            if walk < hi then
                return ("1C %s: Enhanced Inner Focus for the opening (%.0f to walk)"):format(b.key, walk)
            end
            return nil
        end
        context.gilded1CCastGate = function()
            -- nil: not the mode (the old rules). Our first cast on a batch: once all of it (alive) is in the landing
            -- (the reference did that 52-69 out), or within 45 of its centre / a mob within 20 (no better coverage
            -- coming) - a coverage rule while moving, no readiness wait. After our activation: any cast on one of it
            if not context.gilded1COn() or (context.bossAliveNear and context.bossAliveNear()) then
                return nil
            end
            local character = localPlayer.Character
            local root = character and character:FindFirstChild("HumanoidRootPart")
            local b = root and context.gilded1CBatch(root.Position)
            if not b then
                return nil
            end
            local st = context.gilded1CState()
            st.lastKey = b.key
            local place, reach = context.gilded1CLanding()
            local look = root.CFrame.LookVector
            local ll = math.max(math.sqrt(look.X * look.X + look.Z * look.Z), 0.1)
            local lx, lz = root.Position.X + look.X / ll * place, root.Position.Z + look.Z / ll * place
            local cov = 0
            for _, m in ipairs(b.members) do
                local q = m.root.Position
                if (q.X - lx) ^ 2 + (q.Z - lz) ^ 2 <= reach * reach then
                    cov += 1
                end
            end
            if cov == 0 then
                return false, ("1C %s: none of its %d in the landing (%.0f out)"):format(b.key, b.n, b.d)
            end
            local cdx, cdz = b.x - root.Position.X, b.z - root.Position.Z
            local cdl = math.max(math.sqrt(cdx * cdx + cdz * cdz), 0.1)
            local off = math.deg(math.acos(math.clamp((look.X * cdx + look.Z * cdz) / ll / cdl, -1, 1))) -- off its centre
            if st.cast[b.key] then -- after our own activation on it: any cast on one of it
                return true, ("1C %s: follow-up, %d of %d (%.0f deg)"):format(b.key, cov, b.n, off)
            end
            local pph = context.gilded1CPullPhase and context.gilded1CPullPhase(b)
            local pMine = st.pull and st.pull.key == b.key
            local pSince = st.pullInAt or (pMine and st.pull.phaseAt)
            if pph and not (pSince and os.clock() - pSince >= (config.gildedStairsPullCastMax or 12)) then
                -- D-167 (user): the stairs pull - nobody casts unless all of them are in the landing we face (where they
                -- will be when it lands); 12 s after going in, the old rules
                if pph == "wait" or pMine and pph == "up" then
                    return false, ("1C %s: pull - %s, no cast"):format(b.key, pph)
                end
                local place = context.gilded1CPullReach() -- (defined further on: through the context)
                local pc = context.gilded1CPullCover(b, root.Position, root.Position.X + look.X / ll * place,
                    root.Position.Z + look.Z / ll * place)
                if not pMine and context.gilded1CPullFarBack(root.Position) then -- D-219
                    return false, ("1C %s: pull (%s) - walking on to the cast spot, no cast yet"):format(b.key, pph)
                end
                if pc >= b.n then
                    return true, ("1C %s: pull - all %d in the landing (%.0f deg)"):format(b.key, b.n, off)
                end
                -- D-177 (user): the opening may start before the last of them is in range; none holds its spell once all woke
                local awakeN, totalN = context.gilded1CPullAwake(b)
                local allFor = awakeN >= totalN and st.pullAllAt and os.clock() - st.pullAllAt or -1
                if allFor >= (config.gildedStairsPullOpenA or 0.6) and pc >= b.n - 1
                    or allFor >= (config.gildedStairsPullOpenB or 1.5) and pc >= math.ceil(b.n * 2 / 3)
                    or allFor >= (config.gildedStairsPullOpenC or 2.5) and pc >= 1 then
                    return true, ("1C %s: pull - opening, %d of %d in the landing, all awake %.1fs (%.0f deg)"):format(b.key, pc, b.n, allFor, off)
                end
                return false, ("1C %s: pull (%s) - %d of %d in the landing, no cast until all"):format(b.key, pph, pc, b.n)
            end
            -- D-113: our first cast on it is its opening, also once it is hurt or we are in its fight - most of it (12:29:
            -- the stairs' first casts were "follow-ups" with 1-4 of 6, one 162 deg off; room 4-A three from 80-89 with 2 of 5)
            local share = math.min(b.n, math.max(2, math.ceil(b.n * (config.gilded1COpenShare or 0.6))))
            local hurt = b.opened or (st.engaged and st.engaged[b.key])
            -- D-114: that wait lasts 1 s from when we see it hurt, then any cast on one of it (13:58: it held 4.5 s in room
            -- 8 and 7.5-10.6 s at room 9's top while the batch spread in its fight); room 9's batches (a share of them
            -- opens: 50%) take any at once, and a mob of them on us (within 25) is their fight
            local part = b.ref and b.ref.share
            st.hurtSeen = st.hurtSeen or {}
            if hurt then
                st.hurtSeen[b.key] = st.hurtSeen[b.key] or os.clock()
            end
            -- D-119: a compact batch's 1 s only within 15 of its opening distance (room 6: 60) - U1 / U5 room 6: the late
            -- cast from 84-88 out with 3 of 8 and it took a second cycle; the 17 on-time casts went from 50-56 with 8 of 8.
            -- Further off it closes in first (60% of it in the landing still opens it anywhere)
            -- D-128: that range wait 2 s at most - late accounts held 4-9 s dodging the woken batch's lanes (W14, X20) and
            -- the batch fought on with a cast missing (room-6 deaths: W14 2, W16 1, X19 2, X20 2; none before D-119)
            local hurtGo = hurt and (part or os.clock() - st.hurtSeen[b.key] >= (config.gilded1CHurtWait or 1.0)
                and (b.d <= b.fire + (config.gilded1CHurtNear or 15)
                    or os.clock() - st.hurtSeen[b.key] >= (config.gilded1CHurtFarMax or 2.0)))
            local contact = part and b.nearest <= (config.gilded1CContact or 25) and cov >= math.min(2, b.n)
            local need = part and math.min(b.n, math.max(1, math.ceil(b.n * part))) or b.n
            -- D-115: room 9's top opens from its spot (7-8 of 8 there), not on the way to it (5 of 8) - unless its fight is on
            local viaPending = part and b.ref.viaAlways and config.gilded1CViaAlways ~= false and not hurt
                and not (st.viaDone and st.viaDone[b.key])
            if viaPending then
