                end
                local buffShort = type(spareB) == "number" and seenB ~= nil and os.clock() - seenB
                    >= (config.gildedBuffLife or 5.3) - (config.gildedCastBuffLeft or 0.8) - spareB
                if os.clock() - st.farAt[b.key] < (config.gilded1CTopNearMax or 2.5) and not buffShort then
                    return false, ("1C %s: closing in first - %.0f out (opening from ~%.0f)"):format(b.key, b.d, b.fire)
                end
            else
                st.farAt[b.key] = nil
            end
            if hurtGo and not contact and b.ref and b.ref.aimFine and config.gilded1CAimWait ~= false then
                -- D-119: room 9's top - a hurt batch's first cast waits up to 0.35 s for a landing that holds the aim's best
                -- from here (U2 / U3 / S2: the late pressed 6-21 deg off it at once - one mob fewer in 4 of 6)
                local _, _, an = context.gilded1CAim(b, root.Position)
                st.turnAt = st.turnAt or {}
                if an and cov < an then
                    st.turnAt[b.key] = st.turnAt[b.key] or os.clock()
                    if os.clock() - st.turnAt[b.key] < (config.gilded1CAimWaitMax or 0.35) then
                        return false, ("1C %s: turning to its best landing - %d of %d, %d there"):format(b.key, cov, b.n, an)
                    end
                end
            end
            if not st.cast[b.key] and cov < b.n and context.gilded1CFullRoom and context.gilded1CFullRoom(b) then
                -- D-159: protected - our first cast from the spot whose landing is centred on the whole batch, facing that
                -- centre (13:26: casts from the north-east, 7-8 of 9 each, left the far-west Familiar for a second volley)
                local fs = runtimeState.c1FullSpot
                if fs and fs.key == b.key and os.clock() - fs.at < 1 then
                    local at = math.sqrt((root.Position.X - fs.x) ^ 2 + (root.Position.Z - fs.z) ^ 2)
                    local fdx, fdz = fs.cx - root.Position.X, fs.cz - root.Position.Z
                    local fdl = math.max(math.sqrt(fdx * fdx + fdz * fdz), 0.1)
                    local fOff = math.deg(math.acos(math.clamp((look.X * fdx + look.Z * fdz) / ll / fdl, -1, 1)))
                    if at <= (config.gilded1CFullOpenArrive or 3) + 1 and fOff <= (config.gilded1CFullOpenFace or 12) then
                        return true, ("1C %s: opening from the centred spot, %d of %d (%.0f deg)"):format(b.key, cov, b.n, fOff)
                    end
                    return false, ("1C %s: protected - to the centred spot first (%.0f off, %.0f deg)"):format(b.key, at, fOff)
                end
            end
            if b.ref and b.ref.aimFine and not contact and config.gilded1CTopCloser ~= false then
                -- D-221: room 9's top, first cast from 54 or less of its reference centre (0.6 s at most). From 58-67 the landing's far edge was the back Mages at 44-49 (reach about 45): they took 3 of 4 hits and lived, 3 of 6 runs, +6.7 s each
                local refD = math.sqrt((root.Position.X - b.ref.x) ^ 2 + (root.Position.Z - b.ref.z) ^ 2)
                st.closerAt = st.closerAt or {}
                if refD > (config.gilded1CTopCastD or 54) then
                    st.closerAt[b.key] = st.closerAt[b.key] or os.clock()
                    if os.clock() - st.closerAt[b.key] < (config.gilded1CTopCloserMax or 0.6) then
