            end
            if hurt then
                return false, ("1C %s: opening on it hurt once %d of %d are in the landing (%d at %.0f)"):format(b.key, share, b.n, cov, b.d)
            end
            return false, ("1C %s: opening once %d of %d are in the landing (%d at %.0f)"):format(b.key, need, b.n, cov, b.d)
        end
        context.gilded1CCast = function()
            -- the key went out for the batch: our opening counts once the cooldown started (a key alone is no proof)
            local st = context.gilded1CState()
            local key, at = st.lastKey, os.clock()
            if not key then
                return
            end
            task.delay(config.gilded1CConfirm or 0.4, function()
                local okR, ready = pcall(context.attackReady)
                if okR and ready == false then
                    st.cast[key] = at
                    st.engaged = st.engaged or {}
                    st.engaged[key] = st.engaged[key] or at -- D-111: engaged - never a ready check for it again
                else
                    st.refused = (st.refused or 0) + 1
                    runtimeState.c1Why = ("1C %s: the press did not activate (%d so far)"):format(key, st.refused)
                end
            end)
        end
        context.gilded1CReady = function(b, pos, humanoid)
            -- D-110 (user): the brief ready check the reference made where the team came in spread out (rooms 1, 4,
            -- 8, 9: standing 91-117 studs out for 0.4-3.2 s, then in together - its packs died within 1.0 s of the
            -- cast; a bot batch lived on wherever the four first casts were 1-5 s apart, each Jade Rain ~27% of it).
            -- true (hold) while the party is not here and ready, at most 3.5 s; in at once when every loaded account
            -- is within 125 of the batch and ready (ready stamps for this run and batch, fresh within 1 s), the batch
            -- is hurt, a mob of it is within 45, another account is within its opening distance, or we are hit
            local st = context.gilded1CState()
            st.go = st.go or {}
            if st.go[b.key] then
                return false, "in"
            end
            local function go(text)
                st.go[b.key] = os.clock()
                st.goWhy = st.goWhy or {}
                st.goWhy[b.key] = text -- shown with the approach after it (the recorder's 1C row)
                st.hold = nil
                runtimeState.c1Why = ("1C %s: in - %s"):format(b.key, text)
                pcall(contextLogT, "1c", 2, "Brain", runtimeState.c1Why)
                pcall(function() -- D-113: the others in their check go with us (12:29: the cap sent one at a time)
                    if type(writefile) == "function" and config.gilded1CGoTogether ~= false then
                        writefile(readyStamp("c1go_" .. b.key, localPlayer.Name), tostring(contextWorkspace:GetServerTimeNow()))
                    end
                end)
                return false, text
            end
            if config.gilded1CReadyCheck == false then
                return go("the ready check is off")
            end
            if st.cast[b.key] or (st.engaged and st.engaged[b.key]) then
                -- D-111: engaged (our cast on it, its fight) - 07:21 room 9 top: cast within 45 (no go there), then "ready
                -- check 93 out, 4 of 4 here, 0 ready" 3.5 s on the 5 left of it
                return go("engaged already")
            end
            if b.opened then
                return go("the batch is already hurt")
            end
            if b.nearest <= (config.gilded1CMobClose or 45) then
                return go("a mob of it is close")
            end
            if b.d <= b.fire then
                return go("already in range")
            end
            local pph = context.gilded1CPullPhase and context.gilded1CPullPhase(b)
            if pph == "wait" or (pph == "up" or pph == "hold") and context.gilded1CPullAwake(b) < (config.gildedStairsPullGo or 2) then
                return true, ("the host pulls the Warriors first (%s)"):format(pph) -- D-162/D-163
            end
            local members = partyMembers()
            if not members or #members < 2 then
                return go("no party list")
            end
            local now = os.clock()
            local h = st.hold
            local stageD = context.gilded1CStageFor(b) -- D-113: outside its nearest mob's reach too
            local keepN = context.gilded1CKeepFor(b) + 3
            local stageNear = context.gilded1CStageNear(b) -- D-135: here = at the stage, by each account's nearest mob
            local hereSlack = stageNear and (b.ref.stageSlack or config.gilded1CStageNearSlack or 6)
                or (config.gilded1CStageSlack or 25)
            if not (h and h.key == b.key) or hazardReader.charAt and (h.start or 0) < hazardReader.charAt then -- D-113: not
                -- carried over our respawn (the post-boss test resets accounts already at the check)
                -- the walk to the check point (unbuffed) is allowed on top of the 3.5 s - never an endless hold
                h = { key = b.key, hp = humanoid and humanoid.Health or 0, start = now,
                    walkMax = math.max(b.d - stageD, 0) / (config.gildedWalkSpeedSeen or 19.5) + 1 }
                st.hold = h
            end
            h.seen = now
            if humanoid and h.hp - humanoid.Health > (humanoid.MaxHealth or 0) * (config.gilded1CHitGo or 0.1) then
                return go("we were hit")
            end
            local function goWith(text) -- D-113 (the review): with a teammate's release once our own spells are back -
                -- at most 4 s more (else a ready teammate's release overrode the own-spell wait at the cap)
                if selfReady(now, config.gilded1CBuffLeft or 2.4) then
                    return go(text)
                end
                h.wentWith, h.wentAt = text, h.wentAt or now
                if now - h.wentAt >= (config.gilded1COwnWait or 4) then
                    return go(text)
                end
                return true, ("our Jade Rain / Enhanced Inner Focus first - %s %.1fs ago"):format(text, now - h.wentAt)
            end
            if h.wentWith then
                return goWith(h.wentWith)
            end
            for _, m in ipairs(members) do
                local r = m.player and m.player ~= localPlayer and m.player.Character
                    and m.player.Character:FindFirstChild("HumanoidRootPart")
                if r and math.sqrt((r.Position.X - b.x) ^ 2 + (r.Position.Z - b.z) ^ 2) <= b.fire then
                    return goWith(m.player.Name .. " is going in")
                end
            end
            if not h.countAt or now - h.countAt >= 0.25 then
                h.countAt = now
                local gone = context.gilded1CWentIn(b.key, members) -- D-113: a teammate went in - with it, now
                if gone then
                    return goWith(gone .. " went in")
                end
                h.here, h.loaded, h.ready = groupAt("c1_" .. b.key, Vector3.new(b.x, pos.Y, b.z), members, now,
                    stageD + hereSlack, config.gilded1CBuffLeft or 2.4, -- D-111: up the walk + cast
                    config.gilded1CSkipDead ~= false) -- D-113: a dead teammate (respawning) is not waited for
                if stageNear then
                    h.here = context.gilded1CAtStage(b, members, stageNear + hereSlack)
                end
            end
            if b.d <= stageD + 3 or b.nearest <= keepN then
                h.since = h.since or now
            end
            if (h.loaded or 0) > 0 and (h.here or 0) >= h.loaded and (h.ready or 0) >= h.loaded then
                return go(("all %d here and ready%s"):format(h.loaded, h.since and (" (%.1fs)"):format(now - h.since) or ""))
            end
            if h.since and b.ref and b.ref.after == "room9-stairs" and config.gilded1CTopWaitAll ~= false
                and (h.here or 0) < (h.loaded or 0) and now - h.since < (config.gilded1CTopWaitMax or 12) then
                -- D-170 (user): after the stairs, room 9's top waits for every alive account here (run 7: the cap went in
                -- without Tanker - a second volley); 12 s at most
                return true, ("waiting for all %d after the stairs - %d here, %d ready, %.1fs"):format(h.loaded or 0,
                    h.here or 0, h.ready or 0, now - h.since)
            end
            if h.since and now - h.since >= (config.gilded1CStageMax or 3.5) then
                -- D-114: an alive teammate closing in that is here within 2 s is waited for, 2.5 s more at most
                local soon = context.gilded1CSoon(b, members, stageD + hereSlack)
                if soon and now - h.since < (config.gilded1CStageMax or 3.5) + (config.gilded1CSoonMax or 2.5) then
                    return true, ("%s here in %.1fs - %d of %d here, %d ready"):format(soon.name, soon.eta, h.here or 0,
                        h.loaded or 0, h.ready or 0)
                end
                -- D-113: no more waiting for the others; for our own Jade Rain / Enhanced Inner Focus (the opening needs them)
                -- at most 4 s more (12:29 room 8: the cap sent two in with Jade Rain 1.0-1.9 s off, one died uncast)
                if selfReady(now, config.gilded1CBuffLeft or 2.4)
                    or now - h.since >= (config.gilded1CStageMax or 3.5) + (config.gilded1COwnWait or 4) then
                    return go(("%.1fs up - %d of %d here, %d ready"):format(now - h.since, h.here or 0, h.loaded or 0, h.ready or 0))
                end
                return true, ("our Jade Rain / Enhanced Inner Focus first - %d of %d here, %d ready, %.1fs"):format(h.here or 0,
                    h.loaded or 0, h.ready or 0, now - h.since)
            end
            if now - h.start >= h.walkMax + (config.gilded1CStageMax or 3.5) then
                return go(("%.1fs on the way to the check point - %d of %d here"):format(now - h.start, h.here or 0, h.loaded or 0))
            end
            return true, ("%d of %d here, %d ready%s"):format(h.here or 0, h.loaded or 0, h.ready or 0,
                h.since and (", %.1fs"):format(now - h.since) or "")
        end
        context.gilded1CPullOn = function(b)
            -- D-162 (user): room 9's stairs only, before the batch is hurt, in the 1C mode with a party host
            return config.gildedStairsPull ~= false and b ~= nil and b.ref ~= nil and b.ref.room == "room9"
                and b.ref.name == "stairs" and not b.opened and context.gilded1COn() and context.AF ~= nil
                and context.AF.carry ~= nil
        end
        context.gilded1CPullHost = function()
            local okH, acc = pcall(context.AF.carry)
            return okH and type(acc) == "table" and acc.name and tostring(acc.name) or nil
        end
        context.c1stairsSL = function(x, z) -- D-163: along / across the stairs' centre line (D-100's line)
            local ox, oz = config.gildedStairsX or 1103, config.gildedStairsZ or -604
            local ux, uz = config.gildedStairsUX or 0.71, config.gildedStairsUZ or -0.71
            return (x - ox) * ux + (z - oz) * uz, (x - ox) * -uz + (z - oz) * ux
        end
        context.c1stairsXZ = function(s, l)
            local ox, oz = config.gildedStairsX or 1103, config.gildedStairsZ or -604
            local ux, uz = config.gildedStairsUX or 0.71, config.gildedStairsUZ or -0.71
            return ox + ux * s - uz * l, oz + uz * s + ux * l
        end
        context.c1stairsWide = function(s) -- D-163: how far from the centre line the stairs reach (8 runs of positions)
            if s < -10 then
                return config.gildedStairsWideLow or 22
            elseif s < 10 then
                return config.gildedStairsWideMid or 15
            end
            return config.gildedStairsWideTop or 10
        end
        context.gilded1CPullAwake = function(b)
            -- D-163: how many of the batch are awake (moved 3+ from where we first saw them), of how many
            local st = context.gilded1CState()
            st.pullRest = st.pullRest or setmetatable({}, { __mode = "k" })
            local awake, total = 0, 0
            for _, m in ipairs(b.members or {}) do
                local key = m.model or m
                local q = m.root.Position
                total += 1
                local r0 = st.pullRest[key]
                if not r0 then
                    st.pullRest[key] = q
                elseif (q - r0).Magnitude > 3 then
                    awake += 1
                end
            end
            if total > 0 and awake >= total then
                st.pullAllAt = st.pullAllAt or os.clock()
            end
            return awake, total
        end
        context.gilded1CPullPhase = function(b)
            -- D-162/D-163: the stairs pull's phase ("wait", "up", "hold") and the seconds in it, or nil - the host's own
            -- record, the others its stamp (fresh 1 s, 12 s from its announce at most)
            if not context.gilded1CPullOn(b) then
                return nil
            end
            local st = context.gilded1CState()
            local pl = st.pull
            if pl and pl.key == b.key then
                if pl.phase == "over" then
                    return nil
                end
                return pl.phase, os.clock() - pl.phaseAt
            end
            local host = context.gilded1CPullHost()
            if not host or string.lower(host) == string.lower(localPlayer.Name) or type(readfile) ~= "function" then
                return nil
            end
            local okF, body = pcall(function()
                local pth = readyStamp("pull_" .. b.key, host)
                if type(isfile) == "function" and not isfile(pth) then
                    return nil
                end
                return readfile(pth)
            end)
            if not (okF and type(body) == "string") then
                return nil
            end
            local ph, t, first, phT = string.match(body, "^(%a+)|([%d%.]+)|([%d%.]+)|([%d%.]+)")
            t, first, phT = tonumber(t), tonumber(first), tonumber(phT)
            if not (ph and t and first and phT) or ph == "over" then
                return nil
            end
            local nowS = contextWorkspace:GetServerTimeNow()
            if nowS - t > (config.gildedStairsPullFresh or 4.0) or nowS - first > (config.gildedStairsPullMax or 14) then -- D-169: 4 s (the host's dodges)
                return nil
            end
            return ph, nowS - phT
        end
        context.gilded1CPullPredict = function(b)
            -- D-167: each of the batch where it will be when a landing made now lands (its last 0.1 s+ of movement)
            local st = context.gilded1CState()
            st.pullTrack = st.pullTrack or setmetatable({}, { __mode = "k" })
            local lead = config.gildedStairsPullLead or 0.45
            local now = os.clock()
            local out = {}
            for _, m in ipairs(b.members or {}) do
                local key = m.model or m
                local q = m.root.Position
                local tr = st.pullTrack[key]
                if not tr then
                    tr = { x = q.X, z = q.Z, t = now, vx = 0, vz = 0 }
                    st.pullTrack[key] = tr
                elseif now - tr.t >= 0.1 then
                    local dt = now - tr.t
                    tr.vx, tr.vz = (q.X - tr.x) / dt, (q.Z - tr.z) / dt
                    if math.sqrt(tr.vx * tr.vx + tr.vz * tr.vz) > (config.gildedStairsPullVMax or 40) then
                        tr.vx, tr.vz = 0, 0 -- a teleport / respawn, not a run
                    end
                    tr.x, tr.z, tr.t = q.X, q.Z, now
                end
                out[#out + 1] = Vector3.new(q.X + tr.vx * lead, q.Y, q.Z + tr.vz * lead)
            end
            return out
        end
        context.c1pullReach = function()
            local place, reach = context.gilded1CLanding()
            return place, reach + (config.gildedMobCastInset or 6) - (config.gildedStairsPullInset or 3)
        end
        context.gilded1CPullReach = context.c1pullReach
        context.gilded1CPullCover = function(b, pos, lx, lz)
            -- D-167: how many of the batch (predicted) a landing centred at (lx, lz) holds
            -- D-219: and in it now as well: a Warrior running down the stairs turns back at the host (the prediction
            -- said "in", it stopped 42-51 out and lived: the survivor in 6 of 9 second volleys)
            local _, reach = context.c1pullReach()
            local n = 0
            for i, q in ipairs(context.gilded1CPullPredict(b)) do
                local m = b.members and b.members[i]
                local now = m and m.root and m.root.Position
                if (q.X - lx) ^ 2 + (q.Z - lz) ^ 2 <= reach * reach
                    and (config.gildedStairsCoverNow == false or not now or (now.X - lx) ^ 2 + (now.Z - lz) ^ 2 <= reach * reach) then
                    n += 1
                end
            end
            return n
        end
        context.gilded1CPullFarBack = function(pos)
            -- D-219: an account behind the host, still lower on the stairs than its cast spot, for a limited time after
            -- going in: it walks on and holds its Jade Rain (from 67-73 along the landing does not reach the top Warriors)
            local st = context.gilded1CState()
            if not st.pullInAt or os.clock() - st.pullInAt >= (config.gildedStairsCastHold or 3.2) then
                return false
            end
            return (context.c1stairsSL(pos.X, pos.Z)) < (config.gildedStairsCastS or -61)
        end
        context.gilded1CPullAim = function(b, pos)
            -- D-167: from here, the facing whose landing holds the most of the batch (predicted, 2-deg steps all round);
            -- on a tie the centre nearest the batch's middle. Returns the landing centre x, z and its count
            local place, reach = context.c1pullReach()
            local pts = context.gilded1CPullPredict(b)
            if #pts == 0 then
                return nil
            end
            local mx, mz = 0, 0
            for _, q in ipairs(pts) do
                mx, mz = mx + q.X, mz + q.Z
            end
            mx, mz = mx / #pts, mz / #pts
            local bx, bz, bn, bd
            for k = 0, 179 do
                local a = k * math.pi / 90
                local lx, lz = pos.X + math.cos(a) * place, pos.Z + math.sin(a) * place
                local n = 0
                for _, q in ipairs(pts) do
                    if (q.X - lx) ^ 2 + (q.Z - lz) ^ 2 <= reach * reach then
                        n += 1
                    end
                end
                local d = (lx - mx) ^ 2 + (lz - mz) ^ 2
                if not bn or n > bn or n == bn and d < bd then
                    bx, bz, bn, bd = lx, lz, n, d
                end
            end
            return bx, bz, bn
        end
        context.gilded1CPullCentre = function(b)
            -- D-163: the landing centre that holds the most of the batch - the smallest circle's centre, else a Warrior or
            -- the midpoint of two (nearest that circle's centre on a tie); its count (D-167: where they will be)
            local _, reach = context.c1pullReach()
            local pts = context.gilded1CPullPredict(b)
            if #pts == 0 then
                return nil
            end
            local cx, cz = 0, 0
            for _, q in ipairs(pts) do
                cx, cz = cx + q.X, cz + q.Z
            end
            cx, cz = cx / #pts, cz / #pts
            for i = 1, 60 do
                local fx, fz, fd = cx, cz, -1
                for _, q in ipairs(pts) do
                    local d2 = (q.X - cx) ^ 2 + (q.Z - cz) ^ 2
                    if d2 > fd then
                        fx, fz, fd = q.X, q.Z, d2
                    end
                end
                cx, cz = cx + (fx - cx) / (i + 1), cz + (fz - cz) / (i + 1)
            end
            local cands = { { cx, cz } }
            for i, q in ipairs(pts) do
                cands[#cands + 1] = { q.X, q.Z }
                for j = i + 1, #pts do
                    cands[#cands + 1] = { (q.X + pts[j].X) / 2, (q.Z + pts[j].Z) / 2 }
                end
            end
            local best, bestN, bestD
            for _, c in ipairs(cands) do
                local n = 0
                for _, q in ipairs(pts) do
                    if (q.X - c[1]) ^ 2 + (q.Z - c[2]) ^ 2 <= reach * reach then
                        n += 1
                    end
                end
                local dc = (c[1] - cx) ^ 2 + (c[2] - cz) ^ 2
                if not best or n > bestN or n == bestN and dc < bestD then
                    best, bestN, bestD = c, n, dc
                end
            end
            return best[1], best[2], bestN
        end
        context.gilded1CPullSpot = function(b, pos, side)
            -- D-163: our spot for the opening - `place` out from the best landing centre, below the batch on the stairs,
            -- 40 deg to our side of straight down them (other angles, nearest it, when that is off the stairs)
            local cx, cz, n = context.gilded1CPullCentre(b)
            if not cx then
                return nil
            end
            local place = context.gilded1CLanding()
            local ux, uz = config.gildedStairsUX or 0.71, config.gildedStairsUZ or -0.71
            local base = math.atan2(-uz, -ux) -- down the stairs
            local cs = context.c1stairsSL(cx, cz)
            local want = -(config.gildedStairsPullSide or 0) * side -- D-177: straight down the middle (positive angles turn toward -l)
            local bestP, bestK
            for k = -80, 80, 10 do
                local a = base + math.rad(k)
                local sx, sz = cx + math.cos(a) * place, cz + math.sin(a) * place
                local s, l = context.c1stairsSL(sx, sz)
                if s <= cs + 2 and math.abs(l) <= math.min(context.c1stairsWide(s), config.gildedStairsMiddleSpot or 6) then -- D-177
                    local cost = math.abs(k - want)
                    if not bestK or cost < bestK then
                        bestP, bestK = Vector3.new(sx, pos.Y, sz), cost
                    end
                end
            end
            if not bestP then -- nothing on the stairs at `place`: straight down them, on the centre line
                local s0 = cs - place
                local x0, z0 = context.c1stairsXZ(s0, 0)
                bestP = Vector3.new(x0, pos.Y, z0)
            end
            do -- D-193: never further back than 62: the landing then reaches from 56 down to 18 up (the whole pack)
                local sMin = config.gildedStairsSpotMin or -58 -- D-219: was -62
                local sP, lP = context.c1stairsSL(bestP.X, bestP.Z)
                if sP < sMin then
                    local x1, z1 = context.c1stairsXZ(sMin, math.clamp(lP, -6, 6))
                    bestP = Vector3.new(x1, pos.Y, z1)
                end
            end
            return bestP, cx, cz, n
        end
        context.gilded1CPullStep = function(humanoid, zF, posSeen, now, b, target)
            -- D-163: the host's side of the stairs pull - on up the stairs past the Warriors, never back; true while it
            -- moves us
            if not (context.gilded1CPullOn(b) and context.AF.isHost and context.AF.isHost() == true) then
                return false
            end
            local st = context.gilded1CState()
            if st.cast[b.key] then
                if st.pull and st.pull.key == b.key and st.pull.phase ~= "over" then
                    st.pull.phase = "over"
                end
                return false
            end
            local clock = os.clock()
            local nowS = contextWorkspace:GetServerTimeNow()
            local pl = st.pull
            if pl and pl.key ~= b.key then
                pl = nil
            end
            local stageD = context.gilded1CStageFor(b)
            if not pl then
                if b.d > stageD + (config.gildedStairsPullAnnounce or 40) then
                    return false
                end
                pl = { key = b.key, phase = "wait", at = clock, phaseAt = clock, firstS = nowS, phaseS = nowS }
                st.pull = pl
                pcall(contextLogT, "1c", 1, "Brain", ("1C %s: the host pulls the Warriors - the others hold"):format(b.key))
            end
            if pl.phase == "over" then
                return false
            end
            local function stamp()
                pl.stampAt = clock
                pcall(function()
                    if type(writefile) == "function" then
                        writefile(readyStamp("pull_" .. b.key, localPlayer.Name),
                            ("%s|%.3f|%.3f|%.3f"):format(pl.phase, nowS, pl.firstS, pl.phaseS))
                    end
                end)
            end
            local function phase(ph)
                pl.phase, pl.phaseAt, pl.phaseS = ph, clock, nowS
                pcall(contextLogT, "1c", 2, "Brain", ("1C %s: pull - %s"):format(b.key, ph))
                stamp() -- the others see it at once
            end
            if not (humanoid and humanoid.Health > 0) or clock - pl.at > (config.gildedStairsPullMax or 14) then
                phase("over")
            elseif pl.phase == "up" and clock - pl.phaseAt > (config.gildedStairsPullUp or 8) then
                phase("hold")
            elseif pl.phase == "hold" and clock - pl.phaseAt > (config.gildedStairsPullHold or 6) then
                phase("over")
            end
            if not pl.stampAt or clock - pl.stampAt >= 0.2 then
                stamp()
            end
            if pl.phase == "over" then
                return false
            end
            if pl.phase == "wait" then
                if b.d > stageD + 3 and b.nearest > context.gilded1CKeepFor(b) + 3 then
                    return false -- on to the ready check (it holds there)
                end
                local members = partyMembers() or {}
                local all, here = 0, 0
                for _, m in ipairs(members) do
                    local c = m.player and m.player.Character
                    local r = c and c:FindFirstChild("HumanoidRootPart")
                    local hm = c and c:FindFirstChildOfClass("Humanoid")
                    if r and hm and hm.Health > 0 then
                        all += 1
                        if math.sqrt((r.Position.X - b.x) ^ 2 + (r.Position.Z - b.z) ^ 2) <= stageD + (config.gildedStairsPullHere or 25) then
                            here += 1
                        end
                    end
                end
                pl.waitAt = pl.waitAt or clock
                if here < all and clock - pl.waitAt < (config.gildedStairsPullGather or 5) then
                    runtimeState.c1Why = ("1C %s: pull - waiting for the others at the ready check (%d of %d)"):format(b.key, here, all)
                    return false
                end
                phase("up")
            end
            local awake, total = context.gilded1CPullAwake(b)
            if awake >= (config.gildedStairsPullGo or 2) and not pl.fireS then
                -- D-166: lured - FIRE once every other alive account is at its side spot, or 2.5 s after the 2nd woke
                pl.twoAt = pl.twoAt or clock
                local members = partyMembers() or {}
                local others, ready = 0, 0
                for _, m in ipairs(members) do
                    local c = m.player and m.player ~= localPlayer and m.player.Character
                    local hm = c and c:FindFirstChildOfClass("Humanoid")
                    if hm and hm.Health > 0 then
                        others += 1
                        local okF, v = pcall(function()
                            local pth = readyStamp("pullready_" .. b.key, m.player.Name)
                            if type(isfile) == "function" and not isfile(pth) then
                                return nil
                            end
                            return tonumber(readfile(pth))
                        end)
                        if okF and v and nowS - v <= (config.gildedStairsPullReadyFresh or 0.6) then
                            ready += 1
                        end
                    end
                end
                if ready >= others or clock - pl.twoAt >= (config.gildedStairsPullFireWait or 2.5) then
                    pl.fireS = nowS
                    pcall(function()
                        if type(writefile) == "function" then
                            writefile(readyStamp("pullfire_" .. b.key, localPlayer.Name), ("%.3f"):format(nowS))
                        end
                    end)
                    pcall(contextLogT, "1c", 1, "Brain", ("1C %s: pull - FIRE (%d awake, %d of %d at their spots)"):format(b.key,
                        awake, ready, others))
                end
            end
            local sEnd = config.gildedStairsPullEnd or 18 -- D-193: past the top Warriors' way down, not dragging them out of the landings
            local s0, l0 = context.c1stairsSL(posSeen.X, posSeen.Z)
            if pl.phase == "up" then
                if s0 >= sEnd - 3 then
                    phase("hold")
                else
                    -- on along the stairs, 15 ahead, at the side offset (within their width there) farthest from every Warrior
                    local sT = math.min(s0 + (config.gildedStairsPullAhead or 15), sEnd)
                    local wide = math.min(context.c1stairsWide(sT), config.gildedStairsMiddle or 4) -- D-177: the middle
                    local bestL, bestC
                    for l = -wide, wide, 2.5 do
                        local x, z = context.c1stairsXZ(sT, l)
                        local clear = math.huge
                        for _, m in ipairs(b.members) do
                            local q = m.root.Position
                            clear = math.min(clear, math.sqrt((q.X - x) ^ 2 + (q.Z - z) ^ 2))
                        end
                        local score = math.min(clear, 30) - math.abs(l - l0) * 0.15
                        if not bestC or score > bestC then
                            bestL, bestC = l, score
                        end
                    end
                    local x, z = context.c1stairsXZ(sT, bestL or 0)
                    g(humanoid, zF, Vector3.new(x, posSeen.Y, z), e(), 1)
                    runtimeState.c1Why = ("1C %s: pull - on up the stairs (%d of %d awake, %.0f along of %d)"):format(b.key,
                        awake, total, s0, sEnd)
                    contextSetState(runtimeState.c1Why)
                    return true
                end
            end
            if pl.phase == "hold" then
                -- at the end: side to side, facing the Warriors below - its cast by the opening rule (the gate)
                pl.sideAt = pl.sideAt or clock
                if clock - pl.sideAt > (config.gildedStairsPullSway or 1.2) then
                    pl.sideAt, pl.sway = clock, -(pl.sway or 1)
                end
                local x, z = context.c1stairsXZ(sEnd, (pl.sway or 1) * (config.gildedStairsPullSwayL or 8))
                g(humanoid, zF, Vector3.new(x, posSeen.Y, z), e(), 1)
                local cx, cz, cn = context.gilded1CPullAim(b, posSeen) -- D-167: our own best facing from here
                if cx then
                    runtimeState.c1Face = { x = cx, z = cz, at = clock }
                    runtimeState.gildedFace = { x = cx, z = cz, at = clock }
                end
                runtimeState.c1Why = ("1C %s: pull - at the top end, side to side (%d of %d awake, %d of %d in the best aim)"):format(
                    b.key, awake, total, cn or 0, b.n)
                contextSetState(runtimeState.c1Why)
                if target then
                    p(humanoid, zF, target, now)
                end
                return true
            end
            return false
        end
        context.gilded1CPullLeap = function(humanoid, zF, posSeen, now, target)
            -- D-184 (user: "leap of faith"): the host's run up the stairs comes before the generic hitbox dodges (11 of them bent it 24 off the middle)
            if config.gildedStairsLeap == false or not (context.AF and context.AF.isHost and context.AF.isHost() == true) then
                return false
            end
            local pl = context.gilded1CState().pull
            if not (pl and pl.phase == "up") then
                return false
            end
            if humanoid.MaxHealth > 0 and humanoid.Health / humanoid.MaxHealth < (config.gildedStairsLeapHp or 0.35) then
                return false
            end
            local b = context.gilded1CBatch(posSeen, target)
            if not b or b.key ~= pl.key then
                return false
            end
            return context.gilded1CPullStep(humanoid, zF, posSeen, now, b, target) == true
        end
        context.gilded1CPullQHold = function(b)
            -- D-184: the others' Enhanced Inner Focus waits for 4 awake (at the bottom it ran out 0.5 s before all 6 were in the landing)
            if config.gildedStairsQHold == false or not context.gilded1CPullOn(b) then
                return
            end
            if context.gilded1CState().cast[b.key] then
