            local ph = context.gilded1CPullPhase(b)
            if context.AF.isHost and context.AF.isHost() == true then
                -- D-186: the host's too - until the first awake or 85 before the top of its run (spent at the ready check it ran out before the cast)
                local ch = localPlayer.Character
                local rt = ch and ch:FindFirstChild("HumanoidRootPart")
                if rt and (ph == "wait" or ph == "up") and context.gilded1CPullAwake(b) < 1
                    and context.c1stairsSL(rt.Position.X, rt.Position.Z) < (config.gildedStairsHostQAt or -85) then
                    runtimeState.holdBuffUntil = math.max(runtimeState.holdBuffUntil or 0, os.clock() + 0.35)
                end
                return
            end
            if (ph == "wait" or ph == "up") and context.gilded1CPullAwake(b) < (config.gildedStairsQAwake or 4) then
                runtimeState.holdBuffUntil = math.max(runtimeState.holdBuffUntil or 0, os.clock() + 0.35)
            end
        end
        context.gilded1CPullFireAge = function(b)
            -- D-166: seconds since the host's FIRE for this batch (its stamp, or our own as the host), or nil
            local st = context.gilded1CState()
            local nowS = contextWorkspace:GetServerTimeNow()
            if st.pull and st.pull.key == b.key and st.pull.fireS then
                return nowS - st.pull.fireS
            end
            local host = context.gilded1CPullHost()
            if not host or type(readfile) ~= "function" then
