                end
                return tonumber(readfile(pth))
            end)
            if okF and v and nowS - v >= -1 and nowS - v <= (config.gildedStairsPullMax or 14) then
                return nowS - v
            end
            return nil
        end
        context.gilded1CPullSide = function(humanoid, zF, posSeen, now, b, target)
            -- D-163: the others - once the first Warriors are awake, to the side spot (above), facing the landing centre;
            -- true while it moves us
            if not context.gilded1CPullOn(b) or (context.AF.isHost and context.AF.isHost() == true) then
                return false
            end
            local st = context.gilded1CState()
            if st.cast[b.key] then
                return false
            end
            local ph = context.gilded1CPullPhase(b)
            if ph ~= "up" and ph ~= "hold" then
                return false
            end
            local awake = context.gilded1CPullAwake(b)
            context.gilded1CPullPredict(b) -- (their movement tracked from the start)
            local side = 1
            local members = partyMembers() or {}
            local host, idx = context.gilded1CPullHost(), 0
            for _, m in ipairs(members) do
                local nm = m.player and m.player.Name or (m.acc and m.acc.name)
                if nm and not (host and string.lower(tostring(nm)) == string.lower(host)) then
                    idx += 1
                    if m.player == localPlayer then
                        side = idx % 2 == 1 and -1 or 1
                        break
                    end
                end
            end
            if awake < (config.gildedStairsPullGo or 2) and not st.pullInAt then
                -- D-167: wait at the bottom of the stairs on our side, 57+ from the bottom pair
                local x, z = context.c1stairsXZ(config.gildedStairsPullStageS or -90, side * (config.gildedStairsPullStageL or 0)) -- D-177: the middle
                local stage = Vector3.new(x, posSeen.Y, z)
                local offS = math.sqrt((posSeen.X - x) ^ 2 + (posSeen.Z - z) ^ 2)
                if offS > 3 then
                    g(humanoid, zF, stage, e(), 1)
                else
