                end
                return true
            end
            st.pullInAt = st.pullInAt or os.clock()
            local ax, az, an = context.gilded1CPullAim(b, posSeen)
            if ax and an >= b.n and not context.gilded1CPullFarBack(posSeen) then -- D-219
                -- D-167: a facing from here holds all of them - stand and face it (the gate casts once we do)
                contextReleaseMover(humanoid, zF)
                runtimeState.c1Face = { x = ax, z = az, at = os.clock() }
                runtimeState.gildedFace = { x = ax, z = az, at = os.clock() }
                runtimeState.c1Why = ("1C %s: pull - all %d in the aim from here, facing it"):format(b.key, b.n)
                contextSetState(runtimeState.c1Why)
                if target then
                    p(humanoid, zF, target, now)
