            runtimeState.c1Face = { x = ax or cx, z = az or cz, at = os.clock() }
            runtimeState.gildedFace = { x = ax or cx, z = az or cz, at = os.clock() }
            local off = math.sqrt((posSeen.X - spot.X) ^ 2 + (posSeen.Z - spot.Z) ^ 2)
            if off > 3 then
                g(humanoid, zF, spot, e(), 1)
