                    return true
                end
            end
            if b.roomModel and (b.opened or b.nearest <= (config.gildedRoomContact or 30) or b.d <= close) then
                local fought = hazardReader.gildedRoomFought -- as D-052 marks it: the ring and the fight logic go on
                if not fought then
                    fought = setmetatable({}, { __mode = "k" })
                    hazardReader.gildedRoomFought = fought
                end
