            end
            if b.d <= close or b.opened then
                st.engaged = st.engaged or {}
                st.engaged[b.key] = st.engaged[b.key] or clock -- D-111: engaged - no ready check for it again
            end
            if b.d <= close then
                if b.ident and not st.cast[b.key] and context.gilded1CAim then
