            end
            if st.block and st.block.key == b.key and clock < st.block.untilAt then
                return why("no progress straight on - the normal travel for a moment")
            end
            -- D-110 (the review): the straight way as the normal travel checks it - another level, a learned invisible
            -- wall, the floor on the way - besides walls at step height (party characters and the batch are no wall)
            if math.abs((b.y or posSeen.Y) - posSeen.Y) >= (config.straightDy or 8) then
                -- D-113: the ready check holds here too (the stairs): stand outside its reach - not walk up into it
                local stageL = context.gilded1CStageFor(b)
                if not b.opened and not (st.engaged and st.engaged[b.key]) and config.gilded1CHoldLevels ~= false
                    and (b.d <= stageL + 3 or b.nearest <= context.gilded1CKeepFor(b) + 3) then
                    local holdL, readyL = context.gilded1CReady(b, posSeen, humanoid)
                    if holdL then
                        st.prog = nil
                        contextReleaseMover(humanoid, zF)
                        runtimeState.c1Why = ("1C %s: ready check %.0f out (another level) - %s"):format(b.key, b.d, readyL)
                        contextSetState(runtimeState.c1Why)
                        p(humanoid, zF, target, now)
                        return true
                    end
                end
                local up = b.ref and b.ref.climb and config.gilded1CClimb ~= false and context.gilded1CClimbTo(posSeen, b)
                if up then
                    -- D-117: room 9's top from its stairs - straight up their centre line (15:59: the normal travel's path
                    -- stalled at its 2nd of 32 waypoints on the stairs; the cast went from 80 out with 4 of 9)
                    st.prog = nil
                    g(humanoid, zF, up, e(), 1)
                    runtimeState.c1Why = ("1C %s: up the stairs' centre line to the top (%.0f out)"):format(b.key, b.d)
                    contextSetState(runtimeState.c1Why)
                    p(humanoid, zF, target, now)
                    return true
                end
                return why("another level - the normal travel")
            end
            local goal = Vector3.new(b.x, posSeen.Y, b.z)
            if context.ghostBlocked and context.ghostBlocked(posSeen, goal) then
                return why("an invisible wall on the way - the normal travel")
            end
            local feet = dangerGeometry and dangerGeometry.feet or 3
            local params = contextRaycastParams(b.folder)
            pcall(function()
                local skip = params.FilterDescendantsInstances
                for _, pl in ipairs(game:GetService("Players"):GetPlayers()) do
                    if pl.Character then
                        skip[#skip + 1] = pl.Character
                    end
                end
                params.FilterDescendantsInstances = skip
            end)
            local okW, clear = pcall(contextWalkable, posSeen, b.x, posSeen.Y - feet, b.z, params)
            local via
            st.viaForce = st.viaForce or {}
            -- D-115: room 9's top through its opening spot even with the way clear, before its fight; any batch again
            -- through its spot once stuck in its fight (13:51 room 9 top: 11 s stuck 99-114 from its last two)
            local viaWant = b.ref and ((b.ref.viaAlways and config.gilded1CViaAlways ~= false and not b.opened
                and not (st.engaged and st.engaged[b.key])) or (st.viaForce[b.key] or 0) > clock)
            if not (okW and clear) or viaWant then
