                    else
                        local okV, clearV = pcall(contextWalkable, posSeen, Q.ox, posSeen.Y - feet, Q.oz, params)
                        local okS, clearS = pcall(contextWalkable, spot, b.x, posSeen.Y - feet, b.z, params)
                        if okV and clearV and okS and clearS and not (context.ghostBlocked and context.ghostBlocked(posSeen, spot)) then
                            via = spot -- (and from the spot on to the batch the way is clear)
