                    -- (13:55 room 6: acct2 on "no straight way" came in to 84 and the batch woke before the go)
                    local stageW = context.gilded1CStageFor(b)
                    if not b.opened and not (st.engaged and st.engaged[b.key]) and config.gilded1CHoldWalls ~= false
                        and (b.d <= stageW + 3 or b.nearest <= context.gilded1CKeepFor(b) + 3) then
                        local holdW, readyW = context.gilded1CReady(b, posSeen, humanoid)
                        if holdW then
                            st.prog = nil
                            contextReleaseMover(humanoid, zF)
                            runtimeState.c1Why = ("1C %s: ready check %.0f out (round a wall) - %s"):format(b.key, b.d, readyW)
                            contextSetState(runtimeState.c1Why)
                            p(humanoid, zF, target, now)
                            return true
                        end
                    end
                    local up = b.ref and b.ref.climb and config.gilded1CClimb ~= false and context.gilded1CClimbTo(posSeen, b)
                    if up then
                        -- D-117: room 9's top from its stairs - straight up their centre line (15:59: the normal travel's path
                        -- stalled at its 2nd of 32 waypoints on the stairs; the cast went from 80 out with 4 of 9)
                        st.prog = nil
                        g(humanoid, zF, up, e(), 1)
                        runtimeState.c1Why = ("1C %s: up the stairs' centre line to the top (%.0f out)"):format(b.key, b.d)
                        contextSetState(runtimeState.c1Why)
                        p(humanoid, zF, target, now)
                        return true
                    end
                    return why("no straight way - the normal travel")
                end
            end
            local wd = via and math.max(math.sqrt((via.X - posSeen.X) ^ 2 + (via.Z - posSeen.Z) ^ 2), 0.1) or b.d
            local ux, uz = ((via or goal).X - posSeen.X) / wd, ((via or goal).Z - posSeen.Z) / wd
            local probe = math.min(via and wd or b.d - close, config.gilded1CFloorAhead or 40)
            if config.floorCheck ~= false and context.floorAlong
                and not context.floorAlong(posSeen, Vector3.new(posSeen.X + ux * probe, posSeen.Y, posSeen.Z + uz * probe)) then
                return why("no floor on the way - the normal travel")
