                if b.d > stageD + 3 and b.nearest > context.gilded1CKeepFor(b) + 3 then
                    g(humanoid, zF, via or Vector3.new(b.x - ux * stageD, posSeen.Y, b.z - uz * stageD), e(), 1)
                else
                    contextReleaseMover(humanoid, zF)
