                runtimeState.c1Why = ("1C %s: ready check %.0f out - %s%s"):format(b.key, b.d, ready,
                    team.why ~= "" and (" | " .. team.why) or "")
                contextSetState(runtimeState.c1Why)
                p(humanoid, zF, target, now)
                return true
            end
            local pr = st.prog -- D-110 (the review): 1.5 s without 6 studs of progress - the normal travel for 3 s
