                st.prog = { key = b.key, at = clock, x = posSeen.X, z = posSeen.Z }
            elseif clock - pr.at >= (config.gilded1CProgFor or 1.5) then
                if math.sqrt((posSeen.X - pr.x) ^ 2 + (posSeen.Z - pr.z) ^ 2) < (config.gilded1CProgMin or 6) then
                    st.block, st.prog = { key = b.key, untilAt = clock + (config.gilded1CBlockFor or 3) }, nil
                    if b.opened or (st.engaged and st.engaged[b.key]) then -- D-115: stuck in its fight - by its spot next
                        st.viaForce = st.viaForce or {}
                        st.viaForce[b.key] = clock + (config.gilded1CViaForceFor or 6)
