                            st.viaDone[b.key] = nil
                        end
                    end
                    return why("no progress straight on - the normal travel for a moment")
                end
                st.prog = { key = b.key, at = clock, x = posSeen.X, z = posSeen.Z }
            end
            g(humanoid, zF, via or goal, e(), 1)
            local text = ("1C %s: on to it - %d mobs, %.0f to the centre (opening from ~%.0f)%s%s%s"):format(b.key, b.n, b.d,
                b.fire, via and " | round the wall by its opening spot" or "",
                st.goWhy and st.goWhy[b.key] and (" | in: " .. st.goWhy[b.key]) or "",
                team.why ~= "" and (" | " .. team.why) or "")
            runtimeState.c1Why = text
            contextSetState(text)
            p(humanoid, zF, target, now)
            return true
        end
        context.gildedFireballOut = function(pos, refuge)
            -- D-110 (boss 3): a fireball lane (thirdBossFireballHitbox, 32 x 292) over us in a refuge - the way across
            -- and out of it. 06:25: 3 deaths standing in the colour-wait refuge, hit 1.39-1.45 s after the lane showed;
            -- its danger starts 0.9 s in and the refuge leash kept every dodge inside the refuge
            if not (hazardReader.gildedOn and config.gildedFireballOut ~= false) then
                return nil
            end
            local now = os.clock()
            for model, rec in pairs(hazardReader.models or {}) do
                if type(rec) == "table" and tostring(rec.name) == "thirdbossfireballhitbox"
                    and now - (rec.spawn or now) <= (config.gildedFireballLife or 1.7) and typeof(model) == "Instance" then
                    local part = model:FindFirstChild("hitBox", true) or model:FindFirstChild("precast", true)
                    if part and part:IsA("BasePart") then
                        local pad = config.gildedFireballPad or 4
                        local hx, hz = part.Size.X / 2 + pad, part.Size.Z / 2 + pad
                        local rel = part.CFrame:PointToObjectSpace(pos)
                        if math.abs(rel.X) <= hx and math.abs(rel.Z) <= hz then
                            local out = part.CFrame:PointToWorldSpace(Vector3.new((rel.X >= 0 and 1 or -1) * (hx + 2), rel.Y, rel.Z))
                            return Vector3.new(out.X, pos.Y, out.Z), "out"
                        end
                        if refuge and refuge.x then -- outside it, its lane over the refuge: wait here until it strikes
                            local rr = part.CFrame:PointToObjectSpace(Vector3.new(refuge.x, pos.Y, refuge.z))
                            if math.abs(rr.X) <= hx and math.abs(rr.Z) <= hz then
                                return pos, "wait"
                            end
                        end
                    end
                end
            end
            return nil
        end
        context.gildedRoomNoWait = function(name) -- D-152: Gilded rooms with no first-approach wait (ballistas on the spot)
            local set = config.gildedRoomNoWait
            if set == nil then
                set = { room4 = true }
            end
            return type(set) == "table" and set[tostring(name)] == true
        end
        context.gildedVLineOut = function(pos, now, target)
            -- D-151 (boss 2): acct2-34 @209.8 - "moving off hot ground" ran along a vertical line 6-7 off its centre until
            -- it struck. In a live line's reach: the way straight out across it (our side first), clear of every other line
            if config.gildedVLineOut == false then
                return nil
            end
            local keep = config.gildedVLineStrafeKeep or 4
            local live = {}
            for _, box in ipairs(dangerGeometry.boxes or {}) do
                if tostring(box.name or "") == "secondbossverticalline" and (box.untilAt or 0) > now
                    and (box.from or now) - now < (config.gildedVLineStrafeLead or 1.0) and box.ha and box.hb then
                    live[#live + 1] = box
                end
            end
            local function inReach(x, z)
                for _, box in ipairs(live) do
                    local okD, depth = pcall(contextDepthOf, box, x, box.cy or pos.Y, z, 0)
                    if okD and depth and depth >= -keep then
                        return box
                    end
                end
                return nil
            end
            local box = inReach(pos.X, pos.Z)
            if not box then
                return nil
            end
            if target and not inReach(target.X, target.Z) then
                return nil -- the planner's spot is already clear of every line
            end
            local nx, nz, half = box.ax, box.az, box.ha
            if box.hb < box.ha then
                nx, nz, half = box.bx, box.bz, box.hb
            end
            local off = (pos.X - box.cx) * nx + (pos.Z - box.cz) * nz
            local side = off >= 0 and 1 or -1
            for _, sgn in ipairs({ side, -side }) do
                local need = half + keep + 0.5 - off * sgn
                local q = Vector3.new(pos.X + nx * sgn * need, pos.Y, pos.Z + nz * sgn * need)
                if not inReach(q.X, q.Z) then
                    return q
                end
            end
            return nil
        end
        context.gildedVLineNear = function(pos, y)
            -- D-150 (boss 2): 33 @225.2 (23 Oct) - held between two vertical lines 6.6 apart, then "strafe" took us 2.5 studs
            -- past one line's edge during its strike (D-058: hits reach 6.3 from the centre). No strafe that close
            if config.gildedVLineStrafeKeep == false then
                return false
            end
            for _, box in ipairs(dangerGeometry.boxes or {}) do
                if tostring(box.name or "") == "secondbossverticalline" and (box.untilAt or 0) > y and (box.from or y) - y < (config.gildedVLineStrafeLead or 1.0) then -- D-151: from its spawn
                    local okD, depth = pcall(contextDepthOf, box, pos.X, box.cy or pos.Y, pos.Z, 0)
                    if okD and depth and depth >= -(config.gildedVLineStrafeKeep or 4) then
                        return true
                    end
                end
            end
            return false
        end
        context.gildedWaitThreat = function(pos, y)
            -- D-150 (boss 3; solo and 1C): the fireball wait beside the refuge returns before BB.tick, so the brain's threat
            -- state is the one from before the wait (D-122) - 32 @334.7 / 33 @420.8 (23 Oct): spiral shots (0.83-1.0 s) hit
            -- us standing still in it. A live attack box on us (not the fireball waited for) ends the wait: the dodge runs
            if config.gildedWaitSeeShapes == false then
                return false
            end
            for _, box in ipairs(dangerGeometry.boxes or {}) do
                local bn = tostring(box.name or "")
                if bn ~= "thirdbossfireballhitbox" and (box.untilAt or 0) > y
                    and (box.from or y) - y < (config.gildedRefugeShapeLead or 0.6) then
                    local okD, depth = pcall(contextDepthOf, box, pos.X, box.cy or pos.Y, pos.Z, 0)
                    if okD and depth and depth >= -(config.gildedRefugeShapeMargin or 1.5) then
                        return true, bn
                    end
                end
            end
            return false
        end
        context.gildedBeamLoop = function(WF)
            -- D-110 (boss 1): in the green circle with Kiryne's beam on us, its squares (and our own trail) are left
            -- behind by the loop - they do not drop the circle for a dodge back through the trail
            if not (hazardReader.gildedOn and config.gildedBeamLoop ~= false and WF and tostring(WF.name) == "thirdbossmasssafespotcircles") then
                return false
            end
            if not (context.gildedMyBeamOn and context.gildedMyBeamOn()) then
                return false
            end
            local prim = context.BB and context.BB.primary
            local nm = prim and prim.box and string.lower(tostring(prim.box.name or "")) or ""
            return nm == "" or nm:find("beam", 1, true) ~= nil
        end
        context.gildedLoopTurn = function(WF, Si, pos, loopR, lead, speed, now)
            -- D-116 (boss 1): the loop turns counter-clockwise; with our beam on it turned accounts that came in clockwise
            -- back through their own fresh trail (R1 acct3, 12:29 acct1-4). The turn flips (kept for the
            -- field) when its way crosses our trail and the other does not; not with a teammate within 40 (one loop way)
            if not (hazardReader.gildedOn and config.gildedLoopTurn ~= false and WF and Si
                and tostring(WF.name) == "thirdbossmasssafespotcircles") then
                return lead
            end
            local tk = runtimeState.b1Turn
            if tk and (tk.from ~= WF.from or math.abs(tk.x - Si.x) > 1 or math.abs(tk.z - Si.z) > 1) then
                tk = nil -- another field or another circle
            end
            if context.gildedMyBeamOn and context.gildedMyBeamOn() and context.gildedOwnTrailHit then
                local s = tk and tk.s or 1
                local a0 = math.atan2(pos.Z - Si.z, pos.X - Si.x)
                local function crosses(k)
                    return context.gildedOwnTrailHit(pos.X, pos.Z, Si.x + math.cos(a0 + lead * k) * loopR,
                        Si.z + math.sin(a0 + lead * k) * loopR, speed, now)
                end
                if crosses(s) and not crosses(-s) then
                    local shared = false
                    for _, pl in ipairs(game:GetService("Players"):GetPlayers()) do
                        local r = pl ~= localPlayer and pl.Character and pl.Character:FindFirstChild("HumanoidRootPart")
                        local hh = r and pl.Character:FindFirstChildOfClass("Humanoid")
                        if r and hh and hh.Health > 0
                            and (r.Position.X - Si.x) ^ 2 + (r.Position.Z - Si.z) ^ 2 < (config.gildedLoopTurnShare or 40) ^ 2 then
                            shared = true
                        end
                    end
                    if not shared then
                        s = -s
                    end
                end
                if s ~= 1 or tk then
                    tk = tk or { from = WF.from, x = Si.x, z = Si.z }
                    tk.s = s
                    runtimeState.b1Turn = tk
                end
            end
            return lead * (tk and tk.s or 1)
        end
        context.gildedSquareHit = function(pos, pts, speed, now)
            -- D-130 (boss 1, Kiryne up): a path {x, z, d} meets a shown beam square (ours or a teammate's) while it can
            -- strike when we pass, or a teammate's fresh trail (it stood there 0.3-1.6 s before we pass: its square drops
            -- ~0.4 s after it and strikes at ~0.67 s of age). U1-U3 / V1 / X18-X20: 7 deaths in a teammate's fresh squares
            if not (hazardReader.gildedOn and config.gildedB1Squares ~= false and context.kiryneUp and context.kiryneUp()) then
                return false
            end
            local sp = math.max(speed or 16, 4)
            local pad, m = config.gildedB1SquarePad or 3, config.gildedB1SquareMargin or 2
            local sqs = {}
            for _, b in ipairs(dangerGeometry.boxes or {}) do
                if b.name == "firstbossbeamtrackerline" and b.cx and b.ax and b.bx and (b.untilAt or 0) >= now then
                    sqs[#sqs + 1] = b
                end
            end
            local first, last = config.gildedMateTrailFirst or 0.3, config.gildedMateTrailLast or 1.6
            local r2 = (config.gildedMateTrailR or 7) ^ 2
            for _, pt in ipairs(pts) do
                local at = now + (pt.d or 0) / sp
                for _, b in ipairs(sqs) do
                    if at >= (b.from or 0) - 0.1 and at <= (b.untilAt or 0) then
                        local dx, dz = pt.x - b.cx, pt.z - b.cz
                        if math.abs(dx * b.ax + dz * b.az) <= math.max((b.ha or 5) - pad, 1) + m
                            and math.abs(dx * b.bx + dz * b.bz) <= math.max((b.hb or 5) - pad, 1) + m then
                            return true
                        end
                    end
                end
                for _, tr in pairs(hazardReader.mateTrails or {}) do
                    for _, s in ipairs(tr) do
                        local age = at - s.t
                        if age >= first and age <= last and (pt.x - s.x) ^ 2 + (pt.z - s.z) ^ 2 <= r2 then
                            return true
                        end
                    end
                end
            end
            return false
        end
        context.gildedSquareLine = function(pos, gx, gz, speed, now, stopR)
            -- D-130: the straight way from pos toward (gx, gz), up to stopR from it, every 3 studs
            if not (hazardReader.gildedOn and config.gildedB1Squares ~= false) then
                return false
            end
            local dx, dz = gx - pos.X, gz - pos.Z
            local L = math.sqrt(dx * dx + dz * dz)
            local run = L - (stopR or 0)
            if run < 0.5 then
                return false
            end
            local pts, n = {}, math.max(1, math.ceil(run / 3))
            for i = 1, n do
                local d = run * i / n
                pts[i] = { x = pos.X + dx / L * d, z = pos.Z + dz / L * d, d = d }
            end
            return context.gildedSquareHit(pos, pts, speed, now)
        end
        context.arenaClearReset = function(vector, selfResetAt, humanoid)
            if config.resetAfterArena == false then
                return false
            end
            if hazardReader.gildedOn and config.gildedArenaReset ~= true then
                runtimeState.resetGate = "off in Gilded Skies" -- D-043: the reset is for Northern Lands' pit room
                return false
            end
            if context.bossAliveNear() then
                runtimeState.resetGate = "a boss is alive" -- D-043: never reset in a boss fight
                return false
            end
            context.bigRoomNote(vector, selfResetAt)
            local bigRoom = hazardReader.bigRoom
            if not bigRoom then
                runtimeState.resetGate = "no room"
                return false
            end
            if bigRoom.resetDone then
                runtimeState.resetGate = "done"
                return false
            end
            runtimeState.resetGate = "open"
            if selfResetAt - (bigRoom.at or 0) > 900 then
                runtimeState.resetGate = "room too old"
                return false
            end
            if context.runComplete and context.runComplete() then
                runtimeState.resetGate = "run complete"
                return false
            end
            if hazardReader.charAt and selfResetAt - hazardReader.charAt < (config.resetRespawnGap or 0) then
                runtimeState.resetGate = "just respawned"
                return false
            end
            local B = hazardReader.spawnCp
            if
                config.resetCatchUp ~= false
                and config.resetBelowY ~= false
                and vector.Y > (config.resetBelowY or -40)
                and B
                and hazardReader.charAt == B.at
                and bigRoom.diedInAt == B.at
                and not hazardReader.catchUpUsed
            then
                local z = contextWorkspace:FindFirstChild("dungeon")
                local position, DF
                for index, entry in ipairs(z and z:GetChildren() or {}) do
                    local checkPoint, order = entry:FindFirstChild("checkPoint"), entry:FindFirstChild("order")
                    if
                        checkPoint
                        and checkPoint:IsA("BasePart")
                        and order
                        and tonumber(order.Value) == B.order + 1
                    then
                        position, DF = checkPoint.Position, entry:FindFirstChild("barrier") == nil
                        break
                    end
                end
                if position then
                    local cF, hF =
                        math.sqrt((vector.X - position.X) ^ 2 + (vector.Z - position.Z) ^ 2),
                        math.sqrt((bigRoom.x - position.X) ^ 2 + (bigRoom.z - position.Z) ^ 2)
                    z = nil
                    for index2, enemy in ipairs(hazardReader.enemies) do
                        if
                            enemy.root
                            and enemy.root.Parent
                            and enemy.humanoid
                            and enemy.humanoid.Health > 0
                            and not enemy.isBoss
                        then
                            local yF, EF = enemy.root.Position.X - bigRoom.x, enemy.root.Position.Z - bigRoom.z
                            if yF * yF + EF * EF <= ((bigRoom.r or 120) + 60) ^ 2 then
                                z = enemy
                                break
                            end
                        end
                    end
                    local SF = cF > (config.resetCatchUpFar or 150) and cF > hF
                    if DF and not z and SF and not (context.b1NoReset and context.b1NoReset()) then -- D-176
                        bigRoom.resetDone = true
                        bigRoom.resetWasUs = true
                        runtimeState.selfResetAt = selfResetAt
                        hazardReader.catchUpUsed = true
                        contextLogT(
                            "reset",
                            1,
                            "Brain",
                            ("big room cleared while we were behind it (%.0f from the next checkpoint): resetting to come back there"):format(
                                cF
                            )
                        )
                        pcall(function()
                            humanoid.Health = 0
                        end)
                        pcall(function()
                            humanoid:ChangeState(Enum.HumanoidStateType.Dead)
                        end)
                        task.delay(1, function()
                            pcall(function()
                                local character = localPlayer.Character
                                local humanoid2 = character and (character:FindFirstChildOfClass("Humanoid"))
                                if humanoid2 and humanoid2.Health > 0 then
                                    character:BreakJoints()
                                end
                            end)
                        end)
                        contextSetState("room cleared behind us: reset to the next checkpoint")
                        return true
                    end
                    hazardReader.belowSince = nil
                    runtimeState.resetGate = ("behind the room, %.0f from the next checkpoint (%s)"):format(
                        cF,
                        not SF and "close enough"
                            or not DF and "the next room is still barred"
                            or ("%s alive"):format(tostring(z.model and z.model.Name or "mob"))
                    )
                    return false
                end
            end
            if hazardReader.resetUsed then
                runtimeState.resetGate = "used"
                return false
            end
            if config.resetBelowY ~= false and vector.Y > (config.resetBelowY or -40) then
                hazardReader.belowSince = nil
                runtimeState.resetGate = ("above the drop (y %.0f)"):format(vector.Y)
                return false
            end
            if config.resetBelowY ~= false then
                hazardReader.belowSince = hazardReader.belowSince or selfResetAt
                B = config.resetBelowSettle or 3
                if selfResetAt - hazardReader.belowSince < B then
                    runtimeState.resetGate = ("just landed, reading the floor (%.1f/%.1fs)"):format(
                        selfResetAt - hazardReader.belowSince,
                        B
                    )
                    return false
                end
            end
            if config.resetAfterBob ~= false then
                B = false
                for entry2 in pairs(hazardReader.bossDown or {}) do
                    if entry2:find("bob", 1, true) then
                        B = true
                        break
                    end
                end
                local z = config.resetBelowY ~= false and vector.Y <= (config.resetBelowY or -40)
                if not B and not z then
                    runtimeState.resetGate = "Bob not down yet"
                    return false
                end
            end
            local z, SF, DF = bigRoom.r or 120, vector.X - bigRoom.x, vector.Z - bigRoom.z
            B = SF * SF + DF * DF
            if B <= z * z then
                bigRoom.entered = true
                bigRoom.left = nil
            end
            if bigRoom.entered and B > (z + (config.resetLeaveFar or 40)) ^ 2 then
                bigRoom.left = true
            end
            if bigRoom.left then
                bigRoom.clearSince = nil
                runtimeState.resetGate = ("left the room (%.0f from its centre, r %.0f)"):format(math.sqrt(B), z)
                return false
            end
            if B > (z + (config.resetRoomLeave or 150)) ^ 2 then
                bigRoom.clearSince = nil
                runtimeState.resetGate = ("not in the room (%.0f off)"):format(math.sqrt(B))
                return false
            end
            SF = (z + 60) ^ 2
            for index3, enemy2 in ipairs(hazardReader.enemies) do
                index3 = nil
                if enemy2.humanoid then
                    index3 = enemy2.humanoid.Health > 0
                    enemy2.noHumSince = nil
                else
                    enemy2.noHumSince = enemy2.noHumSince or selfResetAt
                    index3 = selfResetAt - enemy2.noHumSince < (config.resetGhostAfter or 20)
                end
                if
                    enemy2.root
                    and enemy2.root.Parent
                    and index3
                    and math.abs(enemy2.root.Position.Y - vector.Y)
                        <= (config.resetSameLevel or 25)
                then
                    local z, cF, hF, yF =
                        enemy2.root.Position.X - bigRoom.x,
                        enemy2.root.Position.Z - bigRoom.z,
                        enemy2.root.Position.X - vector.X,
                        enemy2.root.Position.Z - vector.Z
                    if
                        z * z + cF * cF <= SF
                        or not enemy2.isBoss and hF * hF + yF * yF <= (config.resetNearAny or 90) ^ 2
                    then
                        bigRoom.clearSince = nil
                        runtimeState.resetGate = ("%s alive at %.0f"):format(
                            tostring(enemy2.model and enemy2.model.Name or "mob"),
                            math.sqrt(
                                (enemy2.root.Position.X - vector.X) ^ 2 + (enemy2.root.Position.Z - vector.Z) ^ 2
                            )
                        )
                        return false
                    end
                end
            end
            bigRoom.clearSince = bigRoom.clearSince or selfResetAt
            B = config.resetAfterClear or 0
            if selfResetAt - bigRoom.clearSince < B then
                contextSetState(
                    ("room cleared (%d groups): resetting in %.1fs to get back up"):format(
                        bigRoom.groups or 0,
                        B - (selfResetAt - bigRoom.clearSince)
                    )
                )
                return true
            end
            if (context.b1NoReset and context.b1NoReset()) then
                return false -- D-176
            end
            bigRoom.resetDone = true
            bigRoom.resetWasUs = true
            runtimeState.selfResetAt = selfResetAt
            hazardReader.resetUsed = true
            contextLogT(
                "reset",
                1,
                "Brain",
                ("big room cleared (%d groups): resetting the character to get back up"):format(
                    bigRoom.groups or 0
                )
            )
            pcall(function()
                humanoid.Health = 0
            end)
            pcall(function()
                humanoid:ChangeState(Enum.HumanoidStateType.Dead)
            end)
            task.delay(1, function()
                pcall(function()
                    local character = localPlayer.Character
                    local humanoid2 = character and (character:FindFirstChildOfClass("Humanoid"))
                    if humanoid2 and humanoid2.Health > 0 then
                        character:BreakJoints()
                    end
                end)
            end)
            contextSetState("room cleared: reset")
            return true
        end
        context.kitePlan = function(vector, F, i)
            if config.meleeKite == false or not (F and F.root and F.root.Parent) or not context.aoeLanding then
                runtimeState.kite = nil
                return nil
            end
            local b = context.aoeLanding()
            if not b then
                runtimeState.kite = nil
                return nil
            end
            local B, z, SF, DF, cF = config.kiteChaseR or 45, {}, 0, 0, 0
            for index, enemy in ipairs(hazardReader.enemies) do
                if
                    enemy.melee
                    and not enemy.isBoss
                    and enemy.root
                    and enemy.root.Parent
                    and enemy.humanoid
                    and enemy.humanoid.Health > 0
                    and a(vector, enemy.root.Position) <= B
                then
                    SF += enemy.root.Position.X
                    DF += enemy.root.Position.Z
                    cF += 1
                    index = H(enemy)
                    if index ~= nil then
                        z[index] = true
                    end
                else
                end
            end
            if cF == 0 then
                runtimeState.kite = nil
                return nil
            end
            SF /= cF
            DF /= cF
            B = {}
            for index2, enemy2 in ipairs(hazardReader.enemies) do
                if
                    not enemy2.isBoss
                    and enemy2.root
                    and enemy2.root.Parent
                    and enemy2.humanoid
                    and enemy2.humanoid.Health > 0
                then
                    index2 = H(enemy2)
                    if index2 ~= nil and not z[index2] then
                        local H = B[index2]
                        if not H then
                            H = {
                                k = index2,
                                n = 0,
                                sx = 0,
                                sz = 0,
                                untag = 0,
                                list = {},
                            }
                            B[index2] = H
                        else
                        end
                        H.n, H.sx, H.sz = H.n + 1, H.sx + enemy2.root.Position.X, H.sz + enemy2.root.Position.Z
                        H.list[#H.list + 1] = enemy2
                        if contextTagTarget(enemy2) then
                            H.untag = H.untag + 1
                        end
                    end
                end
            end
            local H, kite = runtimeState.sweeping == true, runtimeState.kite
            if kite and kite.doneAt then
                runtimeState.kiteDone = {
                    k = kite.k,
                    at = kite.doneAt,
                }
                runtimeState.kite = nil
                kite = nil
            else
            end
            z = runtimeState.kiteDone
            local hF = z and i - z.at < (config.kiteRest or 3) and z.k or nil
            kite = if kite
                    and (i - (kite.startAt or i) > (config.kiteCommit or 8) or i - (kite.at or i) > 1)
                then nil
                else kite
            z = kite and B[kite.k] or nil
            if z then
                z.x, z.z = z.sx / z.n, z.sz / z.n
                if sqrt((z.x - vector.X) ^ 2 + (z.z - vector.Z) ^ 2) > (config.kiteRange or 200) + 20 then
                    kite, z = nil, nil
                else
                end
            else
                kite = nil
            end
            if not z then
                local yF
                for key, entry in pairs(B) do
                    entry.x, entry.z = entry.sx / entry.n, entry.sz / entry.n
                    key = sqrt((entry.x - vector.X) ^ 2 + (entry.z - vector.Z) ^ 2)
                    if key <= (config.kiteRange or 200) and key >= (config.kiteMinD or 12) and entry.k ~= hF then
                        local wF = key - (H and entry.untag > 0 and 1000 or 0)
                        if not z or wF < yF then
                            z, yF = entry, wF
                        else
                        end
                    else
                    end
                end
            else
            end
            if not z then
                runtimeState.kite = nil
                return nil
            end
            B = 0
            for index3, entry2 in ipairs(z.list) do
                index3 = sqrt((entry2.root.Position.X - z.x) ^ 2 + (entry2.root.Position.Z - z.z) ^ 2)
                B = if index3 > B then index3 else B
            end
            H = B + (config.kiteSide or 14)
            if not kite then
                B, hF = z.x - SF, z.z - DF
                local SF = sqrt(B * B + hF * hF)
                if SF < 1 then
                    B, hF = z.x - vector.X, z.z - vector.Z
                    SF = sqrt(B * B + hF * hF)
                else
                end
                if SF < 1 then
                    runtimeState.kite = nil
                    return nil
                end
                B /= SF
                hF /= SF
                local SF = -hF
                local side, yF, EF =
                    (vector.X - z.x) * SF + (vector.Z - z.z) * B >= 0 and 1 or -1, z.x + B * b, z.z + hF * b
                local JF, wF = yF - vector.X, EF - vector.Z
                EF, yF = JF * JF + wF * wF, false
                if EF > 1 then
                    local YF = math.clamp(((z.x - vector.X) * JF + (z.z - vector.Z) * wF) / EF, 0, 1)
                    yF = sqrt((vector.X + JF * YF - z.x) ^ 2 + (vector.Z + wF * YF - z.z) ^ 2) < H
                        and (vector.X - z.x) * B + (vector.Z - z.z) * hF < 0
                else
                end
                kite = {
                    k = z.k,
                    startAt = i,
                    ux = B,
                    uz = hF,
                    nx = SF,
                    nz = B,
                    side = side,
                    flankDone = not yF,
                }
            else
            end
            kite.at = i
            runtimeState.kite = kite
            local SF, DF, yF, EF, JF = z.x + kite.ux * b, z.z + kite.uz * b, "beyond"
            if not kite.flankDone then
                b, B, hF =
                    z.x + kite.nx * kite.side * H,
