        local function SF(cF, hF, yF, MF)
            local orbBehind = runtimeState.orbBehind
            if orbBehind and orbBehind.at == cF then
                return orbBehind.x, orbBehind.z
            end
            local nF, fF, rF = 0, 0, 0
            for entry in pairs(hazardReader.rodinGoodOrbs or {}) do
                if entry.Parent then
                    nF, fF, rF = nF + (entry.Position.X - hF.X), fF + (entry.Position.Z - hF.Z), rF + 1
                else
