            end
            for entry2 in pairs(hazardReader.parts or {}) do
                if entry2.Parent and lowercase(entry2.Name):find("bouncingorbbad", 1, true) then
                    nF, fF, rF = nF + (entry2.Position.X - hF.X), fF + (entry2.Position.Z - hF.Z), rF + 1
                else
                end
            end
            local oF = sqrt(nF * nF + fF * fF)
            local AF, kF
