                        else
                            iF = true
                        end
                        break
                    end
                end
            else
            end
            drawn = false
            if CF then
                for index2, zone in ipairs(hazardReader.zones) do
                    if
                        (zone.name == "sideways missile" and zone.moving or zone.name == "missile path")
                        and zone.ox
                        and zone.dx
                        and (zone.untilAt or 0) > eF
                        and (zone.pathStart or eF) <= eF
                    then
                        local bF, BF, GF, zF =
                            (vector.X - zone.ox) * zone.dx + (vector.Z - zone.oz) * zone.dz,
                            (zone.offset or 0) + (zone.speed or 0) * max(eF - (zone.pathStart or eF), 0),
                            zone.halfL or 16,
                            config.rodinPassedFrac or 0.5
                        local sF, TF =
                            (2 * zF - 1) * (GF + (dangerGeometry.reach or 1.8)),
                            zF >= 1 and (config.rodinMissilePassed or 3)
                        if BF > bF + (sF + (TF or 0)) then
                            zone.untilAt = eF
                            hazardReader.boxGen = (hazardReader.boxGen or 0) + 1
                        end
                    end
                end
                local CF, bF, BF, GF, zF =
                    config.rodinLinesYellowOnly ~= false,
                    -infinity,
                    {},
                    config.rodinLineMem or 5,
                    hazardReader.mlDoneAt and hazardReader.mlDoneAt + (config.rodinVolleyGap or 4) or -infinity
                for index3, zone2 in ipairs(hazardReader.zones) do
                    if zone2.name == "missile path" and zone2.madeAt and not zone2.volley then
                        if
                            hazardReader.mlLastMade == nil
                            or zone2.madeAt > hazardReader.mlLastMade + (config.rodinVolleyGap or 4)
                        then
                            hazardReader.mlVolley = (hazardReader.mlVolley or 0) + 1
                        end
                        zone2.volley = hazardReader.mlVolley
                        hazardReader.mlLastMade = max(hazardReader.mlLastMade or 0, zone2.madeAt)
                    end
                end
                hazardReader.mlMem = hazardReader.mlMem or {}
                local sF = hazardReader.mlMem
                for index4, zone3 in ipairs(hazardReader.zones) do
                    if zone3.name == "missile path" and zone3.ox and zone3.dx then
                        index4 = sF[zone3]
                        if not index4 then
                            index4 = {
                                name = "missile path",
                                ox = zone3.ox,
                                oz = zone3.oz,
                                dx = zone3.dx,
                                dz = zone3.dz,
                            }
                            sF[zone3] = index4
                        else
                        end
                        index4.untilAt, index4.madeAt, index4.volley, index4.pathStart, index4.from =
                            zone3.untilAt, zone3.madeAt, zone3.volley, zone3.pathStart, zone3.from
                    end
                end
                for key, entry in pairs(sF) do
                    if
                        (entry.untilAt or 0) < eF - (config.rodinLineMemVolley or 15)
                        or hazardReader.mlDoneVolley ~= nil
                            and entry.volley ~= nil
                            and entry.volley <= hazardReader.mlDoneVolley
                    then
                        sF[key] = nil
                    end
                end
                local TF
                for key2, entry2 in pairs(sF) do
                    if
                        (
                            (entry2.untilAt or 0) > eF - GF
                            or config.rodinLinesKeepVolley ~= false
                                and entry2.volley ~= nil
                                and (entry2.untilAt or 0) > eF - (config.rodinLineMemVolley or 15)
                        )
                        and (entry2.madeAt or 0) > zF
                        and (
                            hazardReader.mlDoneVolley == nil
                            or (entry2.volley or math.huge) > hazardReader.mlDoneVolley
                        )
                    then
                        BF[#BF + 1] = entry2
                        key2 = entry2.madeAt or entry2.pathStart or entry2.from or 0
                        if key2 > bF then
                            bF, TF = key2, entry2
                        else
                        end
                    else
                    end
                end
                if not CF then
                    for index5, zone4 in ipairs(hazardReader.zones) do
                        if
                            zone4.ox
                            and zone4.dx
                            and (zone4.untilAt or 0) > eF
                            and zone4.name == "sideways missile"
                            and zone4.moving
                        then
                            BF[#BF + 1] = zone4
                            GF = zone4.madeAt or zone4.pathStart or zone4.from or 0
                            if GF > bF then
                                bF, TF = GF, zone4
                            else
                            end
                        else
                        end
                    end
                else
                end
                for key3, entry3 in pairs(CF and {} or hazardReader.parts) do
                    if key3.Parent and lowercase(key3.Name):find("thirdbossmissile", 1, true) then
                        zF = sqrt(entry3.vx * entry3.vx + entry3.vz * entry3.vz)
                        if zF > 2 then
                            local position, tF, HF = key3.Position, entry3.vx / zF, entry3.vz / zF
                            sF, GF =
                                (vector.X - position.X) * tF + (vector.Z - position.Z) * HF,
                                config.rodinPassedFrac or 0.5
                            local bF, WF =
                                (2 * GF - 1) * ((config.missileHalfLen or 16) + (dangerGeometry.reach or 1.8)),
                                GF >= 1 and (config.rodinMissilePassed or 3)
                            if sF > -(bF + (WF or 0)) then
                                local bF = {
                                    ox = position.X,
                                    oz = position.Z,
                                    dx = tF,
                                    dz = HF,
                                }
                                BF[#BF + 1] = bF
                                TF = TF or bF
                            else
                            end
                        else
                        end
                    else
                    end
                end
                GF, zF = false, hazardReader.rodinSplit
                if zF and zF.model and zF.model.Parent and not zF.over then
                    sF = eF - zF.at
                    for index6 = 1, #F, 1 do
                        CF = F[index6] + (zF.shift or 0) - sF
                        GF = if CF > -0.2 and CF < (config.rodinMissileSplitGap or 3) then true else GF
                        GF = if config.rodinSplitOwns ~= false then true else GF
                    end
                else
                end
                zF = hazardReader.rodinFanAt
                CF = config.rodinFanOut ~= false
                    and zF ~= nil
                    and hazardReader.rodinFanYaw ~= nil
                    and eF - zF < (config.rodinFanFor or 5.5)
                if #BF > 0 and TF then
                    local bF = TF.dx
                    local WF = TF.dz
                    local TF, KF, tF, spd, XF = -WF, bF, config.missileLaneHalf or 5, config.burstMax or 28, {}
                    for index7, entry4 in ipairs(BF) do
                        if abs(entry4.dx * bF + entry4.dz * WF) > 0.96 then
                            XF[#XF + 1] = {
                                l = (entry4.ox - vector.X) * TF + (entry4.oz - vector.Z) * KF,
                                passed = (entry4.untilAt or 0) + (config.rodinPassedGrace or 0.3) <= eF,
