                        if #lines > 0 then
                            if config.rodinLinesMine ~= false then
                                pick, ui, set =
                                    if runtimeState.missileLinePt
                                            and eF - (runtimeState.missileLineAt or -infinity)
                                                < (config.rodinMissileKeep or 2.5)
                                        then (runtimeState.missileLinePt.X - vector.X) * TF
                                            + (runtimeState.missileLinePt.Z - vector.Z) * KF
                                        else 0,
                                    infinity
                                for index11 = 1, #lines, 1 do
