                            pick
                            and not control
                            and #set > 0
                            and pick.volley == hazardReader.mlVolley
                            and eF - pick.at < 0.5
                        then
                            ui = 0
                            for index15, entry6 in ipairs(pick.set) do
                                index15 = false
                                for index16, entry7 in ipairs(set) do
                                    if abs(entry7 - entry6) < 2.5 then
                                        index15 = true
                                        break
                                    end
                                end
                                ui = if not index15 then ui + 1 else ui
                            end
                            if ui > 0 and #set < #pick.set then
                                contextLogT(
                                    "rodinlines",
                                    1,
                                    "Brain",
                                    ("%d green line(s) went on their own, %d left (lanes %d, volley %s) - not the all-at-once rule"):format(
                                        ui,
                                        #set,
                                        #sF,
                                        tostring(hazardReader.mlVolley)
                                    )
                                )
                                local di = runtimeState.perf and runtimeState.perf.cur
                                if di then
                                    di.railSolo = (di.railSolo or 0) + ui
                                    di.railSoloLast = {
