                                        left = #set,
                                        lanes = #sF,
                                    }
                                end
                            end
                        end
                        runtimeState.mlPrevSet = {
                            set = set,
                            at = eF,
                            volley = hazardReader.mlVolley,
                        }
                        if control and config.rodinLinesAllAtOnce ~= false then
                            lines = {}
                            runtimeState.mlPrevSet = nil
                            hazardReader.mlDoneAt, hazardReader.mlDoneVolley = eF, hazardReader.mlVolley
                            pick = runtimeState.perf and runtimeState.perf.cur
                            if pick then
                                pick.railAll = (pick.railAll or 0) + 1
                            end
                            hazardReader.missileLines = nil
                            if context.drawMissileLines then
                                pcall(context.drawMissileLines)
                            end
                            contextLogT(
                                "rodin",
                                2,
                                "Brain",
                                ("missile volley %s: both missiles beside our line are past - all the lines gone"):format(
                                    tostring(hazardReader.mlVolley)
                                )
                            )
                        else
                            if control and #lines == 0 then
                                hazardReader.mlDoneAt, hazardReader.mlDoneVolley = eF, hazardReader.mlVolley
                            end
                        end
                        ui, control =
                            config.rodinRailAlways == false and (sF[1] - side >= 0 or sF[#sF] + side <= 0), false
                        for index17, entry8 in ipairs(sF) do
                            control = if abs(entry8) < tF + (dangerGeometry.reach or 1.8) then true else control
                        end
                        if #lines > 0 then
                            control, pick = not odinRings
                                and not iF
                                and not (GF and config.rodinRailSplitYield == true)
                                and not (CF and config.rodinRailFanYield == true)
                            if ui then
                                pick = 0
                            else
                                set = infinity
                                for index18, line in ipairs(lines) do
                                    set = if abs(line) < set then abs(line) else set
                                end
                                if
                                    runtimeState.missileLinePt
                                    and eF - (runtimeState.missileLineAt or -infinity)
                                        < (config.rodinMissileKeep or 2.5)
                                then
                                    local CF = (runtimeState.missileLinePt.X - vector.X) * TF
                                        + (runtimeState.missileLinePt.Z - vector.Z) * KF
                                    for index19, line2 in ipairs(lines) do
                                        index19 = runtimeState.railHop ~= nil
                                                and eF < (runtimeState.railHop.untilAt or 0)
                                            or runtimeState.spiralHop ~= nil
                                                and eF < (runtimeState.spiralHop.untilAt or 0)
                                        if
                                            abs(line2 - CF) < 3
                                            and (
                                                index19
                                                or abs(line2)
                                                    <= set + (config.rodinMissileKeepSlack or 6)
                                            )
                                        then
                                            pick = line2
                                            break
                                        end
                                    end
                                else
                                end
                                if not pick then
                                    local CF, iF =
                                        context.BB ~= nil and context.BB.osc ~= nil, config.rodinMissileTie or 4
                                    local function GF(di)
                                        return -WF * di < -0.5 or abs(WF * di) <= 0.5 and bF * di < 0
                                    end
                                    local function di(Qi, Di)
                                        local ci, hi = -WF * Qi, -WF * Di
                                        return ci < hi - 0.5 or abs(ci - hi) <= 0.5 and bF * Qi < bF * Di
                                    end
                                    for index20, line3 in ipairs(lines) do
                                        if not pick then
                                            pick = line3
                                        else
                                            if CF then
                                                local CF, Di = GF(line3), GF(pick)
                                                pick = if CF and not Di
                                                        or CF == Di and abs(line3) < abs(pick)
                                                    then line3
                                                    else pick
                                            else
                                                pick = if abs(line3) < abs(pick) - iF
                                                        or abs(abs(line3) - abs(pick)) <= iF
                                                            and di(line3, pick)
                                                    then line3
                                                    else pick
                                            end
                                        end
                                    end
                                else
                                end
                                if control then
                                    runtimeState.missileLinePt =
                                        Vector3.new(vector.X + TF * pick, vector.Y, vector.Z + KF * pick)
                                    runtimeState.missileLineAt = eF
                                end
                            end
                            hazardReader.missileLines = {
                                ax = bF,
                                az = WF,
                                nx = TF,
                                nz = KF,
                                bx = vector.X,
                                bz = vector.Z,
                                y = vector.Y,
                                lines = lines,
                                pick = control and not ui and pick or nil,
                                L = sF,
                                P = zF,
                                hw = tF,
                                at = eF,
                            }
                            railCalc.ax = bF
                            railCalc.az = WF
                            railCalc.nx = TF
                            railCalc.nz = KF
                            railCalc.hw = tF
                            railCalc.spd = spd
                            railCalc.L = sF
                            railCalc.P = zF
                            railCalc.hub = hub
                            railCalc.Rin = rin
                            railCalc.hl0 = Si
                            railCalc.ht0 = XF
                            railCalc.side = side
                            railCalc.lines = lines
                            railCalc.outside = ui
                            railCalc.control = control
                            railCalc.pick = pick
                            drawn = true
                        else
                        end
                    else
                    end
                else
                end
            else
            end
            railCalc.odinRings = odinRings
            railCalc.drawn = drawn
            if not drawn then
                hazardReader.missileLines = nil
            end
            runtimeState.railCalc = railCalc
            return railCalc
        end
        context.railSlideGoal = function(eF, NF, IF, FF, CF, gF, iF, bF)
            local BF = NF.X + CF * iF
            local GF = NF.Z + gF * iF
            local function zF(sF, TF)
                return (sF - BF) * IF + (TF - GF) * FF, (sF - BF) * CF + (TF - GF) * gF
            end
            iF, NF = config.rodinRailSlideOrbLat or 12, runtimeState.greenTap
            if NF and NF.at == eF and NF.to then
                local IF, FF = zF(NF.to.X, NF.to.Z)
                if abs(FF) <= iF then
                    return {
                        t = IF,
                        why = "toward the green orb",
                    }
                end
            end
            NF = hazardReader.rodinGoodOrb
            eF = NF and NF.part and NF.part.Parent and NF.part.Position or nil
            if eF then
                local IF, FF = zF(eF.X, eF.Z)
                if abs(FF) <= iF then
                    return {
                        t = IF,
                        why = "toward the green orb",
                    }
                end
            end
            iF = bF and bF.isBoss and bF.root and bF.root.Parent and bF.root.Position or nil
            if not iF then
                return nil
            end
            bF = (
                context.rodinAttackReach and context.rodinAttackReach()
                or context.fireReach and context.fireReach()
                or (config.castStartAt or 44)
            ) - (config.rodinAggroSpare or 3)
            if bF < 8 then
                return nil
            end
            eF, NF = zF(iF.X, iF.Z)
            if abs(NF) >= bF then
                if config.rodinRailSlideNear == false then
                    return nil
                end
                return {
                    t = eF,
                    why = "toward the boss (this line never comes into his reach)",
                }
            end
            zF, iF = sqrt(bF * bF - NF * NF), config.rodinRailBossMin or 10
            local IF, FF, CF = abs(NF) < iF and sqrt(iF * iF - NF * NF) or 0, { -1, 1 }
            for index, entry in ipairs(FF) do
                NF, bF = eF + entry * IF, eF + entry * zF
                entry, index = min(NF, bF), max(NF, bF)
                iF = 0 < entry and entry or (0 > index and index or 0)
                CF = if CF == nil or abs(iF) < abs(CF) then iF else CF
            end
            if CF == nil or abs(CF) < 0.5 then
                return nil
            end
            return {
                t = CF,
                why = "into the boss's reach",
            }
        end
        local function eF(NF)
            local missileLines = hazardReader.missileLines
            if
                config.rodinLaneRule == false
                or missileLines == nil
                or missileLines.L == nil
                or missileLines.P == nil
                or NF - (missileLines.at or -infinity) >= 0.3
            then
                return nil
            end
            return missileLines
        end
        context.missileLaneAt = function(NF, IF, FF)
            local CF = eF(FF)
            if not CF then
                return false
            end
            local FF, gF =
                (NF - CF.bx) * CF.nx + (IF - CF.bz) * CF.nz, (CF.hw or 5) + (dangerGeometry.reach or 1.8)
            for index = 1, #CF.L, 1 do
                if not CF.P[index] and abs(FF - CF.L[index]) < gF then
                    return true
                end
            end
            return false
        end
        context.missileLaneCross = function(NF, IF, FF)
            local CF = eF(FF)
            if not CF then
                return false
            end
            if
                runtimeState.escRedAt ~= nil
                and FF - runtimeState.escRedAt < 0.25
                and config.rodinYellowFreeInRed ~= false
                and context.missileBodyCatch
            then
                return context.missileBodyCatch(NF, IF, config.burstMax or 28)
            end
            local gF, iF =
                (NF.X - CF.bx) * CF.nx + (NF.Z - CF.bz) * CF.nz, (IF.X - CF.bx) * CF.nx + (IF.Z - CF.bz) * CF.nz
            IF, FF, NF = min(gF, iF), max(gF, iF), (CF.hw or 5) + (dangerGeometry.reach or 1.8)
            for index = 1, #CF.L, 1 do
                iF = CF.L[index]
                if not CF.P[index] and iF + NF > IF and iF - NF < FF and abs(gF - iF) >= NF then
                    return true
                end
            end
            return false
        end
        local function NF(IF, vector)
            local missileLines = hazardReader.missileLines
            if
                config.rodinRailStay == false
                or missileLines == nil
                or missileLines.pick == nil
                or IF - (missileLines.at or -infinity) >= 0.3
            then
                return nil
            end
            if
                abs(
                    (vector.X - missileLines.bx - missileLines.nx * missileLines.pick)
                            * missileLines.nx
                        + (vector.Z - missileLines.bz - missileLines.nz * missileLines.pick)
                            * missileLines.nz
                ) > (config.rodinRailOnTol or 2)
            then
                return nil
            end
            return missileLines
        end
        local function IF(FF, CF, missileLines)
            if config.rodinRailStay == false then
                return false
            end
            local rodinSweep = hazardReader.rodinSweep
            if rodinSweep and rodinSweep.model and rodinSweep.model.Parent then
                return false
            end
            if missileLines then
                return NF(FF, CF) ~= nil
            end
            missileLines = hazardReader.missileLines
            return missileLines ~= nil and missileLines.pick ~= nil and FF - (missileLines.at or -infinity) < 0.3
        end
        local function FF(CF, gF)
            if config.rodinRailPassedSide == false then
                return nil
            end
            local missileLines = hazardReader.missileLines
            if
                missileLines == nil
                or missileLines.pick == nil
                or missileLines.L == nil
                or missileLines.P == nil
                or CF - (missileLines.at or -infinity) >= 0.3
            then
                return nil
            end
            local bF, BF =
                (gF.X - missileLines.bx) * missileLines.nx + (gF.Z - missileLines.bz) * missileLines.nz,
                (missileLines.hw or 5) + (dangerGeometry.reach or 1.8)
            gF, CF = BF + 0.5
            for index = 1, #missileLines.L, 1 do
                if missileLines.L[index] - BF >= bF and not missileLines.P[index] then
                    CF = missileLines.L[index] - BF
                    break
                end
            end
            local GF
            for index2 = #missileLines.L, 1, -1 do
                if missileLines.L[index2] + BF <= bF and not missileLines.P[index2] then
                    GF = missileLines.L[index2] + BF
                    break
                end
            end
            local BF, zF = missileLines.L[#missileLines.L], missileLines.L[1]
            return {
                ml = missileLines,
                a0 = bF,
                lo = min(if GF == nil then zF ~= nil and zF < bF and zF - gF or bF else GF, bF),
                hi = max(if CF == nil then BF ~= nil and BF > bF and BF + gF or bF else CF, bF),
            }
        end
        local function CF(gF)
            return gF ~= nil and (gF.hi - gF.a0 > 1.5 or gF.a0 - gF.lo > 1.5)
        end
        local function gF(iF, bF, BF)
