        local function contextMissileBodyCatch(vector, BF, GF, zF)
            local sF, TF, WF, KF =
                (config.missileLaneHalf or 5) + (dangerGeometry.reach or 1.8) + (config.rodinHopMissilePad or 1),
                (config.missileHalfLen or 16) + (dangerGeometry.reach or 1.8),
                BF.X - vector.X,
                BF.Z - vector.Z
            BF = sqrt(WF * WF + KF * KF)
            local tF = math.clamp(math.ceil(BF / 3), 1, 40)
