                if key.Parent and string.lower(key.Name):find("thirdbossmissile", 1, true) then
                    local di = sqrt((entry.vx or 0) ^ 2 + (entry.vz or 0) ^ 2)
                    if di > 2 then
                        local Qi, Li, position = entry.vx / di, entry.vz / di, key.Position
                        for index = 0, tF, 1 do
                            local di = index / tF
