                (config.missileLaneHalf or 5) + KF + (config.rodinHopMissilePad or 1),
                (config.missileLaneHalf or 5) + KF,
                BF.X - vector.X,
                BF.Z - vector.Z
            BF = math.sqrt(XF * XF + di * di)
            local Qi, Li, Oi, Si, Di, Pi =
                math.clamp(math.ceil(BF / 1.5), 2, 60),
                math.max(GF, 1),
                XF * TF + di * WF,
                math.huge,
                math.huge,
                math.huge
            for index, entry in ipairs(context.hopMissiles(sF)) do
                index = nil
                if math.abs(entry.dx * WF - entry.dz * TF) > 0.96 then
                    KF, GF = (entry.ox - vector.X) * TF + (entry.oz - vector.Z) * WF, Oi >= 0 and 1 or -1
