            local di, Qi, Li, Oi, Si, Di, Pi, _i =
                HF / WF,
                XF / WF,
                dangerGeometry.reach or 1.8,
                config.rodinSpiralTight or 0.5,
                config.rodinSpiralSlack or 0.8,
                config.rodinSpiralGone or 0.45,
                config.rodinSpiralUnc or 0.3,
                (config.rodinSpiralGrid or 3) / tF
            for index, entry in ipairs(sF) do
                if entry.left >= -Di then
                    HF, XF, KF = (entry.r0 or entry.R) + Li + Oi, vector.X - entry.x, vector.Z - entry.z
                    index = XF * XF + KF * KF - HF * HF
