                            end
                        end
                    end
                end
            end
            return true
        end
        local function sF(TF, WF, KF, tF, HF, XF, di, Qi, Li, Oi)
            local Si = runtimeState.spiralPath
            if Si and WF - Si.at < (config.rodinSpiralReplan or 0.2) then
                while true do
                    local idx, path = Si.idx, Si.path
                    if not (idx <= #path and a(TF, Si.path[Si.idx]) < 2) then
                        break
