        local function WF(vector, tF, HF, XF, di, Qi, vector2, Oi, Si)
            local Di, Pi, _i = max(XF, 4), Qi.bx + Qi.nx * Qi.pick, Qi.bz + Qi.nz * Qi.pick
            local li, ci, ui, hi, mi =
