                        local Ji = Vector3.new(pi, vector.Y, Ui)
                        local forced, Yi =
                            context.spiralWalkBad(HF, vector, Ji, Di, 0, true), GF(HF, pi, Ui, index)
                        if forced == 0 and Yi then
                            local Ei = index2 * (config.rodinSpiralTravelW or 1.5)
                                + (di and sqrt((di.X - pi) ^ 2 + (di.Z - Ui) ^ 2) or 0)
