            local ci, ui = WF(vector, HF, XF, di, Qi, Li, vector2, Si, Di), config.rodinRailLineFar or 200
            if Pi and ui > Di and not (ci and GF(XF, ci.q.X, ci.q.Z, ci.travel / _i)) then
