        context.spiralAround = function(tF, HF, goal, di)
            if
                config.rodinSpiralAround == false
                or not goal
                or not (context.spiralList and hazardReader.rodinRig and hazardReader.rodinRig.Parent)
            then
                return nil
            end
            local Qi = context.spiralList(HF, (dangerGeometry.reach or 1.8) + (config.rodinSpiralMargin or 1.5))
            if #Qi == 0 then
                return nil
            end
            local Li = runtimeState.spiralAround
            if Li and HF - Li.at < (config.rodinSpiralReplan or 0.2) and a(Li.goal, goal) < 3 then
                while true do
                    local idx, path = Li.idx, Li.path
                    if not (idx <= #path and a(tF, Li.path[Li.idx]) < 2) then
                        break
                    end
                    Li.idx = Li.idx + 1
                end
                if Li.idx <= #Li.path then
                    for index = min(Li.idx + 3, #Li.path), Li.idx, -1 do
                        if eF(Qi, tF, Li.path[index], di) then
