                goal,
                hazardReader.arenaCentre,
                ((config.rodinSweepArenaR or 100) - 4) ^ 2,
                context.BB and context.BB.blueBeams and context.BB.blueBeams() or nil,
                false,
                config.rodinSpiralAroundW or 0.3,
                nil,
                FF(HF, tF)
