                    goal = Li.path[index2]
                    break
                end
            end
            return goal
        end
        local function eF(tF, HF, XF, di, Qi, Li, Oi, Si, Di)
            local Pi = runtimeState[tF]
            if Pi and XF - Pi.at < (config.rodinSpiralReplan or 0.2) then
                while true do
                    local idx, path = Pi.idx, Pi.path
                    if not (idx <= #path and a(HF, Pi.path[Pi.idx]) < 2) then
                        break
                    end
                    Pi.idx = Pi.idx + 1
                end
                if Pi.idx <= #Pi.path then
                    return Pi.path[min(Pi.idx + 1, #Pi.path)], Pi
                end
            end
            local _i = not Di and zF(HF, XF, di, Qi, nil, Li, Oi, nil, false, nil, nil, Si) or nil
            _i = if not _i then (zF(HF, XF, di, Qi, nil, Li, Oi, nil, true, nil, nil, Si)) else _i
            if not _i then
                runtimeState[tF] = nil
