            return _i.path[min(2, #_i.path)], Pi
        end
        local function tF(HF, vector)
            if
                config.rodinSpiralFirst == false
                or not (context.spiralList and hazardReader.rodinRig and hazardReader.rodinRig.Parent)
            then
                return false
            end
            if
                runtimeState.spiralOut
                and runtimeState.spiralOut.coveredAt
                and HF - runtimeState.spiralOut.coveredAt < 0.25
            then
                return true
            end
            local di, Qi =
                context.spiralList(HF, (dangerGeometry.reach or 1.8) + (config.rodinSpiralMargin or 1.5)),
                config.rodinSpiralEngage or 1
            for index, entry in ipairs(di) do
                if
                    (not entry.pred or entry.left <= Qi)
                    and (vector.X - entry.x) ^ 2 + (vector.Z - entry.z) ^ 2 < entry.R * entry.R
                then
                    return true
                end
            end
            return false
        end
        local function HF(XF)
            local di = XF and XF.name
            return not (di == "bonusbosslongline" or di == "rodin line next")
        end
        local function XF(di)
            local arenaCentre = hazardReader.arenaCentre
            if not arenaCentre then
                return nil
            end
            if not hazardReader.rodinSpawnPt then
                local bonusBossPlayerSpawnPart = contextWorkspace:FindFirstChild("bonusBossPlayerSpawnPart")
                if bonusBossPlayerSpawnPart then
                    hazardReader.rodinSpawnPt = bonusBossPlayerSpawnPart.Position
                end
            end
            local Li = hazardReader.rodinSpawnPt
            local Oi, Si =
                (Li and math.atan2(Li.Z - arenaCentre.Z, Li.X - arenaCentre.X) or math.rad(
                    config.rodinEntranceDeg or 161
                )) + math.rad(config.rodinFlameStandDeg or -28.9),
