            local ui = config.touchLanesAsOne ~= false
                and ci ~= nil
                and ci.model ~= nil
                and ci.model.Parent ~= nil
                and not runtimeState.touchdownOn
            local hi, mi, Ri, yi, qi, Vi =
                ui and context.BB.blueBeamsLong and context.BB.blueBeamsLong(config.touchLaneHold or 4.4) or Oi,
                config.beamEscapeWays or 32,
                ui and (config.touchBeamFar or 60) or (config.beamEscapeFar or 40),
                {},
