                    if not context.BB.onBlueBeam(Ri, Ji, 0.5, hi) then
                        if spare(Ri, Ji, _i) then
                            local cost = index2
                                + (
                                    vector2
                                        and (sqrt((vector2.X - Ri) ^ 2 + (vector2.Z - Ji) ^ 2) - a(
                                            vector,
                                            vector2
