                            cost = if Di then cost + YF(Di, Ri, Ji) else cost
                            cost = if context.BB.yellowAt
                                    and context.BB.yellowAt(Ri, Ji, Li + _i, hi)
                                then cost + (config.rodinYellowCost or 1000)
                                else cost
                            local Li, Pi = #yi + 1, {}
                            Pi.q, Pi.d, Pi.cost, yi[Li] = Vector3.new(Ri, vector.Y, Ji), index2, cost, Pi
                            break
