                            ji = if spare2 >= (config.beamThroughSpare or 0.8)
                                    and spare2 > Vi + 0.3
                                    and (not ji or spare2 > ji.spare)
                                    and spare(Ri, Ji, _i)
                                then {
                                    q = Vector3.new(Ri, vector.Y, Ji),
                                    d = index2,
                                    spare = spare2,
                                }
                                else ji
                        else
                        end
                    end
                end
                if ji then
                    qi[#qi + 1] = ji
                end
            end
            table.sort(yi, function(Li, Pi)
                return Li.cost < Pi.cost
            end)
            for index3 = 1, min(#yi, config.beamEscapeTry or 16), 1 do
                ci = yi[index3]
                if
                    not context.BB.pathTouchesRed(vector, ci.q, Si)
                    and context.BB.orbPathSafe(vector, ci.q, Si)
