                    return ci, "clear"
                end
            end
            table.sort(qi, function(Li, Pi)
                return Li.spare > Pi.spare
            end)
            for index4 = 1, min(#qi, config.beamThroughTry or 8), 1 do
                Di = qi[index4]
                if
                    not context.BB.pathTouchesRed(vector, Di.q, Si)
                    and context.BB.orbPathSafe(vector, Di.q, Si)
