                        local eta = math.max(d - math.max((sp.r or 20) - edgeIn, 1), 0) / speedNow
                        if not soonEta or eta < soonEta then
                            soonSpot, soonEta = sp, eta
                        end
                        local pen = 0 -- D-106: a circle a teammate is closer to is theirs (ties by name)
                        if config.gildedCircleShare ~= false then
                            for _, pl in ipairs(game:GetService("Players"):GetPlayers()) do
                                local r = pl ~= localPlayer and pl.Character and pl.Character:FindFirstChild("HumanoidRootPart")
                                local hh = r and pl.Character:FindFirstChildOfClass("Humanoid")
                                if r and hh and hh.Health > 0 then
                                    local dm = math.sqrt((r.Position.X - sp.x) ^ 2 + (r.Position.Z - sp.z) ^ 2)
                                    if dm < d - 2 or math.abs(dm - d) <= 2 and string.lower(pl.Name) < string.lower(localPlayer.Name) then
                                        pen = 1000
                                    end
                                end
                            end
                        end
                        -- D-111: with our beam on, not a circle whose way crosses our own fresh trail (E/F: 3 of 5 beam deaths
                        -- turned back through it at the switch to the circles; the squares of its last ~0.4 s are not down yet)
                        local back = beamOn and context.gildedOwnTrailHit
                            and context.gildedOwnTrailHit(posSeen.X, posSeen.Z, sp.x, sp.z, speedNow, y)
                        -- D-130 (boss 1): its straight way crosses a beam square or a teammate's fresh trail
                        local sqWay = not back and eta <= leftT and context.gildedSquareLine
                            and context.gildedSquareLine(posSeen, sp.x, sp.z, speedNow, y, math.max((sp.r or 20) - edgeIn, 1))
                        if eta <= leftT and not back and not sqWay and pen == 0 and (not cleanEta or eta < cleanEta) then
                            cleanSpot, cleanEta = sp, eta
                        end
                        if eta <= leftT and not back then
                            if pen == 0 and (not freeEta or eta < freeEta) then
                                freeSpot, freeEta = sp, eta
                            end
                            if not fwdEta or eta < fwdEta then
                                fwdSpot, fwdEta = sp, eta
                            end
                        end
                        if eta <= leftT and not back and not sqWay and (not bestD or d + pen < bestD) then
                            local okR, way = pcall(context.safeRoute, posSeen, sp.x, sp.z, speedNow, y, true)
                            if okR and way then
                                bestSpot, bestD = sp, d + pen
                            end
                        end
                    end
                    -- D-111: no clear way to any - one in time that is no teammate's and not behind us, then one not behind us,
                    -- then the soonest (E: two accounts in one circle, the fallback ignored the claim; both died in it)
                    if bestSpot and bestD and bestD >= 1000 and cleanSpot and config.gildedB1FreeCircle ~= false
                        and context.kiryneUp and context.kiryneUp() then
                        -- D-138 (boss 1): the circle with a clear way is a teammate's (D-106: d + 1000). While that teammate's
                        -- beam is on its squares fill the circle (Y22 acct1, X20 acct3: a free circle 20-27 studs off
                        -- passed over, dead in the teammate's squares) - a free, clean circle in time comes first (D-130)
                        local now, beamed = os.clock(), false
                        for _, pl in ipairs(game:GetService("Players"):GetPlayers()) do
                            local ch = pl ~= localPlayer and pl.Character
                            local r = ch and ch:FindFirstChild("HumanoidRootPart")
                            local hh = r and ch:FindFirstChildOfClass("Humanoid")
                            local tr = r and hazardReader.mateTrails and hazardReader.mateTrails[ch]
                            if tr and #tr > 0 and now - tr[#tr].t <= 0.5 and hh and hh.Health > 0 then
                                local dB = a(posSeen, Vector3.new(bestSpot.x, posSeen.Y, bestSpot.z))
                                local dm = math.sqrt((r.Position.X - bestSpot.x) ^ 2 + (r.Position.Z - bestSpot.z) ^ 2)
                                if dm < dB - 2 or math.abs(dm - dB) <= 2 and string.lower(pl.Name) < string.lower(localPlayer.Name) then
                                    beamed = true
                                end
                            end
                        end
                        if beamed then
                            bestSpot = cleanSpot
                        end
                    end
                    local ownC = context.gildedB1OwnCircle and context.gildedB1OwnCircle(posSeen, speedNow, leftT, edgeIn, y)
                    if ownC then
                        bestSpot = ownC -- D-168 (1C): our own circle, in our quadrant
                    end
                    bestSpot = bestSpot or cleanSpot or freeSpot or fwdSpot or soonSpot -- D-130: clean of squares first (D-138)
                    -- D-110 (boss 1, our beam on): keep the circle chosen for this field while we still reach it in time -
                    -- a switch turned accounts back through their own trail (06:21 / 06:25: 5 deaths in the walk)
                    local pk = runtimeState.b1Pick
                    if pk and pk.from == WF.from and context.gildedMyBeamOn and context.gildedMyBeamOn() then
                        for _, sp in ipairs(hazardReader.safeSpots) do
                            if math.abs(sp.x - pk.x) < 1 and math.abs(sp.z - pk.z) < 1 then
                                local dk = a(posSeen, Vector3.new(sp.x, posSeen.Y, sp.z))
                                if math.max(dk - math.max((sp.r or 20) - edgeIn, 1), 0) / speedNow <= leftT then
                                    bestSpot = sp
                                end
                            end
                        end
                    end
                    if bestSpot then
                        runtimeState.b1Pick = { from = WF.from, x = bestSpot.x, z = bestSpot.z }
                    end
                    if bestSpot then
                        Si, Oi = bestSpot, a(posSeen, Vector3.new(bestSpot.x, posSeen.Y, bestSpot.z))
                    end
                end
                if Si and context.gildedFireballOut then
                    local outP, how = context.gildedFireballOut(posSeen, Si) -- D-110 (boss 3): a fireball lane over the refuge
                    if outP and how == "wait" and context.gildedWaitThreat and context.gildedWaitThreat(posSeen, y) then
                        -- D-150: an attack on us while waiting - this tick goes to the dodge (as D-043 / D-122)
                        runtimeState.refugeLeash = nil
                        Si, u, outP = nil, false, nil
                    end
                    if outP and not (how == "wait" and context.BB and context.BB.lethal) then -- another attack: its dodge
                        runtimeState.refugeLeash = nil
                        if how == "wait" then
                            contextReleaseMover(humanoid, zF)
                            contextSetState("FIREBALL: its lane is over the refuge - waiting outside it until it strikes")
                        else
                            g(humanoid, zF, outP, config.tweenEscape, 1)
                            contextSetState("FIREBALL: across and out of its lane - back into the refuge after it")
                        end
                        if target then
                            p(humanoid, zF, target, y)
                        end
                        return
                    end
                end
                local threat = context.BB ~= nil and (
                    context.BB.lethal == true
                    or (context.BB.count or 0) > 0
                    or hazardReader.gildedOn and context.BB.active == true -- D-049: warnings too
                )
                if not threat and hazardReader.gildedOn and wfName == "gilded memory" and config.gildedRefugeSeeShapes ~= false then
                    -- D-122 (final boss): BB.tick runs after this block, so while the refuge loop / walk returns early the
                    -- brain's threat state stays as it was before the field - an S-shape circle or spiral shot that shows
                    -- during the field was never a threat (15:51-17:31: 8 hits inside the memory circle, "moving inside it").
                    -- The live boxes: a young one holding us gives this tick to the dodge (leashed in the refuge, D-043)
                    for _, box in ipairs(dangerGeometry.boxes or {}) do
                        local bn = box.name
                        if (bn == "thirdbosssshapecircle" or bn == "thirdbossspiralshot") and (box.untilAt or 0) > y
                            and (box.from or y) - y < (config.gildedRefugeShapeLead or 0.6) then
                            local okD, depth = pcall(contextDepthOf, box, posSeen.X, box.cy or posSeen.Y, posSeen.Z, 0)
                            if okD and depth and depth >= -(config.gildedRefugeShapeMargin or 1.5) then
                                threat = true
                                break
                            end
                        end
                    end
                end
                local soft = tostring(WF.name or ""):find("orb collect", 1, true) ~= nil
                local orbUrgent = false
                if soft and Si and hazardReader.gildedOn and hazardReader.gildedCollect and hazardReader.gildedCollect.fuseAt then
                    -- D-085: little time left on our orb - only an attack about to hit us still comes first
                    local sp = math.max(humanoid.WalkSpeed * (context.speedMul and context.speedMul() or 1), 16)
                    orbUrgent = hazardReader.gildedCollect.fuseAt - y < Oi / sp + (config.gildedOrbUrgent or 2.5)
                end
                if threat and soft and not (orbUrgent and not context.BB.lethal) then
                    -- D-043: the orb waits (~6 s); the dodge comes first, the collect resumes after it
                    runtimeState.refugeLeash = nil
                    Si, u = nil, false
                elseif u and threat and Si and not (context.gildedBeamLoop and context.gildedBeamLoop(WF)) then
                    -- D-043: an attack while in the refuge: dodge, but every move stays inside it (g)
                    if not (context.gildedRefugeFree and context.gildedRefugeFree(WF)) and tostring(WF.name) ~= "gilded smash" then -- D-059 boss 3; D-061 the hammer's band clamps instead
                        local edge = tostring(WF.name) == "thirdbossmasssafespotcircles" and (config.gildedCircleEdge or 6) or (config.safeInset or 2)
                        runtimeState.refugeLeash = { x = Si.x, z = Si.z, r = max((Si.r or 4) - edge, 1.5), at = os.clock(), name = tostring(WF.name) }
                    end
                    Si, u = nil, false
                end
                local loopName = tostring(WF.name)
                local loopR = hazardReader.gildedOn and config.gildedCircleMove ~= false and (
                    loopName == "thirdbossmasssafespotcircles" and ((context.gildedMyBeamOn and context.gildedMyBeamOn())
                        and max((Si and Si.r or 20) - (config.gildedCircleEdge or 6) - 1, 3) -- D-110: wide while our beam follows
                        or max((Si and Si.r or 20) * (config.gildedCircleLoop or 0.45), 3)) -- boss 1
                    or loopName == "gilded smash" and (config.gildedSmashLoop or 2.5) -- boss 2 (D-046)
                    or loopName:sub(1, 13) == "gilded colour" and (config.gildedColourLoop or 2.5) -- boss 3 (D-046)
                    or loopName == "gilded memory" and (config.gildedMemoryLoop or 6) -- boss 3 (D-049; D-051: 6 studs)
                    or loopName == "gilded firewall gap" and (config.gildedFireLoop or 2) -- boss 3 (D-049; D-054: 2)
                ) or nil
                if u and Si and loopR and loopName == "gilded firewall gap" and Si.lx and config.gildedFireForward ~= false then
                    -- D-061 (boss 3): along the gap's centre line toward Vytelus instead of circling on the spot
                    local bossPos
                    for _, enemy in ipairs(hazardReader.enemies or {}) do
                        if enemy.isBoss and enemy.root and enemy.root.Parent then
                            bossPos = enemy.root.Position
                        end
                    end
                    local lx, lz = Si.lx, Si.lz
                    local along = (posSeen.X - Si.x) * lx + (posSeen.Z - Si.z) * lz
                    local nx, nz = Si.x + lx * along, Si.z + lz * along -- the line point beside us
                    local nextWall = false
                    if config.gildedFireNext == true and hazardReader.fireWalls then -- D-073: off (the lean was cumulative: run7-10 hit at the gap's edge)
                        -- D-072 (boss 3): a later wall in flight - stand toward its gap (up to 8 off this line), no walk
                        -- toward the boss (toward the walls)
                        local sx, sz = -lz, lx
                        local bestOff
                        for _, w in ipairs(hazardReader.fireWalls) do
                            local a2 = (posSeen.X - w.origin.X) * w.look.X + (posSeen.Z - w.origin.Z) * w.look.Z
                            local passT = w.startAt + math.max(a2, 0) / w.speed
                            if a2 > -5 and a2 < w.length and passT > (WF.passAt or WF.untilAt - 0.8) + 0.2 then
                                local off = (w.origin.X - nx) * sx + (w.origin.Z - nz) * sz
                                if not bestOff then
                                    bestOff = off
                                end
                            end
                        end
                        if bestOff then
                            nextWall = true
                            local shift = math.clamp(bestOff, -(config.gildedFireShift or 8), config.gildedFireShift or 8)
