                        if math.abs(toBoss) > (config.gildedFireBossStop or 20) then
                            local s = toBoss > 0 and 1 or -1
                            nx, nz = nx + lx * s * (config.gildedFireStep or 3), nz + lz * s * (config.gildedFireStep or 3)
                        end
                    end
                    Si.x, Si.z = nx, nz -- the refuge moves along its line with us (clamps follow)
                    runtimeState.refugeLeash = nil
                    g(humanoid, zF, Vector3.new(nx, posSeen.Y, nz), config.tweenEscape, 1)
                    contextSetState(("FLAME WALL: in its gap, %s (passes in %.1fs)"):format(
                        still and "standing on its centre line" or "along it toward the boss", (WF.passAt or WF.untilAt - 0.8) - y))
                    if target then
                        p(humanoid, zF, target, y)
                    end
                    return
                end
                if u and Si and loopR then
                    -- D-044/D-046: keep moving inside the refuge (never standing), dodges leashed inside it
                    local ang = os.clock() * (config.gildedCircleTurn or 1.4) * (loopName == "thirdbossmasssafespotcircles" and 1 or 2)
                    do -- D-057: aim ahead of where the bot is on the loop, so it never catches its target and stops
                        local ox, oz = posSeen.X - Si.x, posSeen.Z - Si.z
                        if config.gildedLoopLead ~= false and ox * ox + oz * oz > 0.25 then
                            local lead = config.gildedLoopLeadRad or 1.0
                            if loopName == "thirdbossmasssafespotcircles" and context.gildedLoopTurn then -- D-116 (boss 1)
                                lead = context.gildedLoopTurn(WF, Si, posSeen, loopR, lead,
                                    math.max(humanoid.WalkSpeed * (context.speedMul and context.speedMul() or 1), 16), y)
                            end
                            ang = math.atan2(oz, ox) + lead
                        end
                    end
                    local inset = loopName == "thirdbossmasssafespotcircles" and (config.gildedCircleEdge or 6) or (config.safeInset or 2)
                    runtimeState.refugeLeash = { x = Si.x, z = Si.z, r = max((Si.r or 20) - inset, 1.5), at = os.clock(), name = loopName } -- D-050: boss 1 keeps 6 from the edge
                    local loopAt = Vector3.new(Si.x + math.cos(ang) * loopR, posSeen.Y, Si.z + math.sin(ang) * loopR)
                    if hazardReader.gildedOn and config.gildedRefugeDodge ~= false and context.BB and context.BB.wayClear then
                        -- D-100: S-shape circles / spiral shots hit inside the memory circle on the blind loop
                        local okL, clearL = pcall(context.BB.wayClear, posSeen, loopAt, config.tweenEscape, y)
                        local spdL = math.max(humanoid.WalkSpeed * (context.speedMul and context.speedMul() or 1), 16)
                        local sqL = loopName == "thirdbossmasssafespotcircles" and context.gildedSquareLine
                            and context.gildedSquareLine(posSeen, loopAt.X, loopAt.Z, spdL, y, 0) -- D-130: squares / fresh trail
                        if okL and clearL == false or sqL then
                            local rMax = max((Si.r or 20) - inset, 1.5)
                            local best, bestD
                            -- D-130: pass 1 (its way crosses squares / a teammate's fresh trail) keeps off them and 4+ studs
                            -- off our spot; pass 2 is D-100's search as before (only when the loop's way is not clear)
                            for pass = sqL and 1 or 2, (okL and clearL == false) and 2 or 1 do
                                for ringK = 0, best and -1 or 3 do
                                    local rr = rMax * ringK / 3
                                    for k = 0, (ringK == 0 and 0 or 11) do
                                        local a = k * math.pi / 6
                                        local q = Vector3.new(Si.x + math.cos(a) * rr, posSeen.Y, Si.z + math.sin(a) * rr)
                                        local dd = (q.X - posSeen.X) ^ 2 + (q.Z - posSeen.Z) ^ 2
                                        local back = loopName == "thirdbossmasssafespotcircles" and context.gildedOwnTrailHit
                                            and context.gildedOwnTrailOn and context.gildedOwnTrailOn()
                                            and context.gildedOwnTrailHit(posSeen.X, posSeen.Z, q.X, q.Z, spdL, y)
                                        if pass == 1 and not back
                                            and (dd < 16 or context.gildedSquareLine(posSeen, q.X, q.Z, spdL, y, 0)) then
                                            back = true
                                        end
                                        if not back and (not bestD or dd < bestD) then -- D-111: E, acct1 reversed onto its trail
                                            local okC, clearC = pcall(context.BB.wayClear, posSeen, q, config.tweenEscape, y)
                                            if okC and clearC ~= false then
                                                best, bestD = q, dd
                                            end
                                        end
                                    end
                                end
                            end
                            if best then
                                loopAt = best
                            end
                        end
                    end
                    g(humanoid, zF, loopAt, config.tweenEscape, 1)
                    contextSetState(("SAFE SPOT: moving inside it (%s), field for %.1fs"):format(loopName, WF.untilAt - y))
                    if target then
                        p(humanoid, zF, target, y)
                    end
                    return
                end
                if u then
                    contextReleaseMover(humanoid, zF)
                    contextSetState(("SAFE SPOT: standing in it, field for %.1fs"):format(WF.untilAt - y))
                    if target then
                        p(humanoid, zF, target, y)
                    end
                    return
                end
                local shapeYield -- D-137: "on" (it holds us: the dodge) / "ahead" (on the next 0.3 s of the straight way: hold)
                if Si and hazardReader.gildedOn and wfName == "gilded firewall gap" and config.gildedFireShapeYield ~= false then
                    -- D-137 (26 acct2: D-125 stood down at the circle's edge and "SAFE SPOT: 71 studs to the nearest of 1"
                    -- walked into it, struck at 1.01; X20 acct1: out of one by its escape, D-125 walked back in)
                    local spdY = math.max(humanoid.WalkSpeed * (context.speedMul and context.speedMul() or 1), 16)
                    local dxY, dzY = Si.x - posSeen.X, Si.z - posSeen.Z
                    local dlY = math.sqrt(dxY * dxY + dzY * dzY)
                    for _, box in ipairs(dangerGeometry.boxes or {}) do
                        local bn = tostring(box.name or "")
                        if (bn == "thirdbosssshapecircle" or bn == "thirdbossspiralshot") and y >= (box.from or 0) - 0.1
                            and (box.untilAt or 0) > y then
                            for k = 0, 3 do
                                local f = dlY > 0.5 and math.min(spdY * 0.1 * k / dlY, 1) or 0
                                local okD, depth = pcall(contextDepthOf, box, posSeen.X + dxY * f, box.cy or posSeen.Y, posSeen.Z + dzY * f, 0)
                                if okD and depth ~= nil and depth >= (k == 0 and -1.5 or -0.5) then
                                    shapeYield = (k == 0 or shapeYield == "on") and "on" or "ahead"
                                    break
                                end
                            end
                        end
                    end
                    if shapeYield == "ahead" and not (context.BB and context.BB.lethal) then
                        contextReleaseMover(humanoid, zF)
                        contextSetState("FLAME WALL: holding - a young S-shape circle on the way to the gap can strike")
                        if target then
                            p(humanoid, zF, target, y)
                        end
                        return
                    end
                end
                if Si and hazardReader.gildedOn and wfName == "gilded firewall gap" and config.gildedFireShapeWalk ~= false
                    and not shapeYield
                    and WF.passAt and context.BB and context.BB.wayClear then
                    -- D-125 (U1 / U3): a far gap with little time - S-shape circles and spiral shots do not stop the walk
                    -- (0.8-1.0 s of "STEP OFF ... standing still" killed six); one holding us in its strike window is dodged
                    local spd = math.max(humanoid.WalkSpeed * (context.speedMul and context.speedMul() or 1), 16)
                    local passG = WF.passAt -- D-137 (run 22): the wall's pass at the gap point, not at our spot along its line
                    local wl = WF.wall
                    if config.gildedFireGapPass ~= false and wl and wl.origin and wl.look and (wl.speed or 0) > 0 then
                        passG = wl.startAt + math.max((Si.x - wl.origin.X) * wl.look.X + (Si.z - wl.origin.Z) * wl.look.Z, 0) / wl.speed
                    end
                    local walkW = math.max(Oi - (Si.r or 6), 0) / spd
                    if config.gildedFireLapseModel ~= false and context.gildedWalkTime then
                        local okT, tW = pcall(context.gildedWalkTime, math.max(Oi - (Si.r or 6), 0), humanoid)
                        if okT and type(tW) == "number" then
                            walkW = tW
                        end
                    end
                    local spareW = (passG - y) - walkW
                    if Oi > (config.gildedFireFarWalk or 30) and spareW < (config.gildedFireFarSpare or 2) and spareW > -0.5 then
                        local all, keep, struck = dangerGeometry.boxes or {}, {}, false
                        for _, box in ipairs(all) do
                            local bn = tostring(box.name or "")
                            if bn == "thirdbosssshapecircle" or bn == "thirdbossspiralshot" then
                                if y >= (box.from or 0) - 0.1 and (box.untilAt or 0) > y then
                                    local okD, depth = pcall(contextDepthOf, box, posSeen.X, box.cy or posSeen.Y, posSeen.Z, 0)
                                    struck = struck or (okD and depth ~= nil and depth >= -1.5)
                                end
                            elseif not bn:find("flamewall", 1, true) then
                                keep[#keep + 1] = box
                            end
                        end
