                            dangerGeometry.boxes = keep
                            local okW, clearW = pcall(context.BB.wayClear, posSeen, Vector3.new(Si.x, posSeen.Y, Si.z), config.tweenEscape, y)
                            dangerGeometry.boxes = all
                            if okW and clearW ~= false then
                                g(humanoid, zF, Vector3.new(Si.x, posSeen.Y, Si.z), config.tweenEscape, 1)
                                contextSetState(("FLAME WALL: far gap, straight past the circles (%.0f studs, %.1fs spare)"):format(Oi, spareW))
                                if target then
                                    p(humanoid, zF, target, y)
                                end
                                return
                            end
                        end
                    end
                end
