                local circleWalk = hazardReader.gildedOn
                    and tostring(WF.name) == "thirdbossmasssafespotcircles"
                    and (WF.from - y) > math.max(config.gildedCircleWaitLeft or 0.6, Oi / (config.gildedCircleWalkSpeed or 26) + 0.8) -- D-048/D-060 (boss 1): wait for a clear way only with time to spare
                if Si and threat and context.gildedRefugeFree and context.gildedRefugeFree(WF) then
                    orbWayBlocked = true -- D-059 (boss 3): not yet near its blast - dodge first, back in after
                end
                local smashNear = false -- D-111 (boss 2): the hammer about to strike - the straight way, no detour
                if Si and hazardReader.gildedOn and tostring(WF.name) == "gilded smash" and config.gildedSmashDirect ~= false
                    and WF.strikeAt then
                    local spd = math.max(humanoid.WalkSpeed * (context.speedMul and context.speedMul() or 1), 16)
                    smashNear = WF.strikeAt - y < Oi / spd + (config.gildedSmashUrgent or 1.0)
                end
                if Si and not orbWayBlocked and not smashNear and hazardReader.gildedOn and context.safeRoute
                    and (tostring(WF.name) == "gilded smash" or tostring(WF.name) == "gilded orb collect"
                        or tostring(WF.name) == "gilded firewall gap" -- D-067 (boss 3): into the gap on a clear way
                        or tostring(WF.name) == "thirdbossmasssafespotcircles" and context.gildedMyBeamOn
                            and context.gildedMyBeamOn()) -- D-110 (boss 1): to the green circle round our own trail
                    and not (context.BB and context.BB.lethal) then
                    -- D-061 (boss 2): a route clear of every attack at the times we pass (passive circles 17 studs off)
                    local speedNow = math.max(humanoid.WalkSpeed, 16)
                    local okR, via = pcall(context.safeRoute, posSeen, Si.x, Si.z, speedNow, y, false,
                        (tostring(WF.name) == "gilded orb collect" or tostring(WF.name) == "gilded smash")
                            and { fresh = config.gildedOrbFresh or 0.9 } or nil) -- D-074; D-084: the hammer's spot too
