            local sf = context.startFailsafe
            if type(sf) ~= "table" or sf.job ~= job then
                -- a new attempt (another dungeon server, or this script's first look): clear the previous attempt's
                -- timer, request and start-wall synchronization state
                local prev = type(sf) == "table" and sf or nil
                sf = { job = job, requests = 0 }
                context.startFailsafe = sf
                if prev then
                    if runtimeState.preStart and runtimeState.preStart.job ~= job then
