                local a, b = from[key], to[key]
                if typeof(a) == "Color3" and typeof(b) == "Color3" and map[a:ToHex()] == nil then
                    map[a:ToHex()] = b
                end
            end
            usePalette(name)
            local list = root:GetDescendants()
            table.insert(list, 1, root)
            local changed = 0
            for _, inst in ipairs(list) do
