                                end)
                                if ok and typeof(value) == "Color3" then
                                    local new = map[value:ToHex()]
                                    if new then
                                        inst[prop] = new
                                        changed += 1
                                    end
                                elseif ok and typeof(value) == "ColorSequence" then
                                    local points, hit = {}, false
                                    if inst:GetAttribute("AurBody") then
                                        points = {
                                            ColorSequenceKeypoint.new(0, theme.BodyTop),
                                            ColorSequenceKeypoint.new(0.45, theme.BodyMid),
                                            ColorSequenceKeypoint.new(1, theme.BodyBot),
