                local h = f.AbsoluteSize.Y
                local cut = math.clamp(1 / (h > 4 and h or 48), 0.002, 0.2)
                local lineT, fillT = state.line and 0 or 1, state.fillT or (state.hover and 0.45 or 1)
                gradient.Color = ColorSequence.new({
