        -- Aur_Hub (D-026, D-028): one message style for every post: a linked title, ### sections, one inline-code line
        -- per fact. One builder serves the run and Rodin reports (single and merged), the late drops, the alerts and
        -- the hub preview; post() restyles anything else on the way out.
        local reportRank = { common = 1, uncommon = 2, rare = 3, epic = 4, legendary = 5, ultimate = 6 }
        local reportDot = {
            ultimate = "\u{1F534}",
            legendary = "\u{1F7E1}",
            epic = "\u{1F7E3}",
            rare = "\u{1F535}",
            uncommon = "\u{1F7E2}",
            common = "\u{26AA}",
            unknown = "\u{26AB}",
        }
        local reportRarity = {
            ultimate = "Ultimate",
            legendary = "Legendary",
            epic = "Epic",
            rare = "Rare",
            uncommon = "Uncommon",
            common = "Common",
            unknown = "Unsorted",
        }
        local reportKind = {
            weapons = "Weapon",
            helmets = "Helmet",
            chests = "Chest",
            abilities = "Ability",
            keys = "Key",
            pets = "Pet",
        }
        local reportSep = " \u{00B7} "
        local reportUrl = "https://www.roblox.com/games/77649408247578"
        local function reportNumber(value)
            value = tonumber(value) or 0
            local size = math.abs(value)
            for _, step in ipairs({ { 1e12, "T" }, { 1e9, "B" }, { 1e6, "M" }, { 1e3, "K" } }) do
                if size >= step[1] * 0.99995 then
                    return (("%.1f"):format(value / step[1]):gsub("%.0$", "")) .. step[2]
                end
            end
            return tostring(math.floor(value + 0.5))
        end
        local function reportSigned(value)
            value = tonumber(value) or 0
            return (value < 0 and "-" or "+") .. reportNumber(math.abs(value))
        end
        local function reportCode(value)
            return "`" .. (tostring(value):gsub("`", "'")) .. "`"
        end
        local function reportClock(secs)
            secs = math.max(0, math.floor((tonumber(secs) or 0) + 0.5))
            local h, m, s = math.floor(secs / 3600), math.floor(secs / 60) % 60, secs % 60
            return h > 0 and ("%d:%02d:%02d"):format(h, m, s) or ("%02d:%02d"):format(m, s)
        end
        local function reportStats(item) -- "Phys 997 Spell 51M at max · Godpot 25.4%", or nil
            local parts = {}
            local ok, final = pcall(context.itemFinalStats, item)
            if ok and type(final) == "table" then
                if (final.phys or 0) > 0 then
                    parts[#parts + 1] = "Phys " .. reportNumber(final.phys)
                end
                if (final.spell or 0) > 0 then
                    parts[#parts + 1] = "Spell " .. reportNumber(final.spell)
                end
                if (final.hp or 0) > 0 then
                    parts[#parts + 1] = "HP " .. reportNumber(final.hp)
                end
            end
            local text = #parts > 0 and table.concat(parts, " ") .. " at max" or nil
            if config.whGodpot ~= false and context.itemGodpot then
                local okPot, pot = pcall(context.itemGodpot, item)
                if okPot and tonumber(pot) then
                    text = (text and text .. reportSep or "") .. ("Godpot %.1f%%"):format(pot)
                end
            end
            return text
        end
        local function reportDrops(items, cards, bag, bagMax, plainBelow, withStats)
            local sorted = {}
            for _, item in ipairs(items or {}) do
                sorted[#sorted + 1] = item
            end
            table.sort(sorted, function(left, right)
                local a, b = reportRank[left.rarity] or 0, reportRank[right.rarity] or 0
                if a ~= b then
                    return a > b
                end
                return tostring(left.name) < tostring(right.name)
            end)
            local lines = {}
            for _, item in ipairs(sorted) do
                local rarity = reportRank[item.rarity] and item.rarity or "unknown"
                local kind = reportKind[tostring(item.cat or "")]
                local line = reportDot[rarity] .. " " .. reportRarity[rarity] .. reportSep .. tostring(item.name or "?")
                    .. (kind and " (" .. kind .. ")" or "")
                if withStats ~= false and config.whBest ~= false and (reportRank[rarity] or 0) >= (plainBelow or 0) then
                    local stats = reportStats(item)
                    if stats then
                        line = line .. reportSep .. stats
                    end
                end
                lines[#lines + 1] = reportCode(line)
            end
            if #lines == 0 then
                bag, bagMax, cards = tonumber(bag), tonumber(bagMax), tonumber(cards) or 0
                if bag and bagMax and bag >= bagMax then
                    lines[1] = reportCode(("No drops" .. reportSep .. "bag full (%d/%d), drops are lost"):format(bag, bagMax))
                elseif cards > 0 then
                    lines[1] = reportCode(("%d reward%s, but the inventory would not open"):format(cards, cards == 1 and "" or "s"))
                else
                    lines[1] = reportCode("No drops this run")
                end
            end
            return lines
        end
        webhooks.reportDrops = reportDrops
        -- a short message in the same style: sections = { { "Heading", { "line", { raw = "<t:..:R>" } } } }
        local function compose(title, sections)
            local out = {}
            for _, sec in ipairs(sections) do
                if #sec[2] > 0 then
                    out[#out + 1] = "### " .. sec[1]
                    for _, line in ipairs(sec[2]) do
                        out[#out + 1] = type(line) == "table" and tostring(line.raw) or reportCode(line)
                    end
                end
            end
            return { title = title, url = reportUrl, description = table.concat(out, "\n"), aurStyle = true }
        end
        webhooks.compose = compose
        -- the safety net: an embed built the old way (bold description, fields) comes out in the same style
        webhooks.restyle = function(embed)
            if type(embed) ~= "table" or embed.aurStyle then
                return embed
            end
            local function clean(value)
                value = tostring(value or ""):gsub("%*%*", ""):gsub("%*", ""):gsub("`", ""):gsub("^%s+", ""):gsub("%s+$", "")
                return value
            end
            local function line(value)
                value = clean(value)
                if value == "" then
                    return nil
                end
                return (value:find("<t:", 1, true) or value:find("<@", 1, true)) and value or reportCode(value)
            end
            local out, desc = {}, tostring(embed.description or "")
            local already = desc:find("^###") or desc:find("^`")
            if already then
                out[1] = desc
            elseif desc ~= "" then
                local lines = {}
                for piece in (desc:gsub("\n", "   ") .. "   "):gmatch("(.-)%s%s%s+") do
                    lines[#lines + 1] = line(piece)
                end
                if #lines > 0 then
                    out[#out + 1] = "### Results"
                    for _, l2 in ipairs(lines) do
                        out[#out + 1] = l2
                    end
                end
            end
            for _, field in ipairs(embed.fields or {}) do
                local lines = {}
                for piece in (tostring(field.value or "") .. "\n"):gmatch("(.-)\n") do
                    lines[#lines + 1] = line(piece)
                end
                if #lines > 0 then
                    out[#out + 1] = "### " .. clean(field.name)
                    for _, l2 in ipairs(lines) do
                        out[#out + 1] = l2
                    end
                end
            end
            local text2 = table.concat(out, "\n")
            if #text2 > 4000 then
                text2 = text2:sub(1, 3990) .. "\n`...`"
            end
            embed.description, embed.fields = text2, nil
            if not already then -- old titles were sentence case ("Dungeon completed")
                embed.title = tostring(embed.title or ""):gsub("(%a)([%w']*)", function(first, rest)
                    return first:upper() .. rest
                end)
            end
            embed.url = embed.url or reportUrl
            embed.aurStyle = true
            return embed
        end
        webhooks.rpt = {
            code = reportCode,
            sep = reportSep,
            number = reportNumber,
            signed = reportSigned,
            clock = reportClock,
            dot = reportDot,
            url = reportUrl,
        }
        -- Aur_Hub (D-029): the shared loot-report formatter (every result webhook goes through it)
        local reportBar = string.rep("\u{2501}", 20)
        local function reportEscape(value) -- dynamic text inside markdown
            return (tostring(value):gsub("([\\%*_~|`>])", "\\%1"))
        end
        local nameHints = {
            helmets = { "helmet", "helm", "hat", "hood", "crown", "mask", "cap" },
            chests = { "armor", "armour", "robe", "plate", "chest" },
            weapons = {
                "blade", "sword", "axe", "staff", "spear", "mace", "hammer", "sceptre", "scepter", "hatchet",
                "shield", "bow", "dagger", "lance", "scythe", "wand",
            },
        }
        local function itemSuffix(item)
            local cat = tostring(item.cat or "")
            if cat == "abilities" then
                return reportSep .. "Ability"
            elseif cat == "keys" then
                return reportSep .. "Key"
            elseif cat == "pets" then
                return reportSep .. "Pet"
            end
            local hints = nameHints[cat]
            if not hints then
                return ""
            end
            local lower = string.lower(tostring(item.name or ""))
            for _, hint in ipairs(hints) do
                if lower:find(hint, 1, true) then
                    return "" -- the name already says what it is
                end
            end
            return reportSep .. (reportKind[cat] or "Item")
        end
        local function itemStatLines(item) -- { "`Phys 993 · Spell 969`", "`HP 254.1M · Godpot 30.9%`" }, stats shown?
            local first, second = {}, {}
            local ok, final = pcall(context.itemFinalStats, item)
            if config.whBest ~= false and ok and type(final) == "table" then
                if (final.phys or 0) > 0 then
                    first[#first + 1] = "Phys " .. reportNumber(final.phys)
                end
                if (final.spell or 0) > 0 then
                    first[#first + 1] = "Spell " .. reportNumber(final.spell)
                end
                if (final.hp or 0) > 0 then
                    second[#second + 1] = "HP " .. reportNumber(final.hp)
                end
            end
            local shown = #first > 0 or #second > 0
            if config.whGodpot ~= false and context.itemGodpot then
                local okPot, pot = pcall(context.itemGodpot, item)
                if okPot and tonumber(pot) then
                    second[#second + 1] = ("Godpot %.1f%%"):format(pot)
                end
            end
            local lines = {}
            if #first > 0 then
                lines[#lines + 1] = reportCode(table.concat(first, reportSep))
            end
            if #second > 0 then
                lines[#lines + 1] = reportCode(table.concat(second, reportSep))
            end
            return lines, shown
        end
        local function itemBlocks(items) -- rarity order (highest first, stable), identical items merged as x2
            local list = {}
            for index, item in ipairs(items or {}) do
                list[#list + 1] = { item = item, order = index }
            end
            table.sort(list, function(left, right)
                local a, b = reportRank[left.item.rarity] or 0, reportRank[right.item.rarity] or 0
                if a ~= b then
                    return a > b
                end
                return left.order < right.order
            end)
            local groups, byKey, anyStats = {}, {}, false
            for _, entry in ipairs(list) do
                local item = entry.item
                local lines, shown = itemStatLines(item)
                anyStats = anyStats or shown
                local key = table.concat({ tostring(item.rarity), tostring(item.name), tostring(item.cat), table.concat(lines, "|") }, "\0")
                if byKey[key] then
                    byKey[key].count += 1
                else
                    byKey[key] = { item = item, lines = lines, count = 1 }
                    groups[#groups + 1] = byKey[key]
                end
            end
            local blocks = {}
            for _, group in ipairs(groups) do
                local item = group.item
                local rarity = reportRank[item.rarity] and item.rarity or "unknown"
                local head = reportDot[rarity] .. " **" .. reportEscape(item.name or "?") .. "**"
                    .. (group.count > 1 and " \u{00D7}" .. group.count or "") .. itemSuffix(item)
                blocks[#blocks + 1] = #group.lines > 0 and head .. "\n" .. table.concat(group.lines, "\n") or head
            end
            return blocks, anyStats, groups
        end
        local function noDrops(cards, bag, bagMax)
            bag, bagMax, cards = tonumber(bag), tonumber(bagMax), tonumber(cards) or 0
            if bag and bagMax and bag >= bagMax then
                return reportCode(("No drops" .. reportSep .. "bag full (%d/%d), drops are lost"):format(bag, bagMax))
            elseif cards > 0 then
                return reportCode(("%d reward%s, but the inventory would not open"):format(cards, cards == 1 and "" or "s"))
            end
            return reportCode("No drops this run")
        end
        local function sessionLine()
            if config.whWins == false then
                return nil
            end
            local wins, losses = webhooks.wins or 0, webhooks.losses or 0
            local total = wins + losses
            local rate = total > 0 and ("%d%% WR"):format(math.floor(wins / total * 100 + 0.5)) or "\u{2014} WR"
            return reportCode("\u{1F3C6} " .. ("%d W / %d L"):format(wins, losses) .. (config.whRatio ~= false and reportSep .. rate or ""))
        end
        local function detailLines(account) -- only with "Detailed report" on: the numbers the compact layout leaves out
            if config.whDetailed ~= true then
                return {}
            end
            local have, got = {}, {}
            if config.whGold ~= false and tonumber(account.gold) then
                have[#have + 1] = "\u{1F947} " .. reportNumber(account.gold) .. " Gold"
            end
            if config.whGold ~= false and tonumber(account.gems) then
                have[#have + 1] = "\u{1F48E} " .. reportNumber(account.gems) .. " Gems"
            end
            if config.whInv ~= false and tonumber(account.bag) then
                have[#have + 1] = ("\u{1F392} %d/%d"):format(account.bag, tonumber(account.bagMax) or i())
            end
            if config.whGold ~= false and tonumber(account.goldGain) then
                got[#got + 1] = reportSigned(account.goldGain) .. " Gold"
            end
            if config.whGold ~= false and tonumber(account.gemsGain) then
                got[#got + 1] = reportSigned(account.gemsGain) .. " Gems"
            end
            if tonumber(account.candyGain) then
                got[#got + 1] = reportSigned(account.candyGain) .. " Candy"
            end
            local haul = config.whWorth ~= false and account.items and #account.items > 0 and p(account.items) or 0
            if haul > 0 then
                got[#got + 1] = "\u{1F4B0} " .. reportNumber(haul) .. " haul"
            end
            if config.whDeaths ~= false and tonumber(account.deaths) then
                got[#got + 1] = ("\u{2620}\u{FE0F} %d death%s"):format(account.deaths, account.deaths == 1 and "" or "s")
            end
            local lines = {}
            if #have > 0 then
                lines[#lines + 1] = reportCode(table.concat(have, reportSep))
            end
            if #got > 0 then
                lines[#lines + 1] = reportCode(table.concat(got, reportSep))
            end
            return lines
