        -- spec: { title, encounter, location, won, outcome, secs, best, accounts = { { name, spoiler, level, items, cards,
        -- bag, bagMax, lines, gold, gems, goldGain, gemsGain, candyGain, deaths } }, extra = { title, lines }, session
        -- (default true), sessionExtra }  ->  embeds. D-032: items are inline fields, two per row.
        local blank = "\u{200B}"
        local function itemField(group)
            local item = group.item
            local rarity = reportRank[item.rarity] and item.rarity or "unknown"
            local name = reportDot[rarity] .. " " .. reportEscape(item.name or "?")
                .. (group.count > 1 and " \u{00D7}" .. group.count or "") .. itemSuffix(item)
            return {
                name = name:sub(1, 250),
                value = #group.lines > 0 and table.concat(group.lines, "\n") or blank,
                inline = true,
            }
        end
        webhooks.combinedFields = function(accounts, add) -- D-229 (user): the accounts numbered, then all the party's loot in one list
            local names, drops = {}, {}
            for index, account in ipairs(accounts) do
                local name = reportEscape(account.name or ("Account " .. index))
                if account.spoiler then
                    name = "||" .. name .. "||"
                end
                names[#names + 1] = ("(%d) %s"):format(index, name)
                    .. (config.whLevel ~= false and tonumber(account.level) and (" \u{00B7} Lv. %d"):format(account.level) or "")
                    .. (config.whDeaths ~= false and tonumber(account.deaths) and (" \u{00B7} \u{2620}\u{FE0F} %d"):format(account.deaths) or "")
                    .. (account.items ~= nil and #account.items == 0 and " " .. noDrops(account.cards, account.bag, account.bagMax) or "") -- full bag, inventory that would not open
                for _, line in ipairs(account.lines or {}) do -- D-230: everything the old per-account block had
                    names[#names] = names[#names] .. "\n" .. reportCode(line)
                end
                for _, line in ipairs(detailLines(account)) do
                    names[#names] = names[#names] .. "\n" .. line
                end
                for _, item in ipairs(account.items or {}) do
                    local okPot, pot = false, nil
                    if context.itemGodpot then
                        okPot, pot = pcall(context.itemGodpot, item)
                    end
                    drops[#drops + 1] = { item = item, who = index, pot = okPot and tonumber(pot) or nil }
                end
            end
            add({ name = "Accounts", value = #names > 0 and table.concat(names, "\n"):sub(1, 1000) or blank, inline = false }, "extra")
            table.sort(drops, function(a, b) -- D-232 (user): rarity first, spells included; then best godpot, then items with none
                local ra, rb = reportRank[a.item.rarity] or 0, reportRank[b.item.rarity] or 0
                if ra ~= rb then
                    return ra > rb
                end
                if (a.pot ~= nil) ~= (b.pot ~= nil) then
                    return a.pot ~= nil
                end
                if a.pot and a.pot ~= b.pot then
                    return a.pot > b.pot
                end
                if tostring(a.item.name) ~= tostring(b.item.name) then
                    return tostring(a.item.name) < tostring(b.item.name)
                end
                return a.who < b.who
            end)
            local chunk, size, first = {}, 0, true
            local function flush()
                if #chunk > 0 then
                    add({ name = first and ("Loot, all accounts (%d)"):format(#drops) or "Loot (continued)", value = table.concat(chunk, "\n"), inline = false }, "extra")
                    chunk, size, first = {}, 0, false
                end
            end
            for _, drop in ipairs(drops) do
                local rarity = reportRank[drop.item.rarity] and drop.item.rarity or "unknown"
                local line = ("**(%d)** %s %s"):format(drop.who, reportDot[rarity], reportEscape(drop.item.name or "?")) .. itemSuffix(drop.item) -- D-234
                if drop.pot and config.whGodpot ~= false then -- D-231 (user): only the godpot here; Phys, Spell and HP are on the best drop
                    line = line .. reportSep .. reportCode(("Godpot %.1f%%"):format(drop.pot))
                end
                if size + #line + 1 > 1000 then
                    flush()
                end
                chunk[#chunk + 1] = line
                size += #line + 1
            end
            flush()
            if #drops == 0 then
                add({ name = "Loot, all accounts (0)", value = "No drops", inline = false }, "extra")
            end
        end
        webhooks.lootReport = function(spec)
            local accounts, entries, statsShown = spec.accounts or {}, {}, false
            local combined = spec.combined == true and config.whCombined ~= false -- D-229
            local function add(field, kind, head)
                entries[#entries + 1] = { field = field, kind = kind, head = head }
            end
            local summary = {}
            if spec.encounter and spec.encounter ~= "" then
                summary[#summary + 1] = "\u{2694}\u{FE0F} **" .. reportEscape(spec.encounter) .. "**"
            end
            if spec.location and spec.location ~= "" and spec.location ~= spec.encounter then
                summary[#summary + 1] = reportEscape(spec.location)
            end
            local bits = { spec.outcome or (spec.won and "\u{2713} Victory" or "\u{2717} Defeat") }
            if config.whTime ~= false and tonumber(spec.secs) then
                bits[#bits + 1] = reportClock(spec.secs)
            end
            if #accounts > 0 then
                bits[#bits + 1] = ("%d account%s"):format(#accounts, #accounts == 1 and "" or "s")
            end
            if combined and config.whDeaths ~= false then -- D-230
                local total, known = 0, false
                for _, account in ipairs(accounts) do
                    if tonumber(account.deaths) then
                        total, known = total + tonumber(account.deaths), true
                    end
                end
                if known then
                    bits[#bits + 1] = ("\u{2620}\u{FE0F} %d total death%s"):format(total, total == 1 and "" or "s")
                end
            end
            summary[#summary + 1] = reportCode(table.concat(bits, reportSep))
            if spec.best and config.whBestDrop ~= false then
                local _, shown, groups = itemBlocks({ spec.best })
                statsShown = statsShown or shown
                local field = itemField(groups[1])
                add({
                    name = "\u{1F3C6} Best drop",
                    value = "**" .. field.name .. "**" .. (field.value ~= blank and "\n" .. field.value or ""),
                    inline = false,
                }, "best")
            end
            if combined then
                webhooks.combinedFields(accounts, add)
            end
            for index, account in ipairs(combined and {} or accounts) do
                local label = reportEscape(account.name or ("Account " .. index))
                    .. (config.whLevel ~= false and tonumber(account.level) and (" \u{00B7} Lv. %d"):format(account.level) or "")
                if account.spoiler then
                    label = "||" .. label .. "||" -- Discord spoiler: the name shows when clicked
                end
                local notes, groups = {}, nil
                if account.items ~= nil then
                    local _, shown, found = itemBlocks(account.items)
                    statsShown = statsShown or shown
                    groups = found
                    if #found == 0 then
                        notes[#notes + 1] = noDrops(account.cards, account.bag, account.bagMax)
                    end
                end
                for _, line in ipairs(account.lines or {}) do
                    notes[#notes + 1] = reportCode(line)
                end
                for _, line in ipairs(detailLines(account)) do
                    notes[#notes + 1] = line
                end
                add({
                    name = reportBar,
                    value = (label .. (#notes > 0 and "\n" .. table.concat(notes, "\n") or "")):sub(1, 1000),
                    inline = false,
                }, "head", label)
                for n, group in ipairs(groups or {}) do
                    add(itemField(group), "item", label)
                    if n % 2 == 0 then
                        add({ name = blank, value = blank, inline = true }, "spacer", label)
                    end
                end
            end
            if spec.extra and #spec.extra.lines > 0 then
                local lines = {}
                for _, line in ipairs(spec.extra.lines) do
                    lines[#lines + 1] = reportCode(line)
                end
                add({ name = spec.extra.title, value = table.concat(lines, "\n"):sub(1, 1000), inline = false }, "extra")
            end
            if spec.session ~= false then
                local lines = { sessionLine() }
                for _, line in ipairs(spec.sessionExtra or {}) do
                    lines[#lines + 1] = reportCode(line)
                end
                if #lines > 0 then
                    add({ name = "Session", value = table.concat(lines, "\n"), inline = false }, "session")
                end
            end
            -- pack: at most 24 fields and about 5,000 characters per embed, one embed per message
            local embeds = {}
            local function open()
                local embed = {
                    title = #embeds == 0 and spec.title or spec.title .. " (continued)",
                    url = reportUrl,
                    fields = {},
                    aurStyle = true,
                }
                embeds[#embeds + 1] = embed
                return embed, #embed.title
            end
            local current, size = open()
            current.description = table.concat(summary, "\n")
            size += #current.description
            for _, entry in ipairs(entries) do
                local field = entry.field
                local cost = #field.name + #field.value
                if #current.fields >= 23 or size + cost > 5000 then
                    current, size = open()
                    if entry.kind == "item" or entry.kind == "spacer" then
                        local again = { name = reportBar, value = entry.head .. " (continued)", inline = false }
                        current.fields[1] = again
                        size += #again.name + #again.value
                    end
                end
                if not (entry.kind == "spacer" and (#current.fields == 0 or not current.fields[#current.fields].inline)) then
                    current.fields[#current.fields + 1] = field
                    size += cost
                end
            end
            embeds[#embeds].footer = { text = "Ethereal Enchantment" .. (statsShown and reportSep .. "Item stats at max upgrade" or "") }
            return embeds
        end
        -- deliver a (possibly continued) report: one embed per message, in order; mention and thumbnail on the first
        webhooks.sendReport = function(embeds, opts)
            opts = opts or {}
            local payloads = {}
            for index, embed in ipairs(embeds) do
                embed.color = opts.color
                if index == 1 then
                    embed.author = opts.author
                    if opts.best then
                        v(embed, opts.best)
                    end
                end
                if index == #embeds then
                    embed.timestamp = opts.timestamp or o()
                end
                payloads[index] = {
                    username = name(),
                    embeds = { embed },
                    content = index == 1 and opts.mention or nil,
                }
            end
            task.spawn(function()
                for _, payload in ipairs(payloads) do
                    local finished = false
                    post(payload, function()
                        finished = true
                    end)
                    local started = os.clock()
                    while not finished and os.clock() - started < 30 do
                        task.wait(0.2)
                    end
                end
            end)
            return payloads
        end
