                    local fn = titleLabel and summaries[pageOf(holder) .. "|" .. titleLabel.Text]
                    if fn and entry.summarize then
                        entry.summarize(fn)
                    end
                end
                -- dependent rows: nested under their switch, locked (values kept) while it is off
                local function rowFor(pageId, labelText)
                    local page = shell.pages[pageId]
                    if not page then
                        return nil
                    end
                    for _, d in ipairs(page.body:GetDescendants()) do
                        if d:IsA("TextLabel") and d.Text == labelText then
                            local node = d
                            while node.Parent and node.Parent.Name ~= "Content" and node.Parent ~= page.body do
                                node = node.Parent
