                depends("Visuals", { "Map button", "Follow player", "Smooth 2D map", "Custom attack color", "Rainbow attacks" }, function()
                    return config.minimap ~= false
                end)
                depends("Visuals", { "Hitbox as body", "Hide other players' names", "Hide the player lists", "Hide the chat" }, function()
                    return config.streamer == true
                end)
                do -- rarity dots, same hues as the Discord report (legendary reads gold, like its yellow dot)
                    local hues = {
                        common = Color3.fromHex("94A5B8"),
                        uncommon = Color3.fromHex("22C55E"),
                        rare = Color3.fromHex("3B82F6"),
                        epic = Color3.fromHex("A855F6"),
                        legendary = Color3.fromHex("F5B83D"),
                        ultimate = Color3.fromHex("FF3B3B"),
                    }
                    local function mark(pageId, labelText, rarity)
                        local row = rowFor(pageId, labelText)
                        local label = row and row:FindFirstChildWhichIsA("TextLabel")
                        if not (row and row.Name == "Row" and label) or row:FindFirstChild("RarityDot") then
                            return
                        end
                        local dot = Instance.new("Frame")
                        dot.Name, dot.LayoutOrder, dot.BorderSizePixel = "RarityDot", 0, 0
                        dot.Size, dot.BackgroundColor3 = UDim2.fromOffset(8, 8), hues[rarity]
                        dot:SetAttribute("HLThemeSkip", true)
                        dot.Parent = row
                        uiKit.corner(dot, 4)
                        label.Size = UDim2.new(label.Size.X.Scale, label.Size.X.Offset - 16, label.Size.Y.Scale, label.Size.Y.Offset)
                    end
                    for _, rarity in ipairs({ "common", "uncommon", "rare", "epic", "legendary", "ultimate" }) do
                        mark("AutoSell", rarity:sub(1, 1):upper() .. rarity:sub(2), rarity)
                    end
                    mark("ModDetect", "Legendary", "legendary")
                    mark("ModDetect", "Ultimate", "ultimate")
                    mark("ModDetect", "Any epic", "epic")
                end
                pcall(uiKit.refreshLive)
            end
            do -- Aur_Hub (D-025): one status HUD: header, current action, Session/Ping/FPS, footer, Details
                local tweenService = game:GetService("TweenService")
                local function motion()
                    return config.uiAnimations ~= false
                end
                local function text(parent, value, style, order, color)
                    local label = uiKit.label(parent, value, style, order or 1)
                    label.TextTruncate = Enum.TextTruncate.AtEnd
                    if color then
                        label.TextColor3 = color
                    end
                    return label
                end
                local function box(parent, name, order, height)
                    local f = Instance.new("Frame")
                    f.Name, f.BackgroundTransparency, f.BorderSizePixel = name, 1, 0
                    f.Size, f.LayoutOrder = UDim2.new(1, 0, 0, height or 0), order or 1
                    f.Parent = parent
                    return f
                end
                local function line(parent, order)
                    local f = box(parent, "Sep", order, 1)
                    f.BackgroundTransparency, f.BackgroundColor3 = 0, theme.Hairline
                    return f
                end
                local function across(parent, right, gap)
                    local layout = Instance.new("UIListLayout")
                    layout.FillDirection = Enum.FillDirection.Horizontal
                    layout.VerticalAlignment = Enum.VerticalAlignment.Center
                    layout.HorizontalAlignment = right and Enum.HorizontalAlignment.Right or Enum.HorizontalAlignment.Left
                    layout.SortOrder = Enum.SortOrder.LayoutOrder
                    layout.Padding = UDim.new(0, gap or 6)
                    layout.Parent = parent
                    return layout
                end
                local function fit(label)
                    label.AutomaticSize = Enum.AutomaticSize.X
                    label.Size = UDim2.new(0, 0, 1, 0)
                    label.TextTruncate = Enum.TextTruncate.None
                    return label
                end
                local function cap(value)
                    return value:sub(1, 1):upper() .. value:sub(2)
                end
                local function shortAttack(value)
                    if type(value) ~= "string" or value == "" then
                        return ""
                    end
                    local count = value:match("^(%d+) in the disc")
                    if count then
                        return value:find("firing", 1, true) and "Firing" or (count .. " in reach")
                    end
                    return cap(value:match("^[^,]+") or value)
                end
                local hud = Instance.new("Frame")
                hud.Name, hud.BorderSizePixel, hud.ZIndex = "HUD", 0, 2
                hud.AnchorPoint, hud.Position = Vector2.new(0, 1), UDim2.new(0, 20, 1, -20)
                hud.Size, hud.AutomaticSize = UDim2.fromOffset(500, 0), Enum.AutomaticSize.Y
                hud.BackgroundColor3, hud.BackgroundTransparency = theme.SurfaceHeader, 0.04
                hud.Parent = dungeonAutofarmUi
                uiKit.corner(hud, 10)
                uiKit.stroke(hud, theme.Hairline, 1)
                uiKit.pad(hud, 14, 16, 12, 16)
                uiKit.vlist(hud, 10)
                -- header: A + AUR on the left, the real running state on the right
                local header = box(hud, "Header", 1, 22)
                -- round 4: the user's logo instead of the "E" letter; without a logo, no mark at all
                local cardLogo = context.customLogo and context.customLogo() or nil
                local wordX = 0
                if type(cardLogo) == "string" and cardLogo ~= "" then
                    local mark = Instance.new("ImageLabel")
                    mark.Name, mark.BackgroundTransparency, mark.Image = "BrandLogo", 1, cardLogo
                    mark.ScaleType, mark.Size, mark.Position = Enum.ScaleType.Crop, UDim2.fromOffset(18, 18), UDim2.fromOffset(0, 2)
                    mark:SetAttribute("HLThemeSkip", true)
                    mark.Parent = header
                    uiKit.corner(mark, 4)
                    wordX = 24
                end
                local word = text(header, "Ethereal Enchantment", "rowStat", 2)
                word.Name, word.Position, word.Size = "Wordmark", UDim2.fromOffset(wordX, 0), UDim2.fromOffset(190, 22)
                uiKit.setFont(word, "sans", Enum.FontWeight.SemiBold)
                local state = box(header, "State", 3, 22)
                state.AnchorPoint, state.Position, state.Size = Vector2.new(1, 0), UDim2.fromScale(1, 0), UDim2.new(0.6, 0, 1, 0)
                across(state, true, 6)
                local dotBox = box(state, "DotBox", 1, 15)
                dotBox.Size = UDim2.fromOffset(15, 15)
                local halo = Instance.new("Frame")
                halo.Name, halo.BorderSizePixel, halo.Visible = "Halo", 0, false
                halo.AnchorPoint, halo.Position, halo.Size = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5), UDim2.fromOffset(8, 8)
                halo.BackgroundColor3, halo.BackgroundTransparency = theme.StatusRun, 0.7
                halo.Parent = dotBox
                uiKit.corner(halo, 8)
                local dot = Instance.new("Frame")
                dot.Name, dot.BorderSizePixel, dot.BackgroundColor3 = "Dot", 0, theme.TextMuted
                dot.AnchorPoint, dot.Position, dot.Size = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5), UDim2.fromOffset(7, 7)
                dot.Parent = dotBox
                uiKit.corner(dot, 4)
                local stateText = fit(text(state, "Autofarm off", "captionKey", 2, theme.TextSub))
                stateText.Name = "Status"
                line(hud, 2)
                -- current action: label, summary, compact attack state on the right
                local actionBox = box(hud, "Action", 3, 36)
                local caption = text(actionBox, "Current action", "captionKey", 1, theme.TextMuted)
                caption.TextSize, caption.Size = 11, UDim2.new(1, 0, 0, 14)
                local action = text(actionBox, "", "rowStat", 2)
                action.Name, action.Position, action.Size = "Summary", UDim2.fromOffset(0, 16), UDim2.new(1, -132, 0, 20)
                local attack = text(actionBox, "", "captionKey", 3, theme.TextSub)
                attack.Name, attack.AnchorPoint = "Attack", Vector2.new(1, 0)
                attack.Position, attack.Size = UDim2.new(1, 0, 0, 16), UDim2.fromOffset(124, 20)
                attack.TextXAlignment = Enum.TextXAlignment.Right
                line(hud, 4)
                -- one row: Session, Ping, FPS (RobotoMono digits, updated in place)
                local stats = box(hud, "Stats", 5, 18)
                local function stat(name, index)
                    local cell = box(stats, name .. "Stat", index, 18)
                    cell.Position, cell.Size = UDim2.fromScale((index - 1) / 3, 0), UDim2.new(1 / 3, 0, 1, 0)
                    across(cell, false, 8)
                    fit(text(cell, name, "captionKey", 1, theme.TextMuted))
                    local value = fit(text(cell, "-", "monoStat", 2, theme.TextPrimary))
                    value.Name = "Value"
                    return value
                end
                local sessionValue, pingValue, fpsValue = stat("Session", 1), stat("Ping", 2), stat("FPS", 3)
                if shell and shell.addSessionLabel then
                    shell.addSessionLabel(sessionValue)
                end
                line(hud, 6)
                -- footer: the menu key as a keycap, Details on the right
                local footer = box(hud, "HudFooter", 7, 22)
                local keys = box(footer, "Keys", 1, 22)
                keys.Size = UDim2.new(1, -90, 1, 0)
                across(keys, false, 8)
                local keycap = Instance.new("Frame")
                keycap.Name, keycap.BorderSizePixel, keycap.LayoutOrder = "Keycap", 0, 1
                keycap.BackgroundColor3, keycap.Size, keycap.AutomaticSize = theme.SurfaceField, UDim2.fromOffset(0, 20), Enum.AutomaticSize.X
                keycap.Parent = keys
                uiKit.corner(keycap, 4)
                uiKit.stroke(keycap, theme.Hairline, 1)
                uiKit.pad(keycap, 0, 7, 0, 7)
                local keyText = fit(text(keycap, "", "monoStat", 1, theme.TextPrimary))
                keyText.TextSize = 11
                fit(text(keys, "Open controls", "captionKey", 2, theme.TextSub))
                local detailsButton = Instance.new("TextButton")
                detailsButton.Name, detailsButton.Text, detailsButton.AutoButtonColor = "DetailsButton", "", false
                detailsButton.BackgroundTransparency, detailsButton.BorderSizePixel = 1, 0
                detailsButton.AnchorPoint, detailsButton.Position = Vector2.new(1, 0), UDim2.fromScale(1, 0)
                detailsButton.Size = UDim2.fromOffset(84, 22)
                detailsButton.Parent = footer
                across(detailsButton, true, 4)
                local detailsText = fit(text(detailsButton, "Details", "captionKey", 1, theme.TextSub))
                local detailsChevron = uiKit.icon(detailsButton, "chevron-down", 14, theme.TextSub)
                detailsChevron.LayoutOrder, detailsChevron.Rotation = 2, -90
                -- Details: the full diagnostics (what the old Stats panel showed, plus run time and version)
                local details = box(hud, "Details", 8, 0)
                details.AutomaticSize, details.Visible = Enum.AutomaticSize.Y, false
                uiKit.vlist(details, 8)
                line(details, 1)
                local detailText = text(details, "", "captionKey", 2, theme.TextSub)
                detailText.Name, detailText.TextWrapped, detailText.TextTruncate = "Text", true, Enum.TextTruncate.None
                detailText.TextYAlignment = Enum.TextYAlignment.Top
                detailText.Size, detailText.AutomaticSize = UDim2.new(1, 0, 0, 0), Enum.AutomaticSize.Y
                local detailsOpen, diagnostics = false, ""
                local function hoverDetails(on)
                    tweenService
                        :Create(detailsText, TweenInfo.new(motion() and 0.12 or 0, Enum.EasingStyle.Quad), {
                            TextColor3 = on and theme.TextPrimary or theme.TextSub,
                        })
                        :Play()
                end
                local function setDetails(open)
                    detailsOpen = open == true
                    details.Visible = detailsOpen
                    detailText.Text = diagnostics
                    tweenService
                        :Create(detailsChevron, TweenInfo.new(motion() and 0.16 or 0, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                            Rotation = detailsOpen and 0 or -90,
                        })
                        :Play()
                end
                detailsButton.MouseEnter:Connect(function()
                    hoverDetails(true)
                end)
                detailsButton.MouseLeave:Connect(function()
                    hoverDetails(false)
                end)
                detailsButton.SelectionGained:Connect(function()
                    hoverDetails(true)
                end)
                detailsButton.SelectionLost:Connect(function()
                    hoverDetails(false)
                end)
                detailsButton.Activated:Connect(function()
                    setDetails(not detailsOpen)
                end)
                -- running pulse: one engine tween (no Lua per-frame loop), only while running and on screen
                local pulse
                local function setPulse(on)
                    if on == (pulse ~= nil) then
                        return
                    end
                    if pulse then
                        pulse:Cancel()
                        pulse = nil
                    end
                    halo.Visible = on
                    if on then
                        halo.Size, halo.BackgroundTransparency = UDim2.fromOffset(8, 8), 0.7
                        pulse = tweenService:Create(
                            halo,
                            TweenInfo.new(1.2, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true),
                            { Size = UDim2.fromOffset(15, 15), BackgroundTransparency = 0.92 }
                        )
                        pulse:Play()
                    end
                end
                -- current action: a meaningful change (not just new numbers) fades in; changes within 0.8 s coalesce
                local shownKey, changedAt = nil, 0
                local function setAction(value)
                    if action.Text == value then
                        return
                    end
                    local key = value:gsub("[%d%.%-]+", "#")
                    if key == shownKey then
                        action.Text = value
                        return
                    end
                    if shownKey ~= nil and os.clock() - changedAt < 0.8 then
                        return
                    end
                    shownKey, changedAt = key, os.clock()
                    action.Text = value
                    if motion() and hud.Visible then
                        action.TextTransparency = 0.65
                        tweenService
                            :Create(action, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                                TextTransparency = 0,
                            })
                            :Play()
                    end
                end
                if context.ProfileHud then -- round 4 (D-147): the top-left profile HUD
                    pcall(context.ProfileHud.mount, dungeonAutofarmUi)
                end
                context.HUD = {
                    panel = hud,
                    action = action,
                    attack = attack,
                    status = stateText,
                    dot = dot,
                    halo = halo,
                    keycap = keyText,
                    session = sessionValue,
                    ping = pingValue,
                    fps = fpsValue,
                    details = details,
                    detailText = detailText,
                    setDetails = setDetails,
                    pulsing = function()
                        return pulse ~= nil
                    end,
                }
                local netStats, frames, elapsed = game:GetService("Stats"), 0, 0
                runtimeState.hudPlayStart = runtimeState.hudPlayStart or os.clock()
                runtimeState.hudConnection = runService.Heartbeat:Connect(function(dt)
                    if runtimeState.destroyed then
                        setPulse(false)
                        return
                    end
                    frames, elapsed = frames + 1, elapsed + dt
                    if elapsed < 0.25 then
                        return
                    end
                    local fpsText = tostring(math.floor(frames / elapsed + 0.5))
                    frames, elapsed = 0, 0
                    if fpsValue.Text ~= fpsText then
                        fpsValue.Text = fpsText
                    end
                    local visible = (not context.hudShown or context.hudShown()) and not (context.MM and context.MM.big)
                    if hud.Visible ~= visible then
                        hud.Visible = visible
                    end
                    local camera = contextWorkspace.CurrentCamera
                    local width = math.clamp(math.floor((camera and camera.ViewportSize.X or 1600) - 40), 280, 500)
                    if hud.Size.X.Offset ~= width then
                        hud.Size = UDim2.fromOffset(width, 0)
                    end
                    local keyName = (tostring(config.menuKey or "RightShift"):gsub("(%l)(%u)", "%1 %2"))
                    if keyText.Text ~= keyName then
                        keyText.Text = keyName
                    end
                    -- run time (the old Playtime row, same rules and side effects; shown in Details)
                    local dungeonName, dungeonStarted =
                        contextWorkspace:FindFirstChild("dungeonName"), contextWorkspace:FindFirstChild("dungeonStarted")
                    local inDungeon = dungeonName ~= nil and tostring(dungeonName.Value) ~= ""
                    local started = dungeonStarted ~= nil and dungeonStarted.Value == true
                    local runText
                    if not inDungeon then
                        runText = "Not in dungeon"
                        runtimeState.hudRunAt = nil
                        runtimeState.hudStopAt = nil
                    elseif not started then
                        runText = "Not started"
                        runtimeState.hudRunAt = nil
                        runtimeState.hudStopAt = nil
                    else
                        runtimeState.hudRunAt = runtimeState.hudRunAt or os.clock()
                        local run = context.WH and context.WH.run
                        if run and not run.hudAt and run.at and math.abs(run.at - runtimeState.hudRunAt) < 30 then
                            run.hudAt = runtimeState.hudRunAt
                        end
                        if not runtimeState.hudStopAt and config.hudStopAtEnd ~= false and context.runStopAt then
                            local ok, stopAt = pcall(context.runStopAt, runtimeState.hudRunAt)
                            if ok and stopAt then
                                runtimeState.hudStopAt = stopAt
                            end
                        end
                        local secs = (runtimeState.hudStopAt or os.clock())
                            - runtimeState.hudRunAt
                            - (config.startCountdown or 5)
                        if secs < 0 then
                            runText = ("-00:%02d"):format(math.ceil(-secs))
                        else
                            runText = ("%02d:%02d"):format(math.floor(secs / 60), math.floor(secs % 60))
                                .. (runtimeState.hudStopAt and " - completed" or "")
                        end
                    end
                    -- running state (the same states the footer shows: running, paused by mod detection, off)
                    local running = runtimeState.farmEnabled == true and not runtimeState.destroyed
                    local halted = running and runtimeState.modHalt == true
                    local stateLabel = halted and "Autofarm paused" or (running and "Autofarm running" or "Autofarm off")
                    if context.RunRecorder and context.RunRecorder.recording() then -- Aur_Hub (D-030)
                        stateLabel = stateLabel .. "  ·  REC"
                    end
                    if stateText.Text ~= stateLabel then
                        stateText.Text = stateLabel
                        dot.BackgroundColor3 = halted and theme.StatusWarn or (running and theme.StatusRun or theme.TextMuted)
                    end
                    setPulse(running and not halted and visible and motion())
                    -- current action and attack state
                    local tracked = 0
                    for _ in pairs(hazardReader.models) do
                        tracked += 1
                    end
                    local spots = config.drawSpots and #(context.DG.cands or {}) or -1
                    local erroring = runtimeState.lastErrorAt and os.clock() - runtimeState.lastErrorAt < 6
                    local activity = running and runtimeState.movementState or nil
                    if not activity or tostring(activity) == "" then
                        activity = context.LB and context.LB.status
                    end
                    activity = activity and tostring(activity) ~= "" and tostring(activity) or "Idle"
                    setAction(erroring and "Script error, see Details" or cap(activity))
                    local attackText = running and shortAttack(runtimeState.attackState) or ""
                    if attack.Text ~= attackText then
                        attack.Text = attackText
                    end
                    local ping = 0
                    pcall(function()
                        ping = netStats.Network.ServerStatsItem["Data Ping"]:GetValue()
                    end)
                    if not (tonumber(ping) and ping > 0) and tonumber(runtimeState.pingS) then
                        ping = runtimeState.pingS * 1000
                    end
                    local pingText = tonumber(ping) and ping > 0 and ("%d ms"):format(math.floor(ping + 0.5)) or "-"
                    if pingValue.Text ~= pingText then
                        pingValue.Text = pingText
                    end
                    local lines = {
                        "Action: " .. tostring(runtimeState.movementState or "-"),
                        "Attack: " .. tostring(runtimeState.attackState or "-"),
                        ("Tracked: %d attacks, %s"):format(tracked, spots < 0 and "spots off" or ("%d spots"):format(spots)),
                        "Run: " .. runText,
                        "Dungeon: " .. (inDungeon and tostring(dungeonName.Value) or "Not in dungeon"),
                        "Version: " .. tostring(ver),
                    }
                    if runtimeState.lastErrorAt then
                        lines[#lines + 1] = ("Last error (%ds ago): %s"):format(
                            math.floor(os.clock() - runtimeState.lastErrorAt),
                            tostring(runtimeState.lastError)
                        )
                    end
                    diagnostics = table.concat(lines, "\n")
                    if detailsOpen and detailText.Text ~= diagnostics then
                        detailText.Text = diagnostics
                    end
                    -- unchanged from the old HUD tick: ability ranges, stats note, profile autosave
                    local ranges = {}
                    for key, entry in pairs(hazardReader.abilitySlots or {}) do
                        local reach = entry.cap and entry.cap .. " studs" or (entry.reach and "at least " .. entry.reach or "?")
                        ranges[#ranges + 1] = ("%s %s: %s%s"):format(
                            string.upper(key),
                            entry.name or "?",
                            reach,
                            entry.aoeX
                                    and ", AoE " .. math.floor(entry.aoeX + 0.5) .. (entry.aoeRound and " round" or " x " .. math.floor(
                                        entry.aoeZ + 0.5
                                    ))
                                or ""
                        )
                    end
                    table.sort(ranges)
                    if uiSettings.statsNote and context.Shell and context.Shell.isShown and context.Shell.isShown() then
                        -- Ethereal Enchantment: context.ST (21_statsReporter) read defensively, only while the menu is open
                        local statsModule, note = context.ST, "Stats tracker not loaded"
                        if type(statsModule) == "table" and type(statsModule.status) == "function" then
                            local ok, first, second = pcall(statsModule.status)
                            if not ok then
                                note = "Stats tracker: status unavailable"
                            elseif second ~= nil then
                                note = "Stats tracker: " .. tostring(second)
                            elseif type(first) == "boolean" then
                                note = first and "Stats tracker: ready" or "Stats tracker: not ready"
                            else
                                note = "Stats tracker: " .. tostring(first)
                            end
                        elseif statsModule ~= nil then
                            note = "Stats tracker loaded (no status)"
                        end
                        if uiSettings.statsNote.Text ~= note then
                            uiSettings.statsNote.Text = note
                        end
                    end
                    textControl.Text = #ranges > 0
                            and "Measured - " .. table.concat(ranges, "; ") .. ". The least ranged one sets the fight distance."
                        or "Ability range: not measured yet (cast at a target)"
                    if os.clock() - (runtimeState.profileSaveAt or 0) > 10 then
                        runtimeState.profileSaveAt = os.clock()
                        pcall(context.profiles.autosave)
                    end
                end)
            end
        end
        context.destructScript = contextDestructScript
        context.refreshAllWidgets = contextRefreshAll
        context.setLoopButtonState = function()
            if uiSettings.masterRender then
                pcall(uiSettings.masterRender)
            end
        end
        print(
            ('DUNGEON AUTOFARM %s "%s"  |  build %s'):format(
                ver,
                context.SCRIPT_CODENAME,
                context.SCRIPT_BUILD_DATE
            )
        )
        local bugButton, band2 = pcall(contextLoadConfig)
        if not bugButton then
            runtimeState.lastError, runtimeState.lastErrorAt =
                "config load failed, using defaults: " .. tostring(band2), os.clock()
            context.log("Config", "could not be loaded (" .. tostring(band2) .. ") - running on defaults")
        end
        band2, success2 = pcall(function()
            if context.applyClassProfile then
                context.applyClassProfile(config.classProfile or "mage", true)
                pcall(contextLoadConfig, true)
                contextSaveConfig()
            end
            if context.autoClass then
                pcall(context.autoClass, true)
            end
            local function y()
                local localPlayer2, E, p = game:GetService("Players").LocalPlayer, {}, 0
                local function J()
                    p += 1
                    local w = p
                    task.delay(config.classAutoSettle or 2, function()
                        local Y = w == p and not (context.RT and context.RT.destroyed) and context.autoClass
                        if Y then
                            pcall(context.autoClass)
                        end
                    end)
                end
                local function p(w)
                    if E[w] or not (w.Name == "physicalPower" or w.Name == "spellPower") then
                        return
                    end
                    E[w] = true
                    local connection = w.Changed:Connect(J)
                    if context.sliderConnections then
                        context.sliderConnections[#context.sliderConnections + 1] = connection
                    end
                end
                local w = { "physicalPower", "spellPower" }
                for index, entry in ipairs(w) do
                    index = localPlayer2:FindFirstChild(entry)
                    if index then
                        p(index)
                    end
                end
                local function Y(v)
                    if context.RT and context.RT.destroyed then
                        return
                    end
                    if not E[v] and (v.Name == "physicalPower" or v.Name == "spellPower") then
                        p(v)
                        J()
                    end
                end
                w = localPlayer2.ChildAdded:Connect(Y)
                if context.sliderConnections then
                    context.sliderConnections[#context.sliderConnections + 1] = w
                end
            end
            pcall(y)
        end)
        if not band2 then
            runtimeState.lastError, runtimeState.lastErrorAt =
                "class profile failed: " .. tostring(success2), os.clock()
            context.log("Config", "class profile could not be applied (" .. tostring(success2) .. ")")
        end
        context.detectClass = function()
            local y = localPlayer:FindFirstChild("leaderstats")
            local q, physicalPower, spellPower =
                y and (y:FindFirstChild("Level")),
                localPlayer:FindFirstChild("physicalPower"),
                localPlayer:FindFirstChild("spellPower")
            y = q and tonumber(q.Value)
            if not (y and physicalPower and spellPower) then
                return nil, "not loaded yet"
            end
            local q, J = tonumber(physicalPower.Value) or 0, tonumber(spellPower.Value) or 0
            if y <= 1 then
                return nil, "level 1 - the copied class stays"
            end
            if q == J then
                return nil, ("%d points in each - the copied class stays"):format(q)
            end
            return J > q and "mage" or "warrior", ("%d points in spell power, %d in physical power"):format(J, q)
        end
        if context.firstRunNoConfig then
            task.spawn(function()
                local function y()
                    local q, E = context.detectClass()
                    if q and q ~= config.classProfile and context.applyClassProfile then
                        context.applyClassProfile(q)
                        local p = q == "mage" and "Mage" or "Warrior"
                        context.log("Config", ("first run: class set to %s (%s)"):format(p, E))
                        if context.notify then
                            pcall(context.notify, "info", "Class", ("Set to %s: %s."):format(p, E))
                        end
                        if context.BG and context.BG.check then
                            pcall(context.BG.check)
                        end
                    else
                        context.log(
                            "Config",
                            ("first run: class kept as %s (%s)"):format(tostring(config.classProfile), E)
                        )
                    end
                end
                local now = os.clock()
                while
                    not runtimeState.destroyed
                    and select(2, context.detectClass()) == "not loaded yet"
                    and os.clock() - now < 120
                do
                    task.wait(0.5)
                end
                if runtimeState.destroyed then
                    return
                end
                y()
                if runtimeState.configAsk then
                    while not runtimeState.destroyed and runtimeState.configAsk do
                        task.wait(0.5)
                    end
                    if not runtimeState.destroyed then
                        y()
                    end
                end
            end)
        end
        if context.profiles and context.profiles.current() ~= "Default" then
            pcall(context.profiles.select, context.profiles.current())
        end
        do
            local y
            local q = {
                at = -math.huge,
                raw = nil,
                v = nil,
            }
            context.fpsSharedSave = function()
                local success, raw = pcall(function()
                    local httpService, w = game:GetService("HttpService"), q.v
                    return httpService:JSONEncode(w)
                end)
                if success then
                    pcall(writefile, "Aur_Hub/data/fps.json", raw)
                    q.raw, q.at = raw, os.clock()
                end
            end
            context.fpsShared = function()
                local now = os.clock()
                if q.v and now - q.at < 1.5 then
                    return q.v
                end
                q.at = now
                local success, raw = pcall(readfile, "Aur_Hub/data/fps.json")
                if success and type(raw) == "string" and raw ~= "" and raw ~= q.raw then
                    local success3, J = pcall(function()
                        return game:GetService("HttpService"):JSONDecode(raw)
                    end)
                    if success3 and type(J) == "table" then
                        q.v = J
                        q.raw = raw
                    end
                end
                if not q.v then
                    q.v = {
                        cap = false,
                        carry = tonumber(config.carryFpsCap) or 45,
                        leech = tonumber(config.leechFpsCap) or 15,
                        uncap = false,
                    }
                    context.fpsSharedSave()
                end
                return q.v
            end
            context.hudShown = function()
                return context.fpsShared().hud ~= false
            end
            context.fpsSharedSet = function(q, E)
                context.fpsShared()[q] = E
                context.fpsSharedSave()
                if context.applyFps then
                    pcall(context.applyFps, true)
                end
            end
            context.applyFps = function(contextFpsWant)
                if type(setfpscap) ~= "function" then
                    return
                end
                local E, p = context.fpsShared(), context.afRole and context.afRole() or nil
                if E.cap == true then
                    contextFpsWant = p == "leech" and (tonumber(E.leech) or 15) or (tonumber(E.carry) or 45)
                    context.fpsWant = contextFpsWant
                    pcall(setfpscap, contextFpsWant)
                    return
                end
                contextFpsWant = E.uncap == true
                if contextFpsWant then
                    p = y == nil and type(getfpscap) == "function"
                    if p then
                        local success, p = pcall(getfpscap)
                        E = success
                            and type(p) == "number"
