                                    if not used[j] then
                                        local ox, oz = other(segs[j], tip[1], tip[2])
                                        local nx2, nz2 = ox - tip[1], oz - tip[2]
                                        local nl = math.sqrt(nx2 * nx2 + nz2 * nz2)
                                        local score = (hl > 0 and nl > 0) and (hx * nx2 + hz * nz2) / (hl * nl) or 0
                                        if not best or score > best then
                                            nxt, best = j, score
                                        end
                                    end
                                end
                                if not nxt then
                                    break
                                end
                                used[nxt] = true
                                local ox, oz = other(segs[nxt], tip[1], tip[2])
                                if side == 1 then
                                    pts[#pts + 1] = { ox, oz }
                                else
                                    table.insert(pts, 1, { ox, oz })
                                end
                            end
                        end
                        lines[#lines + 1] = pts
                    end
                end
                local function simplify(pts, i0, i1, out)
                    local ax2, az2, bx2, bz2 = pts[i0][1], pts[i0][2], pts[i1][1], pts[i1][2]
                    local dx, dz = bx2 - ax2, bz2 - az2
                    local L = math.sqrt(dx * dx + dz * dz)
                    local far, fi = 0, nil
                    for i = i0 + 1, i1 - 1 do
                        local d
                        if L < 1e-6 then
                            d = math.sqrt((pts[i][1] - ax2) ^ 2 + (pts[i][2] - az2) ^ 2)
                        else
                            d = math.abs((pts[i][1] - ax2) * dz - (pts[i][2] - az2) * dx) / L
                        end
                        if d > far then
                            far, fi = d, i
                        end
                    end
                    if fi and far > eps then
                        simplify(pts, i0, fi, out)
                        simplify(pts, fi, i1, out)
                    else
                        out[#out + 1] = { ax2, az2, bx2, bz2 }
                    end
                end
                local drawn = {}
                for _, pts in ipairs(lines) do
                    local len = 0
                    for i = 2, #pts do
                        len = len + math.sqrt((pts[i][1] - pts[i - 1][1]) ^ 2 + (pts[i][2] - pts[i - 1][2]) ^ 2)
                    end
                    if #pts >= 2 and len >= (minLen or 0) then
                        simplify(pts, 1, #pts, drawn)
                    end
                end
                return drawn
            end
            context.minimapJoinLines = joinLines
            local function wholeOutline(fm) -- D-073: the whole floor map's edge, every level merged (built in the background)
                local key = tostring(fm) .. ":" .. tostring(fm.version)
                local W = zone.whole
                if W and W.fmRef == fm and (W.building or W.key == key
                    or os.clock() - (W.at or 0) < (config.minimapWholeRebuild or 30)) then
                    return W
                end
                local old = W
                W = { fmRef = fm, key = key, building = true, at = os.clock(), segs = old and old.segs, bounds = old and old.bounds }
                zone.whole = W
                task.spawn(function()
                    local ok = pcall(function()
                        local g = fm.g or 2
                        local OFF, M = 8192, 16384
                        local function id(a, b)
                            return (a + OFF) * M + b + OFF
                        end
                        local F, Nn, X = {}, {}, {}
                        local x0, x1, z0, z1 = math.huge, -math.huge, math.huge, -math.huge
                        local n2 = 0
                        local function tick()
                            n2 += 1
                            if n2 % (config.minimapWholeBatch or 1500) == 0 then
                                task.wait()
                            end
                        end
                        for k in pairs(fm.floor) do
                            local a, b = string.match(k, "^(-?%d+),(-?%d+),")
                            a, b = tonumber(a), tonumber(b)
                            if a and b then
                                F[id(a, b)] = true
                                x0, x1, z0, z1 = math.min(x0, a), math.max(x1, a), math.min(z0, b), math.max(z1, b)
                            end
                            tick()
                        end
                        for k, t in pairs(fm.cross or {}) do
                            local a, b, d = string.match(k, "^(-?%d+),(-?%d+),%-?%d+,(%a)$")
                            a, b = tonumber(a), tonumber(b)
                            if a and b and type(t) == "number" then
                                X[id(a, b) * 2 + (d == "x" and 0 or 1)] = t
                            end
                            tick()
                        end
                        if x0 == math.huge then
                            W.building = false
                            return
                        end
                        -- the outline of the floor itself (as the reference image): floor against anything else
                        local function cross(a, b, dir)
                            local t = X[id(a, b) * 2 + (dir == "x" and 0 or 1)] or 0.5
                            if dir == "x" then
                                return { (a + 0.5 + t) * g, (b + 0.5) * g }
                            end
                            return { (a + 0.5) * g, (b + 0.5 + t) * g }
                        end
                        local segs, done = {}, {}
                        for k in pairs(fm.floor) do
                            local a0, b0 = string.match(k, "^(-?%d+),(-?%d+),")
                            a0, b0 = tonumber(a0), tonumber(b0)
                            if a0 and b0 and not (F[id(a0 + 1, b0)] and F[id(a0 - 1, b0)] and F[id(a0, b0 + 1)] and F[id(a0, b0 - 1)]) then
                                for da = -1, 0 do
                                    for db = -1, 0 do
                                        local a, b = a0 + da, b0 + db
                                        local sid = id(a, b)
                                        if not done[sid] then
                                            done[sid] = true
                                            local ea, eb, ec, ed = F[id(a, b)] == true, F[id(a + 1, b)] == true,
                                                F[id(a + 1, b + 1)] == true, F[id(a, b + 1)] == true
                                            if not (ea == eb and eb == ec and ec == ed) then
                                                local pts = {}
                                                if ea ~= eb then pts[#pts + 1] = cross(a, b, "x") end
                                                if eb ~= ec then pts[#pts + 1] = cross(a + 1, b, "z") end
                                                if ed ~= ec then pts[#pts + 1] = cross(a, b + 1, "x") end
                                                if ea ~= ed then pts[#pts + 1] = cross(a, b, "z") end
                                                local function add(p1, p2)
                                                    if (p1[1] - p2[1]) ^ 2 + (p1[2] - p2[2]) ^ 2 > 0.0004 then
                                                        segs[#segs + 1] = { p1[1], p1[2], p2[1], p2[2] }
                                                    end
                                                end
                                                if #pts == 2 then
                                                    add(pts[1], pts[2])
                                                elseif #pts == 4 then
                                                    add(pts[1], pts[2])
                                                    add(pts[3], pts[4])
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                            tick()
                        end
                        local drawn = joinLines(segs, config.minimapWholeTol or 2.5, config.minimapWholeMinLen or 14)
                        local cap = config.minimapWholeMax or 1500
                        if #drawn > cap then
                            table.sort(drawn, function(s1, s2)
                                return (s1[3] - s1[1]) ^ 2 + (s1[4] - s1[2]) ^ 2 > (s2[3] - s2[1]) ^ 2 + (s2[4] - s2[2]) ^ 2
                            end)
                            for i = #drawn, cap + 1, -1 do
                                drawn[i] = nil
                            end
                        end
                        W.segs = drawn
                        W.bounds = { x0 * g, (x1 + 1) * g, z0 * g, (z1 + 1) * g }
                        W.count = #segs
                    end)
                    W.building = false
                    W.at = os.clock()
                    W.ok = ok
                end)
                return W
            end
            context.minimapWhole = wholeOutline
            zone.draw = function()
                if not VF() then
                    o()
                    return
                end
                local v, k = zone.use3D(), context.DG
                local wholeOn = not v and not zone.big and config.minimapWholeMap ~= false
                if wholeOn then
                    pcall(function() -- D-073: the whole map on the minimap at all times (the floor map's outline, every level)
                        local fm = floorMapNow()
                        local W = fm and wholeOutline(fm)
                        if W and W.segs then
                            local edgeColour = config.minimapEdgeColor or Color3.fromRGB(235, 235, 235)
                            local thin = 0.5 / math.max(dF, 0.01)
                            for _, s in ipairs(W.segs) do
                                local dx, dz = s[3] - s[1], s[4] - s[2]
                                local L = math.sqrt(dx * dx + dz * dz)
                                if L > 0.05 then
                                    DF((s[1] + s[3]) * 0.5, (s[2] + s[4]) * 0.5, L * 0.5 + thin, thin, math.atan2(dz, dx), edgeColour, 0.1, 2)
                                end
                            end
                        end
                    end)
                end
                if not v and config.minimapWalkEdge ~= false and not (wholeOn and zone.whole and zone.whole.segs) then
                    pcall(function() -- D-069: the floor's edge on the minimap - the recorder's floor map, else the walked map
                        local fm = floorMapNow() -- D-073: shared
                        local px, py, pz = zone.cx, zone.cy or 0, zone.cz
                        local R = (zone.big and (config.minimapBigRange or 160) or (config.minimapRange or 110)) + 8
                        local cache = zone.edgeCache
                        local moved = not cache or (cache.x - px) ^ 2 + (cache.z - pz) ^ 2 > 16 or math.abs(cache.y - py) > 3
                            or cache.big ~= zone.big
                        local newer = fm and cache and cache.ver ~= tostring(fm.version) .. tostring(fm)
                        local age = os.clock() - (cache and cache.at or -math.huge)
                        if ((moved or (cache and cache.fm ~= (fm ~= nil))) and age > 0.4) or (newer and age > (config.minimapFloorRefresh or 1.5)) then -- D-069: a new floor map piece at most every 1.5 s
                            local segs = {}
                            local floorCount = 0
                            if fm then
                                -- marching squares on the 2-stud grid; a vertex is floor, no floor (measured) or unknown
                                -- (unknown counts as floor: a line only where the floor is measured to end)
                                local g = fm.g or 2
                                local fy = py - 3
                                local lv = math.floor(fy / 6 + 0.5)
                                local F, N, X = fm.floor, fm.none, fm.cross or {}
                                local x0, x1 = math.floor((px - R) / g), math.floor((px + R) / g)
                                local z0, z1 = math.floor((pz - R) / g), math.floor((pz + R) / g)
                                local W = {}
                                for ix = x0, x1 + 1 do
                                    local col = {}
                                    W[ix] = col
                                    for iz = z0, z1 + 1 do
                                        local base = ix .. "," .. iz .. ","
                                        local on = false
                                        for l = lv - 1, lv + 1 do
                                            local y = F[base .. l]
                                            if y and math.abs(y - fy) <= 7 then
                                                on = true
                                                break
                                            end
                                        end
                                        if on then
                                            floorCount += 1
                                            col[iz] = 1
                                        elseif N[base .. lv] or N[base .. (lv - 1)] or N[base .. (lv + 1)] then
                                            col[iz] = 0
                                        else
                                            col[iz] = 2 -- unknown
                                        end
                                    end
                                end
                                local function isOn(s)
                                    return s ~= 0
                                end
                                local function cross(ix, iz, dir) -- the edge point between vertex (ix, iz) and the next
                                    local b = ix .. "," .. iz .. ","
                                    local t = X[b .. lv .. "," .. dir] or X[b .. (lv - 1) .. "," .. dir] or X[b .. (lv + 1) .. "," .. dir] or 0.5
                                    if dir == "x" then
                                        return (ix + 0.5 + t) * g, (iz + 0.5) * g
                                    end
                                    return (ix + 0.5) * g, (iz + 0.5 + t) * g
                                end
                                for ix = x0, x1 do
                                    local ca, cb = W[ix], W[ix + 1]
                                    for iz = z0, z1 do
                                        local a, b, c, d = ca[iz], cb[iz], cb[iz + 1], ca[iz + 1]
                                        local ea, eb, ec, ed = isOn(a), isOn(b), isOn(c), isOn(d)
                                        -- a line only between measured floor and measured no floor (not at unexplored ground)
                                        local hasFloor = a == 1 or b == 1 or c == 1 or d == 1
                                        local hasNone = a == 0 or b == 0 or c == 0 or d == 0
                                        if hasFloor and hasNone and not (ea == eb and eb == ec and ec == ed) then
                                            local pts = {}
                                            if ea ~= eb then pts[#pts + 1] = { cross(ix, iz, "x") } end
                                            if eb ~= ec then pts[#pts + 1] = { cross(ix + 1, iz, "z") } end
                                            if ed ~= ec then pts[#pts + 1] = { cross(ix, iz + 1, "x") } end
                                            if ea ~= ed then pts[#pts + 1] = { cross(ix, iz, "z") } end
                                            local function add(p1, p2)
                                                if (p1[1] - p2[1]) ^ 2 + (p1[2] - p2[2]) ^ 2 > 0.0004 then -- no zero-length pieces
                                                    segs[#segs + 1] = { p1[1], p1[2], p2[1], p2[2] }
                                                end
                                            end
                                            if #pts == 2 then
                                                add(pts[1], pts[2])
                                            elseif #pts == 4 then
                                                add(pts[1], pts[2])
                                                add(pts[3], pts[4])
                                            end
                                        end
                                    end
                                end
                            end
                            if floorCount < (config.minimapFloorMin or 30) then
                                -- no floor map here yet: the walked map's outline (6-stud cells)
                                segs = {}
                                local idx = context.MapLite and context.MapLite.route and context.MapLite.route()
                                if idx then
                                    local have = {}
                                    for gx = math.floor((px - R) / 24), math.floor((px + R) / 24) do
                                        for gz = math.floor((pz - R) / 24), math.floor((pz + R) / 24) do
                                            local slot = idx[gx .. "," .. gz]
                                            if slot and slot.lo <= py + 10 and slot.hi >= py - 10 then
                                                for _, c in ipairs(slot.cells) do
                                                    if math.abs(c[2] - py) <= 10 then
                                                        have[math.floor(c[1] / 6 + 0.5) .. "," .. math.floor(c[3] / 6 + 0.5)] = true
                                                    end
                                                end
                                            end
                                        end
                                    end
                                    for k2 in pairs(have) do
                                        local a, b = k2:match("(-?%d+),(-?%d+)")
                                        local cx, cz = tonumber(a), tonumber(b)
                                        for _, dd in ipairs({ { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } }) do
                                            if not have[(cx + dd[1]) .. "," .. (cz + dd[2])] then
                                                local mx, mz = (cx + dd[1] * 0.5) * 6, (cz + dd[2] * 0.5) * 6
                                                if dd[1] ~= 0 then
                                                    segs[#segs + 1] = { mx, mz - 3, mx, mz + 3 }
                                                else
                                                    segs[#segs + 1] = { mx - 3, mz, mx + 3, mz }
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                            -- join the pieces into lines and straighten them (corners kept: 0.35-stud tolerance)
                            local function pk(x, z)
                                return math.floor(x * 50 + 0.5) .. "," .. math.floor(z * 50 + 0.5)
                            end
                            local ends = {}
                            for i, s in ipairs(segs) do
                                for e = 0, 1 do
                                    local k = pk(s[1 + e * 2], s[2 + e * 2])
                                    local l = ends[k]
                                    if not l then
                                        l = {}
                                        ends[k] = l
                                    end
                                    l[#l + 1] = i
                                end
                            end
                            local used, lines = {}, {}
                            local function other(s, x, z)
                                if pk(s[1], s[2]) == pk(x, z) then
                                    return s[3], s[4]
                                end
                                return s[1], s[2]
                            end
                            for i, s in ipairs(segs) do
                                if not used[i] then
                                    used[i] = true
                                    local pts = { { s[1], s[2] }, { s[3], s[4] } }
                                    for side = 1, 2 do
                                        while true do
                                            local tip = side == 1 and pts[#pts] or pts[1]
                                            local prev = side == 1 and pts[#pts - 1] or pts[2]
                                            local hx, hz = tip[1] - prev[1], tip[2] - prev[2]
                                            local hl = math.sqrt(hx * hx + hz * hz)
                                            local nxt, best
                                            for _, j in ipairs(ends[pk(tip[1], tip[2])] or {}) do
                                                if not used[j] then
                                                    -- at a branch: the straightest way on
                                                    local ox, oz = other(segs[j], tip[1], tip[2])
                                                    local nx, nz = ox - tip[1], oz - tip[2]
                                                    local nl = math.sqrt(nx * nx + nz * nz)
                                                    local score = (hl > 0 and nl > 0) and (hx * nx + hz * nz) / (hl * nl) or 0
                                                    if not best or score > best then
                                                        nxt, best = j, score
                                                    end
                                                end
                                            end
                                            if not nxt then
                                                break
                                            end
                                            used[nxt] = true
                                            local ox, oz = other(segs[nxt], tip[1], tip[2])
                                            if side == 1 then
                                                pts[#pts + 1] = { ox, oz }
                                            else
                                                table.insert(pts, 1, { ox, oz })
                                            end
                                        end
                                    end
                                    lines[#lines + 1] = pts
                                end
                            end
                            local eps = config.minimapEdgeTolerance or 0.35
                            local function simplify(pts, i0, i1, out)
                                local ax, az, bx, bz = pts[i0][1], pts[i0][2], pts[i1][1], pts[i1][2]
                                local dx, dz = bx - ax, bz - az
                                local L = math.sqrt(dx * dx + dz * dz)
                                local far, fi = 0, nil
                                for i = i0 + 1, i1 - 1 do
                                    local d
                                    if L < 1e-6 then
                                        d = math.sqrt((pts[i][1] - ax) ^ 2 + (pts[i][2] - az) ^ 2)
                                    else
                                        d = math.abs((pts[i][1] - ax) * dz - (pts[i][2] - az) * dx) / L
                                    end
                                    if d > far then
                                        far, fi = d, i
                                    end
                                end
                                if fi and far > eps then
                                    simplify(pts, i0, fi, out)
                                    simplify(pts, fi, i1, out)
                                else
                                    out[#out + 1] = { ax, az, bx, bz }
                                end
                            end
                            local drawn = {}
                            for _, pts in ipairs(lines) do
                                if #pts >= 2 then
                                    simplify(pts, 1, #pts, drawn)
                                end
                            end
                            cache = { x = px, y = py, z = pz, big = zone.big, at = os.clock(), segs = drawn, fm = fm ~= nil,
                                ver = fm and tostring(fm.version) .. tostring(fm) or "" }
                            zone.edgeCache = cache
                        end
                        if cache then
                            local edgeColour = config.minimapEdgeColor or Color3.fromRGB(235, 235, 235)
                            for _, s in ipairs(cache.segs) do
                                local dx, dz = s[3] - s[1], s[4] - s[2]
                                local L = math.sqrt(dx * dx + dz * dz)
                                if L > 0.05 then
                                    DF((s[1] + s[3]) * 0.5, (s[2] + s[4]) * 0.5, L * 0.5 + 0.15, 0.3, math.atan2(dz, dx), edgeColour, 0.1, 2)
                                end
                            end
                        end
                    end)
                end
                local a, jF, UF = k and k.now or os.clock(), context.WALLS and context.WALLS.parts, zone.cy or 0
                if jF and not v then
                    for index = 1, math.min(#jF, 400), 1 do
                        local wF = jF[index]
                        if wF and wF.Parent then
                            local transform, size = wF.CFrame, wF.Size
                            index = size.Y * 0.5
                            if
                                math.abs(transform.UpVector.Y) > 0.7
                                and transform.Y + index > UF - 1
                                and transform.Y - index < UF + 4
                            then
                                local rightVector = transform.RightVector
                                DF(
                                    transform.X,
                                    transform.Z,
                                    size.X * 0.5,
                                    size.Z * 0.5,
                                    math.atan2(rightVector.Z, rightVector.X),
                                    color2,
                                    0.35,
                                    2
                                )
                            end
                        end
                    end
                end
                UF, jF = hazardReader.rodinRig, not v
                local JF = jF and UF and UF.Parent and hazardReader.arenaCentre
                if JF then
                    UF = hazardReader.arenaCentre
                    SF(UF.X, UF.Z, (config.rodinSweepArenaR or 100) * dF, color2, 0.3, 2, 2)
                end
                UF = jF and config.mapCrystals ~= false
                if UF then
                    JF = contextWorkspace:FindFirstChild("secondBossCrystals")
                    if JF then
                        local iterateArray, YF = ipairs, vmHelpers[127](JF:GetChildren())
                        for key, entry in iterateArray(vmHelpers:jB(YF)) do
                            key = string.lower(entry.Name)
                            local wF = key == "red" and Color3.fromRGB(255, 60, 60)
                                or key == "green" and Color3.fromRGB(60, 255, 60)
                                or key == "yellow" and Color3.fromRGB(255, 235, 40)
                                or nil
                            key = wF and (entry:IsA("BasePart"))
                            if key then
                                local YF = math.max(entry.Size.X * 0.5 * dF, 6)
                                SF(entry.Position.X, entry.Position.Z, YF, wF, 0.15, 6)
                                SF(entry.Position.X, entry.Position.Z, YF + 3, wF, 0.2, 6, 2)
                            end
                        end
                    end
                end
                UF = jF and config.mapOrbLinks ~= false and hazardReader.orbScan
                if UF then
                    local function wF(YF, vF, MF, ZF, nF, fF, rF)
                        local oF, AF = MF - YF, ZF - vF
                        local kF = math.sqrt(oF * oF + AF * AF)
                        if kF < 1 then
                            return
                        end
                        DF(
                            (YF + MF) * 0.5,
                            (vF + ZF) * 0.5,
                            kF * 0.5,
                            fF * 0.5 / math.max(dF, 0.01),
                            math.atan2(AF, oF),
                            nF,
                            rF,
                            4
                        )
                    end
                    JF = localPlayer.Character
                    local YF, vF, MF =
                        JF and (JF:FindFirstChild("HumanoidRootPart")),
                        context.otherRoots and context.otherRoots() or {},
                        {}
                    for index2, entry2 in ipairs(hazardReader.orbScan) do
                        index2 = entry2.part
                        local fF = index2 and hazardReader.parts[index2]
                        if index2 and index2.Parent and fF and not MF[index2] then
                            MF[index2] = true
                            local position, rF = index2.Position, entry2.colour
                            local oF = rF == "red" and Color3.fromRGB(255, 60, 60)
                                or rF == "green" and Color3.fromRGB(60, 255, 60)
                                or rF == "yellow" and Color3.fromRGB(255, 235, 40)
                                or Color3.new(1, 1, 1)
                            if entry2.mine and YF then
                                rF = hazardReader.orbNear and hazardReader.orbNear.part == index2
                                wF(
                                    YF.Position.X,
                                    YF.Position.Z,
                                    position.X,
                                    position.Z,
                                    oF,
                                    rF and 3 or 2,
                                    rF and 0.05 or 0.35
                                )
                            elseif (fF.stick == "other" or fF.owner == "other") and #vF > 0 then
                                local YF, ZF = math.huge
                                for index3, entry3 in ipairs(vF) do
                                    index3 = (entry3.Position.X - position.X) ^ 2
                                        + (entry3.Position.Z - position.Z) ^ 2
                                    if index3 < YF then
                                        YF, ZF = index3, entry3
                                    else
                                    end
                                end
                                ZF = if fF.lineRoot and fF.lineRoot.Parent then fF.lineRoot else ZF
                                if ZF then
                                    wF(
                                        ZF.Position.X,
                                        ZF.Position.Z,
                                        position.X,
                                        position.Z,
                                        Color3.fromRGB(150, 155, 170),
                                        1,
                                        0.45
                                    )
