local abs, max, min, sqrt, floor = math.abs, math.max, math.min, math.sqrt, math.floor
local HUGE = math.huge

local API = { Version = 6 }
local S = nil -- the current (or last) recording; nil before the first Start
-- AurRecorder 1.9.0: the ranges for the current recording (wider for the bonus boss)
local function bonusRec() -- labels starting with any of CFG.BonusLabels ("bonusboss", "boss_bonus")
	if S == nil or type(CFG.BonusLabels) ~= "table" then return false end
	local lab = string.lower(tostring(S.label or ""))
	for _, pre in CFG.BonusLabels do
		if string.sub(lab, 1, #pre) == pre then return true end
	end
	return false
end
local function hazardRange() return bonusRec() and (CFG.BonusHazardRange or CFG.HazardRange) or CFG.HazardRange end
local function untrackRange() return bonusRec() and (CFG.BonusUntrackRange or CFG.UntrackRange) or CFG.UntrackRange end
local function enemyRange() return bonusRec() and (CFG.BonusEnemyRange or CFG.EnemyRange) or CFG.EnemyRange end
local function alwaysUnder(inst) -- AurRecorder 1.9.0: a part under one of CFG.AlwaysTrackUnder (6 levels)
	local set = CFG.AlwaysTrackUnder
	if not set then return false end
	if inst.Parent and string.lower(inst.Parent.Name) == "pool" then return false end -- 1.9.2: sampled as "pool" rows
	local node = inst.Parent
	for _ = 1, 6 do
		if node == nil or node == Workspace then return false end
		if set[string.lower(node.Name)] then return true end
		node = node.Parent
	end
	return false
end
local running = false
local destroyed = false
local ui = {} -- panel instances
local uiConns = {} -- panel connections (live while the panel exists)
local pick = { label = CFG.Label, controller = CFG.Controller } -- panel choices for the next recording
local message = nil -- one-line note on the panel (e.g. why Start was refused)

--------------------------------------------------------------------------------
-- Formatting
--------------------------------------------------------------------------------
local function num(x, fmt)
	if type(x) ~= "number" or x ~= x or x == HUGE or x == -HUGE then return "null" end
	return string.format(fmt or "%.2f", x)
end

local function vec(v, fmt) return "[" .. num(v.X, fmt) .. "," .. num(v.Y, fmt) .. "," .. num(v.Z, fmt) .. "]" end

local function str(s)
	s = tostring(s)
	local ok, r = pcall(HttpService.JSONEncode, HttpService, s)
	if ok and type(r) == "string" then return r end
	return '"' .. string.gsub(s, '[%c"\\]', "?") .. '"'
end

local function hex(c) return string.format('"%02x%02x%02x"', floor(c.R * 255 + 0.5), floor(c.G * 255 + 0.5), floor(c.B * 255 + 0.5)) end

local function hdist(a, b)
	local dx, dz = a.X - b.X, a.Z - b.Z
	return sqrt(dx * dx + dz * dz)
end

-- Horizontal distance from p to a part's footprint (0 when p is over it): long lanes and beams count by their
-- extent, not by their centre.
local function footprintDist(cf, size, p)
	local q = p - cf.Position
	local d2 = 0
	for i = 1, 3 do
		local axis = i == 1 and cf.XVector or (i == 2 and cf.YVector or cf.ZVector)
		if abs(axis.Y) < 0.7 then
			local e = abs(q:Dot(axis)) - (i == 1 and size.X or (i == 2 and size.Y or size.Z)) * 0.5
			if e > 0 then d2 += e * e end
		end
	end
	return sqrt(d2)
end

local function clock(sec)
	sec = max(0, floor(sec))
	if sec >= 3600 then return string.format("%d:%02d:%02d", sec // 3600, (sec // 60) % 60, sec % 60) end
	return string.format("%02d:%02d", sec // 60, sec % 60)
end

local function mb(bytes)
	if bytes < 1048576 then return string.format("%.0f KB", bytes / 1024) end
	return string.format("%.1f MB", bytes / 1048576)
end

-- Console lines can carry licence keys or tokens from other scripts: drop such lines, shorten the rest.
local SENSITIVE = { "key", "token", "license", "licence", "auth", "password", "hwid", "webhook", "cookie", "secret" }
local function redact(s)
	s = tostring(s)
	local l = string.lower(s)
	for _, w in SENSITIVE do
		if string.find(l, w, 1, true) then return "<redacted: line mentions '" .. w .. "'>" end
	end
	s = string.gsub(s, "https?://%S+", "<url>")
	if string.sub(s, 1, 4) ~= "[BN]" then -- v4: BossNav's own lines keep their hazard names
		s = string.gsub(s, "[%w_%-]+", function(tok)
			if #tok >= 20 then return "<long-token>" end
			return nil
		end)
	end
	return string.sub(s, 1, CFG.LogChars)
end

--------------------------------------------------------------------------------
-- Output: rows are buffered and written as numbered part files
--------------------------------------------------------------------------------
local function newState(label, controller)
	return {
		label = label, controller = controller, t0 = os.clock(), endT = nil, open = false, stopReason = nil, limit = nil,
		conns = {}, errAt = -HUGE, result = nil,
		out = { prefix = nil, buf = {}, bufBytes = 0, part = 0, lines = 0, bytes = 0, written = 0, failed = 0, files = {} },
		stats = { frames = 0, dtSum = 0, dtMax = 0, cost = 0, costMax = 0, costN = 0, logs = 0, logsDropped = 0, marks = 0,
			hpEvents = 0, hpLost = 0, casts = 0, status = 0, prescanMs = 0, dropped = 0, logRepeats = 0 },
		last = { p = -HUGE, e = -HUGE, h = -HUGE, s = -HUGE, a = -HUGE, perf = -HUGE, flush = -HUGE, panel = -HUGE, rep = -HUGE, floor = -HUGE, psum = -HUGE }, -- D-095: psum
		me = { char = nil, hum = nil, root = nil, hp = nil, ws = nil, conns = {}, lastPos = nil, lastT = nil,
			nid = nil, nd = nil, nearMobs = {}, hadEnemies = false },
		tracked = {}, trackedCount = 0, nextHazard = 0, pending = {}, tally = {}, tallyKeys = 0,
		mobs = {}, nextEnemy = 0, abilities = {}, status = {}, statusCount = {}, lastBn = nil, logSeen = {}, logKeys = 0,
	}
end

local function emit(kind, body)
	if not (S and S.open) then return end
	local out = S.out
	local line = '{"t":' .. num(os.clock() - S.t0, "%.3f") .. ',"k":"' .. kind .. '"' .. ((body and body ~= "") and ("," .. body) or "") .. "}"
	out.buf[#out.buf + 1] = line
	out.lines += 1
	out.bytes += #line + 1
	out.bufBytes += #line + 1
	if S.stopReason == nil then
		if out.bytes >= CFG.MaxMB * 1048576 then
			S.stopReason, S.limit = "safety limit: size " .. CFG.MaxMB .. " MB", "size"
		elseif out.lines >= CFG.MaxLines then
			S.stopReason, S.limit = "safety limit: " .. CFG.MaxLines .. " lines", "lines"
		end
	end
end

local function guard(where, fn, ...)
	local ok, err = pcall(fn, ...)
	if not ok and S and os.clock() - S.errAt > 2 then
		S.errAt = os.clock()
		emit("err", '"where":' .. str(where) .. ',"msg":' .. str(err))
	end
end

local function flush()
	local out = S.out
	if #out.buf == 0 or out.prefix == nil then return end
	out.part += 1
	local name = string.format("%spart-%03d.jsonl", out.prefix, out.part)
	local body = table.concat(out.buf, "\n") .. "\n"
	table.clear(out.buf)
	out.bufBytes = 0
	if pcall(writefile, name, body) then
		out.files[#out.files + 1] = name
		out.written += #body
	else
		out.failed += 1
	end
end

-- FightRecorder/<stamp>-<label>/ when folders work, else flat FightRecorder-<stamp>-<label>-* files.
local function prepareOutput(label)
	local clean = string.gsub(tostring(label), "[^%w_%-]", "_")
	local base = CFG.Folder .. "/" .. os.date("%Y%m%d-%H%M%S") .. "-" .. clean
	if CFG.ExactName then -- v6: the name the user typed, made unique
		if CFG.PerAccount ~= false then -- D-078: one folder per account - accounts recording at once never share one
			local okN, who = pcall(function() return game:GetService("Players").LocalPlayer.Name end)
			if okN and type(who) == "string" and who ~= "" then
				clean = clean .. "-" .. string.gsub(who, "[^%w_%-]", "_")
			end
		end
		base = CFG.Folder .. "/" .. clean
		local n = 1
		while n < 1000 and select(2, pcall(function() return isfolder(base) or isfile(base .. "/README.txt") end)) == true do
			n += 1
			base = CFG.Folder .. "/" .. clean .. "-" .. n
		end
	end
	local note = "FightRecorder v6 output: part-NNN.jsonl (one JSON object per line, in order) and summary.json\n"
	local okDir = pcall(function()
		for folder in string.gmatch(CFG.Folder, "[^/]+") do -- nested folders (e.g. Aur_Hub/recordings)
			local path = string.sub(CFG.Folder, 1, (string.find(CFG.Folder, folder, 1, true) or 1) + #folder - 1)
			if not isfolder(path) then makefolder(path) end
		end
		if not isfolder(base) then makefolder(base) end
	end)
	if okDir and pcall(writefile, base .. "/README.txt", note) then return base .. "/" end
	local flat = string.gsub(base, "/", "-") .. "-"
	if pcall(writefile, flat .. "README.txt", note) then return flat end
	return nil
end

--------------------------------------------------------------------------------
-- Instance helpers (reads only)
--------------------------------------------------------------------------------
local function watched(name)
	local l = string.lower(name)
	for _, w in CFG.Watch do
		if string.find(l, w, 1, true) then return true end
	end
	return false
end

local function parentPath(inst)
	local names, p, n = {}, inst.Parent, 0
	while p and p ~= game and n < 3 do
		n += 1
		table.insert(names, 1, p.Name)
		p = p.Parent
	end
	return table.concat(names, "/")
end

-- Inside a player character or a model with a Humanoid (a mob's own body).
local function inHumanoidModel(inst)
	local m = inst:IsA("Model") and inst or inst:FindFirstAncestorOfClass("Model")
	while m do
		if Players:GetPlayerFromCharacter(m) or m:FindFirstChildOfClass("Humanoid") then return true end
		m = m:FindFirstAncestorOfClass("Model")
	end
	return false
end

local function shapeOf(inst)
	if inst:IsA("Part") then return inst.Shape.Name end
	if inst:IsA("MeshPart") then return "Mesh" end
	return inst.ClassName
end

--------------------------------------------------------------------------------
-- You
--------------------------------------------------------------------------------
local function unbindCharacter()
	for _, c in S.me.conns do pcall(c.Disconnect, c) end
	table.clear(S.me.conns)
end

-- Body overlap estimate: your root point against the part's box grown by a rough body size.
local function overlaps(inst, p)
	local q = inst.CFrame:PointToObjectSpace(p)
	local h = inst.Size * 0.5
	return abs(q.X) <= h.X + 1.5 and abs(q.Y) <= h.Y + 3 and abs(q.Z) <= h.Z + 1.5
end

local function onHealth(new)
	local me, stats = S.me, S.stats
	local old = me.hp
	me.hp = new
	if old == nil or new == old then return end
	local d = new - old
	stats.hpEvents += 1
	if d < 0 then stats.hpLost -= d end
	local root = me.root
	local p = root and root.Parent and root.Position
	local hz, mob = {}, {}
	if p then
		local near = {}
		for inst, rec in S.tracked do
			if inst.Parent then
				local dist = footprintDist(inst.CFrame, inst.Size, p)
				if dist <= CFG.DamageNear then near[#near + 1] = { rec.id, dist, overlaps(inst, p) } end
			end
		end
		table.sort(near, function(a, b) return a[2] < b[2] end)
		for i = 1, min(#near, 6) do hz[i] = string.format("[%d,%s,%s]", near[i][1], num(near[i][2], "%.1f"), tostring(near[i][3])) end
		for _, e in me.nearMobs do
			if e[4] <= CFG.DamageNear and #mob < 4 then mob[#mob + 1] = string.format("[%d,%s]", e[1], num(e[4], "%.1f")) end
		end
	end
	emit("hp", string.format('"hp":%s,"d":%s,"pos":%s,"near_hz":[%s],"near_mob":[%s],"note":"proximity only, not the cause"',
		num(new, "%.1f"), num(d, "%.1f"), p and vec(p) or "null", table.concat(hz, ","), table.concat(mob, ",")))
	if d < -1e6 then guard("hitsnap", CFG._hitSnap, p, d) end -- 1.9.3
end

local function onWalkSpeed()
	local me = S.me
	local hum = me.hum
	if not hum then return end
	local ws = hum.WalkSpeed
	if ws == me.ws then return end
	emit("ws", string.format('"from":%s,"to":%s,"note":"set by the game, Ethos or another script (source unknown)"', num(me.ws), num(ws)))
	me.ws = ws
end

local function bindCharacter()
	local me = S.me
	local char = LocalPlayer.Character
	local hum = char and char:FindFirstChildOfClass("Humanoid")
	if char == me.char and hum == me.hum then
		if hum and not (me.root and me.root.Parent) then me.root = hum.RootPart end
		return
	end
	unbindCharacter()
	me.char, me.hum = char, hum
	me.root = hum and hum.RootPart
	me.lastPos, me.lastT = nil, nil
	if hum then
		me.hp, me.ws = hum.Health, hum.WalkSpeed
		me.conns[#me.conns + 1] = hum.HealthChanged:Connect(function(v) guard("health", onHealth, v) end)
		me.conns[#me.conns + 1] = hum:GetPropertyChangedSignal("WalkSpeed"):Connect(function() guard("walkspeed", onWalkSpeed) end)
		emit("char", string.format('"hp":%s,"maxhp":%s,"ws":%s', num(hum.Health, "%.1f"), num(hum.MaxHealth, "%.1f"), num(hum.WalkSpeed)))
	else
		emit("char", '"none":true')
	end
end

local function samplePlayer(now)
	local me = S.me
	local hum, root = me.hum, me.root
	if not (hum and root and root.Parent) then return end
	local p = root.Position
	local v = root.AssemblyLinearVelocity
	local mv = nil
	if me.lastPos and now - me.lastT > 1e-3 then mv = hdist(p, me.lastPos) / (now - me.lastT) end
	me.lastPos, me.lastT = p, now
	local md = hum.MoveDirection
	local look = root.CFrame.LookVector
	emit("p", string.format('"pos":%s,"v":%s,"mv":%s,"md":[%s,%s],"ws":%s,"hp":%s,"st":%s,"yaw":%s,"air":%s,"ne":%s,"nid":%s',
		vec(p), vec(v), num(mv), num(md.X, "%.3f"), num(md.Z, "%.3f"), num(hum.WalkSpeed), num(hum.Health, "%.1f"),
		str(hum:GetState().Name), num(math.deg(math.atan2(-look.X, -look.Z)), "%.1f"), tostring(hum.FloorMaterial == Enum.Material.Air),
		num(me.nd, "%.1f"), me.nid and tostring(me.nid) or "null"))
end

--------------------------------------------------------------------------------
-- Enemies: non-player Humanoids, found once at Start and then from DescendantAdded
--------------------------------------------------------------------------------
local function considerMob(h)
	local mobs = S.mobs
	if mobs[h] then return end
	local m = h.Parent
	if not (m and m:IsA("Model")) or Players:GetPlayerFromCharacter(m) then return end
	S.nextEnemy += 1
	mobs[h] = { id = S.nextEnemy, seen = false, dead = false, removed = false }
	-- AurRecorder 1.4.0: the animations a mob starts (its attack wind-up), within range
	local rec = mobs[h]
	local function hook(animator)
		if rec.animConn then return end
		rec.animConn = animator.AnimationPlayed:Connect(function(track)
			guard("anim", function()
				if not rec.seen or rec.dead then return end
				local r = h.RootPart or (h.Parent and h.Parent.PrimaryPart)
				local me = S.me.root
				if not (r and me and me.Parent) or hdist(r.Position, me.Position) > enemyRange() then return end
				local anim = track.Animation
				emit("anim", string.format('"id":%d,"anim":%s,"name":%s,"len":%s,"speed":%s', rec.id,
					str(anim and anim.AnimationId or ""), str(track.Name), num(track.Length, "%.2f"), num(track.Speed, "%.2f")))
			end)
		end)
		S.conns[#S.conns + 1] = rec.animConn
	end
	pcall(function()
		local animator = h:FindFirstChildOfClass("Animator")
		if animator then
			hook(animator)
		else
			local c
			c = h.ChildAdded:Connect(function(ch)
				if ch:IsA("Animator") then
					hook(ch)
					c:Disconnect()
				end
			end)
			S.conns[#S.conns + 1] = c
		end
	end)
end

local function sampleEnemies()
	local me = S.me
	local root = me.root
	if not (root and root.Parent) then return end
	local p = root.Position
	local list = {}
	for h, rec in S.mobs do
		local m = h.Parent
		if rec.removed or m == nil then
			if rec.seen then emit("edel", '"id":' .. rec.id) end
			S.mobs[h] = nil
		else
			local r = h.RootPart or m.PrimaryPart
			if r then
				local d = hdist(r.Position, p)
				if d <= enemyRange() then
					if not rec.seen then
						rec.seen = true
						emit("enew", string.format('"id":%d,"name":%s,"maxhp":%s,"path":%s', rec.id, str(m.Name), num(h.MaxHealth, "%.0f"), str(parentPath(m))))
					end
					if h.Health <= 0 then
						if not rec.dead then
							rec.dead = true
							emit("edie", '"id":' .. rec.id)
						end
					else
						list[#list + 1] = { rec.id, r.Position, h.Health, d }
					end
				end
			end
		end
	end
	table.sort(list, function(a, b) return a[4] < b[4] end)
	local parts = {}
	for i = 1, min(#list, CFG.MaxEnemies) do
		local e = list[i]
		parts[i] = string.format("[%d,%s,%s,%s,%s,%s]", e[1], num(e[2].X), num(e[2].Y), num(e[2].Z), num(e[3], "%.0f"), num(e[4], "%.1f"))
	end
	me.nid, me.nd, me.nearMobs = list[1] and list[1][1], list[1] and list[1][4], list
	if #parts > 0 or me.hadEnemies then emit("e", '"l":[' .. table.concat(parts, ",") .. "]") end
	me.hadEnemies = #parts > 0
end

--------------------------------------------------------------------------------
-- Hazard candidates: new parts only (DescendantAdded), looked at one frame later (after the game has
-- positioned them), tracked while nearby. Nothing scans the whole Workspace per frame.
--------------------------------------------------------------------------------
local function tallyAdd(reason, name, parent)
	local key = reason .. ":" .. (parent and (parent.Name .. "/") or "") .. name
	local tally = S.tally
	if tally[key] then
		tally[key] += 1
	elseif S.tallyKeys < 300 then
		S.tallyKeys += 1
		tally[key] = 1
	else
		tally["other:too many names"] = (tally["other:too many names"] or 0) + 1
	end
end

local function endHazard(inst, rec, why, now)
	S.tracked[inst] = nil
	S.trackedCount -= 1
	emit("h-", string.format('"id":%d,"why":%s,"life":%s,"pos":%s', rec.id, str(why), num(now - rec.addT, "%.3f"), vec(rec.pos)))
end

-- v4: where a listed attack part really is inside its bounding box (rays that can hit only that part). Read-only.
local probeParams = RaycastParams.new()
probeParams.FilterType = Enum.RaycastFilterType.Include
local function probeShape(inst, id)
	local parent = inst.Parent
	if not (CFG.ProbeModels[string.lower(inst.Name)] or (parent and CFG.ProbeModels[string.lower(parent.Name)])) then return end
	if (S.probes or 0) >= CFG.MaxProbes then return end
	S.probes = (S.probes or 0) + 1
	probeParams.FilterDescendantsInstances = { inst }
	local cf, size = inst.CFrame, inst.Size
	local axes = {}
	for i, ax in { cf.XVector, cf.YVector, cf.ZVector } do
		if math.abs(ax.Y) < 0.7 then axes[#axes + 1] = { v = ax, half = (i == 1 and size.X or (i == 2 and size.Y or size.Z)) * 0.5 } end
	end
	local function read(prop)
		local ok, v = pcall(function() return inst[prop] end)
		if not ok or v == nil then return "null" end
		if typeof ~= nil and typeof(v) == "EnumItem" then return str(v.Name) end
		return tostring(v)
	end
	if #axes < 2 then
		emit("geo", string.format('"id":%d,"tilted":true,"queryable":%s', id, read("CanQuery")))
		return
	end
	local n = (math.max(size.X, size.Z) > 200 and CFG.ProbeGridBig) or CFG.ProbeGrid
	local queryable = read("CanQuery") -- AurRecorder 1.5.1: reported as it was; probed queryable for the rays only
	local wasQ = inst.CanQuery
	if not wasQ then pcall(function() inst.CanQuery = true end) end
	local cells, top, depth = {}, cf.Position.Y + size.Magnitude * 0.5 + 2, size.Magnitude + 4
	for i = 0, n - 1 do
		for j = 0, n - 1 do
			local u, v = (i / (n - 1)) * 2 - 1, (j / (n - 1)) * 2 - 1
			local p = cf.Position + axes[1].v * (u * axes[1].half * 0.98) + axes[2].v * (v * axes[2].half * 0.98)
			local res = Workspace:Raycast(Vector3.new(p.X, top, p.Z), Vector3.new(0, -depth, 0), probeParams)
			cells[#cells + 1] = (res and (res.Instance == inst or res.Instance:IsDescendantOf(inst))) and "1" or "0"
		end
	end
	if not wasQ then pcall(function() inst.CanQuery = false end) end
	emit("geo", string.format('"id":%d,"n":%d,"mask":%s,"axis1":%s,"half1":%s,"axis2":%s,"half2":%s,"queryable":%s,"touch":%s,"fidelity":%s',
		id, n, str(table.concat(cells)), vec(axes[1].v, "%.3f"), num(axes[1].half), vec(axes[2].v, "%.3f"), num(axes[2].half),
		queryable, read("CanTouch"), read("CollisionFidelity")))
end

-- the host script's own drawings are not attacks (Aur_Hub's dev visuals filled the 200-part tracker in dungeon-run6-3)
local HOST_VISUALS = { DungeonAutofarmVisuals = true, AoEMarker = true, DQBubble = true }
local function hostVisual(inst)
	local node = inst
	for _ = 1, 8 do
		if node == nil or node == Workspace then return false end
		if HOST_VISUALS[node.Name] then return true end
		node = node.Parent
	end
	return false
end

local function track(inst, addT, why, d, cd)
	S.nextHazard += 1
	local cf, s = inst.CFrame, inst.Size
	local rec = { id = S.nextHazard, addT = addT, pos = cf.Position, size = s, tr = inst.Transparency, col = inst.Color, ax = cf.XVector, ay = cf.YVector }
	S.tracked[inst] = rec
	S.trackedCount += 1
	local src = nil
	for _, e in S.me.nearMobs do
		if (e[2] - cf.Position).Magnitude <= CFG.SourceRadius then
			src = e[1]
			break
		end
	end
	emit("h+", string.format('"id":%d,"name":%s,"cls":%s,"path":%s,"why":%s,"pos":%s,"size":%s,"ax":%s,"ay":%s,"shape":%s,"mat":%s,"col":%s,"tr":%s,"cc":%s,"an":%s,"v":%s,"dist":%s,"cdist":%s,"est_source":%s,"added_t":%s',
		rec.id, str(inst.Name), str(inst.ClassName), str(parentPath(inst)), str(why), vec(cf.Position), vec(s), vec(cf.XVector, "%.3f"),
		vec(cf.YVector, "%.3f"), str(shapeOf(inst)), str(inst.Material.Name), hex(inst.Color), num(inst.Transparency), tostring(inst.CanCollide),
		tostring(inst.Anchored), vec(inst.AssemblyLinearVelocity), num(d, "%.1f"), num(cd, "%.1f"), src and tostring(src) or "null", num(addT - S.t0, "%.3f")))
	pcall(probeShape, inst, rec.id)
end

local function processPending()
	if #S.pending == 0 then return end
	local list = S.pending
	S.pending = {}
	local me = S.me
	local root = me.root
	local rp = root and root.Parent and root.Position
	local camera = Workspace.CurrentCamera
	for _, e in list do
		local inst = e.inst
		local name = inst.Name
		local parent = inst.Parent
		if parent == nil then
			tallyAdd("gone_before_sampling", name)
		elseif hostVisual(inst) then
			tallyAdd("host_visual", name, parent)
		elseif not S.tracked[inst] and not (me.char and inst:IsDescendantOf(me.char)) then
			local named = watched(name) or (parent ~= Workspace and watched(parent.Name))
			local pl = string.lower(parent.Name)
			if bonusRec() and CFG._noisy(name, parentPath(inst)) then -- 1.9.3
				tallyAdd("cosmetic", name, parent)
				continue
			end
			local always = CFG.AlwaysTrack ~= nil and CFG.AlwaysTrack[pl] == true -- D-091
				or CFG.AlwaysTrackNames ~= nil and CFG.AlwaysTrackNames[string.lower(name)] == true -- D-095
				or alwaysUnder(inst) -- AurRecorder 1.9.0 (the bonus boss's effects)
			local noCap = always or CFG.CapExempt ~= nil and CFG.CapExempt[pl] == true
			local cf, s = inst.CFrame, inst.Size
			local pos = cf.Position
			local d = rp and footprintDist(cf, s, rp) or HUGE
			local attached = inst.AssemblyRootPart
			if attached == inst then attached = nil end
			if camera and inst:IsDescendantOf(camera) then
				tallyAdd("camera", name, parent)
			elseif d > hazardRange() and not always then
				tallyAdd("far", name, parent)
			elseif inHumanoidModel(inst) then
				tallyAdd("inside_character_or_mob", name, parent)
			elseif attached and me.char and attached:IsDescendantOf(me.char) then
				tallyAdd("attached_to_you", name, parent)
			elseif attached and inHumanoidModel(attached) then
				tallyAdd("attached_to_character_or_mob", name, parent)
			elseif name == "PrimaryPart" and parent ~= Workspace and parent:IsA("Model") then
				tallyAdd("model_pivot_duplicate", name, parent) -- the attack model's pivot; its hitBox / precast are tracked
			elseif inst.CanCollide and not named then
				tallyAdd("colliding", name, parent)
			elseif max(s.X, s.Y, s.Z) > CFG.MaxHazardSize and not named and not always then
				tallyAdd("large", name, parent)
			elseif not named and rp and hdist(pos, rp) < CFG.OnPlayerRadius and abs(pos.Y - rp.Y) < 6 then
				tallyAdd("appeared_on_you", name, parent)
			elseif S.trackedCount >= CFG._cap() and not noCap then
				S.stats.dropped += 1
				tallyAdd("DROPPED_tracker_full", name, parent)
				if S.stats.dropped <= CFG.MaxDropRows then
					emit("drop", string.format('"name":%s,"path":%s,"dist":%s,"tracked":%d', str(name), str(parentPath(inst)), num(d, "%.1f"), S.trackedCount))
				end
			else
				track(inst, e.t, (named or always) and "watch_name" or "new_noncolliding_part", d, rp and hdist(pos, rp) or nil)
				if always and S.tracked[inst] then
					S.tracked[inst].always = true -- D-091: not untracked for range
				end
			end
		end
	end
end

-- AurRecorder 1.9.2: the bonus boss's pooled ring parts (as rings, not 720 tracked parts) and who is highlighted
-- AurRecorder 1.9.3: what the bonus boss recordings could not answer (bonus labels only)
CFG._noisy = function(name, path)
	local s = string.lower(tostring(name) .. "/" .. tostring(path))
	for _, w in CFG.BonusIgnore do
		if string.find(s, w, 1, true) then return true end
	end
	return false
end
CFG._hitSnap = function(p, d, after)
	if not p or not bonusRec() then return end
	local seen, list, R = {}, {}, CFG.HitSnapR or 40
	local function add(inst)
		if seen[inst] or not inst:IsA("BasePart") or inst.Position.Y < -1000 then return end
		seen[inst] = true
		local m = inst:FindFirstAncestorOfClass("Model")
		if m and Players:GetPlayerFromCharacter(m) then return end
		if CFG._noisy(inst.Name, parentPath(inst)) then return end
		local dist = footprintDist(inst.CFrame, inst.Size, p)
		if dist <= R then list[#list + 1] = { inst, dist } end
	end
	local ok, parts = pcall(function() return Workspace:GetPartBoundsInRadius(p, R) end)
	if ok and parts then for _, x in parts do add(x) end end
	local fx = Workspace:FindFirstChild("voidsbaneV3Effects")
	if fx then for _, x in fx:GetDescendants() do add(x) end end
	table.sort(list, function(a, b) return a[2] < b[2] end)
	local out = {}
	for i = 1, min(#list, CFG.HitSnapMax or 60) do
		local q, dd = list[i][1], list[i][2]
		out[i] = string.format("[%s,%s,%s,%s,%s,%s,%s]", str(q.Name), str(parentPath(q)), num(dd, "%.1f"), vec(q.Size), hex(q.Color), num(q.Transparency), tostring(q.CanTouch))
	end
	emit("hs", string.format('"d":%s,"pos":%s,"n":%d,"after":%s,"l":[%s]', num(d, "%.1f"), vec(p), #list, tostring(after or 0), table.concat(out, ",")))
	if not after then
		if S.snapBuf and #S.snapBuf > 0 then emit("hsb", '"buf":[' .. table.concat(S.snapBuf, ",") .. "]") end
		task.delay(0.15, function()
			if running and S then guard("hitsnap2", CFG._hitSnap, p, d, 0.15) end
		end)
	end
end
CFG._samplePlayers = function()
	if not bonusRec() or not Workspace:FindFirstChild("Voidsbane Vytelus") then return end
	local out = {}
	for _, pl in Players:GetPlayers() do
		local c = pl.Character
		local r = c and c:FindFirstChild("HumanoidRootPart")
		local h = c and c:FindFirstChildOfClass("Humanoid")
		if r and h then
			out[#out + 1] = string.format("[%s,%.1f,%.1f,%.2f]", str(pl.Name), r.Position.X, r.Position.Z, h.MaxHealth > 0 and h.Health / h.MaxHealth or 0)
		end
	end
	local okT, st = pcall(function() return Workspace:GetServerTimeNow() end)
	local okC, look = pcall(function() return Workspace.CurrentCamera.CFrame.LookVector end)
	emit("pp", string.format('"st":%s,"cam":%s,"l":[%s]', okT and num(st, "%.3f") or "null", okC and look and vec(look, "%.2f") or "null", table.concat(out, ",")))
end
CFG._fxAdded = function(inst)
	if not running or not S or not bonusRec() then return end
	local cls = inst.ClassName
	local fx = Workspace:FindFirstChild("voidsbaneV3Effects")
	if inst:IsA("BasePart") and fx and inst:IsDescendantOf(fx) and inst.Position.Y > -1000 then
		-- 1.9.4: what kind of part it really is (a TouchTransmitter = a real touch hitbox), once its children are in
		S.fxaT = S.fxaT or {}
		local ka = inst.Name .. "|" .. (inst.Parent and inst.Parent.Name or "")
		if os.clock() - (S.fxaT[ka] or -HUGE) >= (CFG.FxEvery or 0.5) then
			S.fxaT[ka] = os.clock()
			task.delay(0.05, function()
				guard("fxa", function()
					if not running or not inst.Parent then return end
					local kids = {}
					for _, k in inst:GetChildren() do kids[#kids + 1] = str(k.ClassName .. ":" .. k.Name) end
					emit("fxa", string.format('"name":%s,"path":%s,"touch":%s,"query":%s,"collide":%s,"attrs":%s,"pattrs":%s,"kids":[%s]', str(inst.Name),
						str(parentPath(inst)), tostring(inst.CanTouch), tostring(inst.CanQuery), tostring(inst.CanCollide), CFG._attrs(inst),
						inst.Parent and CFG._attrs(inst.Parent) or "{}", table.concat(kids, ",")))
				end)
			end)
		end
	end
	if not CFG.FxClasses[cls] then return end
	local okL, inLight = pcall(function() return inst:IsDescendantOf(game:GetService("Lighting")) end)
	if cls ~= "Highlight" and cls ~= "Sound" and not (fx and inst:IsDescendantOf(fx)) and not (okL and inLight) then return end
	S.fxT = S.fxT or {}
	local key = cls .. "|" .. inst.Name .. "|" .. (inst.Parent and inst.Parent.Name or "")
	local now = os.clock()
	if now - (S.fxT[key] or -HUGE) < (CFG.FxEvery or 0.5) then return end
	S.fxT[key] = now
	local col = ""
	pcall(function()
		if cls == "Highlight" then col = hex(inst.FillColor)
		elseif cls == "Decal" or cls == "Texture" then col = hex(inst.Color3)
		elseif cls == "Beam" or cls == "Trail" or cls == "ParticleEmitter" then col = hex(inst.Color.Keypoints[1].Value)
		end
	end)
	local ad = ""
	pcall(function() if cls == "Highlight" and inst.Adornee then ad = inst.Adornee.Name end end)
	local sid = ""
	pcall(function() if cls == "Sound" then sid = inst.SoundId end end)
	emit("fx", string.format('"cls":%s,"name":%s,"path":%s,"col":%s,"adornee":%s,"sid":%s', str(cls), str(inst.Name), str(parentPath(inst)), col ~= "" and col or '""', str(ad), str(sid)))
end
CFG._sampleUi = function()
	if not bonusRec() or not Workspace:FindFirstChild("Voidsbane Vytelus") then return end
	S.uiOn = S.uiOn or {}
	local pg = Players.LocalPlayer and Players.LocalPlayer:FindFirstChildOfClass("PlayerGui")
	local now = {}
	if pg then
		for _, g in pg:GetDescendants() do
			if g:IsA("TextLabel") and g.Visible and #g.Text >= 4 and #g.Text <= 40 and (string.find(g.Text, "!", 1, true) or g.Text == string.upper(g.Text)) and string.find(g.Text, "%a%a%a") then
				now[g.Text] = true
			end
		end
	end
	for t in now do
		if not S.uiOn[t] then S.uiOn[t] = true emit("ui", string.format('"text":%s,"on":true', str(t))) end
	end
	for t in S.uiOn do
		if not now[t] then S.uiOn[t] = nil emit("ui", string.format('"text":%s,"on":false', str(t))) end
	end
end
CFG._sampleTint = function()
	if not bonusRec() or not S.me.char then return end
	local head = S.me.char:FindFirstChild("Head")
	if not head then return end
	local c = hex(head.Color)
	if c ~= S.tint then S.tint = c emit("tint", '"head":' .. c) end
end
CFG._arena = function()
	if not bonusRec() or not Workspace:FindFirstChild("Voidsbane Vytelus") then return end
	S.arenaN = (S.arenaN or 0) + 1
	if S.arenaN > (CFG.ArenaScans or 8) then return end
	local c = Vector3.new(CFG.RingX or 1357, 100, CFG.RingZ or -905)
	local ok, parts = pcall(function() return Workspace:GetPartBoundsInRadius(c, 90) end)
	if not (ok and parts) then return end
	local out = {}
	for _, q in parts do
		if max(q.Size.X, q.Size.Z) >= 15 and q.Size.Y <= 12 and #out < 120 and not CFG._noisy(q.Name, parentPath(q)) then
			local nd = 0
			for _, k in q:GetChildren() do if k:IsA("Decal") or k:IsA("Texture") or k:IsA("SurfaceGui") then nd += 1 end end
			out[#out + 1] = string.format("[%s,%s,%s,%s,%s,%s,%d]", str(q.Name), str(parentPath(q)), vec(q.Position), vec(q.Size), hex(q.Color), num(q.Transparency), nd)
			S.arenaParts = S.arenaParts or {}
			if #S.arenaParts < 40 then S.arenaParts[#S.arenaParts + 1] = q end
		end
	end
	emit("arena", '"l":[' .. table.concat(out, ",") .. "]")
end
-- AurRecorder 1.9.4: everything else a recording can hold (bonus labels, Voidsbane up)
CFG._vbUp = function()
	return bonusRec() and Workspace:FindFirstChild("Voidsbane Vytelus") or nil
end
CFG._jsonVal = function(v)
	local t = typeof(v)
	if t == "number" then return num(v, "%.3f")
	elseif t == "boolean" then return tostring(v)
	elseif t == "Vector3" then return vec(v)
	elseif t == "Color3" then return hex(v)
	end
	return str(tostring(v))
end
CFG._attrs = function(inst)
	local out = {}
	local ok, a = pcall(function() return inst:GetAttributes() end)
	if ok and a then
		for k, v in a do out[#out + 1] = str(k) .. ":" .. CFG._jsonVal(v) end
	end
	table.sort(out)
	return "{" .. table.concat(out, ",") .. "}"
end
CFG._snapTick = function()
	if not CFG._vbUp() then return end
	local root = S.me.root
	if not (root and root.Parent) then return end
	local p = root.Position
	local ok, parts = pcall(function() return Workspace:GetPartBoundsInRadius(p, CFG.SnapR or 30) end)
	if not (ok and parts) then parts = {} end
	local fx = Workspace:FindFirstChild("voidsbaneV3Effects")
	if fx then
		for _, x in fx:GetDescendants() do
			if x:IsA("BasePart") and hdist(x.Position, p) <= (CFG.SnapR or 30) + max(x.Size.X, x.Size.Z) then parts[#parts + 1] = x end
		end
	end
	local list, dupe = {}, {}
	for _, q in parts do
		local m = q:FindFirstAncestorOfClass("Model")
		local first = not dupe[q]
		dupe[q] = true
		if first and not q.CanCollide and q.Position.Y > -1000 and not (m and Players:GetPlayerFromCharacter(m)) and not CFG._noisy(q.Name, parentPath(q)) then
			list[#list + 1] = { q, footprintDist(q.CFrame, q.Size, p) }
		end
	end
	table.sort(list, function(a, b) return a[2] < b[2] end)
	local out = {}
	for i = 1, min(#list, 20) do
		out[i] = string.format("[%s,%s,%s]", str(list[i][1].Name), str(list[i][1].Parent and list[i][1].Parent.Name or ""), num(list[i][2], "%.1f"))
	end
	S.snapBuf = S.snapBuf or {}
	table.insert(S.snapBuf, string.format('[%s,[%s]]', num(os.clock() - S.t0, "%.2f"), table.concat(out, ",")))
	if #S.snapBuf > 10 then table.remove(S.snapBuf, 1) end
end
CFG._charWatch = function()
	if not CFG._vbUp() then return end
	local c = S.me.char
	if not c then S.ccSeen = nil return end
	local now = {}
	for _, k in c:GetChildren() do
		if not k:IsA("Accessory") and not k:IsA("BasePart") and not k:IsA("Tool") then now[k.ClassName .. ":" .. k.Name] = true end
	end
	local attrs = CFG._attrs(c)
	local hum = S.me.hum
	local state = hum and tostring(hum:GetState()) or ""
	local was = S.ccSeen
	if was and was.c == c then
		for k in now do if not was.now[k] then emit("cc", string.format('"add":%s', str(k))) end end
		for k in was.now do if not now[k] then emit("cc", string.format('"del":%s', str(k))) end end
		if attrs ~= was.attrs then emit("cc", '"attrs":' .. attrs) end
		if state ~= was.state then emit("cc", '"state":' .. str(state)) end
	end
	S.ccSeen = { c = c, now = now, attrs = attrs, state = state }
end
CFG._bossWatch = function()
	local vb = CFG._vbUp()
	if not vb then return end
	local h = vb:FindFirstChildOfClass("Humanoid")
	if h and h.Health ~= S.bossHp then
		local okT, st = pcall(function() return Workspace:GetServerTimeNow() end)
		emit("bh", string.format('"hp":%s,"d":%s,"st":%s', num(h.Health, "%.1f"), S.bossHp and num(h.Health - S.bossHp, "%.1f") or "null", okT and num(st, "%.3f") or "null"))
		S.bossHp = h.Health
	end
	local vals = {}
	for _, k in vb:GetChildren() do
		if k:IsA("ValueBase") then vals[#vals + 1] = str(k.Name) .. ":" .. CFG._jsonVal(k.Value) end
	end
	table.sort(vals)
	local sig = table.concat(vals, ",") .. CFG._attrs(vb)
	if sig ~= S.bossSig then S.bossSig = sig emit("bv", '"v":' .. str(sig)) end
end
CFG._worldWatch = function()
	if not CFG._vbUp() then return end
	local vals = {}
	for _, k in Workspace:GetChildren() do
		if k:IsA("ValueBase") then vals[#vals + 1] = str(k.Name) .. ":" .. CFG._jsonVal(k.Value) end
	end
	table.sort(vals)
	local sig = table.concat(vals, ",")
	if sig ~= S.worldSig then S.worldSig = sig emit("wv", '"v":' .. str(sig)) end
end
CFG._walls = function()
	if not CFG._vbUp() then return end
	local root = S.me.root
	if not (root and root.Parent) then return end
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	local skip = {}
	for _, pl in Players:GetPlayers() do if pl.Character then skip[#skip + 1] = pl.Character end end
	local fx = Workspace:FindFirstChild("voidsbaneV3Effects")
	if fx then skip[#skip + 1] = fx end
	params.FilterDescendantsInstances = skip
	local o, out = root.Position, {}
	for k = 0, 35 do
		local a = k * math.pi / 18
		local hit = Workspace:Raycast(o, Vector3.new(math.cos(a) * 240, 0, math.sin(a) * 240), params)
		out[k + 1] = hit and string.format("%.0f", hit.Distance) or "null"
	end
	emit("wall", string.format('"pos":%s,"d":[%s]', vec(o), table.concat(out, ",")))
end
CFG._arenaWatch = function()
	if not CFG._vbUp() or not S.arenaParts then return end
	S.arenaSig = S.arenaSig or {}
	for _, q in S.arenaParts do
		if q.Parent then
			local sig = hex(q.Color) .. num(q.Transparency)
			for _, k in q:GetChildren() do
				if k:IsA("Decal") or k:IsA("Texture") then sig = sig .. hex(k.Color3) .. num(k.Transparency) end
			end
			if S.arenaSig[q] and S.arenaSig[q] ~= sig then
				emit("arc", string.format('"name":%s,"pos":%s,"sig":%s', str(q.Name), vec(q.Position), str(sig)))
			end
			S.arenaSig[q] = sig
		end
	end
end
CFG._net = function()
	if not CFG._vbUp() then return end
	local okP, ping = pcall(function() return game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue() end)
	emit("net", '"ping":' .. (okP and num(ping, "%.0f") or "null"))
end
CFG._cap = function() return bonusRec() and (CFG.BonusMaxTracked or 1000) or CFG.MaxTracked end
CFG._samplePool = function()
	local fx = Workspace:FindFirstChild("voidsbaneV3Effects")
	local pool = fx and fx:FindFirstChild("pool")
	if not pool then return end
	local cx, cz = CFG.RingX or 1357, CFG.RingZ or -905
	local rings = {}
	for _, p in pool:GetChildren() do
		if p:IsA("BasePart") and p.Position.Y > -1000 then
			local dx, dz = p.Position.X - cx, p.Position.Z - cz
			local key = floor(math.sqrt(dx * dx + dz * dz) / 6)
			local ring = rings[key]
			if not ring then
				ring = { n = 0, r = 0, bins = {}, col = hex(p.Color) }
				rings[key] = ring
			end
			ring.n += 1
			ring.r += math.sqrt(dx * dx + dz * dz)
			ring.bins[floor(((math.deg(math.atan2(dz, dx)) + 360) % 360) / 10)] = true
		end
	end
	local out = {}
	for _, ring in rings do
		local t = table.create(36)
		for i = 0, 35 do t[i + 1] = ring.bins[i] and "#" or "." end
		out[#out + 1] = string.format('[%.1f,%d,"%s",%s]', ring.r / ring.n, ring.n, table.concat(t), ring.col)
	end
	if #out > 0 then
		-- 1.9.4: the same parts by colour, with their extent (the bars use this pool as well)
		local byCol = {}
		for _, p in pool:GetChildren() do
			if p:IsA("BasePart") and p.Position.Y > -1000 then
				local c = hex(p.Color)
				local g = byCol[c]
				if not g then g = { n = 0, x0 = HUGE, x1 = -HUGE, z0 = HUGE, z1 = -HUGE } byCol[c] = g end
				g.n += 1
				g.x0, g.x1, g.z0, g.z1 = min(g.x0, p.Position.X), max(g.x1, p.Position.X), min(g.z0, p.Position.Z), max(g.z1, p.Position.Z)
			end
		end
		local cols = {}
		for c, g in byCol do cols[#cols + 1] = string.format("[%s,%d,%.0f,%.0f,%.0f,%.0f]", c, g.n, g.x0, g.x1, g.z0, g.z1) end
		emit("pool", '"rings":[' .. table.concat(out, ",") .. '],"cols":[' .. table.concat(cols, ",") .. "]")
	end
end
CFG._sampleHighlights = function()
	S.hl = S.hl or {}
	for _, pl in Players:GetPlayers() do
		local c = pl.Character
		local h = c and c:FindFirstChildWhichIsA("Highlight", true)
		if not h and c then
			for _, w in Workspace:GetChildren() do
				if w:IsA("Highlight") and w.Adornee == c then h = w break end
			end
		end
		local was = S.hl[pl.Name]
		if (h ~= nil) ~= (was == true) then
			S.hl[pl.Name] = h ~= nil
			emit("hl", string.format('"name":%s,"on":%s,"inst":%s,"fill":%s', str(pl.Name), tostring(h ~= nil),
				str(h and h.Name or ""), h and hex(h.FillColor) or '""'))
		end
	end
end

local function sampleHazards(now)
	local root = S.me.root
	local rp = root and root.Parent and root.Position
	local moved, changes = {}, {}
	for inst, rec in S.tracked do
		if inst.Parent == nil then
			endHazard(inst, rec, "removed", now)
		else
			local cf = inst.CFrame
			local p = cf.Position
			if (p - rec.pos).Magnitude > 0.05 then
				rec.pos = p
				moved[#moved + 1] = string.format("[%d,%s,%s,%s]", rec.id, num(p.X), num(p.Y), num(p.Z))
			end
			local s = inst.Size
			if (s - rec.size).Magnitude > 0.05 then
				rec.size = s
				changes[#changes + 1] = string.format('[%d,"s",%s,%s,%s]', rec.id, num(s.X), num(s.Y), num(s.Z))
			end
			local tr = inst.Transparency
			if abs(tr - rec.tr) > 0.04 then
				rec.tr = tr
				changes[#changes + 1] = string.format('[%d,"tr",%s]', rec.id, num(tr))
			end
			local c, o = inst.Color, rec.col
			if abs(c.R - o.R) + abs(c.G - o.G) + abs(c.B - o.B) > 0.03 then
				rec.col = c
				changes[#changes + 1] = string.format('[%d,"col",%s]', rec.id, hex(c))
			end
			local ax, ay = cf.XVector, cf.YVector
			if ax:Dot(rec.ax) < 0.9995 or ay:Dot(rec.ay) < 0.9995 then
				rec.ax, rec.ay = ax, ay
				changes[#changes + 1] = string.format('[%d,"rot",%s,%s]', rec.id, vec(ax, "%.3f"), vec(ay, "%.3f"))
			end
			if now - rec.addT > CFG.MaxTrackTime then
				endHazard(inst, rec, "max_track_time", now)
			elseif rp and not rec.always and footprintDist(cf, s, rp) > untrackRange() then
				endHazard(inst, rec, "out_of_range", now)
			end
		end
	end
	if #moved > 0 or #changes > 0 then
		emit("h", '"m":[' .. table.concat(moved, ",") .. '],"c":[' .. table.concat(changes, ",") .. "]")
	end
end

--------------------------------------------------------------------------------
-- Spell and buff signals: ability Tools (Backpack / character) with a cooldown value, and value objects /
-- attributes on your character, Humanoid and player. Small containers only.
--------------------------------------------------------------------------------
local function onCooldown(a, v)
	local prev = a.prev
	a.prev = v
	if type(v) ~= "number" or type(prev) ~= "number" then return end
	if v > prev + 0.01 then
		local act = prev <= 0
		if act then S.stats.casts += 1 end
		emit("cd", string.format('"slot":%s,"name":%s,"from":%s,"to":%s,"est_activation":%s', str(a.slot), str(a.name), num(prev), num(v), tostring(act)))
	elseif prev > 0 and v <= 0 then
		emit("cd", string.format('"slot":%s,"name":%s,"ready":true', str(a.slot), str(a.name)))
	end
end

local function scanAbilities()
	local abilities = S.abilities
	for i = 1, 2 do
		local holder = i == 1 and LocalPlayer:FindFirstChild("Backpack") or S.me.char
		if holder then
			for _, tool in holder:GetChildren() do
				local cd = tool:IsA("Tool") and tool:FindFirstChild("cooldown")
				if cd and cd:IsA("ValueBase") and type(cd.Value) == "number" and not abilities[cd] then
					local slot = tool:FindFirstChild("abilitySlot")
					local a = { slot = (slot and slot:IsA("ValueBase") and type(slot.Value) == "string") and slot.Value or "?", name = tool.Name, prev = cd.Value }
					abilities[cd] = a
					a.conn = cd.Changed:Connect(function(v) guard("cooldown", onCooldown, a, v) end)
					emit("ab", string.format('"slot":%s,"name":%s,"cd":%s,"buffPower":%s', str(a.slot), str(a.name), num(cd.Value), tostring(tool:FindFirstChild("buffPower") ~= nil)))
				end
			end
		end
	end
	for cd, a in abilities do
		if cd.Parent == nil or cd.Parent.Parent == nil then
			pcall(a.conn.Disconnect, a.conn)
			abilities[cd] = nil
		end
	end
end

local function valueText(v)
	local t = typeof and typeof(v) or type(v)
	if t == "number" then return num(v, "%.4g") end
	if t == "boolean" or t == "nil" then return tostring(v) end
	if t == "Instance" then return str(v.Name) end
	return str(string.sub(tostring(v), 1, 60))
end

local function statusScan()
	local status, statusCount, stats = S.status, S.statusCount, S.stats
	local seen = {}
	local function note(key, text)
		seen[key] = true
		local old = status[key]
		if old == text then return end
		status[key] = text
		local n = (statusCount[key] or 0) + 1
		statusCount[key] = n
		if n <= CFG.MaxStatusPerKey and stats.status < CFG.MaxStatusRows then
			stats.status += 1
			emit("st", string.format('"key":%s,"ev":%s,"v":%s', str(key), str(old == nil and "add" or "set"), text))
		end
	end
	local function visit(owner, obj)
		if obj == nil then return end
		for _, c in obj:GetChildren() do
			if c:IsA("ValueBase") then
				local ok, v = pcall(function() return c.Value end)
				note(owner .. "." .. c.Name, ok and valueText(v) or '"?"')
			elseif c:IsA("ForceField") then
				note(owner .. "." .. c.Name, "true")
			end
		end
		local ok, attrs = pcall(obj.GetAttributes, obj)
		if ok and type(attrs) == "table" then
			for n, v in attrs do note(owner .. "@" .. n, valueText(v)) end
		end
	end
	visit("char", S.me.char)
	visit("hum", S.me.hum)
	visit("player", LocalPlayer)
	for key in status do
		if not seen[key] then
			status[key] = nil
			if stats.status < CFG.MaxStatusRows then
				stats.status += 1
				emit("st", string.format('"key":%s,"ev":"del"', str(key)))
			end
		end
	end
end

--------------------------------------------------------------------------------
-- Our own controller (mode BossNav only): exact state from BossNav, emitted when it changes
--------------------------------------------------------------------------------
local function sampleBossNav()
	local bn = rawget(_G, "BossNav")
	if type(bn) ~= "table" or type(bn.GetDiagnostics) ~= "function" then
		if S.lastBn ~= "absent" then
			S.lastBn = "absent"
			emit("bn", '"running":false')
		end
		return
	end
	local ok, d = pcall(bn.GetDiagnostics, bn)
	if not ok or type(d) ~= "table" then return end
	local sig = table.concat({ tostring(d.decision), tostring(d.active), tostring(d.goal), tostring(d.spellState), num(d.speed, "%.1f"), tostring(d.attacks) }, "|")
	if sig == S.lastBn then return end
	S.lastBn = sig
	emit("bn", string.format('"running":true,"decision":%s,"active":%s,"goal":%s,"spell":%s,"speed":%s,"attacks":%s,"hazards":%s',
		str(d.decision), str(d.active), str(d.goal), str(d.spellState), num(d.speed), num(d.attacks, "%d"), num(d.hazards, "%d")))
end

-- v5: Aur_Hub's state (mode Aur_Hub only), read from _G.Aur_Hub.context, emitted when it changes
local function sampleAurHub()
	local ah = rawget(_G, "Aur_Hub")
	local ctx = type(ah) == "table" and ah.context or nil
	local rt = type(ctx) == "table" and ctx.RT or nil
	if type(rt) ~= "table" or rt.destroyed then
		if S.lastAh ~= "absent" then
			S.lastAh = "absent"
			emit("ah", '"running":false')
		end
		return
	end
	local dg, bb = type(ctx.DG) == "table" and ctx.DG or {}, type(ctx.BB) == "table" and ctx.BB or {}
	local state = tostring(rt.movementState or "")
	local sig = table.concat({ state, tostring(rt.farmEnabled), tostring(bb.lethal), num(dg.dangerHere, "%.2f") }, "|")
	if sig == S.lastAh then return end
	S.lastAh = sig
	emit("ah", string.format('"running":true,"farm":%s,"state":%s,"ping_ms":%s,"tick_ms":%s,"danger_here":%s,"lethal":%s',
		tostring(rt.farmEnabled == true), str(string.sub(state, 1, 160)), num((tonumber(rt.pingS) or 0) * 1000, "%.0f"),
		num(tonumber(rt.tickMs) or 0, "%.2f"), num(tonumber(dg.dangerHere) or 0, "%.2f"), tostring(bb.lethal == true)))
end

--------------------------------------------------------------------------------
-- Panel
--------------------------------------------------------------------------------
local C = {
	bg = Color3.fromRGB(22, 24, 30), bar = Color3.fromRGB(34, 37, 46), field = Color3.fromRGB(42, 46, 56),
	text = Color3.fromRGB(232, 234, 240), dim = Color3.fromRGB(150, 156, 170), green = Color3.fromRGB(56, 168, 98),
	red = Color3.fromRGB(190, 60, 60), off = Color3.fromRGB(70, 74, 86), rec = Color3.fromRGB(255, 90, 90),
	ok = Color3.fromRGB(110, 220, 140), warn = Color3.fromRGB(255, 170, 60), bad = Color3.fromRGB(255, 90, 90),
}

local function make(className, props, parent)
	local o = Instance.new(className)
	for k, v in props do o[k] = v end
	if parent then o.Parent = parent end
	return o
end

local function uiConnect(signal, fn) uiConns[#uiConns + 1] = signal:Connect(fn) end

local function refreshPanel()
	if not ui.gui then return end
	local now = os.clock()
	local status, color, info, folder
	if running then
		local el = now - S.t0
		status, color = string.format("RECORDING  %s  (safety limit %g min)", clock(el), CFG.MaxMinutes), C.rec
		info = string.format("%s  |  %d lines  |  hits %d  casts %d  marks %d%s", mb(S.out.bytes), S.out.lines, S.stats.hpEvents, S.stats.casts,
			S.stats.marks, S.stats.dropped > 0 and string.format("  |  DROPPED %d", S.stats.dropped) or "")
		folder = "Writing to: " .. tostring(S.out.prefix)
	elseif S and S.result then
		local r = S.result
		if r.limit then
			status, color = "STOPPED BY SAFETY LIMIT (" .. string.gsub(r.reason, "^safety limit: ", "") .. "), saved", C.warn
		elseif r.reason == "teleport" then
			status, color = "Stopped: teleport started, saved", C.warn
		else
			status, color = "Saved (" .. r.reason .. ")", C.ok
		end
		if r.failed > 0 then status, color = status .. string.format("  |  %d WRITE(S) FAILED", r.failed), C.bad end
		info = string.format("%s  |  %s  |  %d lines in %d file(s)  |  hits %d  casts %d  marks %d%s", clock(r.seconds), mb(r.bytes), r.lines,
			r.parts, S.stats.hpEvents, S.stats.casts, S.stats.marks, S.stats.dropped > 0 and string.format("  |  DROPPED %d parts", S.stats.dropped) or "")
		folder = "Folder: " .. tostring(r.prefix) .. "  (executor workspace)"
	else
		status, color = "Idle: nothing is being recorded", C.dim
		info = "Press Start Recording before the first room (inside the dungeon server)."
		folder = "Files go to: " .. CFG.Folder .. "/<date-time>-<label>/  (executor workspace)"
	end
	if message then info = message end
	ui.status.Text, ui.status.TextColor3 = status, color
	ui.info.Text, ui.folder.Text = info, folder
	ui.start.BackgroundColor3 = running and C.off or C.green
	ui.stop.BackgroundColor3 = running and C.red or C.off
	ui.mark.BackgroundColor3 = running and C.bar or C.off
	ui.mode.Text = pick.controller == "bossnav" and "Mode: BossNav (comparison)"
		or pick.controller == "aurhub" and "Mode: Aur_Hub (comparison)"
		or "Mode: Ethos (our controller off)"
	ui.mode.BackgroundColor3 = running and C.off or C.field
	ui.label.TextEditable = not running
	if not ui.label:IsFocused() then ui.label.Text = pick.label end
end

local startRecording, stopRecording, destroyAll -- defined below
local fmSaveRef -- 1.6.0: the floor map's save (defined with the sensor)

local function createPanel()
	local pg = LocalPlayer:FindFirstChildOfClass("PlayerGui")
	if pg == nil then return false end
	local old = pg:FindFirstChild("FightRecorderUI")
	if old then old:Destroy() end
	local gui = make("ScreenGui", { Name = "FightRecorderUI", ResetOnSpawn = false, DisplayOrder = 60 })
	local main = make("Frame", { Name = "Panel", Size = UDim2.fromOffset(360, 196), Position = UDim2.new(1, -380, 0, 70),
		BackgroundColor3 = C.bg, BorderSizePixel = 0 }, gui)
	make("UICorner", { CornerRadius = UDim.new(0, 8) }, main)
	local bar = make("Frame", { Name = "Bar", Size = UDim2.new(1, 0, 0, 28), BackgroundColor3 = C.bar, BorderSizePixel = 0 }, main)
	make("UICorner", { CornerRadius = UDim.new(0, 8) }, bar)
	make("TextLabel", { Size = UDim2.new(1, -40, 1, 0), Position = UDim2.fromOffset(10, 0), BackgroundTransparency = 1,
		Text = "FightRecorder v6 (read-only)", TextColor3 = C.text, Font = Enum.Font.GothamBold, TextSize = 13,
		TextXAlignment = Enum.TextXAlignment.Left }, bar)
	local close = make("TextButton", { Name = "Close", Size = UDim2.fromOffset(24, 20), Position = UDim2.new(1, -28, 0, 4), Text = "X",
		BackgroundColor3 = C.off, BorderSizePixel = 0, TextColor3 = C.text, Font = Enum.Font.GothamBold, TextSize = 12 }, bar)
	local function label(name, y, h, size)
		return make("TextLabel", { Name = name, Size = UDim2.new(1, -20, 0, h), Position = UDim2.fromOffset(10, y), BackgroundTransparency = 1,
			Text = "", TextColor3 = C.dim, Font = Enum.Font.Code, TextSize = size, TextWrapped = true,
			TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top }, main)
	end
	ui.status = label("Status", 34, 18, 14)
	ui.info = label("Info", 54, 30, 12)
	ui.folder = label("Folder", 86, 30, 11)
	ui.mode = make("TextButton", { Name = "Mode", Size = UDim2.fromOffset(210, 24), Position = UDim2.fromOffset(10, 120),
		BackgroundColor3 = C.field, BorderSizePixel = 0, TextColor3 = C.text, Font = Enum.Font.Gotham, TextSize = 12, Text = "" }, main)
	ui.label = make("TextBox", { Name = "Label", Size = UDim2.fromOffset(120, 24), Position = UDim2.fromOffset(230, 120),
		BackgroundColor3 = C.field, BorderSizePixel = 0, TextColor3 = C.text, Font = Enum.Font.Code, TextSize = 12,
		ClearTextOnFocus = false, PlaceholderText = "label", Text = pick.label }, main)
	local function button(name, text, x, w)
		local b = make("TextButton", { Name = name, Size = UDim2.fromOffset(w, 30), Position = UDim2.fromOffset(x, 154), Text = text,
			BackgroundColor3 = C.off, BorderSizePixel = 0, TextColor3 = Color3.new(1, 1, 1), Font = Enum.Font.GothamBold, TextSize = 13 }, main)
		make("UICorner", { CornerRadius = UDim.new(0, 5) }, b)
		return b
	end
	ui.start = button("Start", "Start Recording", 10, 140)
	ui.stop = button("Stop", "Stop Recording", 156, 130)
	ui.mark = button("Mark", "Mark", 292, 58)
	ui.gui = gui
	uiConnect(ui.start.Activated, function()
		if not running then startRecording() end
	end)
	uiConnect(ui.stop.Activated, function()
		if running then stopRecording("stop button") end
	end)
	uiConnect(ui.mark.Activated, function() API.Mark("button") end)
	uiConnect(ui.mode.Activated, function()
		if running then return end
		pick.controller = pick.controller == "ethos" and "bossnav" or pick.controller == "bossnav" and "aurhub" or "ethos"
		message = nil
		refreshPanel()
	end)
	uiConnect(ui.label.FocusLost, function()
		if not running then
			local t = string.match(ui.label.Text, "^%s*(.-)%s*$")
			if t ~= "" then pick.label = string.sub(t, 1, 40) end
		end
		refreshPanel()
	end)
	uiConnect(close.Activated, function() destroyAll("panel closed") end)
	local dragging, dragStart, startPos = false, nil, nil
	uiConnect(bar.InputBegan, function(input)
		local t = input.UserInputType
		if t == Enum.UserInputType.MouseButton1 or t == Enum.UserInputType.Touch then
			dragging, dragStart, startPos = true, input.Position, main.Position
		end
	end)
	uiConnect(UserInputService.InputChanged, function(input)
		local t = input.UserInputType
		if dragging and (t == Enum.UserInputType.MouseMovement or t == Enum.UserInputType.Touch) then
			local delta = input.Position - dragStart
			main.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
		end
	end)
	uiConnect(UserInputService.InputEnded, function(input)
		local t = input.UserInputType
		if t == Enum.UserInputType.MouseButton1 or t == Enum.UserInputType.Touch then dragging = false end
	end)
	gui.Parent = pg
	refreshPanel()
	return true
end

--------------------------------------------------------------------------------
-- Recording
--------------------------------------------------------------------------------
local function summaryTable(now)
	local top = {}
	for k, c in S.tally do top[#top + 1] = { k = k, c = c } end
	table.sort(top, function(a, b) return a.c > b.c end)
	local tallyList = {}
	for i = 1, min(#top, 60) do tallyList[i] = { top[i].k, top[i].c } end
	local stats, out = S.stats, S.out
	return {
		version = API.Version, label = tostring(S.label), controller = tostring(S.controller), reason = S.stopReason,
		safetyLimit = S.limit ~= nil, seconds = floor((now - S.t0) * 1000) / 1000, lines = out.lines, bytes = out.bytes,
		parts = out.part, failedWrites = out.failed, files = out.files, hazardsTracked = S.nextHazard, enemiesKnown = S.nextEnemy,
		hpEvents = stats.hpEvents, hpLost = stats.hpLost, estCasts = stats.casts, logLines = stats.logs, logLinesDropped = stats.logsDropped,
		marks = stats.marks, droppedHazards = stats.dropped, logRepeats = stats.logRepeats, fps = stats.dtSum > 0 and floor(stats.frames / stats.dtSum * 10) / 10 or 0,
		frameMaxMs = floor(stats.dtMax * 10000) / 10, recorderAvgMs = stats.costN > 0 and floor(stats.cost / stats.costN * 10000) / 10 or 0,
		recorderMaxMs = floor(stats.costMax * 10000) / 10, prescanMs = stats.prescanMs, maxMinutes = CFG.MaxMinutes, maxMB = CFG.MaxMB,
		notTracked = tallyList,
	}
end

-- D-091: summary.json while recording too (a teleport can end the script before the stop writes it)
local function partialSummary(now)
	local ok, sum = pcall(summaryTable, now)
	if not ok or type(sum) ~= "table" then return end
	sum.partial = true
	local out = S.out
	sum.files, sum.lines, sum.bytes, sum.parts = out.files, out.lines, out.bytes, out.part
	local okE, body = pcall(HttpService.JSONEncode, HttpService, sum)
	if okE then pcall(writefile, out.prefix .. "summary.json", body) end
end

-- Repeated console lines: how many more times each was printed since the last report.
local function reportRepeats()
	for _, e in S.logSeen do
		if e.n > e.reported then
			emit("log_repeat", string.format('"count":%d,"total":%d,"msg":%s', e.n - e.reported, e.n, str(string.sub(e.text, 1, 120))))
			e.reported = e.n
		end
	end
end

function stopRecording(reason)
	if not running then return end
	running = false
	if fmSaveRef then pcall(fmSaveRef, true) end -- 1.6.0: the floor map
	S.stopReason = S.stopReason or reason
	local now = os.clock()
	for _, c in S.conns do pcall(c.Disconnect, c) end
	table.clear(S.conns)
	unbindCharacter()
	for _, a in S.abilities do pcall(a.conn.Disconnect, a.conn) end
	table.clear(S.abilities)
	local sum = summaryTable(now)
	local parts = {}
	for _, e in sum.notTracked do parts[#parts + 1] = string.format("[%s,%d]", str(e[1]), e[2]) end
	reportRepeats()
	emit("tally", '"not_tracked":[' .. table.concat(parts, ",") .. "]")
	emit("stop", string.format('"why":%s,"safety_limit":%s,"seconds":%s,"lines":%d,"hazards":%d,"hp_events":%d,"est_casts":%d,"dropped":%d,"log_repeats":%d',
		str(S.stopReason), tostring(S.limit ~= nil), num(now - S.t0, "%.1f"), S.out.lines, S.nextHazard, S.stats.hpEvents, S.stats.casts,
		S.stats.dropped, S.stats.logRepeats))
	flush()
	S.open = false
	local out = S.out
	sum.files, sum.lines, sum.bytes, sum.parts, sum.failedWrites = out.files, out.lines, out.bytes, out.part, out.failed
	local ok, body = pcall(HttpService.JSONEncode, HttpService, sum)
	if not (ok and pcall(writefile, out.prefix .. "summary.json", body)) then out.failed += 1 end
	table.clear(S.tracked)
	S.pending = {}
	table.clear(S.mobs)
	S.endT = now
	S.result = { reason = S.stopReason, limit = S.limit, seconds = now - S.t0, lines = out.lines, bytes = out.bytes, parts = out.part,
		failed = out.failed, prefix = out.prefix }
	print(string.format("[FR] %s after %s: %d lines (%s) in %d file(s) at %s%s",
		S.limit and ("STOPPED BY SAFETY LIMIT (" .. string.gsub(S.stopReason, "^safety limit: ", "") .. ")") or ("stopped (" .. S.stopReason .. ")"),
		clock(now - S.t0), out.lines, mb(out.bytes), out.part, tostring(out.prefix),
		out.failed > 0 and string.format(" | %d write(s) FAILED", out.failed) or ""))
	refreshPanel()
end

-- The interval has passed (4 ms early counts: 3 frames at 60 fps add up to 0.0499 s, not 0.05).
local function due(key, interval, now)
	local last = S.last
	if now - (last[key] or -HUGE) < interval - 0.004 then return false end
	last[key] = now
	return true
end

-- AurRecorder 1.6.0: the floor map sensor. Rays straight down on a 2-stud grid round the character find the floor it can
-- stand on at its own level (solid, facing up, within a step of its feet); every floor edge is then narrowed to a
-- quarter stud between the two cells. The map is kept per dungeon in Aur_Hub/data/floormap_<dungeon>.json and grows
-- across runs; a revisited cell is measured again and corrected. Shared live (getgenv().AurFloorMap) for the minimap.
local FM = { data = nil, key = nil, dirty = false, saveAt = 0, centre = nil, cursor = 1, offsets = nil,
	revisit = 1, refineAt = 1, params = nil, paramsAt = -math.huge, loadTried = {},
	touched = {}, touchedX = {} } -- D-078: the cells / edge points this account measured (merged into the shared file)

local function fmKey()
	local v = Workspace:FindFirstChild("dungeonName")
	local name = v and tostring(v.Value) or ""
	name = string.lower((name:gsub("%s", "")))
	return name ~= "" and name or nil
end

local function fmPath(key) return "Aur_Hub/data/floormap_" .. key .. ".json" end
local function fmWho() -- D-078: this account, for its own working file
	local okN, who = pcall(function() return game:GetService("Players").LocalPlayer.Name end)
	return (okN and type(who) == "string" and who ~= "") and string.gsub(who, "[^%w_%-]", "_") or "player"
end
local function fmMine(key) return "Aur_Hub/data/floormap_" .. key .. "." .. fmWho() .. ".json" end
local function fmLock(key) return "Aur_Hub/data/floormap_" .. key .. ".lock" end
local function fmApply(d, part) -- D-078: a working file's cells over the map (and remembered as ours to merge)
	for k, v in pairs(type(part.floor) == "table" and part.floor or {}) do
		d.floor[k], d.none[k] = v, nil
		FM.touched[k] = true
	end
	for k in pairs(type(part.none) == "table" and part.none or {}) do
		d.none[k], d.floor[k] = true, nil
		FM.touched[k] = true
	end
	for k, v in pairs(type(part.cross) == "table" and part.cross or {}) do
		d.cross[k] = v ~= false and v or nil
		FM.touchedX[k] = true
	end
	for k in pairs(type(part.gone) == "table" and part.gone or {}) do -- cells measured again and cleared
		d.floor[k], d.none[k] = nil, nil
		FM.touched[k] = true
	end
end

local function fmShare()
	local env = (type(getgenv) == "function" and getgenv()) or _G
	env.AurFloorMap = FM.data
end

local function fmLoad(key)
	FM.key = key
	FM.data = { v = 1, g = CFG.FloorGrid, key = key, floor = {}, none = {}, cross = {}, version = 0 }
	if type(readfile) == "function" then
		local ok, body = pcall(readfile, fmPath(key))
		if ok and type(body) == "string" and #body > 2 then
			local ok2, t = pcall(HttpService.JSONDecode, HttpService, body)
			if ok2 and type(t) == "table" and t.g == CFG.FloorGrid then
				FM.data.floor = type(t.floor) == "table" and t.floor or {}
				FM.data.none = type(t.none) == "table" and t.none or {}
				FM.data.cross = type(t.cross) == "table" and t.cross or {}
			end
		end
	end
	-- D-078: working files left by any account (a teleport or a crash before its merge) are taken in
	pcall(function()
		if type(listfiles) ~= "function" then return end
		local prefix = "floormap_" .. key .. "."
		for _, f in ipairs(listfiles("Aur_Hub/data")) do
			local name = tostring(f):match("([^/\\]+)$") or ""
			if name:sub(1, #prefix) == prefix and name:sub(-5) == ".json" and name ~= "floormap_" .. key .. ".json" then
				local okR, body = pcall(readfile, "Aur_Hub/data/" .. name)
				local okD, part = false, nil
				if okR and type(body) == "string" then
					okD, part = pcall(HttpService.JSONDecode, HttpService, body)
				end
				if okD and type(part) == "table" then
					fmApply(FM.data, part)
				end
			end
		end
	end)
	FM.data.version = 1
	fmShare()
end

function fmSaveRef(force) -- forward-declared: stopRecording saves through it
	if not (FM.data and FM.key and type(writefile) == "function") then return end
	if not FM.dirty and not force then return end
	FM.dirty = false
	local d = FM.data
	pcall(function()
		if type(isfolder) == "function" and type(makefolder) == "function" then
			if not isfolder("Aur_Hub") then makefolder("Aur_Hub") end
			if not isfolder("Aur_Hub/data") then makefolder("Aur_Hub/data") end
		end
	end)
	-- D-078: only what this account measured, to its own working file (several accounts never overwrite each other)
	local part = { v = 1, g = d.g, key = d.key, floor = {}, none = {}, cross = {}, gone = {} }
	for k in pairs(FM.touched) do
		if d.floor[k] ~= nil then part.floor[k] = d.floor[k]
		elseif d.none[k] then part.none[k] = true
		else part.gone[k] = true end
	end
	for k in pairs(FM.touchedX) do
		part.cross[k] = d.cross[k] == nil and false or d.cross[k]
	end
	local okP, partBody = pcall(HttpService.JSONEncode, HttpService, part)
	if okP then pcall(writefile, fmMine(FM.key), partBody) end
	if not force or CFG.FloorShared == false then return end
	-- at the stop: into the shared file, under a short lock, the shared file read again first (others' cells stay)
	local lock = fmLock(FM.key)
	local waited = 0
	while waited < 6 do
		local okL, held = pcall(function()
			if not isfile(lock) then return false end
			local t = tonumber((readfile(lock) or ""):match("^(%d+)"))
			return t ~= nil and os.time() - t < 10
		end)
		if not (okL and held) then break end
		task.wait(0.25)
		waited += 0.25
	end
	pcall(writefile, lock, tostring(os.time()) .. " " .. fmWho())
	local shared = { floor = {}, none = {}, cross = {} }
	local okR, body = pcall(readfile, fmPath(FM.key))
	local readOk = not okR or type(body) ~= "string" or #body <= 2 -- no shared file yet: start one
	if okR and type(body) == "string" and #body > 2 then
		local okD, t = pcall(HttpService.JSONDecode, HttpService, body)
		if okD and type(t) == "table" and t.g == CFG.FloorGrid then
			shared.floor = type(t.floor) == "table" and t.floor or {}
			shared.none = type(t.none) == "table" and t.none or {}
			shared.cross = type(t.cross) == "table" and t.cross or {}
			readOk = true
		end
	end
	if readOk then -- (a shared file that could not be read is left alone; the working file keeps our cells)
		for k, v in pairs(part.floor) do shared.floor[k], shared.none[k] = v, nil end
		for k in pairs(part.none) do shared.none[k], shared.floor[k] = true, nil end
		for k in pairs(part.gone) do shared.floor[k], shared.none[k] = nil, nil end
		for k, v in pairs(part.cross) do shared.cross[k] = v ~= false and v or nil end
		local ok, out = pcall(HttpService.JSONEncode, HttpService, { v = 1, g = d.g, key = d.key, floor = shared.floor, none = shared.none, cross = shared.cross })
		if ok and pcall(writefile, fmPath(FM.key), out) then
			if type(delfile) == "function" then pcall(delfile, fmMine(FM.key)) end
			FM.touched, FM.touchedX = {}, {}
		end
	end
	if type(delfile) == "function" then pcall(delfile, lock) end
end

local function fmParams(now)
	if FM.params and now - FM.paramsAt < 5 then return FM.params end
	local ex = {}
	for _, pl in Players:GetPlayers() do
		if pl.Character then ex[#ex + 1] = pl.Character end
	end
	local dungeon = Workspace:FindFirstChild("dungeon")
	if dungeon then
		for _, room in dungeon:GetChildren() do
			local ef = room:FindFirstChild("enemyFolder")
			if ef then ex[#ex + 1] = ef end
		end
	end
	local p = RaycastParams.new()
	p.FilterType = Enum.RaycastFilterType.Exclude
	p.FilterDescendantsInstances = ex
	p.RespectCanCollide = true
	FM.params, FM.paramsAt = p, now
	return p
end

-- the floor at (x, z) for feet at height fy: its height, or nil (no floor at this level: an edge, a drop, a hole)
local function fmProbe(x, z, fy, params)
	local hit = Workspace:Raycast(Vector3.new(x, fy + 5, z), Vector3.new(0, -12.5, 0), params)
	if hit and hit.Normal.Y >= 0.55 and hit.Position.Y >= fy - 7 then
		return hit.Position.Y
	end
	return nil
end

local function fmOffsets()
	if FM.offsets then return FM.offsets end
	local r = math.ceil(CFG.FloorRadius / CFG.FloorGrid)
	local list = {}
	for dx = -r, r do
		for dz = -r, r do
			if dx * dx + dz * dz <= r * r then list[#list + 1] = { dx, dz, dx * dx + dz * dz } end
		end
	end
	table.sort(list, function(a, b) return a[3] < b[3] end)
	FM.offsets = list
	return list
end

local function floorTick(now)
	if not CFG.FloorMap then return end
	local root = S.me.root
	local hum = S.me.hum
	if not (root and root.Parent and hum and hum.Health > 0) then return end
	if hum.FloorMaterial == Enum.Material.Air then return end
	local key = fmKey()
	if not key then return end
	if FM.key ~= key then fmLoad(key) end
	local d, g = FM.data, CFG.FloorGrid
	local pos = root.Position
	local fy = pos.Y - (hum.HipHeight + root.Size.Y * 0.5)
	local lv = math.floor(fy / 6 + 0.5)
	local cx, cz = math.floor(pos.X / g), math.floor(pos.Z / g)
	local centre = cx .. "," .. cz .. "," .. lv
	if FM.centre ~= centre then FM.centre, FM.cursor = centre, 1 end
	local params = fmParams(now)
	local offsets = fmOffsets()
	local rays, checks, changed = 0, 0, false
	local function cellKey(ix, iz) return ix .. "," .. iz .. "," .. lv end
	local function measure(ix, iz)
		rays += 1
		local k = cellKey(ix, iz)
		local y = fmProbe((ix + 0.5) * g, (iz + 0.5) * g, fy, params)
		local cellChanged = false -- D-078
		if y then
			local old = d.floor[k]
			y = math.floor(y * 10 + 0.5) / 10
			if old ~= y then d.floor[k], changed, cellChanged = y, true, true end
			if d.none[k] then d.none[k], changed, cellChanged = nil, true, true end
		else
			if not d.none[k] then d.none[k], changed, cellChanged = true, true, true end
			if d.floor[k] then d.floor[k], changed, cellChanged = nil, true, true end
		end
		if cellChanged then FM.touched[k] = true end
		if changed then -- a corrected cell: its edge points are measured again
			d.cross[k .. ",x"], d.cross[k .. ",z"] = nil, nil
			d.cross[cellKey(ix - 1, iz) .. ",x"], d.cross[cellKey(ix, iz - 1) .. ",z"] = nil, nil
			if cellChanged then
				FM.touchedX[k .. ",x"], FM.touchedX[k .. ",z"] = true, true
				FM.touchedX[cellKey(ix - 1, iz) .. ",x"], FM.touchedX[cellKey(ix, iz - 1) .. ",z"] = true, true
			end
		end
		return y ~= nil
	end
	-- the nearest cells not yet known at this level
	while FM.cursor <= #offsets and rays < CFG.FloorRays and checks < CFG.FloorChecks do
		local o = offsets[FM.cursor]
		FM.cursor += 1
		checks += 1
		local ix, iz = cx + o[1], cz + o[2]
		local k = cellKey(ix, iz)
		if d.floor[k] == nil and d.none[k] == nil then measure(ix, iz) end
	end
	-- revisited: known cells measured again, a few per frame (a correction replaces the old value)
	for _ = 1, CFG.FloorRevisit do
		local o = offsets[FM.revisit]
		FM.revisit = FM.revisit % #offsets + 1
		if o then measure(cx + o[1], cz + o[2]) end
	end
	-- the edges: between a floor cell and a no-floor cell, where the floor ends (binary search, a quarter stud)
	local refined = 0
	for _ = 1, math.min(#offsets, CFG.FloorRefineChecks) do -- a cursor over the whole area, round and round
		if refined >= CFG.FloorRefine then break end
		local o = offsets[FM.refineAt]
		FM.refineAt = FM.refineAt % #offsets + 1
		local ix, iz = cx + o[1], cz + o[2]
		local ka = cellKey(ix, iz)
		local fa = d.floor[ka] ~= nil
		if fa or d.none[ka] then
			for _, dir in { { 1, 0, "x" }, { 0, 1, "z" } } do
				local kb = cellKey(ix + dir[1], iz + dir[2])
				local fb = d.floor[kb] ~= nil
				local ck = ka .. "," .. dir[3]
				if (fb or d.none[kb]) and fa ~= fb and d.cross[ck] == nil and refined < CFG.FloorRefine then
					refined += 1
					local lo, hi = 0, 1 -- fraction from cell A's centre toward cell B's
					local ax, az = (ix + 0.5) * g, (iz + 0.5) * g
					for _ = 1, 3 do
						local mid = (lo + hi) / 2
						local on = fmProbe(ax + dir[1] * g * mid, az + dir[2] * g * mid, fy, params) ~= nil
						rays += 1
						if on == fa then lo = mid else hi = mid end
					end
					d.cross[ck] = math.floor((lo + hi) / 2 * 100 + 0.5) / 100
					FM.touchedX[ck] = true -- D-078
					changed = true
				end
			end
		end
	end
	if changed then
		d.version = (d.version or 0) + 1
		FM.dirty = true
	end
	if now - FM.saveAt >= CFG.FloorSave then
		FM.saveAt = now
		fmSaveRef(false)
	end
end

local function tick(dt)
	local c0 = os.clock()
	if not running then return end
	if c0 - S.t0 >= CFG.MaxMinutes * 60 and S.stopReason == nil then
		S.stopReason, S.limit = "safety limit: " .. CFG.MaxMinutes .. " min", "duration"
	end
	if S.stopReason then return stopRecording(S.stopReason) end
	local stats = S.stats
	stats.frames += 1
	stats.dtSum += dt or 0
	stats.dtMax = max(stats.dtMax, dt or 0)
	stats.winFrames, stats.winDt = (stats.winFrames or 0) + 1, (stats.winDt or 0) + (dt or 0) -- 1.9.8: this second alone (fps and frame_max_ms cover the whole recording)
	stats.winMax = max(stats.winMax or 0, dt or 0)
	bindCharacter()
	processPending()
	if due("p", CFG.PlayerInterval, c0) then samplePlayer(c0) end
	if due("e", CFG.EnemyInterval, c0) then
		sampleEnemies()
		if S.controller == "bossnav" then sampleBossNav() elseif S.controller == "aurhub" then sampleAurHub() end
	end
	if due("h", CFG.HazardInterval, c0) then sampleHazards(c0) end
	if due("pl", CFG.PoolInterval or 0.1, c0) then guard("pool", CFG._samplePool) end
	if due("hl", CFG.HighlightInterval or 0.1, c0) then guard("highlight", CFG._sampleHighlights) end
	if due("pp", CFG.PlayersInterval or 0.2, c0) then guard("players", CFG._samplePlayers) end
	if due("ui", CFG.UiInterval or 0.25, c0) then guard("ui", CFG._sampleUi) end
	if due("tn", CFG.TintInterval or 0.1, c0) then guard("tint", CFG._sampleTint) end
	if due("ar", CFG.ArenaInterval or 5, c0) then guard("arena", CFG._arena) end
	if due("sn", 0.1, c0) then guard("snap", CFG._snapTick) end
	if due("cc", 0.1, c0) then guard("char", CFG._charWatch) end
	if due("bw", 0.05, c0) then guard("boss", CFG._bossWatch) end
	if due("wv", 0.5, c0) then guard("world", CFG._worldWatch) end
	if due("wl", 1, c0) then guard("walls", CFG._walls) end
	if due("arc", 0.2, c0) then guard("arenaw", CFG._arenaWatch) end
	if due("net", 1, c0) then guard("net", CFG._net) end
	if due("floor", CFG.FloorInterval, c0) then guard("floor", floorTick, c0) end
	if due("s", CFG.StatusInterval, c0) then statusScan() end
	if due("a", CFG.AbilityInterval, c0) then scanAbilities() end
	if due("rep", CFG.LogRepeatInterval, c0) then reportRepeats() end
	if due("perf", CFG.PerfInterval, c0) then
		emit("perf", string.format('"fps":%s,"frame_max_ms":%s,"rec_avg_ms":%s,"rec_max_ms":%s,"tracked":%d,"win_fps":%s,"win_frame_max_ms":%s',
			stats.dtSum > 0 and num(stats.frames / stats.dtSum, "%.1f") or "null", num(stats.dtMax * 1000, "%.1f"),
			stats.costN > 0 and num(stats.cost / stats.costN * 1000, "%.3f") or "null", num(stats.costMax * 1000, "%.3f"), S.trackedCount,
			(stats.winDt or 0) > 0 and num(stats.winFrames / stats.winDt, "%.1f") or "null", num((stats.winMax or 0) * 1000, "%.1f")))
		stats.winFrames, stats.winDt, stats.winMax = 0, 0, 0
	end
	if due("flush", CFG.FlushInterval, c0) or S.out.bufBytes >= CFG.FlushBytes then flush() end
	if CFG.PartialSummaryEvery and due("psum", CFG.PartialSummaryEvery, c0) then partialSummary(c0) end -- D-091
	if due("panel", CFG.PanelInterval, c0) then refreshPanel() end
	local cost = os.clock() - c0
	stats.cost += cost
	stats.costN += 1
	stats.costMax = max(stats.costMax, cost)
end

function startRecording()
	if running or destroyed then return false end
	message = nil
	if type(writefile) ~= "function" then
		message = "This executor has no writefile: nothing can be saved."
		refreshPanel()
		return false
	end
	local controller, label = pick.controller, pick.label
	if controller == "bossnav" and type(rawget(_G, "BossNav")) ~= "table" then
		message = "BossNav is not running: execute BossNav first, or switch the mode to Ethos."
		refreshPanel()
		return false
	end
	if controller == "aurhub" and type(rawget(_G, "Aur_Hub")) ~= "table" then
		message = "Aur_Hub is not running: execute Aur_Hub first, or switch the mode."
		refreshPanel()
		return false
	end
	local switched = {}
	if controller == "ethos" then -- our own controllers must not move you during an Ethos recording
		local ah = rawget(_G, "Aur_Hub")
		if type(ah) == "table" and type(ah.destroy) == "function" then
			local ok = pcall(ah.destroy)
			switched[#switched + 1] = "Aur_Hub" .. (ok and " destroyed" or " destroy FAILED")
		end
		for _, name in { "BossNav", "NavDodge" } do
			local c = rawget(_G, name)
			if type(c) == "table" and type(c.Destroy) == "function" then
				local ok = pcall(c.Destroy, c)
				switched[#switched + 1] = name .. (ok and " destroyed" or " destroy FAILED")
			end
		end
	end
	local prefix = prepareOutput(label)
	if prefix == nil then
		message = "writefile failed: nothing was recorded."
		refreshPanel()
		return false
	end
	local okRun, errRun = pcall(function() -- D-079: a failure here is reported, not a silent README-only folder
		S = newState(label, controller)
		S.out.prefix = prefix
		S.open = true
		running = true
		local c0 = os.clock()
		local found = 0
		for _, d in Workspace:GetDescendants() do -- once per recording, to find the enemies that already exist
			if d:IsA("Humanoid") then
				considerMob(d)
				found += 1
			end
		end
		S.stats.prescanMs = floor((os.clock() - c0) * 10000) / 10
		local sw = {}
		for i, s in switched do sw[i] = str(s) end
		emit("start", string.format('"version":%d,"label":%s,"controller":%s,"date":%s,"place":%s,"switched_off":[%s],"prescan_humanoids":%d,"prescan_ms":%s,"limits":{"max_minutes":%s,"max_mb":%s},"cfg":{"player_dt":%s,"enemy_dt":%s,"hazard_dt":%s,"hazard_range":%s,"enemy_range":%s}',
			API.Version, str(label), str(controller), str(os.date("%Y-%m-%d %H:%M:%S")), str(game.PlaceId), table.concat(sw, ","),
			found, num(S.stats.prescanMs, "%.1f"), num(CFG.MaxMinutes, "%g"), num(CFG.MaxMB, "%g"), num(CFG.PlayerInterval, "%.3f"),
			num(CFG.EnemyInterval, "%.3f"), num(CFG.HazardInterval, "%.3f"), num(hazardRange(), "%.0f"), num(enemyRange(), "%.0f")))
		bindCharacter()
		local conns = S.conns
		local keySet = {}
		for _, k in CFG.Keys do keySet[k] = true end
		local function onInput(input, down)
			if input.UserInputType ~= Enum.UserInputType.Keyboard or UserInputService:GetFocusedTextBox() ~= nil then return end
			local code = input.KeyCode
			if down and code == CFG.StopKey then
				S.stopReason = S.stopReason or "stop key"
			elseif down and code == CFG.MarkKey then
				API.Mark("key")
			elseif keySet[code.Name] then
				local ar, yaw = "null", "null" -- D-091: the facing and AutoRotate at each press / release
				pcall(function()
					local ch = S.me.char
					local hum = ch and ch:FindFirstChildOfClass("Humanoid")
					local root = S.me.root
					if hum and type(hum.AutoRotate) == "boolean" then ar = tostring(hum.AutoRotate) end
					if root and root.Parent then
						local lv = root.CFrame.LookVector
						yaw = string.format("%.1f", math.deg(math.atan2(-lv.X, -lv.Z)))
					end
				end)
				emit("key", '"key":' .. str(code.Name) .. ',"down":' .. tostring(down) .. ',"ar":' .. ar .. ',"yaw":' .. yaw)
			end
		end
		pcall(function() -- 1.9.4: Lighting's effects and anything a GUI highlights
			local function watch(service)
				conns[#conns + 1] = service.DescendantAdded:Connect(function(inst)
					if running then guard("fx", CFG._fxAdded, inst) end
				end)
			end
			watch(game:GetService("Lighting"))
			local pg = Players.LocalPlayer and Players.LocalPlayer:FindFirstChildOfClass("PlayerGui")
			if pg then watch(pg) end
		end)
		conns[#conns + 1] = Workspace.DescendantAdded:Connect(function(inst)
			if not running then return end
			guard("fx", CFG._fxAdded, inst) -- 1.9.3
			if inst:IsA("Humanoid") then
				guard("mob", considerMob, inst)
			elseif inst:IsA("BasePart") then
				if #S.pending < CFG.MaxPending then
					S.pending[#S.pending + 1] = { inst = inst, t = os.clock() }
				else
					S.stats.dropped += 1
					tallyAdd("DROPPED_too_many_new_parts_in_one_frame", inst.Name, inst.Parent)
				end
			end
		end)
		conns[#conns + 1] = Workspace.DescendantRemoving:Connect(function(inst)
			if not running then return end
			local rec = S.tracked[inst]
			if rec then guard("remove", endHazard, inst, rec, "removed", os.clock()) end
			local m = S.mobs[inst]
			if m then m.removed = true end
		end)
		conns[#conns + 1] = UserInputService.InputBegan:Connect(function(input) guard("input", onInput, input, true) end)
		conns[#conns + 1] = UserInputService.InputEnded:Connect(function(input) guard("input", onInput, input, false) end)
		conns[#conns + 1] = LogService.MessageOut:Connect(function(msg, mtype)
			if not running or string.sub(tostring(msg), 1, 4) == "[FR]" then return end
			guard("log", function()
				local text = redact(msg)
				local key = string.gsub(text, "%d+", "#")
				local seen = S.logSeen[key]
				if seen then -- the same line again: counted, reported every LogRepeatInterval s
					seen.n += 1
					S.stats.logRepeats += 1
					return
				end
				local stats = S.stats
				if S.logKeys >= CFG.MaxLogLines then
					stats.logsDropped += 1
					return
				end
				S.logKeys += 1
				S.logSeen[key] = { n = 1, reported = 1, text = text }
				stats.logs += 1
				emit("log", '"ty":' .. str(mtype and mtype.Name or "?") .. ',"msg":' .. str(text))
			end)
		end)
		-- a teleport ends this script: save everything as soon as it starts
		conns[#conns + 1] = LocalPlayer.OnTeleport:Connect(function(state)
			if running and (state == Enum.TeleportState.Started or state == Enum.TeleportState.InProgress) then
				guard("teleport", stopRecording, "teleport")
			end
		end)
		conns[#conns + 1] = RunService.Heartbeat:Connect(function(dt) guard("tick", tick, dt) end)
		print(string.format("[FR] recording '%s' (%s), safety limit %g min / %g MB | output %s", tostring(label), tostring(controller),
			CFG.MaxMinutes, CFG.MaxMB, prefix))
		if #switched > 0 then print("[FR] our controller switched off: " .. table.concat(switched, ", ")) end
		flush() -- the start row is on disk at once
	end)
	if not okRun then
		running = false
		if S and S.conns then for _, c in S.conns do pcall(c.Disconnect, c) end end
		local why = tostring(errRun)
		pcall(writefile, prefix .. "error.txt", "The recording could not start: " .. why .. "\n")
		print("[FR] the recording could not start: " .. why)
		message = "The recording could not start: " .. why
		refreshPanel()
		return false
	end
	refreshPanel()
	return true
end

function destroyAll(reason)
	if destroyed then return end
	if running then stopRecording(reason or "destroyed") end
	destroyed = true
	for _, c in uiConns do pcall(c.Disconnect, c) end
	table.clear(uiConns)
	if ui.gui then pcall(ui.gui.Destroy, ui.gui) end
	table.clear(ui)
	if rawget(_G, "FightRecorder") == API then _G.FightRecorder = nil end
	local reg = rawget(_G, "FightRecorders") -- D-079
	if type(reg) == "table" and reg[CFG.Owner] == API then reg[CFG.Owner] = nil end
end

function API.Start() return startRecording() end
function API.Stop() stopRecording("manual (API)") end
function API.Destroy() destroyAll("destroyed") end
function API.Mark(text)
	if not running then return end
	local stats = S.stats
	stats.marks += 1
	emit("mark", string.format('"n":%d,"text":%s', stats.marks, str(text or "")))
	print(string.format("[FR] mark %d at %s", stats.marks, clock(os.clock() - S.t0)))
	refreshPanel()
end
function API.Note(kind, fields) -- v6: a row from the host program; values: number, string, boolean or a table (JSON)
	if not running or type(kind) ~= "string" then return end
	local keys, parts = {}, {}
	for k in pairs(fields or {}) do keys[#keys + 1] = tostring(k) end
	table.sort(keys)
	for _, k in keys do
		local v = fields[k]
		local text
		if type(v) == "number" then
			text = num(v, "%.3f")
		elseif type(v) == "boolean" then
			text = tostring(v)
		elseif type(v) == "table" then
			local ok, encoded = pcall(HttpService.JSONEncode, HttpService, v)
			text = ok and encoded or "null"
		else
			text = str(v)
		end
		parts[#parts + 1] = str(k) .. ":" .. text
	end
	emit(kind, table.concat(parts, ","))
end
function API.Tracked() -- v6: the attack parts being tracked right now (read-only), for a host's visuals
	local out = {}
	if running and S and S.tracked then
		for inst, rec in pairs(S.tracked) do
			out[#out + 1] = { inst = inst, id = rec.id, age = os.clock() - (rec.addT or os.clock()) }
		end
	end
	return out
end
function API.SetLabel(label) pick.label = tostring(label or CFG.Label) end
function API.SetController(controller) pick.controller = tostring(controller or CFG.Controller) end
function API.Status()
	return { running = running, seconds = S and ((S.endT or os.clock()) - S.t0) or 0, bytes = S and S.out.bytes or 0,
		lines = S and S.out.lines or 0, folder = S and S.out.prefix, reason = S and S.stopReason, safetyLimit = S and S.limit ~= nil }
end

--------------------------------------------------------------------------------
-- Boot: replace an earlier copy (saving its recording), then show the panel. Nothing is recorded yet.
--------------------------------------------------------------------------------
do -- D-079: a copy replaces only its own kind (Aur_Hub's built-in recorder and AurRecorder no longer remove each other)
	local reg = rawget(_G, "FightRecorders")
	if type(reg) ~= "table" then
		reg = {}
		_G.FightRecorders = reg
	end
	local prev = reg[CFG.Owner]
	local legacy = rawget(_G, "FightRecorder")
	if prev == nil and CFG.Owner ~= "Aur_Hub" and type(legacy) == "table" and legacy.Owner == nil then
		prev = legacy -- an older copy (before owners) under the shared name
	end
	if type(prev) == "table" then
		if type(prev.Destroy) == "function" then
			pcall(prev.Destroy)
		elseif type(prev.Stop) == "function" then
			pcall(prev.Stop) -- v1
		end
	end
	reg[CFG.Owner] = API
	API.Owner = CFG.Owner
end
if CFG.Owner ~= "Aur_Hub" then
	_G.FightRecorder = API
end
if CFG.Headless then
	print("[FR] FightRecorder v6 ready (built in): nothing is recorded until Start")
else
	if not createPanel() then print("[FR] no PlayerGui: use _G.FightRecorder.Start() / .Stop()") end
	print("[FR] FightRecorder v6 ready: press Start Recording on the panel (nothing is recorded until then)")
end
            return API
        end
        local RR = { api = nil, holdFarm = false, last = nil }
        local function sanitize(name)
            name = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", ""):gsub("[^%w_%-]", "_"):sub(1, 60)
            if name == "" or name:match("^_+$") then
                name = "run"
            end
            return name
        end
        RR.sanitize = sanitize
        local function ensure()
            local reg = rawget(_G, "FightRecorders") -- D-079: our own recorder, not AurRecorder's
            if RR.api and type(reg) == "table" and reg.Aur_Hub == RR.api then
                return RR.api
            end
            local saved = rawget(_G, "FightRecorderOptions")
            _G.FightRecorderOptions = {
                Headless = true,
                ExactName = true,
                Folder = "Aur_Hub/recordings",
                Controller = "aurhub",
                Label = "run",
                Owner = "Aur_Hub", -- D-079
            }
            local ok, api = pcall(loadRecorder)
            _G.FightRecorderOptions = saved
            RR.api = ok and type(api) == "table" and api or nil
            if not ok and context.log then
                context.log("Recorder", "could not load: " .. tostring(api))
            end
            return RR.api
        end
        RR.status = function()
            local api = RR.api
            if not (api and api.Status) then
                return { running = false }
            end
            local ok, status = pcall(api.Status)
            return ok and status or { running = false }
        end
        RR.recording = function()
            return RR.status().running == true
        end
        RR.start = function(name, playYourself)
            if type(writefile) ~= "function" then
                return false, "This executor cannot write files, so nothing can be recorded."
            end
            local api = ensure()
            if not api then
                return false, "The recorder could not be loaded."
            end
            if RR.recording() then
                return false, "Already recording."
            end
            api.SetLabel(sanitize(name))
            api.SetController("aurhub")
            if not api.Start() then
                return false, "The recording could not start (writefile failed)."
            end
            RR.holdFarm = playYourself == true
            runtimeState.farmHold = RR.holdFarm or nil -- D-034: every automatic switch-on respects it
            if RR.holdFarm and runtimeState.farmEnabled and context.setAutofarm then
                context.setAutofarm(false)
            end
            api.Note("aur", {
                version = tostring(context.SCRIPT_VERSION),
                play_yourself = RR.holdFarm,
                name = sanitize(name),
            })
            RR.last = nil
            return true
        end
        RR.stop = function()
            if not RR.recording() then
                return false
            end
            pcall(RR.api.Stop)
            RR.holdFarm = false
            runtimeState.farmHold = nil
            RR.last = RR.status()
            return true
        end
        RR.mark = function(text)
            if RR.recording() then
                pcall(RR.api.Mark, text or "mark")
                return true
            end
            return false
        end
        -- the bosses' server events and hitbox warnings, as "evt" rows (Aur_Hub sees these; the standalone recorder
        -- does not). Values are made JSON-safe: CFrame -> position + look, Vector3 -> [x, y, z], Instance -> path.
        local function plain(value, depth)
            local kind = typeof(value)
            if kind == "number" or kind == "boolean" then
                return value
            elseif kind == "string" then
                return #value > 200 and value:sub(1, 200) .. "..." or value
            elseif kind == "Vector3" then
                return { math.floor(value.X * 100) / 100, math.floor(value.Y * 100) / 100, math.floor(value.Z * 100) / 100 }
            elseif kind == "CFrame" then
                return { pos = plain(value.Position, depth), look = plain(value.LookVector, depth) }
            elseif kind == "Instance" then
                local ok, path = pcall(value.GetFullName, value)
                return ok and path or value.Name
            elseif kind == "table" and (depth or 0) < 3 then
                local out, n = {}, 0
                for k, v in pairs(value) do
                    n += 1
                    if n > 24 then
                        out["..."] = "more"
                        break
                    end
                    out[tostring(k)] = plain(v, (depth or 0) + 1)
                end
                return out
            end
            return tostring(value)
        end
        RR.event = function(name, payload)
            if not (RR.api and RR.recording()) then
                return
            end
            local fields = { name = tostring(name), data = plain(payload, 0) }
            pcall(function()
                local root = game:GetService("Players").LocalPlayer.Character.HumanoidRootPart
                fields.me = plain(root.Position, 0)
            end)
            pcall(function()
                fields.server_time = workspace:GetServerTimeNow()
            end)
            pcall(RR.api.Note, "evt", fields)
        end
        context.recordEvent = RR.event
        RR.destroy = function()
            RR.holdFarm = false
            runtimeState.farmHold = nil
            if RR.bar then
                RR.bar.destroy()
            end
            if RR.api then -- D-079: our own copy (no longer the shared _G.FightRecorder)
                pcall(RR.api.Destroy) -- saves an active recording first
            end
            RR.api = nil
        end
        -- while "Play it yourself" is on, Autofarm stays off for the whole recording (it switches itself on in a
        -- dungeon otherwise); the hold ends with the recording
        task.spawn(function()
            while not runtimeState.destroyed do
                task.wait(0.5)
                if RR.holdFarm then
                    if not RR.recording() then
                        RR.holdFarm = false
                        runtimeState.farmHold = nil
                        RR.last = RR.status()
                    elseif runtimeState.farmEnabled and context.setAutofarm then
                        context.setAutofarm(false)
                    end
                end
            end
        end)
        do -- Aur_Hub (D-031): the recorder bar, always in front (its own ScreenGui above everything), like TinyTask
            local players = game:GetService("Players")
            local userInputService = game:GetService("UserInputService")
            local bar = { conns = {} }
            local function make(class, props, parent)
                local object = Instance.new(class)
                for key, value in pairs(props) do
                    object[key] = value
                end
                object.Parent = parent
                return object
            end
            local function mmss(seconds)
                seconds = math.max(0, math.floor(tonumber(seconds) or 0))
                return ("%02d:%02d"):format(math.floor(seconds / 60), seconds % 60)
            end
            local function notify(kind, title, text)
                if context.notify then
                    pcall(context.notify, kind, title, text)
                end
            end
            local function save()
                if context.saveConfig then
                    pcall(context.saveConfig)
                end
            end
            function bar.build()
                local uiKit = context.UIKit
                local playerGui = players.LocalPlayer and players.LocalPlayer:FindFirstChild("PlayerGui")
                if bar.gui or not (uiKit and playerGui) then
                    return
                end
                local theme = uiKit.Theme
                local old = playerGui:FindFirstChild("AurRecorderBar")
                if old then
                    old:Destroy()
                end
                local gui = make("ScreenGui", {
                    Name = "AurRecorderBar",
                    ResetOnSpawn = false,
                    IgnoreGuiInset = true,
                    DisplayOrder = 1000,
                    ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
                }, playerGui)
                local frame = make("Frame", {
                    Name = "Bar",
                    Size = UDim2.fromOffset(410, 40),
                    BackgroundColor3 = theme.SurfaceHeader,
                    BorderSizePixel = 0,
                    Active = true,
                }, gui)
                uiKit.corner(frame, 10)
                local outline = uiKit.stroke(frame, theme.Hairline, 1)
                uiKit.pad(frame, 0, 8, 0, 10)
                uiKit.hlist(frame, 8)
                local x, y = tonumber(config.recorderBarX) or -1, tonumber(config.recorderBarY) or -1
                if x < 0 or y < 0 then
                    local camera = workspace.CurrentCamera
                    local width = camera and camera.ViewportSize.X or 1280
                    x, y = math.max(0, math.floor((width - 410) / 2)), 60
                end
                frame.Position = UDim2.fromOffset(x, y)
                local brand = uiKit.label(frame, "AUR", "rowStat", 1)
                brand.Name, brand.Size, brand.TextColor3 = "Grip", UDim2.fromOffset(32, 26), theme.AccentB
                uiKit.setFont(brand, "sans", Enum.FontWeight.Bold)
                local record = make("TextButton", {
                    Name = "Record",
                    Text = "",
                    LayoutOrder = 2,
                    Size = UDim2.fromOffset(28, 28),
                    BackgroundColor3 = theme.SurfaceField,
                    AutoButtonColor = false,
                    BorderSizePixel = 0,
                }, frame)
                uiKit.corner(record, 14)
                local dot = make("Frame", {
                    Name = "Dot",
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    Position = UDim2.fromScale(0.5, 0.5),
                    Size = UDim2.fromOffset(12, 12),
                    BackgroundColor3 = Color3.fromHex("E5484D"),
                    BorderSizePixel = 0,
                }, record)
                dot:SetAttribute("HLThemeSkip", true)
                local dotCorner = uiKit.corner(dot, 6)
                local box = make("TextBox", {
                    Name = "Name",
                    LayoutOrder = 3,
                    Size = UDim2.fromOffset(140, 26),
                    Text = tostring(config.recordName or ""),
                    PlaceholderText = "recording name",
                    ClearTextOnFocus = false,
                    TextSize = 12,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    BackgroundColor3 = theme.SurfaceField,
                    TextColor3 = theme.TextPrimary,
                    PlaceholderColor3 = theme.TextMuted,
                    BorderSizePixel = 0,
                }, frame)
                uiKit.corner(box, 6)
                uiKit.pad(box, 0, 8, 0, 8)
                uiKit.setFont(box, "sans", Enum.FontWeight.Medium)
                local timer = uiKit.label(frame, "00:00", "monoStat", 4)
                timer.Name, timer.Size, timer.TextColor3 = "Timer", UDim2.fromOffset(46, 26), theme.TextSub
                local mark = make("TextButton", {
                    Name = "Mark",
                    Text = "",
                    LayoutOrder = 5,
                    Size = UDim2.fromOffset(28, 28),
                    BackgroundColor3 = theme.SurfaceField,
                    AutoButtonColor = false,
                    BorderSizePixel = 0,
                }, frame)
                uiKit.corner(mark, 6)
                local flag = uiKit.icon(mark, "flag", 14, theme.TextSub)
                flag.AnchorPoint, flag.Position = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5)
                local who = make("TextButton", {
                    Name = "Who",
                    LayoutOrder = 6,
                    Size = UDim2.fromOffset(72, 26),
                    BackgroundColor3 = theme.SurfaceField,
                    AutoButtonColor = false,
                    BorderSizePixel = 0,
                    TextSize = 11,
                    TextColor3 = theme.TextSub,
                }, frame)
                uiKit.corner(who, 6)
                uiKit.setFont(who, "sans", Enum.FontWeight.Medium)
                local hide = make("TextButton", {
                    Name = "Hide",
                    Text = "",
                    LayoutOrder = 7,
                    Size = UDim2.fromOffset(22, 22),
                    BackgroundTransparency = 1,
                    AutoButtonColor = false,
                }, frame)
                local cross = uiKit.icon(hide, "x", 14, theme.TextMuted)
                cross.AnchorPoint, cross.Position = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5)
                uiKit.tip(record, "Record or stop. Stopping saves to Aur_Hub/recordings/<name>/ in the executor workspace; the run ending also saves it.")
                uiKit.tip(box, "The recording's folder name (letters, digits, - and _). A used name gets -2, -3 ...")
                uiKit.tip(mark, "Mark this moment in the recording ([ does the same, ] stops).")
                uiKit.tip(who, "Who plays while recording: you (Autofarm held off) or Autofarm.")
                uiKit.tip(hide, "Hide the bar. Show it again from Farm Settings > Advanced > Run recorder.")
                local function paint()
                    local st = RR.status()
                    local recording = st.running == true
                    dotCorner.CornerRadius = UDim.new(0, recording and 2 or 6)
                    dot.BackgroundColor3 = recording and theme.TextPrimary or Color3.fromHex("E5484D")
                    record.BackgroundColor3 = recording and Color3.fromHex("C9363C") or theme.SurfaceField
                    outline.Color = recording and Color3.fromHex("C9363C") or theme.Hairline
                    timer.Text = mmss(recording and st.seconds or 0)
                    timer.TextColor3 = recording and theme.TextPrimary or theme.TextSub
                    box.TextEditable = not recording
                    who.Text = config.recordPlayYourself ~= false and "Play: you" or "Play: auto"
                    if not box:IsFocused() and box.Text ~= tostring(config.recordName or "") and not recording then
                        box.Text = tostring(config.recordName or "")
                    end
                end
                bar.paint = paint
                box.FocusLost:Connect(function()
                    config.recordName = box.Text
                    save()
                end)
                record.MouseButton1Click:Connect(function()
                    if RR.recording() then
                        RR.stop()
                        local last = RR.last
                        notify("success", "Recording saved", last and last.folder and tostring(last.folder) or "Aur_Hub/recordings")
                    else
                        if box.Text ~= "" then
                            config.recordName = box.Text
                            save()
                        end
                        local ok, why = RR.start(config.recordName, config.recordPlayYourself ~= false)
                        notify(ok and "run" or "error", ok and "Recording" or "Recorder", ok and tostring(RR.status().folder) or tostring(why))
                    end
                    paint()
                end)
                mark.MouseButton1Click:Connect(function()
                    if RR.mark("bar") then
                        flag.ImageColor3 = theme.AccentB
                        task.delay(0.6, function()
                            flag.ImageColor3 = theme.TextSub
                        end)
                    end
                end)
                who.MouseButton1Click:Connect(function()
                    if RR.recording() then
                        return -- decided at Start
                    end
                    config.recordPlayYourself = config.recordPlayYourself == false
                    save()
                    paint()
                end)
                hide.MouseButton1Click:Connect(function()
                    bar.setShown(false)
                end)
                -- drag from anywhere that is not a button or the name box; the place is remembered
                local dragFrom, startPos
                frame.InputBegan:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                        dragFrom, startPos = input.Position, frame.Position
                    end
                end)
                bar.conns[#bar.conns + 1] = userInputService.InputChanged:Connect(function(input)
                    if dragFrom and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                        local delta = input.Position - dragFrom
                        local camera = workspace.CurrentCamera
                        local view = camera and camera.ViewportSize or Vector2.new(1920, 1080)
                        frame.Position = UDim2.fromOffset(
                            math.clamp(startPos.X.Offset + delta.X, 0, math.max(0, view.X - 410)),
                            math.clamp(startPos.Y.Offset + delta.Y, 0, math.max(0, view.Y - 40))
                        )
                    end
                end)
                bar.conns[#bar.conns + 1] = userInputService.InputEnded:Connect(function(input)
                    if dragFrom and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
                        dragFrom = nil
                        config.recorderBarX, config.recorderBarY = frame.Position.X.Offset, frame.Position.Y.Offset
                        save()
                    end
                end)
                bar.gui, bar.frame = gui, frame
                paint()
            end
            function bar.setShown(shown)
                config.recorderBar = shown == true
                save()
                if shown and config.recorderEnabled == true then
                    bar.build()
                end
                if bar.gui then
                    bar.gui.Enabled = shown == true
                end
            end
            function bar.destroy()
                for _, connection in ipairs(bar.conns) do
                    pcall(connection.Disconnect, connection)
                end
                table.clear(bar.conns)
                if bar.gui then
                    pcall(bar.gui.Destroy, bar.gui)
                    bar.gui = nil
                end
            end
            function bar.applyEnabled() -- the bar exists only while the recorder is switched on (D-032)
                if config.recorderEnabled == true and config.recorderBar ~= false then
                    bar.build()
                    if bar.gui then
                        bar.gui.Enabled = true
                    end
                elseif bar.gui then
                    bar.gui.Enabled = false
                end
            end
            if config.recorderEnabled == true and config.recorderBar ~= false then
                task.defer(function()
                    pcall(bar.build)
                end)
            end
            task.spawn(function() -- the timer: once a second, only while the bar is shown
                while not runtimeState.destroyed do
                    task.wait(1)
                    if bar.gui and bar.gui.Enabled and bar.paint then
                        pcall(bar.paint)
                    end
                end
            end)
            RR.bar = bar
        end
        context.RunRecorder = RR
    end
    components.mapLite = function(context) -- Aur_Hub (D-041): "Simplify the map" - local, visual only
        -- Hides scenery on this client only. What is solid stays solid: CanCollide, CanQuery, CanTouch, Transparency,
        -- Size and position are never written and nothing is added, so every floor, wall, stair and invisible barrier
        -- behaves exactly as the game made it - no shortcut, no floating platform. Only the Map folder is touched (never
        -- the dungeon rooms, mobs, checkpoints, attacks or players). Hidden:
        --   * parts you can walk through (decoration), and decals / textures / particles / lights / beams / GUIs;
        --   * where a walked route is known: solid parts far from it (still solid, only not drawn).
        -- "Floors and stairs only" (mapLiteSee): where the walked route is known, every solid part nobody stood on (walls,
        -- rocks, pillars, railings) is not drawn - still solid; elsewhere only walls go.
