1;229,102,-150;229,102,-149;229,102,-148;229,102,-147;229,102,-146;229,102,-145;229,102,-144;229,102,-143;229,102,-142;229,102,-141;229,103,-146;230,101,-141;230,101,-140;230,102,-158;230,102,-157;230,102,-156;230,102,-155;230,102,-154;230,102,-153;230,102,-152;230,102,-151;230,102,-150;230,102,-149;230,102,-148;230,102,-147;230,102,-146;230,102,-145;230,102,-144;230,102,-143;230,103,-161;230,104,-161;230,105,-163;230,106,-163;231,101,-144;231,101,-143;231,101,-142;231,101,-141;231,102,-158;231,102,-157;231,102,-154;231,102,-153;231,102,-152;231,102,-151;231,102,-150;231,102,-149;231,102,-148;231,102,-147;231,102,-146;231,102,-145;231,102,-144;231,104,-162;231,104,-161;231,105,-163;231,105,-162;231,105,-161;231,106,-163;232,101,-145;232,101,-144;232,101,-143;232,101,-142;232,102,-158;232,102,-153;232,102,-152;232,102,-150;232,102,-149;232,102,-148;232,102,-147;232,102,-146;232,102,-145;232,103,-158;232,105,-162;232,105,-161;232,106,-162;232,106,-160;232,107,-163;233,101,-146;233,101,-144;233,101,-143;233,102,-157;233,102,-154;233,102,-153;233,102,-152;233,102,-151;233,102,-150;233,102,-149;233,102,-148;233,102,-147;233,102,-146;233,103,-158;233,104,-159;233,104,-158;233,105,-160;233,105,-159;233,106,-162;233,106,-160;233,107,-162;233,108,-162;234,101,-148;234,101,-147;234,101,-146;234,102,-157;234,102,-156;234,102,-155;234,102,-154;234,102,-153;234,102,-152;234,102,-151;234,102,-150;234,102,-149;234,102,-148;234,102,-147;234,103,-158;234,103,-157;234,104,-159;234,104,-158;234,105,-159;234,106,-160;234,106,-159;234,108,-162;234,108,-161;235,101,-148;235,101,-147;235,102,-156;235,102,-155;235,102,-154;235,102,-153;235,102,-152;235,102,-151;235,102,-150;235,102,-149;235,102,-148;235,103,-157;235,103,-156;235,104,-158;235,104,-157;235,105,-160;235,105,-159;235,105,-158;235,106,-160;235,107,-160;235,108,-161;235,108,-160;235,109,-161;236,101,-148;236,101,-147;236,102,-154;236,102,-151;236,102,-150;236,102,-149;236,102,-148;236,102,-147;236,103,-156;236,103,-147;236,104,-