        }
        local COARSE = 24
        local routeIndex, routeFor = nil, nil
        local function dungeonKey()
            local value = workspace:FindFirstChild("dungeonName")
            local name = value and tostring(value.Value) or ""
            return (name:lower():gsub("%s", ""))
        end
        local function route()
            local key = dungeonKey()
            if routeFor == key then
                return routeIndex
            end
            routeFor, routeIndex = key, nil
            local entry = ROUTES[key]
            if not entry or entry.data:sub(1, 4) == "--@@" then
                return nil
            end
            local index = {}
            for x, y, z in entry.data:gmatch("(-?%d+),(-?%d+),(-?%d+)") do
                local wx, wy, wz = tonumber(x) * entry.cell, tonumber(y) * (entry.ycell or entry.cell), tonumber(z) * entry.cell
                local k = math.floor(wx / COARSE) .. "," .. math.floor(wz / COARSE)
                local slot = index[k]
                if slot then
                    slot.lo, slot.hi = math.min(slot.lo, wy), math.max(slot.hi, wy)
                else
                    slot = { lo = wy, hi = wy, cells = {} }
                    index[k] = slot
                end
                slot.cells[#slot.cells + 1] = { wx, wy, wz } -- D-044: where the player stood, for "walked on"
            end
            routeIndex = index
            return index
        end
        ML.route = route
        -- is any part of this box within reach of the walked route?
        local function nearRoute(part, index)
            local cf, size = part.CFrame, part.Size
            local r = cf.RightVector * size.X * 0.5
            local u = cf.UpVector * size.Y * 0.5
            local b = cf.LookVector * size.Z * 0.5
            local ex = math.abs(r.X) + math.abs(u.X) + math.abs(b.X)
            local ey = math.abs(r.Y) + math.abs(u.Y) + math.abs(b.Y)
            local ez = math.abs(r.Z) + math.abs(u.Z) + math.abs(b.Z)
            local reach = config.mapLiteNear or 40
            local p = cf.Position
            local below, above = config.mapLiteBelow or 30, config.mapLiteAbove or 60
            for gx = math.floor((p.X - ex - reach) / COARSE), math.floor((p.X + ex + reach) / COARSE) do
                for gz = math.floor((p.Z - ez - reach) / COARSE), math.floor((p.Z + ez + reach) / COARSE) do
                    local slot = index[gx .. "," .. gz]
                    if slot and p.Y + ey >= slot.lo - below and p.Y - ey <= slot.hi + above then
                        return true
                    end
                end
            end
            return false
        end
        ML.nearRoute = nearRoute
        -- D-059: a point near where players stood (the walked map); nil when no map is known here
        ML.knownFloor = function(x, y, z, slack)
            local index = route()
            if not index then
                return nil
            end
            slack = slack or 6
            for gx = math.floor((x - slack) / COARSE), math.floor((x + slack) / COARSE) do
                for gz = math.floor((z - slack) / COARSE), math.floor((z + slack) / COARSE) do
                    local slot = index[gx .. "," .. gz]
                    if slot and y >= slot.lo - 8 and y <= slot.hi + 8 then
                        for _, c in ipairs(slot.cells) do
                            if math.abs(c[1] - x) <= slack and math.abs(c[3] - z) <= slack and math.abs(c[2] - y) <= 8 then
                                return true
                            end
                        end
                    end
                end
            end
            return false
        end
        -- D-044: did a player stand on top of this part? (a route cell over its footprint whose height - the character's
        -- root, about 3 studs over what it stands on, in whole studs - is 1..9 studs above the part's top)
        local function walkedOn(part, index)
            local cf, size = part.CFrame, part.Size
            local r = cf.RightVector * size.X * 0.5
            local u = cf.UpVector * size.Y * 0.5
            local b = cf.LookVector * size.Z * 0.5
            local ex = math.abs(r.X) + math.abs(u.X) + math.abs(b.X)
            local ey = math.abs(r.Y) + math.abs(u.Y) + math.abs(b.Y)
            local ez = math.abs(r.Z) + math.abs(u.Z) + math.abs(b.Z)
            local p = cf.Position
            local top = p.Y + ey
            local slack = config.mapLiteCellSlack or 3
            for gx = math.floor((p.X - ex - slack) / COARSE), math.floor((p.X + ex + slack) / COARSE) do
                for gz = math.floor((p.Z - ez - slack) / COARSE), math.floor((p.Z + ez + slack) / COARSE) do
                    local slot = index[gx .. "," .. gz]
                    -- D-228: feet are 2.5-3.4 above the floor (p1-p99 of 44,176 grounded samples): 1-5, was 1-9, which also kept what lay under a walkway
                    if slot and slot.hi >= top + 1 and slot.lo <= top + (config.mapLiteWalkHi or 5) then
                        for _, c in ipairs(slot.cells) do
                            local dy = c[2] - top
                            if dy >= 1 and dy <= (config.mapLiteWalkHi or 5) and math.abs(c[1] - p.X) <= ex + slack and math.abs(c[3] - p.Z) <= ez + slack then
                                return true
                            end
                        end
                    end
                end
            end
            return false
        end
        ML.walkedOn = walkedOn
        -- D-067: a wall standing beside the walked floor (a route cell within 6 studs of its footprint, the cell's height
        -- inside the wall's height): the arena's boundary
        local function bordersRoute(part, index)
            local cf, size = part.CFrame, part.Size
            local r = cf.RightVector * size.X * 0.5
            local u = cf.UpVector * size.Y * 0.5
            local b = cf.LookVector * size.Z * 0.5
            local ex = math.abs(r.X) + math.abs(u.X) + math.abs(b.X)
            local ey = math.abs(r.Y) + math.abs(u.Y) + math.abs(b.Y)
            local ez = math.abs(r.Z) + math.abs(u.Z) + math.abs(b.Z)
            local p = cf.Position
            local near = config.mapLiteBorder or 6
            for gx = math.floor((p.X - ex - near) / COARSE), math.floor((p.X + ex + near) / COARSE) do
                for gz = math.floor((p.Z - ez - near) / COARSE), math.floor((p.Z + ez + near) / COARSE) do
                    local slot = index[gx .. "," .. gz]
                    if slot and slot.hi >= p.Y - ey and slot.lo <= p.Y + ey + 6 then
                        for _, c in ipairs(slot.cells) do
                            if c[2] >= p.Y - ey and c[2] <= p.Y + ey + 6
                                and math.abs(c[1] - p.X) <= ex + near and math.abs(c[3] - p.Z) <= ez + near then
                                return true
                            end
                        end
                    end
                end
            end
            return false
        end
        ML.bordersRoute = bordersRoute
        local EFFECTS = {
            ParticleEmitter = true, Fire = true, Smoke = true, Sparkles = true, Beam = true, Trail = true,
            PointLight = true, SpotLight = true, SurfaceLight = true, SurfaceGui = true, BillboardGui = true,
        }
        local function remember(object, key, value)
            local saved = ML.saved[object]
            if not saved then
                saved = {}
                ML.saved[object] = saved
            end
            if saved[key] == nil then
                saved[key] = { object[key] }
            end
            object[key] = value
        end
        -- never touch an attack, its warning or its effects (D-043), whatever folder it sits in
        local ATTACK_WORDS = { "precast", "hitbox", "telegraph", "warning", "indicator", "damage", "boss", "attack" }
        local function isAttack(object)
            local node = object
            for _ = 1, 6 do
                if node == nil or node == workspace then
                    return false
                end
                local lower = node.Name:lower()
                for _, word in ipairs(ATTACK_WORDS) do
                    if lower ~= "bossroom" and lower:find(word, 1, true) then -- D-228: the last boss's room is a room
                        return true
                    end
                end
                -- (not the attack name list: it holds plain names like "rock" that map scenery also uses - D-044)
                node = node.Parent
            end
            return false
        end
        ML.isAttack = isAttack
        -- a wall: much taller than it is thick (world box). Floors, steps and ramps are flat.
        local function isWall(part)
            local cf, size = part.CFrame, part.Size
            local r = cf.RightVector * size.X * 0.5
            local u = cf.UpVector * size.Y * 0.5
            local b = cf.LookVector * size.Z * 0.5
            local ex = math.abs(r.X) + math.abs(u.X) + math.abs(b.X)
            local ey = math.abs(r.Y) + math.abs(u.Y) + math.abs(b.Y)
            local ez = math.abs(r.Z) + math.abs(u.Z) + math.abs(b.Z)
            return ey * 2 >= (config.mapLiteWallTall or 8) and ey >= math.min(ex, ez) * 1.2
        end
        ML.isWall = isWall
        function ML.canDelete(part) -- D-224: never something that can be used, holds a part, or belongs to a rig
            for _, d in ipairs(part:GetDescendants()) do
                if d:IsA("BasePart") or d:IsA("ProximityPrompt") or d:IsA("ClickDetector") or d:IsA("TouchTransmitter")
                    or d:IsA("SurfaceGui") or d:IsA("BillboardGui") then
                    return false
                end
            end
            local model = part:FindFirstAncestorOfClass("Model")
            return not (model and (model:FindFirstChildOfClass("Humanoid") or model:FindFirstChildOfClass("AnimationController")))
        end
        -- D-227 (user): the AA hub's Remove Map colours: charcoal world, navy floors, a lighter navy for walls; solid, not see-through
        ML.NAVY = { world = Color3.fromRGB(14, 18, 24), floor = Color3.fromRGB(30, 48, 78) } -- D-228 (user): one colour for all of it
        function ML.isExcess(part, index) -- D-228: something fixed in a dungeon room nobody stands on (walls, props)
            if config.mapLiteSee ~= true or not part:IsA("BasePart") or part.Transparency >= 1 or part.LocalTransparencyModifier >= 1 or not part.Anchored
                or part.Name == "checkPoint" or part.Name == "barrier" or part.Name == "spawn"
                or part:FindFirstAncestor("enemyFolder") or part:FindFirstAncestor("turretFolder") or isAttack(part) or walkedOn(part, index) then
                return false
            end
            for _, d in ipairs(part:GetChildren()) do
                if d:IsA("ProximityPrompt") or d:IsA("ClickDetector") or d:IsA("SurfaceGui") or d:IsA("BillboardGui") then
                    return false
                end
            end
            local model = part:FindFirstAncestorOfClass("Model")
            return not (model and (model:FindFirstChildOfClass("Humanoid") or model:FindFirstChildOfClass("AnimationController")))
        end
        function ML.floorColor(part)
            if config.mapLiteNavy == false then
                return config.mapLiteFloorColor or Color3.fromRGB(150, 150, 150)
            end
            return ML.NAVY.floor
        end
        function ML.opacity()
            if config.mapLiteNavy ~= false then
                return 1
            end
            return math.clamp(tonumber(config.mapLiteOpacity) or 0.25, 0, 1)
        end
        local function apply(object, index)
            if isAttack(object) then
                return
            end
            if object:IsA("BasePart") then
                if object.LocalTransparencyModifier >= 1 or object.Transparency >= 1 then
                    return -- already invisible (an invisible barrier stays exactly as it is)
                end
                local near = not index or nearRoute(object, index)
                -- a big flat see-through surface near the route may be the drawn floor over an invisible collider: keep it
                local floorLike = not object.CanCollide
                    and near
                    and object.Size.X >= (config.mapLiteFloorMin or 12)
                    and object.Size.Z >= (config.mapLiteFloorMin or 12)
                    and object.Size.Y <= math.min(object.Size.X, object.Size.Z) * 0.25
                if floorLike or (object.CanCollide and near) then
                    ML.kept += 1
                    local drop
                    if config.mapLiteSee == true then
                        if index then
                            -- D-044 "floors and stairs only": what nobody stood on goes - D-067: but the arena's
                            -- boundary walls (a wall beside a walked floor, at its height) stay
                            drop = not walkedOn(object, index) -- D-068: walked surfaces only again (no boundary walls)
                        else
                            drop = not floorLike and isWall(object) -- no walked route known here: walls only
                        end
                    end
                    if drop then
                        -- not drawn - still exactly as solid (walls, rocks and pillars keep blocking the way)
                        remember(object, "LocalTransparencyModifier", config.mapLiteWallAmount or 1)
                        ML.walls = (ML.walls or 0) + 1
                    elseif config.mapLiteSee == true and config.mapLiteFlat ~= false then
                        -- D-048: a walked floor or stair, drawn flat and clear: one plain colour, no texture or surface
                        -- pattern. Colour and textures are drawing only (not the material: that would change footing)
                        remember(object, "Color", ML.floorColor(object))
                        if object:IsA("MeshPart") then
                            pcall(remember, object, "TextureID", "")
                        end
                        if config.mapLitePlain ~= false then
                            -- D-059: one shade - a plain surface; the part keeps its own footing (its material's physics pinned)
                            pcall(function()
                                if object.CustomPhysicalProperties == nil then
                                    remember(object, "CustomPhysicalProperties", PhysicalProperties.new(object.Material))
                                end
                                remember(object, "Material", Enum.Material.SmoothPlastic)
                                remember(object, "Reflectance", 0)
                            end)
                        end
                        for _, look in ipairs(object:GetChildren()) do
                            if look:IsA("SurfaceAppearance") or look:IsA("Texture") or look:IsA("Decal") then
                                pcall(remember, look, "Parent", nil)
                            end
                        end
                        ML.flat = (ML.flat or 0) + 1
                    end
                    local opacity = ML.opacity()
                    if not drop and opacity < 1 then
                        -- D-133 (user): what stays drawn shows at 25% opacity (drawing only - just as solid)
                        remember(object, "LocalTransparencyModifier", 1 - opacity)
                    end
                elseif config.mapLiteDelete ~= false and index and not object.CanCollide and ML.canDelete(object) then
                    -- D-224 (the AA hub's Simple Map): scenery you walk through: gone until the next map load
                    object:Destroy()
                    ML.deleted = (ML.deleted or 0) + 1
                else
                    remember(object, "LocalTransparencyModifier", 1)
                    ML.hidden += 1
                end
            elseif object:IsA("Decal") then -- Decal and Texture
                remember(object, "LocalTransparencyModifier", 1)
                ML.effects += 1
            elseif EFFECTS[object.ClassName] then
                remember(object, "Enabled", false)
                ML.effects += 1
            end
        end
        -- D-223 (user: the AA hub's FPS settings): its Calm visuals. Particle-type effects are off everywhere but on our own
        -- character (nothing reads them: the one Beam the reader uses is read by its attachments, not by whether it is on);
        -- teammates' animations stop as they start. Mobs and bosses keep theirs: their attack warnings may depend on them.
        local CALM_FX = { ParticleEmitter = true, Trail = true, Beam = true, Smoke = true, Fire = true, Sparkles = true }
        local OUR_PANELS = { tag = true, num = true, HLTag = true, HLOrbFuse = true } -- D-224: the bot's own labels stay
        ML.calmOff, ML.calmAnims, ML.calmFx = setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" }), 0
        ML.partsOff, ML.boxes = setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" })
        function ML.partJudge(object) -- D-228: drawing only (LocalTransparencyModifier): the hit areas stay exactly as the bot reads them
            if ML.partsOff[object] or object:FindFirstAncestor("DungeonAutofarmVisuals") or object:GetAttribute("AurHubOwned") == true then
                return
            end
            local model = object:FindFirstAncestorOfClass("Model")
            if model and game:GetService("Players"):GetPlayerFromCharacter(model) then
                return
            end
            local attack = isAttack(object) or object:FindFirstAncestor("voidsbaneV3Effects") or object:FindFirstAncestor("turretFolder")
                or object.Name == "dracani comet"
            local enemy = object:FindFirstAncestor("enemyFolder")
            if not ((attack and config.mapLiteHideAttacks == true) or (enemy and not attack and config.mapLiteMobBox == true)) then
                return
            end
            if object:IsA("BasePart") and enemy and object.Name == "HumanoidRootPart" and config.mapLiteMobBox == true and not ML.boxes[object] then
                local box = Instance.new("BoxHandleAdornment") -- follows its part with no script running, and goes with the mob
                box.Name = "AurMobBox"
                box.Adornee = object
                box.Size = Vector3.new(3, 4, 3)
                box.Color3 = Color3.fromRGB(66, 133, 236)
                box.Transparency = 0.35
                box.ZIndex = 1
                box.Parent = object
                ML.boxes[object] = box
            end
            ML.partsOff[object] = object.LocalTransparencyModifier
            object.LocalTransparencyModifier = 1
        end
        function ML.calmJudge(object, gen)
            local players = game:GetService("Players")
            local me = players.LocalPlayer
            if ML.partsOn and (object:IsA("BasePart") or object.ClassName == "Decal") then
                ML.partJudge(object)
                return
            end
            if CALM_FX[object.ClassName] then
                local mine = me and me.Character
                if ML.saved[object] or ML.calmOff[object] or (mine and object:IsDescendantOf(mine)) or object:GetAttribute("AurHubOwned") == true then
                    return
                end
                -- D-227: on a teammate: Calm visuals; everything else (mobs, bosses, their attacks): Turn off mob effects
                local holder = object:FindFirstAncestorOfClass("Model")
                local onPlayer = holder and players:GetPlayerFromCharacter(holder) ~= nil
                if (onPlayer and config.mapLiteCalm == false) or (not onPlayer and config.mapLiteMobFx == false) then
                    return
                end
                local was = { enabled = object.Enabled }
                if object.ClassName == "ParticleEmitter" then -- a burst (Emit) ignores Enabled: nothing lives long enough to draw
                    was.lifetime = object.Lifetime
                    object.Lifetime = NumberRange.new(0)
                end
                object.Enabled = false
                ML.calmOff[object] = was
                ML.calmFx += 1
            elseif object.ClassName == "BillboardGui" then
                -- D-224 (the AA hub's Hide unit panels): the name and health panels over mobs and teammates, the costliest thing to redraw
                local model = config.mapLiteCalm ~= false and config.mapLiteCalmPanels ~= false and object:FindFirstAncestorOfClass("Model")
                if model and not OUR_PANELS[object.Name] and not ML.calmOff[object] and object:GetAttribute("AurHubOwned") ~= true
                    and model:FindFirstChildOfClass("Humanoid") and model ~= (me and me.Character) then
                    ML.calmOff[object] = { enabled = object.Enabled }
                    object.Enabled = false
                    ML.calmFx += 1
                end
            elseif object.ClassName == "Animator" and config.mapLiteCalm ~= false and config.mapLiteCalmAnims ~= false and not ML.calmAnims[object] then
                local model = object:FindFirstAncestorOfClass("Model")
                local owner = model and players:GetPlayerFromCharacter(model)
                if owner and owner ~= me then
                    ML.calmAnims[object] = true
                    local function stop(track)
                        if ML.on and gen == ML.gen then
                            pcall(function()
                                track:Stop(0)
                            end)
                        end
                    end
                    local okT, tracks = pcall(function()
                        return object:GetPlayingAnimationTracks()
                    end)
                    if okT then
                        for _, track in ipairs(tracks) do
                            stop(track)
                        end
                    end
                    ML.conns[#ML.conns + 1] = object.AnimationPlayed:Connect(stop)
                end
            end
        end
        function ML.calmStart(gen)
            ML.partsOn = config.mapLiteHideAttacks == true or config.mapLiteMobBox == true
            if config.mapLiteCalm == false and config.mapLiteMobFx == false and not ML.partsOn then
                return
            end
            ML.conns[#ML.conns + 1] = workspace.DescendantAdded:Connect(function(object)
                if ML.on and gen == ML.gen and (CALM_FX[object.ClassName] or object.ClassName == "Animator" or object.ClassName == "BillboardGui"
                    or (ML.partsOn and (object:IsA("BasePart") or object.ClassName == "Decal"))) then
                    task.defer(function()
                        if ML.on and gen == ML.gen and object.Parent then
                            pcall(ML.calmJudge, object, gen)
                        end
                    end)
                end
            end)
            task.spawn(function() -- one pass, spread over frames
                for i, object in ipairs(workspace:GetDescendants()) do
                    if not ML.on or gen ~= ML.gen then
                        return
                    end
                    if CALM_FX[object.ClassName] or object.ClassName == "Animator" or object.ClassName == "BillboardGui"
                        or (ML.partsOn and (object:IsA("BasePart") or object.ClassName == "Decal")) then
                        pcall(ML.calmJudge, object, gen)
                    end
                    if i % (config.mapLiteBatch or 400) == 0 then
                        task.wait()
                    end
                end
            end)
        end
        local function restore()
            for object, saved in pairs(ML.saved) do
                for key, value in pairs(saved) do
                    pcall(function()
                        object[key] = value[1]
                    end)
                end
            end
            ML.saved = {}
            ML.hidden, ML.kept, ML.effects, ML.walls = 0, 0, 0, 0
            for object, was in pairs(ML.calmOff) do -- D-223
                pcall(function()
                    object.Enabled = was.enabled
                    if was.lifetime then
                        object.Lifetime = was.lifetime
                    end
                end)
            end
            ML.calmOff, ML.calmAnims, ML.calmFx = setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" }), 0
            for object, was in pairs(ML.partsOff) do -- D-228
                pcall(function()
                    object.LocalTransparencyModifier = was
                end)
            end
            for _, box in pairs(ML.boxes) do
                pcall(box.Destroy, box)
            end
            ML.partsOff, ML.boxes = setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" })
            if ML.terrainSaved then -- D-050: the terrain's own colours back
                local terrain = workspace:FindFirstChildOfClass("Terrain")
                for mat, col in pairs(ML.terrainSaved) do
                    if terrain then
                        pcall(terrain.SetMaterialColor, terrain, mat, col)
                    end
                end
                ML.terrainSaved = nil
            end
        end
        local function disconnect()
            for _, connection in ipairs(ML.conns) do
                pcall(function()
                    connection:Disconnect()
                end)
            end
            ML.conns = {}
        end
        function ML.try(object, index) -- D-048: keeps the last error for diagnosis (a failing object is skipped)
            local ok, err = pcall(apply, object, index)
            if not ok then
                ML.lastError = tostring(err)
            end
        end
        function ML.set(on)
            on = on == true
            ML.gen += 1
            local gen = ML.gen
            disconnect()
            restore()
            ML.on = on
            if not on then
                return
            end
            if config.mapLiteLighting ~= false then
                -- D-133: shadows and post effects off while the map is simplified (restored with it); our menu blur stays
                pcall(function()
                    local lighting = game:GetService("Lighting")
                    remember(lighting, "GlobalShadows", false)
                    -- D-223: the rest of the AA hub's lighting switches
                    pcall(remember, lighting, "FogEnd", 9e9)
                    pcall(remember, lighting, "EnvironmentSpecularScale", 0)
                    pcall(remember, lighting, "EnvironmentDiffuseScale", 0)
                    if config.mapLiteNavy ~= false then -- D-227: flat light, so the colours show as they are, on a charcoal night
                        local white, none = Color3.new(1, 1, 1), Color3.new(0, 0, 0)
                        for key, value in pairs({ Ambient = white, OutdoorAmbient = white, Brightness = 0, ColorShift_Top = none, ColorShift_Bottom = none,
                            ClockTime = 0, FogColor = ML.NAVY.world }) do
                            pcall(remember, lighting, key, value)
                        end
                    end
                    for _, fx in ipairs(lighting:GetChildren()) do
                        if (fx:IsA("BloomEffect") or fx:IsA("SunRaysEffect") or fx:IsA("DepthOfFieldEffect") or fx:IsA("BlurEffect") or fx:IsA("ColorCorrectionEffect"))
                            and fx:GetAttribute("AurHubOwned") ~= true then
                            remember(fx, "Enabled", false)
                        elseif fx:IsA("Atmosphere") then
                            pcall(remember, fx, "Density", 0)
                            pcall(remember, fx, "Haze", 0)
                            pcall(remember, fx, "Glare", 0)
                        elseif fx:IsA("Sky") then
                            pcall(remember, fx, "StarCount", 0)
                            pcall(remember, fx, "CelestialBodiesShown", false)
                            if config.mapLiteNavy ~= false then
                                for _, side in ipairs({ "SkyboxBk", "SkyboxDn", "SkyboxFt", "SkyboxLf", "SkyboxRt", "SkyboxUp" }) do
                                    pcall(remember, fx, side, "")
                                end
                            end
                        end
                    end
                    local terrain = workspace:FindFirstChildOfClass("Terrain")
                    if terrain then
                        pcall(remember, terrain, "WaterWaveSize", 0)
                        pcall(remember, terrain, "WaterWaveSpeed", 0)
                        pcall(remember, terrain, "WaterReflectance", 0)
                        for _, c in ipairs(terrain:GetChildren()) do
                            if c:IsA("Clouds") then
                                pcall(remember, c, "Enabled", false)
                            end
                        end
                    end
                end)
            end
            ML.calmStart(gen) -- D-223
            local index = route()
            ML.routeKnown = index ~= nil -- D-077: set again once the dungeon's name (and so its path) is there
            if config.mapLiteSee == true and config.mapLiteFlat ~= false then
                -- D-050: one uniform grey - the terrain too (material colours and grass), drawing only
                pcall(function()
                    local terrain = workspace:FindFirstChildOfClass("Terrain")
                    if terrain then
                        ML.terrainSaved = ML.terrainSaved or {}
                        for _, mat in ipairs(Enum.Material:GetEnumItems()) do
                            local okGet, col = pcall(terrain.GetMaterialColor, terrain, mat)
                            if okGet and col then
                                if ML.terrainSaved[mat] == nil then
                                    ML.terrainSaved[mat] = col
                                end
                                pcall(terrain.SetMaterialColor, terrain, mat, config.mapLiteNavy ~= false and ML.NAVY.floor or config.mapLiteFloorColor or Color3.fromRGB(150, 150, 150))
                            end
                        end
                        remember(terrain, "Decoration", false)
                    end
                end)
                -- the walked floors inside the dungeon rooms: recoloured only (nothing hidden, enemies untouched)
                local function recolour(object)
                    pcall(function()
                        if config.mapLiteExcess ~= false and index and ML.isExcess(object, index) then
                            remember(object, "LocalTransparencyModifier", 1) -- D-228: not drawn; as solid as ever, nothing in the rooms is deleted
                            ML.hidden += 1
                            return
                        end
                        if object:IsA("BasePart") and object.Transparency < 1 and object.CanCollide
                            and not object:FindFirstAncestor("enemyFolder") and not isAttack(object)
                            and object.Name ~= "checkPoint" and object.Name ~= "barrier"
                            and (config.mapLiteRoomWalls ~= false or walkedOn(object, index)) then -- D-059: the rooms' walls too
                            remember(object, "Color", ML.floorColor(object))
                            local opacity = ML.opacity()
                            if opacity < 1 and object.LocalTransparencyModifier < 1 then
                                remember(object, "LocalTransparencyModifier", 1 - opacity) -- D-133: the rooms at 25% too
                            end
                            if object:IsA("MeshPart") then
                                pcall(remember, object, "TextureID", "")
                            end
                            if config.mapLitePlain ~= false then
                                pcall(function()
                                    if object.CustomPhysicalProperties == nil then
                                        remember(object, "CustomPhysicalProperties", PhysicalProperties.new(object.Material))
                                    end
                                    remember(object, "Material", Enum.Material.SmoothPlastic)
                                    remember(object, "Reflectance", 0)
                                end)
                            end
                        end
                    end)
                end
                local function grey(dungeon) -- D-076: now, and every part that loads in later
                    if not index then
                        return
                    end
                    ML.conns[#ML.conns + 1] = dungeon.DescendantAdded:Connect(function(object)
                        if ML.on and gen == ML.gen then
                            task.defer(function()
                                if ML.on and gen == ML.gen and object.Parent then
                                    recolour(object)
                                end
                            end)
                        end
                    end)
                    task.spawn(function()
                        for i, object in ipairs(dungeon:GetDescendants()) do
                            if not ML.on or gen ~= ML.gen then
                                return
                            end
                            recolour(object)
                            if i % (config.mapLiteBatch or 400) == 0 then
                                task.wait()
                            end
                        end
                    end)
                end
                local dungeon = workspace:FindFirstChild("dungeon")
                if dungeon then
                    grey(dungeon)
                else
                    ML.conns[#ML.conns + 1] = workspace.ChildAdded:Connect(function(child) -- D-076: not loaded yet
                        if ML.on and gen == ML.gen and child.Name == "dungeon" and ML.greyed ~= gen then
                            ML.greyed = gen
                            index = index or route() -- D-077
                            ML.routeKnown = index ~= nil
                            grey(child)
                        end
                    end)
                end
            end
            local function attach(root)
                ML.conns[#ML.conns + 1] = root.DescendantAdded:Connect(function(object)
                    if ML.on and gen == ML.gen then
                        task.defer(function()
                            if ML.on and gen == ML.gen and object.Parent then
                                ML.try(object, index)
                            end
                        end)
                    end
                end)
                task.spawn(function() -- in batches, so a big map does not freeze a frame
                    local list = root:GetDescendants()
                    for i, object in ipairs(list) do
                        if not ML.on or gen ~= ML.gen then
                            return
                        end
                        ML.try(object, index)
                        if i % (config.mapLiteBatch or 400) == 0 then
                            task.wait()
                        end
                    end
                    context.log("Map", ("simplified: %d parts hidden, %d solid parts kept, %d effects off%s"):format(
                        ML.hidden, ML.kept, ML.effects, index and " (walked route known)" or ""))
                end)
            end
            local waiting = {}
            for _, name in ipairs(ROOTS) do
                local root = workspace:FindFirstChild(name)
                if root then
                    attach(root)
                else
                    waiting[name] = true -- D-076: the map is not loaded yet - attach when it appears
                end
            end
            if next(waiting) then
                ML.conns[#ML.conns + 1] = workspace.ChildAdded:Connect(function(child)
                    if ML.on and gen == ML.gen and waiting[child.Name] then
                        waiting[child.Name] = nil
                        index = index or route() -- D-077: the dungeon's name may have arrived by now
                        ML.routeKnown = index ~= nil
                        context.log("Map", "the map loaded after the switch-on: simplifying it now")
                        attach(child)
                    end
                end)
            end
        end
        function ML.destroy()
            ML.destroyed = true
            ML.gen += 1
            disconnect()
            restore()
            ML.on = false
        end
        context.MapLite = ML
        pcall(function() -- D-226: 1.9.135's forced level outlives the script across a teleport (its default is Automatic; the game menu's slider is a separate setting)
            local rendering = settings().Rendering
            if rendering.QualityLevel ~= Enum.QualityLevel.Automatic then
                rendering.QualityLevel = Enum.QualityLevel.Automatic
            end
        end)
        function ML.charIn() -- D-227: the world is left alone while the game is still loading our character
            if config.mapLiteWaitChar == false then
                return true
            end
            local me = game:GetService("Players").LocalPlayer
            local ch = me and me.Character
            return ch ~= nil and ch:FindFirstChild("HumanoidRootPart") ~= nil
        end
        task.spawn(function()
            for _ = 1, 360 do
                if ML.destroyed then
                    return
                end
                if ML.charIn() then
                    if config.mapLite == true and not ML.on then
                        ML.set(true)
                    end
                    return
                end
                task.wait(0.5)
            end
        end)
        task.spawn(function() -- D-048: always on in Gilded Skies (the dungeon name may arrive a moment after start)
            for _ = 1, config.mapLiteNameWait or 180 do -- D-077: 3 minutes (was 30 s)
                task.wait(1)
                if ML.destroyed then
                    return
                end
                if dungeonKey() == "gildedskies" and config.mapLiteForceGilded ~= false and ML.charIn() then
                    local wasSee = config.mapLiteSee
                    config.mapLite, config.mapLiteSee = true, true
                    if not ML.on or wasSee ~= true or not ML.routeKnown then -- D-077: also when the path was not known
                        ML.set(true)
                    end
                    return
                end
            end
        end)
    end
    components.appLink = function(context) -- Ethereal Enchantment (Windows app) link: inventory and trades
        -- The app listens on this PC only (127.0.0.1:8766). Every few seconds this copy checks in with its account, server
        -- and the trade it's in, hands back results, and runs what the app asks: read the inventory, hold the bot, or one
        -- trade step (request, accept, add items, confirm, cancel) through the game's own trade remotes. The key the
        -- loader saved authorises it, so only the app that linked this key gets an answer. Nothing runs without the app.
        local config, runtimeState = context.CFG, context.RT
        local httpService = context.HttpService or game:GetService("HttpService")
        local players = game:GetService("Players")
        local remotes = game:GetService("ReplicatedStorage"):WaitForChild("remotes", 30)
        local URL = "http://127.0.0.1:8766/v1/link"
        local IDLE, AWAY = 3, 15 -- seconds between check-ins: app running / not running
        local localPlayer = players.LocalPlayer
        local results, held = {}, nil

        -- The in-game menu, mirrored in the app's Script tab: every control the menu builds is recorded here (its tab,
        -- section, label, kind, range or options, and its own getter and setter), so the app reads a setting the way
        -- the menu shows it and changes it the way a click would: same setter, same side effects, same save, and the
        -- in-game control redrawn. The menu is built after this component, so wrapping the kit now catches all of it.
        local menu = { list = {}, sections = setmetatable({}, { __mode = "k" }), session = tostring(os.time()) .. "-" .. tostring(math.random(1e6)) }
        local PAGES = { Farm = "Farm Settings", AltFarm = "Parties & Runs", ModDetect = "Mod Detection", AutoSell = "Auto Sell",
            Webhook = "Webhook", Visuals = "Visuals", Recorder = "Recorder", Inventory = "Inventory" }
        local kit = context.UIKit
        if type(kit) == "table" then
            local function wrap(name, read)
                local fn = kit[name]
                if type(fn) ~= "function" then
                    return
                end
                kit[name] = function(...)
                    local args = table.pack(...)
                    local res = fn(...)
                    pcall(function()
                        local e = read(table.unpack(args, 1, args.n))
                        if e then
                            e.kind, e.parent = name, args[1]
                            e.holder = type(res) == "table" and res.holder or nil
                            e.render = type(res) == "table" and res.render or nil
                            menu.list[#menu.list + 1] = e
                        end
                    end)
                    return res
                end
            end
            local function wrapSection(name)
                local fn = kit[name]
                if type(fn) ~= "function" then
                    return
                end
                kit[name] = function(parent, title, ...)
                    local res = fn(parent, title, ...)
                    pcall(function()
                        if type(res) == "table" and typeof(res.content) == "Instance" and type(title) == "string" then
                            menu.sections[res.content] = title
                        end
                    end)
                    return res
                end
            end
            wrapSection("section")
            wrapSection("group")
            wrap("toggle", function(_, label, get, set, order, desc)
                return type(get) == "function" and type(set) == "function" and { label = label, get = get, set = set, order = order, desc = desc }
            end)
            wrap("slider", function(_, label, sub, min, max, decimal, get, set, order, desc, step)
                return type(get) == "function" and type(set) == "function"
                    and { label = label, sub = sub, min = tonumber(min), max = tonumber(max), decimal = decimal == true, step = tonumber(step), get = get, set = set, order = order, desc = desc }
            end)
            wrap("rangeSlider", function(_, label, sub, min, max, get, set, order, desc, unit)
                return type(get) == "function" and type(set) == "function"
                    and { label = label, sub = sub, min = tonumber(min), max = tonumber(max), unit = unit, get = get, set = set, order = order, desc = desc }
            end)
            wrap("listInput", function(_, label, sub, get, set, order, desc, placeholder, max)
                return type(get) == "function" and type(set) == "function"
                    and { label = label, sub = sub, get = get, set = set, order = order, desc = desc, placeholder = placeholder, maxItems = tonumber(max) }
            end)
            wrap("dropdown", function(_, label, options, get, set, order, desc)
                return type(get) == "function" and type(set) == "function" and type(options) == "table"
                    and { label = label, options = options, get = get, set = set, order = order, desc = desc }
            end)
            wrap("textInput", function(_, label, get, set, order, desc)
                return type(get) == "function" and type(set) == "function" and { label = label, get = get, set = set, order = order, desc = desc }
            end)
        end
        local function plain(v) -- only what JSON can carry
            local t = type(v)
            if t == "boolean" or t == "string" or (t == "number" and v == v and v ~= math.huge and v ~= -math.huge) then
                return v
            end
            if t == "table" then
                local out = {}
                for i, x in ipairs(v) do
                    out[i] = plain(x)
                end
                return out
            end
            return nil
        end
        -- A closed section or another tab hides a control without it being off, so visibility isn't used. A setting that
        -- depends on another is greyed out in game (the kit's depend marks its row AurLocked) until that one is on.
        local function placeOf(e)
            local page, section, locked = nil, nil, false
            local f = e.holder or e.parent
            while typeof(f) == "Instance" do
                if not section and menu.sections[f] then
                    section = menu.sections[f]
                end
                if PAGES[f.Name] and f:IsA("GuiObject") then
                    page = f.Name
                    break
                end
                if f:GetAttribute("AurLocked") == true then
                    locked = true
                end
                f = f.Parent
            end
            return page, section, locked
        end
        -- A fingerprint of every setting's value, sent with each check-in: when it changes (a click in the in-game
        -- menu, a config load), the app re-reads the settings, so its Script tab follows the game.
        local function settingsRev()
            local parts = {}
            for _, e in ipairs(menu.list) do
                local ok, a, b = pcall(e.get)
                local v = ok and (e.kind == "rangeSlider" and { plain(a), plain(b) } or plain(a)) or nil
                if type(v) == "table" then
                    local items = {}
                    for i = 1, #v do
                        items[i] = tostring(v[i])
                    end
                    v = table.concat(items, "\1")
                end
                parts[#parts + 1] = tostring(v)
            end
            local s, h = table.concat(parts, "\0"), 5381
            for i = 1, #s do
                h = (h * 33 + string.byte(s, i)) % 2147483647
            end
            return tostring(#menu.list) .. "-" .. tostring(h)
        end
        local function settings()
            local out = {}
            for id, e in ipairs(menu.list) do
                local page, section, locked = placeOf(e)
                if page and type(e.label) == "string" then
                    local ok, a, b = pcall(e.get)
                    local value = nil
                    if ok then
                        value = e.kind == "rangeSlider" and { plain(a), plain(b) } or plain(a)
                    end
                    local opts = nil
                    if e.kind == "dropdown" then
                        opts = {}
                        for _, o in ipairs(e.options) do
                            if type(o) == "table" and plain(o.value) ~= nil then
                                opts[#opts + 1] = { value = plain(o.value), label = tostring(o.label or o.value) }
                            end
                        end
                    end
                    out[#out + 1] = {
                        id = id, page = page, pageName = PAGES[page], section = section, kind = e.kind, label = e.label,
                        desc = type(e.desc) == "string" and e.desc or nil, sub = type(e.sub) == "string" and e.sub or nil,
                        order = tonumber(e.order), value = value, min = e.min, max = e.max, decimal = e.decimal, step = e.step,
                        unit = type(e.unit) == "string" and e.unit or nil, options = opts, placeholder = type(e.placeholder) == "string" and e.placeholder or nil,
                        maxItems = e.maxItems, shown = true, locked = locked,
                    }
                end
            end
            return { session = menu.session, settings = out, rev = settingsRev() }
        end
        local function setOne(a)
            if a.session ~= menu.session then
                error("stale: the script restarted, reload the settings")
            end
            local e = menu.list[tonumber(a.id) or 0]
            if not e then
                error("no such setting")
            end
            local v = a.value
            if e.kind == "toggle" then
                e.set(v == true)
            elseif e.kind == "slider" then
                v = tonumber(v)
                if not v then
                    error("not a number")
                end
                if e.min and e.max then
                    v = math.clamp(v, math.min(e.min, e.max), math.max(e.min, e.max))
                end
                e.set(v)
            elseif e.kind == "rangeSlider" then
                local lo, hi = tonumber(type(v) == "table" and v[1]), tonumber(type(v) == "table" and v[2])
                if not (lo and hi) then
                    error("two numbers needed")
                end
                if lo > hi then
                    lo, hi = hi, lo
                end
                e.set(lo, hi)
            elseif e.kind == "listInput" then
                local list = {}
                for _, s in ipairs(type(v) == "table" and v or {}) do
                    s = tostring(s):match("^%s*(.-)%s*$")
                    if s ~= "" then
                        list[#list + 1] = s
                    end
                end
                e.set(list)
            elseif e.kind == "dropdown" then
                local found = false
                for _, o in ipairs(e.options) do
                    if type(o) == "table" and o.value == v then
                        found = true
                    end
                end
                if not found then
                    error("not one of the choices")
                end
                e.set(v)
            elseif e.kind == "textInput" then
                e.set(tostring(v or ""))
            else
                error("can't change this one from the app")
            end
            if type(e.render) == "function" then
                pcall(e.render)
            end
            if context.refreshAll then
                pcall(context.refreshAll)
            end
            if type(kit) == "table" and type(kit.refreshLive) == "function" then
                pcall(kit.refreshLive) -- re-locks / unlocks the settings that depend on this one
            end
            local ok, x, y = pcall(e.get)
            return ok and (e.kind == "rangeSlider" and { plain(x), plain(y) } or plain(x)) or nil
        end

        local function licenseKey()
            if context.savedStatsKey then
                return context.savedStatsKey()
            end
            local ok, k = pcall(function()
                return httpService:JSONDecode(readfile("Aur_Hub/configs/license.json")).key
            end)
            return ok and tostring(k or "") or ""
        end
        local function requestFn()
            return syn and syn.request or http and http.request or http_request or request
        end
        local function remote(name)
            return remotes and remotes:FindFirstChild(name)
        end

        -- the trade this account is in (workspace.trading.<trade>: Sender / Receiver ObjectValues, <name>Accepted bools)
        local function myTrade()
            local folder = workspace:FindFirstChild("trading")
            for _, t in ipairs(folder and folder:GetChildren() or {}) do
                local s, r = t:FindFirstChild("Sender"), t:FindFirstChild("Receiver")
                if (s and s.Value == localPlayer) or (r and r.Value == localPlayer) then
                    return t, s, r
                end
            end
            return nil
        end
        local function tradeState()
            local t, s, r = myTrade()
            if not t then
                return { open = false }
            end
            local function accepted(p)
                local b = p and t:FindFirstChild(p.Name .. "Accepted")
                return b ~= nil and b.Value == true
            end
            local items = 0
            for _, c in ipairs(s and s:GetChildren() or {}) do
                if c:IsA("StringValue") then
                    items += 1
                end
            end
            local cd = t:FindFirstChild("countdownBool")
            return {
                open = true,
                sender = s and s.Value and s.Value.Name or nil,
                receiver = r and r.Value and r.Value.Name or nil,
                senderItems = items,
                senderAccepted = accepted(s and s.Value),
                receiverAccepted = accepted(r and r.Value),
                countdown = cd and cd.Value == true and cd:FindFirstChild("countdown") and cd.countdown.Value or nil,
            }
        end

        local CATS = { weapons = { "weapon", 8 }, helmets = { "helmet", 8 }, chests = { "chest", 7 }, abilities = { "ability", 9 } }
        local function inventory()
            local inv = remote("reloadInvy"):InvokeServer()
            local out = {}
            for key, spec in pairs(CATS) do
                for slot, v in pairs(type(inv) == "table" and inv[key] or {}) do
                    local num = tonumber(string.sub(slot, spec[2]))
                    if num and type(v) == "table" then
                        local eq = v.equipped
                        if type(eq) == "table" then
                            eq = eq.q == true or eq.e == true or eq.q2 == true or eq.e2 == true
                        end
                        out[#out + 1] = {
                            cat = spec[1], num = num, name = tostring(v.name or "?"), rarity = tostring(v.rarity or ""):lower(),
                            phys = tonumber(v.physicalDamage or v.physicalPower), spell = tonumber(v.spellPower),
                            health = tonumber(v.health), level = tonumber(v.levelReq), sell = tonumber(v.sellPrice),
                            upgrade = tonumber(v.currentUpgrade), maxUpgrade = tonumber(v.maxUpgrades), equipped = eq == true,
                            image = v.imageId ~= nil and tostring(v.imageId) or nil, enchant = v.enchantment ~= nil and tostring(v.enchantment) or nil,
                        }
                    end
                end
            end
            return out
        end

        -- while a trade waits or runs: a dungeon run carries on to the end, but back in the lobby this account doesn't
        -- queue, host, join a party or rejoin a host (runtimeState.tradeHold, read by the lobby tick), so it stays put
        local function hold(on)
            held = on and true or nil
            runtimeState.tradeHold = held
            return true
        end
        local function where()
            local lb = context.LB
            local place = lb and lb.place or nil
            if place == "Lobby" then
                return "lobby"
            end
            if place == "Level" or place == "100+" then
                return "dungeon"
            end
            local dn = workspace:FindFirstChild("dungeonName")
            if dn and tostring(dn.Value) ~= "" then
                return "dungeon"
            end
            return game.PlaceId == 77649408247578 and "lobby" or "other"
        end
        local function waitFor(secs, check)
            local t0 = os.clock()
            while os.clock() - t0 < secs do
                local v = check()
                if v then
                    return v
                end
                task.wait(0.25)
            end
            return nil
        end

        local RUN = {
            inventory = function()
                return inventory()
            end,
            settings = function()
                return settings()
            end,
            setting = function(a)
                return setOne(a)
            end,
            hold = function(a)
                return hold(a.on == true)
            end,
            request = function(a)
                local p = players:FindFirstChild(tostring(a.to))
                if not p then
                    error("not_in_server")
                end
                return tostring(remote("sendTradeRequest"):InvokeServer(p))
            end,
            accept = function(a)
                local p = players:FindFirstChild(tostring(a.from))
                if not p then
                    error("not_in_server")
                end
                local r = remote("acceptTradeRequest"):InvokeServer(p)
                if r == "tradingDisabled" or r == "DND" or r == "busyTrading" then
                    error(tostring(r))
                end
                if not waitFor(6, function() return myTrade() end) then
                    error("trade_not_opened")
                end
                return tostring(r)
            end,
            add = function(a)
                local want = 0
                for _, it in ipairs(a.items or {}) do
                    remote("addItemToTradeFolder"):FireServer(tostring(it.cat), tonumber(it.num))
                    want += 1
                    task.wait(0.35)
                end
                local n = waitFor(8, function()
                    local s = tradeState()
                    return s.open and s.senderItems >= want and s.senderItems or nil
                end)
                if not n then
                    error("items_not_added (" .. tostring(tradeState().senderItems or 0) .. " of " .. want .. ")")
                end
                return n
            end,
            confirm = function()
                if not myTrade() then
                    error("no_trade")
                end
                remote("playerAcceptTrade"):FireServer()
                return true
            end,
            cancel = function()
                if myTrade() then
                    pcall(function() remote("changePlayerToNotBusyTrading"):FireServer() end)
                    pcall(function() remote("deleteTradeGuis"):FireServer() end)
                end
                hold(false)
                return true
            end,
        }

        local function run(c)
            local f = type(c) == "table" and RUN[c.cmd]
            if not f then
                return { id = c and c.id, ok = false, error = "unknown_command" }
            end
            local ok, v = pcall(f, type(c.args) == "table" and c.args or {})
            if ok then
                return { id = c.id, ok = true, data = v }
            end
            return { id = c.id, ok = false, error = tostring(v):gsub("^.-:%d+: ", ""):sub(1, 200) }
        end

        task.spawn(function()
            local pause = IDLE
            while not (runtimeState and runtimeState.destroyed) do
                local key, fn = licenseKey(), requestFn()
                if key == "" or type(fn) ~= "function" then
                    task.wait(AWAY)
                else
                    local names = {}
                    for _, p in ipairs(players:GetPlayers()) do
                        names[#names + 1] = p.Name
                    end
                    local sent = results
                    results = {}
                    local okBody, body = pcall(function()
                        return httpService:JSONEncode({
                            proto = 1, userId = localPlayer.UserId, name = localPlayer.Name, displayName = localPlayer.DisplayName,
                            placeId = game.PlaceId, jobId = game.JobId, players = names, trade = tradeState(), held = held ~= nil, where = where(),
                            settingsRev = #menu.list > 0 and select(2, pcall(settingsRev)) or nil, results = sent,
                        })
                    end)
                    local ok, res = false, nil
                    if okBody then
                        ok, res = pcall(fn, { Url = URL, Method = "POST", Body = body,
                            Headers = { ["Content-Type"] = "application/json", ["Authorization"] = "Bearer " .. key } })
                    end
                    local code = ok and type(res) == "table" and tonumber(res.StatusCode or res.status_code) or 0
                    if code == 200 then
                        local okJson, reply = pcall(function()
                            return httpService:JSONDecode(tostring(res.Body or res.body or ""))
                        end)
                        reply = okJson and type(reply) == "table" and reply or {}
                        for _, c in ipairs(type(reply.commands) == "table" and reply.commands or {}) do
                            results[#results + 1] = run(c)
                        end
                        pause = tonumber(reply.poll) and math.clamp(reply.poll / 1000, 0.3, 30) or IDLE
                        if #results > 0 then
                            pause = 0.05 -- hand the results back straight away
                        end
                    else
                        for _, r in ipairs(sent) do
                            results[#results + 1] = r -- the app wasn't there: keep them for next time
                        end
                        if held and code == 0 then
                            hold(false) -- the app is gone mid-trade: let the bot carry on
                        end
                        pause = AWAY
                    end
                    task.wait(pause)
                end
            end
            hold(false)
        end)
    end
    components.statsReporter = function(context) -- Ethereal Enchantment stats tracker, Stage 2 (docs/20_ETHEREAL_STATS_DESIGN.md)
        -- context.ST: the reporter the hooks in 05 / 10 / 11 / 17 call. It only reads state and never decides anything for
        -- the bot. The hooks only record (a table insert or a counter bump); ids, files, JSON and HTTP all happen in one
        -- worker thread (task.spawn, a 0.5 s tick). Nothing runs on the Heartbeat stages and an outage never blocks.
        -- Runs only when statsEnabled == true and a key is set. The key goes only into the Authorization header of
        -- POST <base>/v1/report; it is never logged, written to the queue files or put in a URL.
        -- D-144 / D-155: statsKey -> the local companion (127.0.0.1 / localhost); the key the old license gate saved
        -- (Aur_Hub/configs/license.json) -> the cloud (an https statsUrl, else 01's STATS_CLOUD_URL), so every account
        -- that ran with a key is grouped under its owner there. That key never goes to a plain-http address.
        local config, runtimeState = context.CFG, context.RT
        local httpService = context.HttpService or game:GetService("HttpService")
        local players = game:GetService("Players")
        local BRAND, PROTO = "Ethereal Enchantment", 1
        local TICK, CADENCE, STATUS_EVERY, DRAIN_GAP = 0.5, 30, 60, 2
        local BACKOFF_MIN, BACKOFF_MAX, BATCH, CAP = 30, 300, 100, 2000
        local MAX_BYTES = 256 * 1024 -- a request body stays well under the companion's 1 MB limit (413)
        local RUN_BUCKET = 600 -- runId = <JobId>:<start os.time() rounded down to 10 min>, shared on this PC
        local RARITIES = { "common", "uncommon", "rare", "epic", "legendary", "ultimate" }
        local ST = { sent = 0, failed = 0, mobs = 0, note = "off", wantsRodin = false }
        context.ST = ST

        local localPlayer = players.LocalPlayer
        local userId = tonumber(localPlayer and localPlayer.UserId) or 0
        local SEQ_FILE = "Aur_Hub/data/stats_seq_" .. tostring(userId) .. ".json"
        local QUEUE_FILE = "Aur_Hub/data/stats_queue_" .. tostring(userId) .. ".jsonl"
        local RUNS_FILE = "Aur_Hub/data/stats_runs.json" -- JobId -> runId start, so accounts on this PC agree

        local inbox = {} -- raw records from the hooks (worker-only from here on)
        local queue = {} -- events waiting for an acknowledgement, oldest first
        local queued = {} -- id -> true
        local lineOf = {} -- id -> its JSON line (encoded once; the file is rewritten from these)
        local cur = nil -- the run being tracked: { run = <webhooks.run>, gold, gems, mob, boss, runId, partial }
        local ended = nil -- D-148: { run, rec } - the run_end recorded at the completion (its loot merged in later)
        local held = {} -- D-148: event id -> os.clock() from which it may be sent (a run_end waiting for its loot)
        local inflight = {} -- D-148: the ids in the request that is out
        local drainInbox, endFields -- D-148: worker-side, also called by the completion hook
        local S = {
            started = false,
            seq = 0,
            copyId = nil,
            lastRun = nil, -- { job, id, startSent, endSent } (persisted with the seq)
            sessionStart = nil,
            nextSendAt = 0,
            backoff = 0,
            retryAt = nil,
            flush = false,
            lastSentAt = nil,
            problem = nil, -- nil | "rejected" (401 / 403) | "unreachable" | "nohttp"
            rejectText = nil,
            maxBatch = 100,
            rejectedIds = 0, -- events the companion refused (its "rejected" list): removed, never retried
            rejectReason = nil,
            why = nil,
            rejectedKey = nil,
            rewrite = false,
            resetSeen = nil,
            statusAt = nil,
            loggedProblem = nil,
        }

        local function trim(s)
            return (tostring(s or ""):match("^%s*(.-)%s*$"))
        end
        local function statsBase()
            local u = trim(config.statsUrl):gsub("/+$", "")
            if not (u:match("^https?://[%w%.%-%[%]:]+") ) then
                return ""
            end
            return u
        end
        local savedKey = { at = -math.huge, key = "" }
        local function licenseKey() -- D-155: the key system is gone; a key the old gate saved still reports (read only)
            if os.clock() - savedKey.at < 10 then
                return savedKey.key
            end
            local ok, k = pcall(function()
                local f = "Aur_Hub/configs/license.json"
                if not (isfile and readfile and isfile(f)) then
                    return ""
                end
                local t = httpService:JSONDecode(readfile(f))
                if type(t) ~= "table" or t.revoked == true then
                    return ""
                end
                return tostring(t.key or "")
            end)
            savedKey.at, savedKey.key = os.clock(), ok and trim(k) or ""
            return savedKey.key
        end
        context.savedStatsKey = licenseKey -- D-155: for the debug copy's redaction (18)
        local function cloudBase() -- D-155: an https statsUrl, else the build's stats cloud
            local u = statsBase()
            if u:match("^https://") then
                return u
            end
            return trim(config.STATS_CLOUD_URL):gsub("/+$", "")
        end
        local function isLocal(u)
            local host = (u:match("^https?://([^/]+)") or ""):lower():gsub(":%d+$", "")
            return host == "127.0.0.1" or host == "localhost" or host == "[::1]"
        end
        local function route() -- (key, base): statsKey wins for the local companion, the license key for the cloud
            local sk, su = trim(config.statsKey), statsBase()
            if sk ~= "" and su ~= "" and isLocal(su) then
                return sk, su
            end
            local lk = licenseKey()
            local lb = lk ~= "" and cloudBase() or ""
            if lk ~= "" and lb ~= "" then
                return lk, lb
            end
            return sk, su
        end
        local function key()
            return (route())
        end
        local function baseUrl()
            local _, b = route()
            return b
        end
        local function active()
            return config.statsEnabled == true and key() ~= "" and not (runtimeState and runtimeState.destroyed)
        end
        -- the key, wherever it might show up in text we keep (an executor's error message), becomes <stats key>
        local function scrub(text)
            text = tostring(text or "")
            for _, k in ipairs({ trim(config.statsKey), licenseKey() }) do -- D-144: both keys
                if #k >= 3 then
                    local out, from = {}, 1
                    while true do
                        local a, b = text:find(k, from, true)
                        if not a then
                            break
                        end
                        out[#out + 1] = text:sub(from, a - 1) .. "<stats key>"
                        from = b + 1
                    end
                    out[#out + 1] = text:sub(from)
                    text = table.concat(out)
                end
            end
            return text:gsub("[Bb]earer%s+%S+", "Bearer <stats key>"):sub(1, 160)
        end
        local function log(msg)
            if context.log then
                pcall(context.log, "Stats", scrub(msg))
            end
        end
        local function push(rec)
            if #inbox < CAP or rec.k == "run_end" then -- the worker drains this every 0.5 s; run_end is never dropped
                inbox[#inbox + 1] = rec
            end
        end
        local function leader(name)
            local p = players.LocalPlayer
            local ls = p and p:FindFirstChild("leaderstats")
            local v = ls and ls:FindFirstChild(name)
            return v and tonumber(v.Value) or nil
        end
        local function known(s)
            s = s ~= nil and tostring(s) or ""
            if s == "" or s == "?" or s == "Unknown" or s == "unknown" then
                return nil
            end
            return s
        end

        -- hooks (record only) --------------------------------------------------------------------------------------
        ST.active = active
        ST.url = function()
            return baseUrl()
        end
        ST.noteRunStart = function(run, gold, gems) -- 17 webhooks.start
            if not active() or type(run) ~= "table" then
                cur = nil
                return
            end
            cur = { run = run, gold = gold, gems = gems, mob = 0, boss = 0 }
            ST.mobs = 0
            push({ k = "run_start", at = os.time(), cur = cur })
        end
        ST.noteKill = function(isBoss) -- 17 noteKillAll (05's kill notes): counted for the tracked run only
            local c = cur
            if not c or c.ended then
                return
            end
            if isBoss then
                c.boss += 1
            else
                c.mob += 1
                ST.mobs = c.mob
            end
        end
        ST.noteDeath = function() -- 17's death detector (it already skips the reset grace after selfResetAt)
            if not active() then
                return
            end
            local r = runtimeState and runtimeState.selfResetAt
            if type(r) == "number" and os.clock() - r < (tonumber(config.whResetGrace) or 5) then
                return
            end
            push({ k = "death", at = os.time(), cur = cur })
        end
        ST.noteSell = function(count, plan, after) -- 11 sellNow, after the bag check
            if not active() or not tonumber(count) or tonumber(count) <= 0 then
                return
            end
            push({ k = "sell", at = os.time(), count = tonumber(count), plan = plan, after = after })
        end
        local function endRec(run, won, gold, gems) -- one run_end record (the tracked run's counts end here)
            local c = cur ~= nil and cur.run == run and cur or nil
            local secs = nil
            if won and context.WH and context.WH.runSecs then
                local ok, v = pcall(context.WH.runSecs, run)
                secs = ok and tonumber(v) or nil
            end
            local rec = { k = "run_end", at = os.time(), cur = c, run = run, won = won and true or false, secs = secs,
                gold = gold, gems = gems }
            if c then
                c.ended = true
                rec.mob, rec.boss = c.mob, c.boss
                cur = nil
            end
            return rec
        end
        -- D-148: 17 at the completion (the run monitor, both results; webhooks.finish's start too). The run_end goes into
        -- the queue FILE now with what is known (result, clear time, kills; gold / gems only once credited). The teleport
        -- back to the lobby ends an alt's script ~5-6 s after the end, long before its loot read: the next copy then
        -- sends this record under its id. It stays on disk, out of the batches, for `hold` s so the loot can join it.
        ST.noteRunEnd = function(run, won, gold, gems, hold)
            if not active() or type(run) ~= "table" or (ended and ended.run == run) then
                return
            end
            local rec = endRec(run, won, gold, gems)
            rec.early, rec.hold = true, tonumber(hold) or 0
            ended = { run = run, rec = rec }
            push(rec)
            if S.ready and drainInbox then
                local ok, err = pcall(drainInbox) -- synchronous: id, seq file and queue file before anything yields
                if not ok then
                    log("run_end could not be written: " .. tostring(err))
                end
            end
        end
        -- 17 webhooks.finish (both paths), after the loot read: measured = the loot diff really has a start and an end inventory
        ST.reportRun = function(run, won, items, measured, gold, gems)
            if not active() or type(run) ~= "table" then
                return
            end
            if ended and ended.run == run then -- D-148: the run_end exists: merge the loot in while it is unsent
                local rec = ended.rec
                rec.items, rec.measured, rec.early, rec.hold = items, measured == true, nil, nil
                if type(gold) == "number" then -- the later balance (a late credit); never below the one at the end
                    rec.gold = type(rec.gold) == "number" and math.max(rec.gold, gold) or gold
                end
                if type(gems) == "number" then
                    rec.gems = type(rec.gems) == "number" and math.max(rec.gems, gems) or gems
                end
                local e = rec.ev -- nil: still in the inbox, the worker builds it with the loot
                if e and queued[e.id] and not inflight[e.id] and endFields then
                    local ok = pcall(endFields, e, rec)
                    if ok then
                        lineOf[e.id] = nil
                        S.rewrite = true -- the file gets the loot on the next tick, before that tick sends
                    end
                end
                if e then
                    held[e.id] = nil
                end
                S.flush = true
                return
            end
            local rec = endRec(run, won, gold, gems)
            rec.items, rec.measured = items, measured == true
            push(rec)
            S.flush = true
        end
        ST.noteRodinDrops = function() end -- Rodin's drops come after run_end; the protocol has no event for them
        ST.noteFirstCast = function() end -- nothing to report
        ST.emit = function(kind, fields)
            if not active() or type(kind) ~= "string" or kind == "" then
                return
            end
            push({ k = kind, at = os.time(), fields = fields, cur = cur })
        end
        ST.flush = function()
            S.flush = true
        end
        ST.queued = function()
            return #queue + #inbox
        end
        ST.status = function() -- (short text, healthy)
            if config.statsEnabled ~= true then
                return "off", false
            end
            if key() == "" then
                return "off (no key)", false
            end
            if baseUrl() == "" then
                return "no address (statsUrl)", false
            end
            if S.problem == "rejected" and S.rejectedKey == key() then
                return S.rejectText or "key rejected", false
            end
            local wait = S.retryAt and math.max(math.ceil(S.retryAt - os.clock()), 0)
            if S.problem == "nohttp" then
                return ("no HTTP in this executor, retry in %ds"):format(wait or 0), false
            end
            if S.problem == "unreachable" then
                return ("service unreachable, retry in %ds"):format(wait or 0), false
            end
            local n = #queue + #inbox
            local refused = S.rejectedIds > 0 and (", %d refused (%s)"):format(S.rejectedIds, S.rejectReason or "?") or ""
            if S.lastSentAt then
                return ("queued %d, last sent %ds ago%s"):format(n, math.floor(os.clock() - S.lastSentAt), refused), true
            end
            return ("queued %d, nothing sent yet%s"):format(n, refused), true
        end

        -- worker side ----------------------------------------------------------------------------------------------
        local function readJson(path)
            local ok, v = pcall(function()
                if not (isfile and readfile and isfile(path)) then
                    return nil
                end
                return httpService:JSONDecode(readfile(path))
            end)
            return ok and type(v) == "table" and v or nil
        end
        local function writeRaw(path, body)
            if not writefile then
                return false
            end
            pcall(context.ensureFolders)
            return (pcall(writefile, path, body))
        end
        local function writeJson(path, v)
            local ok, body = pcall(function()
                return httpService:JSONEncode(v)
            end)
            return ok and writeRaw(path, body)
        end
        local function saveSeq()
            return writeJson(SEQ_FILE, { seq = S.seq, copyId = S.copyId, lastRun = S.lastRun })
        end
        local function encodeLines(list)
            local lines = {}
            for _, e in ipairs(list) do
                local line = lineOf[e.id]
                if not line then
                    local ok, l = pcall(function()
                        return httpService:JSONEncode(e)
                    end)
                    line = ok and l .. "\n" or nil
                    lineOf[e.id] = line
                end
                lines[#lines + 1] = line
            end
            return table.concat(lines)
        end
        local function rewriteQueue()
            S.rewrite = false
            writeRaw(QUEUE_FILE, encodeLines(queue))
        end
        local function appendQueue(list)
            if #list == 0 then
                return
            end
            local body = encodeLines(list)
            local ok = false
            if appendfile and isfile then
                ok = pcall(function()
                    if isfile(QUEUE_FILE) then
                        appendfile(QUEUE_FILE, body)
                    else
                        writefile(QUEUE_FILE, body)
                    end
                end)
            end
            if not ok then
                rewriteQueue()
            end
        end
        local function seqOf(id)
            return tonumber(tostring(id):match(":(%d+)$")) or 0
        end
        local function capQueue()
            while #queue > CAP do
                local drop = nil
                for i, e in ipairs(queue) do
                    if e.kind == "status" then
                        drop = i
                        break
                    end
                end
                if not drop then
                    for i, e in ipairs(queue) do
                        if e.kind ~= "run_end" then
                            drop = i
                            break
                        end
                    end
                end
                if not drop then
                    break -- only run_end left: never dropped
                end
                queued[queue[drop].id], lineOf[queue[drop].id] = nil, nil
                table.remove(queue, drop)
                S.rewrite = true
            end
        end
        local function startUp()
            S.started = true
            S.sessionStart = os.time()
            local saved = readJson(SEQ_FILE)
            if saved then
                S.seq = math.max(tonumber(saved.seq) or 0, 0)
                S.copyId = type(saved.copyId) == "string" and saved.copyId or nil
                S.lastRun = type(saved.lastRun) == "table" and saved.lastRun or nil
            end
            if not S.copyId then
                local ok, g = pcall(function()
                    return httpService:GenerateGUID(false)
                end)
                S.copyId = ok and type(g) == "string" and g or ("c" .. tostring(os.time()) .. tostring(math.random(1e5, 1e6)))
            end
            -- the queue a previous copy (or a crash, or a teleport) left: delivered again with the same ids
            pcall(function()
                if not (isfile and readfile and isfile(QUEUE_FILE)) then
                    return
                end
                local n = 0
                for line in tostring(readfile(QUEUE_FILE)):gmatch("[^\n]+") do
                    n += 1
                    if n % 200 == 0 then
                        task.wait() -- a long queue file is read over several frames
                    end
                    local ok, e = pcall(function()
                        return httpService:JSONDecode(line)
                    end)
                    if ok and type(e) == "table" and type(e.id) == "string" and type(e.kind) == "string" and not queued[e.id] then
                        queued[e.id], lineOf[e.id] = true, line .. "\n"
                        queue[#queue + 1] = e
                        S.seq = math.max(S.seq, seqOf(e.id)) -- never reuse an id, even without the seq file
                    end
                end
            end)
            capQueue()
            S.ready = true -- D-148: the old queue is loaded and the seq is past its ids
            S.resetSeen = runtimeState and runtimeState.selfResetAt
            log(("reporter on (%d queued from before)"):format(#queue))
        end
        local function sharedRunStart(job, at)
            local runs = readJson(RUNS_FILE) or {}
            local t = tonumber(runs[job])
            if t and math.abs(at - t) < 3600 then
                return t
            end
            t = math.floor(at / RUN_BUCKET) * RUN_BUCKET
            local keep = { [job] = t }
            for j, v in pairs(runs) do
                if type(j) == "string" and tonumber(v) and at - tonumber(v) < 6 * 3600 then
                    keep[j] = keep[j] or tonumber(v)
                end
            end
            writeJson(RUNS_FILE, keep)
            return t
        end
        local function jobId()
            local j = tostring(game.JobId or "")
            return j ~= "" and j or "nojob"
        end
        local function runIdFor(at)
            local job = jobId()
            if S.lastRun and S.lastRun.job == job and type(S.lastRun.id) == "string" then
                return S.lastRun.id, true
            end
            local id = job .. ":" .. tostring(sharedRunStart(job, at))
            S.lastRun = { job = job, id = id }
            return id, false
        end
        local function partyKey()
            local ok, id = pcall(function()
                local AF = context.AF
                if not (AF and AF.role and AF.role() ~= nil and AF.partyOf and localPlayer) then
                    return nil
                end
                local p = AF.partyOf(localPlayer.Name)
                return p and p.id
            end)
            return ok and type(id) == "string" and id ~= "" and id or nil
        end
        local function soldNames(plan, after)
            local names, present = {}, nil
            if type(after) == "table" then
                present = {}
                for _, cat in pairs(after) do
                    if type(cat) == "table" then
                        for _, it in pairs(cat) do
                            if type(it) == "table" and type(it.UniqueItemID) == "string" then
                                present[it.UniqueItemID] = true
                            end
                        end
                    end
                end
            end
            for _, it in ipairs(type(plan) == "table" and plan or {}) do
                local name = type(it) == "table" and it.name or type(it) == "string" and it or nil
                local uid = type(it) == "table" and type(it.uid) == "string" and it.uid or nil
                if name and not (uid and present and present[uid]) and #names < 100 then
                    names[#names + 1] = tostring(name):sub(1, 80)
                end
            end
            return names
        end
        local function snapshot()
            local s = { at = os.time() }
            pcall(function()
                local dn = workspace:FindFirstChild("dungeonName")
                local map = dn and known(dn.Value)
                s.inDungeon = map ~= nil
                s.map = map
                local run = context.WH and context.WH.run
                s.difficulty = run and known(run.difficulty) or nil
                local act = runtimeState and runtimeState.movementState
                if type(act) == "string" and act ~= "" then
                    s.activity = act:sub(1, 80)
                end
            end)
            s.gold, s.gems, s.level = leader("Gold"), leader("Gems"), leader("Level")
            return s
        end
        -- D-148: a run_end's fields from its record - at the build, and again when the loot is merged in
        endFields = function(e, rec)
            local c = rec.cur
            local whole = c ~= nil and not c.partial
            e.clearSecs, e.goldEarned, e.gemsEarned, e.items, e.itemCount, e.mobKills, e.bossKills = nil, nil, nil, nil, nil, nil, nil
            e.loot = nil
            e.result = rec.won and "win" or "loss"
            if rec.won and rec.secs and rec.secs > 0 then
                e.clearSecs = rec.secs
            end
            local function delta(now, was) -- at the completion the reward may not be credited yet: left out, never 0
                if not (whole and type(was) == "number" and type(now) == "number") then
                    return nil
                end
                if rec.early and now - was <= 0 then
                    return nil
                end
                return now - was
            end
            e.goldEarned = delta(rec.gold, c and c.gold)
            e.gemsEarned = delta(rec.gems, c and c.gems)
            if rec.measured and type(rec.items) == "table" and not (c and c.partial) then
                local by = {}
                for _, r in ipairs(RARITIES) do
                    by[r] = 0
                end
                for _, it in ipairs(rec.items) do
                    local r = type(it) == "table" and tostring(it.rarity or ""):lower() or ""
                    if by[r] then
                        by[r] += 1
                    end
                end
                e.items, e.itemCount = by, #rec.items
                -- the drops themselves (name, rarity, category, value) for the Windows app's Items tab; the license server's
                -- relay keeps them and leaves them out of what it passes on to the stats worker
                local loot = {}
                for _, it in ipairs(rec.items) do
                    if type(it) == "table" and it.name ~= nil and #loot < 60 then
                        loot[#loot + 1] = { n = tostring(it.name):sub(1, 80), r = tostring(it.rarity or ""):lower(), c = it.cat ~= nil and tostring(it.cat) or nil,
                            v = tonumber(it.sell or it.value), im = it.img,
                            p = tonumber(it.phys), s = tonumber(it.spell), h = tonumber(it.hp) }
                    end
                end
                e.loot = #loot > 0 and loot or nil
            end
            if whole then
                e.mobKills, e.bossKills = rec.mob, rec.boss
            end
        end
        -- one raw record -> one event (or nil); ids are assigned by the caller
        local function build(rec)
            local e = { kind = rec.k, at = rec.at }
            local c = rec.cur
            if rec.k == "run_start" then
                local id, reused = runIdFor(rec.at)
                c.runId = id
                if reused then
                    c.partial = true -- this copy started mid-run (re-executed): its counts would be partial
                    if S.lastRun.startSent then
                        return nil
                    end
                end
                S.lastRun.startSent = true
                e.runId = id
                e.dungeon = known(c.run.dungeon)
                e.difficulty = known(c.run.difficulty)
                e.partyKey = partyKey()
            elseif rec.k == "run_end" then
                local id = c and c.runId
                if not id then
                    local at = rec.at - math.floor(os.clock() - (tonumber(rec.run.at) or os.clock()))
                    id = runIdFor(at)
                end
                if S.lastRun and S.lastRun.id == id and S.lastRun.endSent then
                    return nil
                end
                if S.lastRun and S.lastRun.id == id then
                    S.lastRun.endSent = true
                end
                e.runId = id
                endFields(e, rec)
            elseif rec.k == "death" or rec.k == "reset" then
                e.runId = c and c.runId or nil
            elseif rec.k == "sell" then
                e.count = rec.count
                e.names = soldNames(rec.plan, rec.after)
            elseif rec.k == "session_start" then
                e.version = context.SCRIPT_VERSION
            elseif rec.k == "status" then
                for k, v in pairs(rec.snap or (type(rec.fields) == "table" and rec.fields) or {}) do
                    if k ~= "id" and k ~= "kind" then
                        e[k] = v
                    end
                end
            else
                if type(rec.fields) == "table" then
                    for k, v in pairs(rec.fields) do
                        local t = type(v)
                        if type(k) == "string" and k ~= "id" and k ~= "kind" and (t == "string" or t == "number" or t == "boolean" or t == "table") then
                            e[k] = v
                        end
                    end
                end
                if e.runId == nil and c and c.runId then
                    e.runId = c.runId
                end
            end
            return e
        end
        drainInbox = function()
            if #inbox == 0 then
                return
            end
            local list = inbox
            inbox = {}
            local fresh = {}
            for _, rec in ipairs(list) do
                local ok, e = pcall(build, rec)
                if ok and e then
                    S.seq += 1
                    e.id = ("%d:%s:%s:%d"):format(userId, e.runId or ("s" .. tostring(S.sessionStart)), e.kind, S.seq)
                    rec.ev = e -- D-148: the loot is merged into this event while it waits
                    if tonumber(rec.hold) and rec.hold > 0 then
                        held[e.id] = os.clock() + rec.hold
                    end
                    fresh[#fresh + 1] = e
                elseif not ok then
                    log("an event could not be built: " .. tostring(e))
                end
            end
            if #fresh == 0 then
                return
            end
            saveSeq() -- before the events can be sent: a re-executed copy never reuses these ids
            for _, e in ipairs(fresh) do
                queued[e.id] = true
                queue[#queue + 1] = e
            end
            appendQueue(fresh)
            capQueue()
        end
        local function requestFn()
            return syn and syn.request or http and http.request or http_request or request
        end
        local function fail(problem, why)
            ST.failed += 1
            S.backoff = S.backoff > 0 and math.min(S.backoff * 2, BACKOFF_MAX) or BACKOFF_MIN
            S.retryAt = os.clock() + S.backoff
            S.problem, S.why = problem, why
            if S.loggedProblem ~= problem then
                S.loggedProblem = problem
                log(("%s (%s); retrying with backoff"):format(problem == "nohttp" and "no HTTP request function" or "service unreachable", scrub(why)))
            end
        end
        local function send()
            local k, base = key(), baseUrl()
            if base == "" or #queue == 0 then
                return
            end
            local ready = {} -- D-148: a run_end waiting for its loot stays on disk, out of the batches
            for _, e in ipairs(queue) do
                if not held[e.id] then
                    ready[#ready + 1] = e
                end
            end
            if #ready == 0 then
                return
            end
            if base:find(k, 1, true) then
                S.problem, S.why = "unreachable", "the address contains the key"
                return
            end
            local now = os.clock()
            if S.retryAt and now < S.retryAt then
                return
            end
            if not S.flush and now < S.nextSendAt then
                return
            end
            S.flush = false
            local fn = requestFn()
            if not fn then
                fail("nohttp", "this executor has no HTTP request function")
                return
            end
            local p = players.LocalPlayer
            local planned = math.min(S.maxBatch, BATCH, #ready)
            local batch, okBody, body
            local status = snapshot()
            while true do
                batch = {}
                for i = 1, planned do
                    batch[i] = ready[i]
                end
                okBody, body = pcall(function()
                    return httpService:JSONEncode({
                        proto = PROTO,
                        account = { userId = userId, name = p and p.Name or nil, displayName = p and p.DisplayName or nil },
                        client = { brand = BRAND, version = context.SCRIPT_VERSION, copyId = S.copyId, sentAt = os.time() },
                        status = status,
                        events = batch,
                    })
                end)
                if not okBody or #body <= MAX_BYTES or planned <= 1 then
                    break
                end
                planned = math.ceil(planned / 2)
            end
            if not okBody then
                fail("unreachable", "could not encode the batch")
                return
            end
            inflight = {}
            for _, e in ipairs(batch) do
                inflight[e.id] = true
            end
            local ok, res = pcall(fn, {
                Url = base .. "/v1/report",
                Method = "POST",
                Headers = { ["Content-Type"] = "application/json", ["Authorization"] = "Bearer " .. k },
                Body = body,
            })
            inflight = {}
            if runtimeState and runtimeState.destroyed then
                return -- re-executed while this request was out: the new copy owns the files now (it resends; duplicates are fine)
            end
            if not ok then
                fail("unreachable", tostring(res))
                return
            end
            local code = type(res) == "table" and tonumber(res.StatusCode or res.status_code) or 0
            if code == 401 or code == 403 then -- 401 unknown / revoked key, 403 the key belongs to another account
                ST.failed += 1
                S.problem, S.why, S.rejectedKey = "rejected", "HTTP " .. code, k
                S.rejectText = code == 403 and "key bound to another account" or "key rejected"
                S.retryAt, S.backoff = nil, 0
                if S.loggedProblem ~= "rejected" then
                    S.loggedProblem = "rejected"
                    log(S.rejectText .. " (HTTP " .. code .. "): sending stopped until the key changes")
                end
                return
            end
            if code == 413 then -- too large: smaller batches from now on; one event alone that is too large is dropped
                ST.failed += 1
                if #batch > 1 then
                    S.maxBatch = math.max(1, math.floor(#batch / 2))
                else
                    local id = batch[1] and batch[1].id
                    for i, e in ipairs(queue) do
                        if e.id == id then
                            table.remove(queue, i)
                            queued[id], lineOf[id] = nil, nil
                            break
                        end
                    end
                    S.rejectedIds += 1
                    S.rejectReason = "too large"
                    rewriteQueue()
                end
                log(("request too large (HTTP 413): batches of %d from now on"):format(S.maxBatch))
                S.nextSendAt = os.clock() + DRAIN_GAP
                return
            end
            if code < 200 or code >= 300 then
                fail("unreachable", "HTTP " .. code)
                return
            end
            local okJson, reply = pcall(function()
                return httpService:JSONDecode(tostring(res.Body or res.body or ""))
            end)
            if not okJson or type(reply) ~= "table" then
                fail("unreachable", "HTTP " .. code .. " without a JSON reply")
                return
            end
            local done = {}
            for _, list in ipairs({ reply.accepted, reply.duplicate }) do
                for _, id in ipairs(type(list) == "table" and list or {}) do
                    done[tostring(id)] = true
                end
            end
            -- refused events ({id, reason}) leave the queue too, so they are never retried forever
            local refused, reason = 0, nil
            for _, r in ipairs(type(reply.rejected) == "table" and reply.rejected or {}) do
                local id = type(r) == "table" and r.id or r
                if id ~= nil and queued[tostring(id)] and not done[tostring(id)] then
                    done[tostring(id)] = true
                    refused += 1
                    reason = type(r) == "table" and r.reason ~= nil and tostring(r.reason) or reason
                end
            end
            if refused > 0 then
                S.rejectedIds += refused
                S.rejectReason = scrub(reason or "no reason given"):sub(1, 60)
                log(("%d event%s refused by the companion: %s"):format(refused, refused == 1 and "" or "s", S.rejectReason))
            end
            local keep, removed = {}, 0
            for _, e in ipairs(queue) do
                if done[e.id] then
                    queued[e.id], lineOf[e.id] = nil, nil
                    removed += 1
                else
                    keep[#keep + 1] = e
                end
            end
            queue = keep
            ST.sent += removed - refused
            S.lastSentAt, S.backoff, S.retryAt = os.clock(), 0, nil
            S.maxBatch = math.min(BATCH, S.maxBatch * 2) -- back up after a 413
            if S.problem then
                log("delivering again")
            end
            S.problem, S.why, S.loggedProblem = nil, nil, nil
            S.nextSendAt = os.clock() + ((#batch >= math.min(S.maxBatch, BATCH) and #queue > 0 and removed > 0) and DRAIN_GAP or CADENCE)
            if removed > 0 then
                rewriteQueue()
            end
        end
        local function tick()
            if not active() then
                S.resetSeen = runtimeState and runtimeState.selfResetAt -- nothing stale when switched on later
                S.statusAt = nil
                return
            end
            if not S.started then
                startUp()
                push({ k = "session_start", at = os.time() })
                S.nextSendAt = os.clock() -- the first batch goes out right away
            end
            if S.problem == "rejected" and S.rejectedKey ~= key() then
                S.problem, S.why, S.rejectedKey, S.loggedProblem = nil, nil, nil, nil
                S.flush = true
            end
            local r = runtimeState and runtimeState.selfResetAt
            if type(r) == "number" and r ~= S.resetSeen then
                push({ k = "reset", at = os.time() - math.max(math.floor(os.clock() - r), 0), cur = cur })
            end
            S.resetSeen = r
            if not S.statusAt or os.clock() - S.statusAt >= STATUS_EVERY then
                S.statusAt = os.clock()
                push({ k = "status", at = os.time(), snap = snapshot() })
            end
            for id, t in pairs(held) do -- D-148: the loot did not come in time: the run_end goes as it is
                if os.clock() >= t then
                    held[id] = nil
                    S.flush = true
                end
            end
            drainInbox()
            if S.rewrite then
                rewriteQueue()
            end
            if not (S.problem == "rejected") then
                send()
            end
        end
        task.spawn(function()
            local loggedError = false
            while not (runtimeState and runtimeState.destroyed) do
                task.wait(TICK)
                local ok, err = pcall(tick)
                if not ok and not loggedError then
                    loggedError = true
                    log("worker error: " .. tostring(err))
                end
                ST.note = (ST.status())
            end
        end)
    end
    components.profileHud = function(context) -- Ethereal Enchantment (round 4): the top-left account / session HUD
        -- Replaces the game's own profile display (avatar + level, name, HP, EXP, gold, gems, the Halloween currency and the
        -- XP boost) with one Ethereal panel, and carries the Session time and Activity that left the hub (D-147).
        -- VISUAL ONLY: it reads values and hides / restores the game's own profile elements. It never changes farming,
        -- combat, movement or party decisions. Updates come from events (Changed, GetPropertyChangedSignal, ChildAdded,
        -- CharacterAdded) plus the hub's existing 1 s session refresher; nothing runs per frame.
        -- Sources (docs/06_DECISIONS.md D-147): leaderstats Gold / Gems / Level, Player.Candy, Player.xpBoost and the
        -- Humanoid are read by existing code; PlayerGui.playerStatus.Frame.{playerName, healthFrame, portraitBorder,
        -- levelBorder, moneyMain, xpFrame} are the names 18's streamer mode already edits. The XP Boost box and the
        -- Halloween tile are found by a text heuristic (a hypothesis until a recording's guiDump confirms them);
        -- hudGameHidePaths ("playerStatus/Frame/name; Gui/Frame") adds containers without a code change.
        local config, runtimeState = context.CFG, context.RT
        local players = game:GetService("Players")
        local guiService = game:GetService("GuiService")
        local localPlayer = players.LocalPlayer
        local KNOWN = { "playerName", "healthFrame", "portraitBorder", "levelBorder", "moneyMain", "xpFrame" }
        local SKIP_GUI = {
            DungeonAutofarmUI = true,
            AurRecorder = true,
            Chat = true,
            BubbleChat = true,
            TouchGui = true,
            Freecam = true,
            playerStatsLeaderboard = true,
            leaderboard = true,
        }
        local PH = { hidden = {}, found = {}, sources = {} }
        context.ProfileHud = PH
        local gui, panel, parts, compactNow = nil, nil, nil, nil
        local conns, dataConns, charConns, humConns = {}, {}, {}, {}
        local humanoid, scanGen, scanAt, thumb = nil, 0, -math.huge, nil
        local boostLabel, eventIcon

        local function on(list, signal, fn)
            local ok, c = pcall(function()
                return signal:Connect(fn)
            end)
            if ok and c then
                list[#list + 1] = c
            end
            return c
        end
        local function drop(list)
            for _, c in ipairs(list) do
                pcall(function()
                    c:Disconnect()
                end)
            end
            table.clear(list)
        end
        local function enabled()
            return config.hudReplaceGame ~= false and not (runtimeState and runtimeState.destroyed)
        end

        -- numbers in the game's own short form (12.77B, 203.12K, 1.01T)
        local SUFFIX = { "K", "M", "B", "T", "Qd", "Qn", "Sx", "Sp" }
        local MULT = { K = 1e3, M = 1e6, B = 1e9, T = 1e12, QD = 1e15, QN = 1e18, SX = 1e21, SP = 1e24 }
        local function short(n)
            n = tonumber(n)
            if not n or n ~= n then
                return nil
            end
            local sign = n < 0 and "-" or ""
            n = math.abs(n)
            if n < 1000 then
                return sign .. tostring(math.floor(n + 0.5))
            end
            local i = 0
            while n >= 1000 and i < #SUFFIX do
                n, i = n / 1000, i + 1
            end
            local text = ("%.2f"):format(math.floor(n * 100) / 100):gsub("%.?0+$", "")
            return sign .. text .. SUFFIX[i]
        end
        local function parseShort(s)
            s = tostring(s or ""):gsub("[,%s]", "")
            local num, suf = s:match("^(%-?%d+%.?%d*)(%a*)$")
            local v = tonumber(num)
            if not v then
                return nil
            end
            if suf ~= "" then
                local m = MULT[suf:upper()]
                if not m then
                    return nil
                end
                v *= m
            end
            return v
        end
        local function pair(text) -- "1.01T/9.21T" -> "1.01T", "9.21T", ratio (the game's own short form is kept)
            local a, b = tostring(text or ""):match("^%s*([^/]-)%s*/%s*([^/]-)%s*$")
            local x, y = parseShort(a), parseShort(b)
            if x and y then
                return a, b, y > 0 and math.clamp(x / y, 0, 1) or 0
            end
        end
        local function hms(seconds)
            seconds = math.max(0, math.floor(tonumber(seconds) or 0))
            return ("%02d:%02d:%02d"):format(math.floor(seconds / 3600), math.floor(seconds % 3600 / 60), seconds % 60)
        end
        PH.short, PH.parseShort, PH.pair = short, parseShort, pair

        -- live values
        local function valueObject(parent, name)
            local v = parent and parent:FindFirstChild(name)
            if v and v:IsA("ValueBase") then
                return v
            end
            return nil
        end
        local function leader(name)
            local v = valueObject(localPlayer:FindFirstChild("leaderstats"), name)
            return v and tonumber(v.Value) or nil
        end
        local function playerGui()
            return localPlayer:FindFirstChild("PlayerGui")
        end
        local function gameFrame() -- the game's profile: PlayerGui.playerStatus.Frame (see 18's streamer mode)
            local pg = playerGui()
            local status = pg and pg:FindFirstChild("playerStatus")
            return status and status:FindFirstChild("Frame") or nil
        end
        local function gameText(container, name)
            local frame = gameFrame()
            local box = frame and frame:FindFirstChild(container)
            local label = box and box:FindFirstChild(name)
            if label and label:IsA("TextLabel") then
                return label
            end
            return nil
        end
        local function ours(inst)
            return gui ~= nil and (inst == gui or inst:IsDescendantOf(gui))
        end
        local function viewport()
            local camera = workspace.CurrentCamera
            return camera and camera.ViewportSize or Vector2.new(1920, 1080)
        end

        -- the game's profile elements: hide while we replace them, restore exactly what was there
        local function restoreOne(inst)
            local rec = PH.hidden[inst]
            if not rec then
                return
            end
            PH.hidden[inst] = nil
            pcall(function()
                rec.conn:Disconnect()
            end)
            if inst.Parent then
                pcall(function()
                    inst[rec.prop] = rec.value
                end)
            end
        end
        local function hideOne(inst)
            if PH.hidden[inst] then
                return
            end
            local prop = inst:IsA("LayerCollector") and "Enabled" or "Visible"
            local rec = { prop = prop, value = inst[prop] == true, ours = false }
            PH.hidden[inst] = rec
            -- the game may show it again (or hide it) later: remember what it wants, keep it hidden while we replace it
            rec.conn = inst:GetPropertyChangedSignal(prop):Connect(function()
                if rec.ours then
                    rec.ours = false
                    return
                end
                if inst[prop] then
                    rec.value, rec.ours = true, true
                    inst[prop] = false
                else
                    rec.value = false
                end
            end)
            if inst[prop] then
                rec.ours = true
                inst[prop] = false
            end
        end
        function PH.restoreAll()
            local list = {}
            for inst in pairs(PH.hidden) do
                list[#list + 1] = inst
            end
            for _, inst in ipairs(list) do
                restoreOne(inst)
            end
        end
        local function climb(node, stop, maxW, maxH, vw)
            -- the smallest container around a matched label: up while still small and in the left part of the screen;
            -- never into the game's profile frame, never a frame holding the party list
            local best, p = node, node.Parent
            while p and p:IsA("GuiObject") and p ~= stop do
                if p:FindFirstChild("teammateHolder") then
                    break
                end
                local size, pos = p.AbsoluteSize, p.AbsolutePosition
                if size.X > maxW or size.Y > maxH or pos.X + size.X > vw * 0.6 then
                    break
                end
                best, p = p, p.Parent
            end
            return best
        end
        local function scan() -- on start, respawn, a new ScreenGui, a setting change; never per frame
            local frame, pg = gameFrame(), playerGui()
            local targets, found = {}, { profile = 0, boost = false, event = false, paths = 0 }
            if frame then
                for _, name in ipairs(KNOWN) do
                    local c = frame:FindFirstChild(name)
                    if c and c:IsA("GuiObject") then
                        targets[#targets + 1] = c
                        found.profile += 1
                    end
                end
            end
            if pg then
                for path in tostring(config.hudGameHidePaths or ""):gmatch("[^;,\n]+") do
                    local node = pg
                    for name in path:gmatch("[^/]+") do
                        name = (name:gsub("^%s+", ""):gsub("%s+$", ""))
                        node = node and name ~= "" and node:FindFirstChild(name) or node
                    end
                    if node and node ~= pg and (node:IsA("GuiObject") or node:IsA("LayerCollector")) and not ours(node) then
                        targets[#targets + 1] = node
                        found.paths += 1
                    end
                end
            end
            boostLabel, eventIcon = nil, nil
            if pg and config.hudGameHideAuto ~= false then
                local vw, vh = viewport().X, viewport().Y
                local candyValue = valueObject(localPlayer, "Candy")
                local candy = candyValue and tonumber(candyValue.Value)
                local forms = nil
                if candy and candy >= 10 then
                    forms = { [tostring(math.floor(candy))] = true, [tostring(short(candy)):upper()] = true }
                end
                local mates = frame and frame:FindFirstChild("teammateHolder")
                local function skip(d)
                    if mates and d:IsDescendantOf(mates) then
                        return true
                    end
                    for _, t in ipairs(targets) do
                        if d == t or d:IsDescendantOf(t) then
                            return true
                        end
                    end
                    return false
                end
                for _, sg in ipairs(pg:GetChildren()) do
                    if sg:IsA("ScreenGui") and sg.Enabled and not SKIP_GUI[sg.Name] and not sg.Name:lower():find("boss") and not ours(sg) then
                        for _, d in ipairs(sg:GetDescendants()) do
                            if found.boost and (found.event or not forms) then
                                break
                            end
                            if d:IsA("TextLabel") then
                                local pos = d.AbsolutePosition
                                if pos.X < vw * 0.5 and pos.Y < vh * 0.5 and not skip(d) then
                                    local text = tostring(d.Text)
                                    if not found.boost and text:lower():find("xp%s*boost") then
                                        local box = climb(d, frame, math.max(320, vw * 0.25), math.max(140, vh * 0.2), vw)
                                        targets[#targets + 1] = box
                                        found.boost = box:GetFullName()
                                        for _, t in ipairs(box:GetDescendants()) do
                                            if t:IsA("TextLabel") and tostring(t.Text):match("%d+:%d%d") then
                                                boostLabel = t
                                            end
                                        end
                                    elseif forms and not found.event and forms[(text:gsub("[,%s]", ""):upper())] then
                                        local box = climb(d, frame, math.max(360, vw * 0.25), math.max(140, vh * 0.2), vw)
                                        local image = box:FindFirstChildWhichIsA("ImageLabel", true) or box:FindFirstChildWhichIsA("ImageButton", true)
                                        if image and box ~= d then
                                            targets[#targets + 1] = box
                                            found.event = box:GetFullName()
                                            eventIcon = tostring(image.Image or "")
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
            PH.found = found
            local want = {}
            if enabled() and panel then
                for _, t in ipairs(targets) do
                    want[t] = true
                end
            end
            for inst in pairs(PH.hidden) do
                if not want[inst] then
                    restoreOne(inst)
                end
            end
            for inst in pairs(want) do
                hideOne(inst)
            end
            return found
        end
        PH.scan = scan
        local function scheduleScan(delay)
            scanGen += 1
            local mine = scanGen
            task.delay(delay or 0.5, function()
                if mine == scanGen and panel and enabled() then
                    scanAt = os.clock()
                    pcall(scan)
                    pcall(PH.bindData)
                end
            end)
        end
        function PH.status()
            if not enabled() then
                return "Game profile HUD: shown (the replacement is off)"
            end
            if not panel then
                return "Game profile HUD: waiting for the window"
            end
            local f, n = PH.found or {}, 0
            for _ in pairs(PH.hidden) do
                n += 1
            end
            if n == 0 then
                return "Game profile HUD: not found yet - nothing of the game's is hidden; our values show n/a where unknown"
            end
            return ("Game profile HUD: %d hidden (profile %d, XP Boost %s, Halloween %s%s)"):format(
                n,
                f.profile or 0,
                f.boost and "found" or "not found",
                f.event and "found" or "not found",
                (f.paths or 0) > 0 and (", " .. f.paths .. " from hudGameHidePaths") or ""
            )
        end

        -- the panel
        local function make(class, props, parent)
            local inst = Instance.new(class)
            for k, v in pairs(props) do
                inst[k] = v
            end
            inst.Parent = parent
            return inst
        end
        local function build(parent)
            local kit = context.UIKit
            local theme = kit.Theme
            local function text(p, name, value, size, color, family, weight, align)
                local l = make("TextLabel", {
                    Name = name,
                    BackgroundTransparency = 1,
                    Text = value or "",
                    TextSize = size,
                    TextColor3 = color,
                    TextXAlignment = align or Enum.TextXAlignment.Left,
                    TextYAlignment = Enum.TextYAlignment.Center,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    ZIndex = 3,
                }, p)
                kit.setFont(l, family or "sans", weight or Enum.FontWeight.Medium)
                return l
            end
            local function icon(p, name, color, size)
                local img = kit.icon(p, name, size or 14, color, 3)
                img:SetAttribute("HLThemeSkip", true)
                return img
            end
            local root = make("Frame", {
                Name = "ProfileHud",
                BackgroundColor3 = theme.SurfaceHeader,
                BackgroundTransparency = 0.18,
                BorderSizePixel = 0,
                ZIndex = 2,
                Active = false,
            }, parent)
            kit.corner(root, 10)
            local rim = kit.stroke(root, theme.PanelStroke or theme.Hairline, 1)
            rim.Transparency = theme.PanelStrokeA or 0.5
            local p = { root = root }
            p.header = make("Frame", { Name = "Header", BackgroundTransparency = 1, ZIndex = 2 }, root)
            local logo = context.customLogo and context.customLogo() or nil
            if type(logo) == "string" and logo ~= "" then -- the user's logo (Aur_Hub/images/logo.*); none: no mark at all
                p.logo = make("ImageLabel", {
                    Name = "BrandLogo",
                    BackgroundTransparency = 1,
                    Image = logo,
                    ScaleType = Enum.ScaleType.Crop,
                    ZIndex = 3,
                }, p.header)
                p.logo:SetAttribute("HLThemeSkip", true)
                kit.corner(p.logo, 4)
            end
            p.brand = text(p.header, "Brand", "ETHEREAL ENCHANTMENT", 14, theme.AccentA, "display", Enum.FontWeight.Bold)
            p.avatar = make("ImageLabel", {
                Name = "Avatar",
                BackgroundColor3 = theme.SurfaceField,
                BackgroundTransparency = 0.2,
                BorderSizePixel = 0,
                Image = thumb or "",
                ScaleType = Enum.ScaleType.Crop,
                ZIndex = 3,
            }, root)
            kit.corner(p.avatar, 8)
            local avatarRim = kit.stroke(p.avatar, theme.PanelStroke or theme.Hairline, 1)
            avatarRim.Transparency = theme.PanelStrokeA or 0.5
            p.avatarFallback = icon(p.avatar, "user", theme.TextMuted, 22)
            p.avatarFallback.Name = "Fallback"
            p.avatarFallback.AnchorPoint, p.avatarFallback.Position = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5)
            p.badge = make("Frame", {
                Name = "LevelBadge",
                BackgroundColor3 = theme.SurfaceHeader,
                BackgroundTransparency = 0.05,
                BorderSizePixel = 0,
                ZIndex = 4,
            }, root)
            kit.corner(p.badge, 5)
            kit.stroke(p.badge, theme.AccentB, 1).Transparency = 0.35
            p.level = text(p.badge, "Level", "n/a", 12, theme.TextPrimary, "display", Enum.FontWeight.Bold, Enum.TextXAlignment.Center)
            p.level.Size, p.level.ZIndex = UDim2.fromScale(1, 1), 5
            p.name = text(root, "Username", "@" .. localPlayer.Name, 16, theme.TextPrimary, "display", Enum.FontWeight.Bold)
            local function bar(name, caption)
                local holder = make("Frame", { Name = name, BackgroundTransparency = 1, ZIndex = 2 }, root)
                local cap = text(holder, "Label", caption, 12, theme.TextSub, "sans", Enum.FontWeight.Bold)
                cap.Size = UDim2.new(0, 30, 1, 0)
                local track = make("Frame", {
                    Name = "Track",
                    Position = UDim2.fromOffset(32, 1),
                    Size = UDim2.new(1, -32, 1, -2),
                    BackgroundColor3 = theme.SurfaceField,
                    BackgroundTransparency = 0.15,
                    BorderSizePixel = 0,
                    ClipsDescendants = true,
                    ZIndex = 3,
                }, holder)
                kit.corner(track, 4)
                local fill = make("Frame", {
                    Name = "Fill",
                    Size = UDim2.fromScale(0, 1),
                    BackgroundColor3 = Color3.new(1, 1, 1),
                    BorderSizePixel = 0,
                    ZIndex = 3,
                }, track)
                fill:SetAttribute("HLThemeSkip", true)
                kit.corner(fill, 4)
                local grad = make("UIGradient", {}, fill)
                local value = text(track, "Value", "n/a", 12, theme.TextPrimary, "sans", Enum.FontWeight.Bold, Enum.TextXAlignment.Right)
                value.Size, value.Position, value.ZIndex = UDim2.new(1, -12, 1, 0), UDim2.fromOffset(6, 0), 4
                value.TextStrokeTransparency, value.TextStrokeColor3 = 0.55, Color3.new(0, 0, 0)
                return { holder = holder, fill = fill, grad = grad, value = value }
            end
            p.hp = bar("HP", "HP")
            p.exp = bar("EXP", "EXP")
            p.exp.grad.Color = ColorSequence.new(Color3.fromHex("6FA8FF"), Color3.fromHex("A9C8FF"))
            p.money = make("Frame", { Name = "Currencies", BackgroundTransparency = 1, ZIndex = 2 }, root)
            local function cell(name, iconName, color, tipText)
                local f = make("Frame", { Name = name, BackgroundTransparency = 1, ZIndex = 2 }, p.money)
                local img = icon(f, iconName, color, 14)
                img.Name = "Icon"
                img.AnchorPoint, img.Position = Vector2.new(0, 0.5), UDim2.new(0, 0, 0.5, 0)
                local v = text(f, "Value", "n/a", 13, theme.TextPrimary, "sans", Enum.FontWeight.SemiBold)
                v.Position, v.Size = UDim2.fromOffset(18, 0), UDim2.new(1, -18, 1, 0)
                pcall(kit.tip, f, tipText)
                return { frame = f, icon = img, value = v }
            end
            p.gold = cell("Gold", "coins", Color3.fromHex("F5C542"), "Gold")
            p.gems = cell("Gems", "gem", Color3.fromHex("C9B6FF"), "Gems")
            p.event = cell("Event", "wand-2", Color3.fromHex("FFA94D"), "Halloween candy (the event currency)")
            local function line(name, iconName, caption)
                local f = make("Frame", { Name = name, BackgroundTransparency = 1, ZIndex = 2 }, root)
                local img = icon(f, iconName, theme.TextMuted, 14)
                img.Name = "Icon"
                img.AnchorPoint, img.Position = Vector2.new(0, 0.5), UDim2.new(0, 0, 0.5, 0)
                local cap = text(f, "Label", caption, 12, theme.TextSub, "sans", Enum.FontWeight.Medium)
                cap.Position, cap.Size = UDim2.fromOffset(20, 0), UDim2.new(0.45, -20, 1, 0)
                local v = text(f, "Value", "n/a", 13, theme.TextPrimary, "sans", Enum.FontWeight.SemiBold, Enum.TextXAlignment.Right)
                v.AnchorPoint, v.Position, v.Size = Vector2.new(1, 0), UDim2.fromScale(1, 0), UDim2.new(0.55, 0, 1, 0)
                return { frame = f, icon = img, label = cap, value = v }
            end
            p.boost = line("Boost", "calendar-clock", "XP Boost")
            p.divider = make("Frame", {
                Name = "Divider",
                BackgroundColor3 = theme.Hairline,
                BackgroundTransparency = 0.2,
                BorderSizePixel = 0,
                ZIndex = 2,
            }, root)
            p.session = line("SessionTime", "clock", "Session")
            kit.setFont(p.session.value, "mono", Enum.FontWeight.Medium)
            p.activity = make("Frame", { Name = "Activity", BackgroundTransparency = 1, ZIndex = 2 }, root)
            p.activityDot = make("Frame", {
                Name = "Dot",
                AnchorPoint = Vector2.new(0, 0.5),
                Position = UDim2.new(0, 3, 0.5, 0),
                Size = UDim2.fromOffset(8, 8),
                BackgroundColor3 = theme.TextMuted,
                BorderSizePixel = 0,
                ZIndex = 3,
            }, p.activity)
            p.activityDot:SetAttribute("HLThemeSkip", true)
            kit.corner(p.activityDot, 4)
            p.activityText = text(p.activity, "Value", "Idle", 12, theme.TextSub, "sans", Enum.FontWeight.Medium)
            p.activityText.Position, p.activityText.Size = UDim2.fromOffset(20, 0), UDim2.new(1, -20, 1, 0)
            return p
        end
        local function layout()
            if not parts then
                return
            end
            local p = parts
            local compact = viewport().X < 760
            compactNow = compact
            local inset = Vector2.new(0, 36)
            pcall(function()
                inset = guiService:GetGuiInset()
            end)
            -- under Roblox's top bar, where the game's profile was (the ScreenGui ignores the inset)
            local w, pad = compact and 244 or 320, compact and 8 or 10
            local inner = w - 2 * pad
            local headH, av, nameH, barH, rowH = compact and 16 or 20, compact and 44 or 58, compact and 18 or 20, compact and 16 or 18, compact and 16 or 18
            local y = compact and 6 or 8
            p.header.Position, p.header.Size = UDim2.fromOffset(pad, y), UDim2.fromOffset(inner, headH)
            local brandX = 0
            if p.logo then
                p.logo.Size = UDim2.fromOffset(headH, headH)
                brandX = headH + 6
            end
            p.brand.Position, p.brand.Size = UDim2.fromOffset(brandX, 0), UDim2.new(1, -brandX, 1, 0)
            p.brand.TextSize = compact and 12 or 14
            y += headH + (compact and 4 or 6)
            local top = y
            p.avatar.Position, p.avatar.Size = UDim2.fromOffset(pad, top), UDim2.fromOffset(av, av)
            p.badge.Size = UDim2.fromOffset(compact and 30 or 34, compact and 16 or 18)
            p.badge.Position = UDim2.fromOffset(pad - 4, top + av - (compact and 12 or 14))
            local x = pad + av + 10
            p.name.Position, p.name.Size = UDim2.fromOffset(x, top - 2), UDim2.fromOffset(w - x - pad, nameH)
            p.name.TextSize = compact and 14 or 16
            p.hp.holder.Position, p.hp.holder.Size = UDim2.fromOffset(x, top + nameH), UDim2.fromOffset(w - x - pad, barH)
            p.exp.holder.Position, p.exp.holder.Size = UDim2.fromOffset(x, top + nameH + barH + 2), UDim2.fromOffset(w - x - pad, barH)
            y = math.max(top + av, top + nameH + 2 * barH + 2) + (compact and 4 or 6)
            p.money.Position, p.money.Size = UDim2.fromOffset(pad, y), UDim2.fromOffset(inner, rowH + 2)
            local third = math.floor(inner / 3)
            for i, c in ipairs({ p.gold, p.gems, p.event }) do
                c.frame.Position, c.frame.Size = UDim2.fromOffset((i - 1) * third, 0), UDim2.fromOffset(third - 4, rowH + 2)
                c.value.TextSize = compact and 12 or 13
            end
            y += rowH + (compact and 4 or 6)
            p.boost.frame.Position, p.boost.frame.Size = UDim2.fromOffset(pad, y), UDim2.fromOffset(inner, rowH)
            y += rowH + (compact and 3 or 5)
            p.divider.Position, p.divider.Size = UDim2.fromOffset(pad, y), UDim2.fromOffset(inner, 1)
            y += compact and 3 or 5
            p.session.frame.Position, p.session.frame.Size = UDim2.fromOffset(pad, y), UDim2.fromOffset(inner, rowH)
            y += rowH + 2
            p.activity.Position, p.activity.Size = UDim2.fromOffset(pad, y), UDim2.fromOffset(inner, rowH)
            y += rowH + (compact and 6 or 8)
            for _, l in ipairs({ p.boost.value, p.session.value }) do
                l.TextSize = compact and 12 or 13
            end
            p.root.Position = UDim2.fromOffset(compact and 8 or 12, inset.Y + (compact and 6 or 8))
            p.root.Size = UDim2.fromOffset(w, y)
            p.root.Visible = true
        end
        PH.layout = layout

        local function setText(label, value)
            value = tostring(value)
            if label.Text ~= value then
                label.Text = value
            end
        end
        local function setBar(b, ratio, valueText, low)
            setText(b.value, valueText or "n/a")
            local scale = ratio and math.clamp(ratio, 0, 1) or 0
            if b.fill.Size.X.Scale ~= scale then
                b.fill.Size = UDim2.fromScale(scale, 1)
            end
            b.fill.Visible = ratio ~= nil
            if low ~= nil then
                local want = low and "low" or "ok"
                if b.mode ~= want then
                    b.mode = want
                    b.grad.Color = low and ColorSequence.new(Color3.fromHex("FF6B5C"), Color3.fromHex("FF9A6B"))
                        or ColorSequence.new(Color3.fromHex("4FD69C"), Color3.fromHex("8FD3FF"))
                end
            end
        end
        local function activityNow()
            local shell = context.Shell
            if shell and shell.activityText then
                local ok, textValue, running = pcall(shell.activityText)
                if ok and textValue then
                    return textValue, running
                end
            end
            return "Idle", runtimeState.farmEnabled == true
        end
        function PH.refresh()
            if not parts then
                return
            end
            local p, theme = parts, context.UIKit.Theme
            local streamer = config.streamer == true
            local sources = PH.sources
            -- name, avatar, level
            if streamer and config.streamerName then
                local alias = tostring(config.streamerNameText or "")
                setText(p.name, alias ~= "" and ("@" .. alias) or "Hidden")
            else
                setText(p.name, "@" .. localPlayer.Name)
            end
            p.avatar.ImageTransparency = streamer and 1 or 0
            p.avatarFallback.Visible = streamer or p.avatar.Image == ""
            local level = leader("Level")
            sources.level = level and "leaderstats.Level" or nil
            if not level then
                local l = gameText("levelBorder", "level")
                level = l and tonumber((tostring(l.Text):match("%d+"))) or nil
                sources.level = level and "playerStatus levelBorder.level (text)" or nil
            end
            if streamer and config.streamerLevel then
                local alias = tostring(config.streamerLevelText or "")
                p.badge.Visible = alias ~= ""
                setText(p.level, alias)
            else
                p.badge.Visible = true
                setText(p.level, level and tostring(level) or "n/a")
            end
            -- HP: the Humanoid; the game's own label while there is none (loading, respawn)
            local hum = humanoid
            if streamer and config.streamerHealth then -- streamer mode hides the game's health: the alias here too
                local alias = tostring(config.streamerHealthText or "")
                setBar(p.hp, nil, alias ~= "" and alias or "Hidden", false)
                sources.hp = "streamer alias"
            elseif hum and hum.Parent and (tonumber(hum.MaxHealth) or 0) > 0 then
                local cur, max = math.max(0, hum.Health), hum.MaxHealth
                local ratio = cur / max
                setBar(p.hp, ratio, short(math.ceil(cur)) .. "/" .. short(math.ceil(max)), ratio <= 0.3)
                sources.hp = "Humanoid"
            else
                local l = gameText("healthFrame", "health")
                local a, b, ratio = pair(l and l.Text)
                if a then
                    setBar(p.hp, ratio, a .. "/" .. b, ratio <= 0.3)
                    sources.hp = "playerStatus healthFrame.health (text)"
                else
                    setBar(p.hp, nil, "n/a", false)
                    sources.hp = nil
                end
            end
            -- EXP: only the game's own label carries it ("1.01T/9.21T")
            do
                local l = gameText("xpFrame", "xp")
                local a, b, ratio = pair(l and l.Text)
                if streamer and config.streamerWealth and (config.streamerXpText or "") ~= "" then
                    setBar(p.exp, nil, tostring(config.streamerXpText), nil)
                elseif a then
                    setBar(p.exp, ratio, a .. "/" .. b, nil)
                else
                    setBar(p.exp, nil, "n/a", nil)
                end
                sources.exp = a and "playerStatus xpFrame.xp (text)" or nil
            end
            -- gold, gems, Halloween candy
            local gold, gems = leader("Gold"), leader("Gems")
            local candyValue = valueObject(localPlayer, "Candy")
            local candy = candyValue and tonumber(candyValue.Value) or nil
            if streamer and config.streamerWealth then
                local g, m = tostring(config.streamerGoldText or ""), tostring(config.streamerGemsText or "")
                setText(p.gold.value, g ~= "" and g or "Hidden")
                setText(p.gems.value, m ~= "" and m or "Hidden")
            else
                setText(p.gold.value, gold and short(gold) or "n/a")
                setText(p.gems.value, gems and short(gems) or "n/a")
            end
            setText(p.event.value, candy and short(candy) or "n/a")
            if eventIcon and eventIcon ~= "" and p.event.icon.Image ~= eventIcon then -- the game's own candy icon
                p.event.icon.Image, p.event.icon.ImageColor3 = eventIcon, Color3.new(1, 1, 1)
            end
            sources.gold, sources.gems = gold and "leaderstats.Gold" or nil, gems and "leaderstats.Gems" or nil
            sources.event = candy and "Player.Candy" or nil
            -- XP boost: Player.xpBoost (seconds left); else the game's own timer text
            local boost = valueObject(localPlayer, "xpBoost")
            local secs = boost and tonumber(boost.Value) or nil
            if secs then
                setText(p.boost.value, secs > 0 and hms(secs) or "inactive")
                p.boost.value.TextColor3 = secs > 0 and theme.AccentB or theme.TextSub
                sources.boost = "Player.xpBoost"
            elseif boostLabel and boostLabel.Parent and tostring(boostLabel.Text):match("%d+:%d%d") then
                setText(p.boost.value, tostring(boostLabel.Text):match("[%d:]+"))
                p.boost.value.TextColor3 = theme.AccentB
                sources.boost = "the game's XP Boost timer (text)"
            else
                setText(p.boost.value, "n/a")
                p.boost.value.TextColor3 = theme.TextSub
                sources.boost = nil
            end
            -- activity (the session time has its own 1 s updater in the hub)
            local activity, running = activityNow()
            setText(p.activityText, activity)
            p.activityDot.BackgroundColor3 = running and theme.AccentB or theme.TextMuted
            if not (context.Shell and context.Shell.addSessionLabel) then
                local started = runtimeState.sessionStartedAt or os.clock()
                setText(p.session.value, hms(os.clock() - started))
            end
        end
        local function refresh()
            pcall(PH.refresh)
        end

        function PH.bindData() -- value objects come and go (loading, respawn): bind what exists now, event-driven
            drop(dataConns)
            local ls = localPlayer:FindFirstChild("leaderstats")
            if ls then
                on(dataConns, ls.ChildAdded, function()
                    task.defer(PH.bindData)
                end)
                for _, name in ipairs({ "Gold", "Gems", "Level" }) do
                    local v = valueObject(ls, name)
                    if v then
                        on(dataConns, v.Changed, refresh)
                    end
                end
            end
            for _, name in ipairs({ "Candy", "xpBoost" }) do
                local v = valueObject(localPlayer, name)
                if v then
                    on(dataConns, v.Changed, refresh)
                end
            end
            for _, pathPair in ipairs({ { "xpFrame", "xp" }, { "levelBorder", "level" }, { "healthFrame", "health" } }) do
                local l = gameText(pathPair[1], pathPair[2])
                if l then
                    on(dataConns, l:GetPropertyChangedSignal("Text"), refresh)
                end
            end
            if boostLabel then
                on(dataConns, boostLabel:GetPropertyChangedSignal("Text"), refresh)
            end
            refresh()
        end
        local function bindHumanoid(h)
            drop(humConns)
            humanoid = h
            if h then
                on(humConns, h:GetPropertyChangedSignal("Health"), refresh)
                on(humConns, h:GetPropertyChangedSignal("MaxHealth"), refresh)
                on(humConns, h.AncestryChanged, refresh)
            end
            refresh()
        end
        local function bindCharacter(char)
            drop(charConns)
            bindHumanoid(char and char:FindFirstChildOfClass("Humanoid") or nil)
            if char then
                on(charConns, char.ChildAdded, function(c)
                    if c:IsA("Humanoid") then
                        bindHumanoid(c)
                    end
                end)
                on(charConns, char.ChildRemoved, function(c)
                    if c == humanoid then
                        bindHumanoid(char:FindFirstChildOfClass("Humanoid"))
                    end
                end)
            end
        end
        PH.bindCharacter = bindCharacter

        function PH.destroy(unload) -- the replacement off, or the script unloading: every hidden original comes back
            scanGen += 1
            drop(conns)
            drop(dataConns)
            drop(charConns)
            drop(humConns)
            humanoid = nil
            PH.restoreAll()
            if panel then
                pcall(function()
                    panel:Destroy()
                end)
            end
            panel, parts = nil, nil
            PH.panel = nil
            if unload then
                gui = nil
            end
        end
        function PH.mount(parent) -- called by 18 once the hub's ScreenGui exists (it stays enabled when the hub hides)
            gui = parent or gui
            if not gui or panel or not enabled() then
                return panel
            end
            parts = build(gui)
            panel = parts.root
            PH.panel, PH.parts = panel, parts
            layout()
            local shell = context.Shell
            if shell and shell.addSessionLabel then
                shell.addSessionLabel(parts.session.value) -- the hub's one session updater (1 s, keeps counting hidden)
            end
            if shell and shell.addSessionRefresher then
                shell.addSessionRefresher(function()
                    if panel then
                        PH.refresh()
                    end
                end)
            else
                task.spawn(function() -- no hub shell (tests): a 1 s refresh of its own, never per frame
                    local mine = panel
                    while mine and mine.Parent and panel == mine do
                        task.wait(1)
                        refresh()
                    end
                end)
            end
            if not thumb then
                task.spawn(function()
                    local ok, image = pcall(function()
                        return players:GetUserThumbnailAsync(localPlayer.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size150x150)
                    end)
                    if ok and type(image) == "string" then
                        thumb = image
                        if parts then
                            parts.avatar.Image = image
                            refresh()
                        end
                    end
                end)
            end
            on(conns, localPlayer.ChildAdded, function(c)
                if c.Name == "leaderstats" or c.Name == "Candy" or c.Name == "xpBoost" then
                    task.defer(PH.bindData)
                    if c.Name == "Candy" then
                        scheduleScan(1)
                    end
                end
            end)
            on(conns, localPlayer.CharacterAdded, function(char)
                bindCharacter(char)
                scheduleScan(1) -- a respawn can rebuild the game's ScreenGuis (ResetOnSpawn)
            end)
            on(conns, localPlayer.CharacterRemoving, function()
                bindCharacter(nil)
            end)
            local pg = playerGui()
            if pg then
                on(conns, pg.ChildAdded, function(c)
                    if c ~= gui then
                        scheduleScan(0.5)
                    end
                end)
            end
            local camera = workspace.CurrentCamera
            if camera then
                on(conns, camera:GetPropertyChangedSignal("ViewportSize"), function()
                    local compact = viewport().X < 760
                    if compact ~= compactNow then
                        layout()
                    end
                end)
            end
            bindCharacter(localPlayer.Character)
            pcall(scan)
            PH.bindData()
            return panel
        end
        function PH.apply() -- the Visuals switch
            if enabled() then
                PH.mount(gui)
            else
                PH.destroy(false)
            end
        end
    end
    return components
end)()

-- boot() starts one copy. D-155: no key system (the D-144 license gate is removed).
local function boot()
    local context = {}
    components.coreSettings(context)
    context.loadConfig()
    components.attackCatalog(context)
    components.gearProfiles(context)
    components.movementBoost(context)
    components.hazardReader(context)
    components.dangerGeometry(context)
    components.odinMechanics(context)
    components.bossPhases(context)
    components.bubbleBoss(context)
    components.movementCombat(context)
    components.inventoryAutomation(context)
    components.partyQueue(context)
    components.raidAutomation(context)
    components.uiLibrary(context)
    components.drawing(context)
    components.walls(context)
    components.statisticsWebhooks(context)
    components.statsReporter(context)
    components.appLink(context) -- the Windows app's trades (after 17: reuses its saved-key reader)
    components.runRecorder(context)
    components.mapLite(context)
    components.profileHud(context) -- round 4 (D-147): before 18, which mounts it on the hub's ScreenGui
    components.interfaceMainLoop(context)

    -- Aur_Hub handle for the console and the recorder: _G.Aur_Hub.version / .context / .destroy()
    _G.Aur_Hub = { version = context.SCRIPT_VERSION, context = context, destroy = _G.DungeonAutofarmDestruct }

    return context
end

return boot()